        protected void validarTablas()
        {
            string tablas = "";
            string mensajeTablas = "";
            DataRow[] filaEncontrada;
            string idioma = Session["idioma"].ToString();

            string strConexion;
            SqlConnection conexion;
            SqlCommand comando;

            strConexion = funcionalidades.recuperarTexto(ConfigurationManager.ConnectionStrings["SQL_ROP"].ToString());
            conexion = new SqlConnection(strConexion);
            conexion.Open();
            comando = conexion.CreateCommand();
            comando.CommandText = "sp_ROP_ConfiguracionTecnicoConsulta";
            comando.CommandTimeout = 60;
            comando.CommandType = CommandType.StoredProcedure;
            comando.Parameters.Clear();
            SqlDataReader dr = comando.ExecuteReader();

            if (dr.HasRows)
            {
                dr.Read();
                Session["PararEjecucion"] = Convert.ToBoolean(dr["PararEjecucionSiTablasMal"]);
            }
            dr.Close();
            comando.Dispose();
            conexion.Close();
            conexion.Dispose();

            strConexion = funcionalidades.recuperarTexto(ConfigurationManager.ConnectionStrings["SQL_ROP"].ToString());
            conexion = new SqlConnection(strConexion);
            conexion.Open();
            comando = conexion.CreateCommand();
            comando.CommandText = "ROP_Flags_Consulta";
            comando.CommandTimeout = 60;
            comando.CommandType = CommandType.StoredProcedure;
            dr = comando.ExecuteReader();
            if (dr.HasRows)
            {
                while (dr.Read())
                {
                    if (idioma == "ESPAÑOL")
                        mensajeTablas = Convert.ToString(dr["ETQ_TextoCastellano"]);
                    if (idioma == "CATALAN")
                        mensajeTablas = Convert.ToString(dr["ETQ_TextoCatalan"]);
                    if (idioma == "INGLES")
                        mensajeTablas = Convert.ToString(dr["ETQ_TextoIngles"]);

                    lblMensajeError.Text = mensajeTablas;
                    MENSAJE_ERROR.Visible = true;
                    lblMensajeError.Visible = true;
                    imgWarning.Visible = true;

                    cmbConcepto.Enabled = false;
                    cmbEmpresa.Enabled = false;
                    txtNumero.Enabled = false;
                    btnBuscarInformacion.Enabled = false;
                    btnContinuarCalculo.Enabled = false;
                    btnContinuarCalculo.Visible = false;

                    tablas = "SALIR";
                    break;
                }
            }
            comando.Dispose();
            conexion.Close();
            conexion.Dispose();

            if (tablas == "SALIR")
                return;

            tablas = "";
            strConexion = funcionalidades.recuperarTexto(ConfigurationManager.ConnectionStrings["SQL_ROP"].ToString());
            conexion = new SqlConnection(strConexion);
            conexion.Open();
            comando = conexion.CreateCommand();
            comando.CommandText = "ROP_Flags";
            comando.CommandTimeout = 60;
            comando.CommandType = CommandType.StoredProcedure;
            dr = comando.ExecuteReader();
            if (dr.HasRows)
            {
                while (dr.Read())
                {
                    if (tablas != "")
                        tablas = tablas + " / ";
                    tablas = tablas + dr["OrigenDatos"].ToString();

                    // quitar esto si quiero la relación de tablas
                    break;
                }
            }
            comando.Dispose();
            conexion.Close();
            conexion.Dispose();

            if (tablas != "")
            {
                MENSAJE_ERROR.Visible = true;

                lblMensajeError.Visible = true;
                imgWarning.Visible = true;
                filaEncontrada = dtIdiomas.Select("ETQ_Control = 'msgErrorTablas'");
                foreach (DataRow filaValor in filaEncontrada)
                {
                    if (idioma == "ESPAÑOL")
                        mensajeTablas = Convert.ToString(filaValor["ETQ_TextoCastellano"]);
                    if (idioma == "CATALAN")
                        mensajeTablas = Convert.ToString(filaValor["ETQ_TextoCatalan"]);
                    if (idioma == "INGLES")
                        mensajeTablas = Convert.ToString(filaValor["ETQ_TextoIngles"]);
                }
                lblMensajeError.Text = mensajeTablas;

                if (Convert.ToBoolean(Session["PararEjecucion"]))
                {
                    cmbConcepto.Enabled = false;
                    cmbEmpresa.Enabled = false;
                    txtNumero.Enabled = false;
                    btnBuscarInformacion.Enabled = false;
                    btnContinuarCalculo.Enabled = false;
                    btnContinuarCalculo.Visible = false;
                }
            }
        }

