        protected void chkNegativos_CheckedChanged(Object sender, EventArgs e)
        {
            DataTable dtPendienteDevolver = new DataTable();
            dtPendienteDevolver = (DataTable)Session["dtPendienteDevolver"];
            DataTable dtSimulacion = new DataTable();
            dtSimulacion = (DataTable)Session["dtSimulacion"];

            DataRow[] filaEncontrada;

            filaEncontrada = dtPendienteDevolver.Select("ARTICULO <> ''");
            foreach (DataRow filaDT in filaEncontrada)
            {
                if (!String.IsNullOrEmpty(Convert.ToString(filaDT["PVP OBRA"])))
                    if (Convert.ToDouble(filaDT["PVP OBRA"]) < 0)
                    {
                        filaDT["SUMAR"] = !chkNegativos.Checked;
                        filaDT.AcceptChanges();
                    }
            }

            filaEncontrada = dtPendienteDevolver.Select("FAMILIA <> '' AND SUBFAMILIA <> '' AND ARTICULO = ''");
            foreach (DataRow filaDT in filaEncontrada)
            {
                // TOTAL SUBFAMILIA
                string strSubfamilia = filaDT["SUBFAMILIA"].ToString();
                int totalSubfamilia = dtPendienteDevolver.AsEnumerable()
                    .Where(y => y.Field<string>("SUBFAMILIA") == strSubfamilia && y.Field<string>("ARTICULO") != "" && y.Field<decimal>("CANTIDAD ORIGINAL") != 0 && y.Field<int>("SUMAR") != 0)
                    .Count();

                filaEncontrada = dtPendienteDevolver.Select("SUBFAMILIA = '" + strSubfamilia + "' AND ARTICULO = ''");
                foreach (DataRow filaSubfamilia in filaEncontrada)
                {
                    if (totalSubfamilia == 0)
                        filaSubfamilia["SUMAR"] = 0;
                    else
                        filaSubfamilia["SUMAR"] = 1;
                    filaDT.AcceptChanges();
                }
            }

            filaEncontrada = dtPendienteDevolver.Select("FAMILIA <> '' AND SUBFAMILIA = '' AND ARTICULO = ''");
            foreach (DataRow filaDT in filaEncontrada)
            {
                // TOTAL FAMILIA
                string strFamilia = filaDT["FAMILIA"].ToString();
                int totalFamilia = dtPendienteDevolver.AsEnumerable()
                    .Where(y => y.Field<string>("FAMILIA") == strFamilia && y.Field<string>("SUBFAMILIA") != "" && y.Field<string>("ARTICULO") == "" && y.Field<decimal>("CANTIDAD ORIGINAL") != 0 && y.Field<int>("SUMAR") != 0)
                    .Count();

                filaEncontrada = dtPendienteDevolver.Select("FAMILIA = '" + strFamilia + "' AND SUBFAMILIA = ''");
                foreach (DataRow filaFamilia in filaEncontrada)
                {
                    if (totalFamilia == 0)
                        filaFamilia["SUMAR"] = 0;
                    else
                        filaFamilia["SUMAR"] = 1;
                    filaDT.AcceptChanges();
                }
            }

            calcularSubtotalesSimulacion(true);

            DataView dvPendientes;
            dvPendientes = dtPendienteDevolver.Select("([CANTIDAD ORIGINAL] <> 0  OR [CONCEPTO COMPLETO] = 'TOTAL') AND SUMAR = 1").CopyToDataTable().DefaultView;
            dvPendientes.Sort = "FAMILIA ASC, SUBFAMILIA ASC, ARTICULO ASC";
            grvDatos.DataSource = dvPendientes.ToTable();
            //grvDatos.DataSource = dtPendienteDevolver;
            grvDatos.DataBind();

            dataGastosFijos.DataSource = dtPendienteDevolver;
            dataGastosFijos.DataBind();

            btnSimular.CssClass = "btn btn-danger";
            btnSimular.Enabled = true;
            grvSimulacion.DataSource = dtSimulacion;
            grvSimulacion.DataBind();
        }

