        protected void calcularSubtotalesSimulacion(bool cantidad)
        {
            DataRow[] filaEncontrada;
            decimal total = 0;
            decimal totalPorcentaje = 0;
            decimal totalSubfamiliaPorcentaje = 0;
            decimal totalFamiliaPorcentaje = 0;
            decimal cantidadOriginal = 0;
            DataTable dtPendienteDevolver = new DataTable();
            dtPendienteDevolver = (DataTable)Session["dtPendienteDevolver"];
            DataTable dtValoresFicha = new DataTable();
            dtValoresFicha = (DataTable)Session["dtValoresFicha"];

            try
            {
                if (cantidad)
                {
                    // SUBFAMILIA
                    filaEncontrada = dtPendienteDevolver.Select("SUBFAMILIA <> '' AND ARTICULO = ''");
                    foreach (DataRow filaDT in filaEncontrada)
                    {
                        total = dtPendienteDevolver.AsEnumerable()
                               .Where(y => y.Field<string>("SUBFAMILIA") == filaDT["SUBFAMILIA"].ToString() && y.Field<string>("ARTICULO") != "" && y.Field<int>("SUMAR") == 1 && y.Field<decimal>("PVP OBRA") >= 0)
                               .Sum(x => Convert.ToDecimal(x.Field<decimal>("CANTIDAD")));

                        totalSubfamiliaPorcentaje = dtPendienteDevolver.AsEnumerable()
                               .Where(y => y.Field<string>("SUBFAMILIA") == filaDT["SUBFAMILIA"].ToString() && y.Field<string>("ARTICULO") != "") // && y.Field<int>("SUMAR") == 1)
                               .Sum(x => Convert.ToDecimal(x.Field<decimal>("CANTIDAD ENTREGADA")) * Convert.ToDecimal(x.Field<decimal>("PVP")));

                        cantidadOriginal = dtPendienteDevolver.AsEnumerable()
                               .Where(y => y.Field<string>("SUBFAMILIA") == filaDT["SUBFAMILIA"].ToString() && y.Field<string>("ARTICULO") != "" && y.Field<int>("SUMAR") == 1 && y.Field<decimal>("PVP OBRA") >= 0)
                               .Sum(x => Convert.ToDecimal(x.Field<decimal>("CANTIDAD ORIGINAL")));

                        if (cantidadOriginal != 0)
                            filaDT["PORCENTAJE DEVOLUCION"] = (Math.Round((total * 100) / cantidadOriginal, 2)).ToString("#,##0.00");
                        else
                            filaDT["PORCENTAJE DEVOLUCION"] = 0;

                        total = dtPendienteDevolver.AsEnumerable()
                               .Where(y => y.Field<string>("SUBFAMILIA") == filaDT["SUBFAMILIA"].ToString() && y.Field<string>("ARTICULO") != "" && y.Field<int>("SUMAR") == 1)
                               .Sum(x => Convert.ToDecimal(x.Field<decimal>("PVP ORIGINAL")));

                        filaDT["PVP ORIGINAL"] = total;

                        total = dtPendienteDevolver.AsEnumerable()
                              .Where(y => y.Field<string>("SUBFAMILIA") == filaDT["SUBFAMILIA"].ToString() && y.Field<string>("ARTICULO") != "" && y.Field<int>("SUMAR") == 1)
                              .Sum(x => Convert.ToDecimal(x.Field<decimal>("PVP OBRA")));

                        filaDT["PVP OBRA"] = total;

                        total = dtPendienteDevolver.AsEnumerable()
                             .Where(y => y.Field<string>("SUBFAMILIA") == filaDT["SUBFAMILIA"].ToString() && y.Field<string>("ARTICULO") != "" && y.Field<int>("SUMAR") == 1)
                             .Sum(x => Convert.ToDecimal(x.Field<decimal>("FACTURACION")));

                        filaDT["FACTURACION"] = total.ToString("#,##0.00");


                        total = dtPendienteDevolver.AsEnumerable()
                          .Where(y => y.Field<string>("SUBFAMILIA") == filaDT["SUBFAMILIA"].ToString() && y.Field<string>("ARTICULO") != "") // && y.Field<int>("SUMAR") == 1)
                          .Sum(x => Convert.ToDecimal(x.Field<decimal>("CANTIDAD ENTREGADA")));

                        filaDT["CANTIDAD ENTREGADA"] = total;

                        if (totalSubfamiliaPorcentaje != 0)
                            filaDT["PORCENTAJE"] = ((Convert.ToDecimal(filaDT["PVP OBRA"]) / totalSubfamiliaPorcentaje) * 100).ToString("#,##0.00");
                        else
                            filaDT["PORCENTAJE"] = 0;

                        total = dtPendienteDevolver.AsEnumerable()
                              .Where(y => y.Field<string>("SUBFAMILIA") == filaDT["SUBFAMILIA"].ToString() && y.Field<string>("ARTICULO") != "" && y.Field<int>("SUMAR") == 1)
                              .Sum(x => Convert.ToDecimal(x.Field<decimal>("FACTURACION LIQUIDACION")));

                        filaDT["FACTURACION LIQUIDACION"] = total;

                        if (Convert.ToDecimal(filaDT["PVP OBRA"]) != 0)
                            filaDT["DESCUENTO"] = ((Convert.ToDecimal(filaDT["PVP OBRA"]) - Convert.ToDecimal(filaDT["FACTURACION LIQUIDACION"])) * 100 / Convert.ToDecimal(filaDT["PVP OBRA"])).ToString("#,##0.00");
                        else
                            filaDT["DESCUENTO"] = 0;

                        filaDT.AcceptChanges();
                    }

                    // FAMILIA
                    filaEncontrada = dtPendienteDevolver.Select("FAMILIA <> '' AND SUBFAMILIA = '' AND ARTICULO = ''");
                    foreach (DataRow filaDT in filaEncontrada)
                    {
                        total = dtPendienteDevolver.AsEnumerable()
                              .Where(y => y.Field<string>("FAMILIA") == filaDT["FAMILIA"].ToString() && y.Field<string>("ARTICULO") != "" && y.Field<int>("SUMAR") == 1 && y.Field<decimal>("PVP OBRA") >= 0)
                              .Sum(x => Convert.ToDecimal(x.Field<decimal>("CANTIDAD")));

                        totalFamiliaPorcentaje = dtPendienteDevolver.AsEnumerable()
                               .Where(y => y.Field<string>("FAMILIA") == filaDT["FAMILIA"].ToString() && y.Field<string>("ARTICULO") != "") // && y.Field<int>("SUMAR") == 1)
                               .Sum(x => Convert.ToDecimal(x.Field<decimal>("CANTIDAD ENTREGADA")) * Convert.ToDecimal(x.Field<decimal>("PVP")));

                        cantidadOriginal = dtPendienteDevolver.AsEnumerable()
                                .Where(y => y.Field<string>("FAMILIA") == filaDT["FAMILIA"].ToString() && y.Field<string>("ARTICULO") != "" && y.Field<int>("SUMAR") == 1 && y.Field<decimal>("PVP OBRA") >= 0)
                                .Sum(x => Convert.ToDecimal(x.Field<decimal>("CANTIDAD ORIGINAL")));

                        if (cantidadOriginal != 0)
                            filaDT["PORCENTAJE DEVOLUCION"] = (Math.Round((total * 100) / cantidadOriginal, 2)).ToString("#,##0.00");
                        else
                            filaDT["PORCENTAJE DEVOLUCION"] = 0;

                        total = dtPendienteDevolver.AsEnumerable()
                          .Where(y => y.Field<string>("FAMILIA") == filaDT["FAMILIA"].ToString() && y.Field<string>("ARTICULO") != "") // && y.Field<int>("SUMAR") == 1)
                          .Sum(x => Convert.ToDecimal(x.Field<decimal>("CANTIDAD ENTREGADA")));

                        filaDT["CANTIDAD ENTREGADA"] = total;

                        total = dtPendienteDevolver.AsEnumerable()
                               .Where(y => y.Field<string>("FAMILIA") == filaDT["FAMILIA"].ToString() && y.Field<string>("ARTICULO") != "" && y.Field<int>("SUMAR") == 1)
                               .Sum(x => Convert.ToDecimal(x.Field<decimal>("PVP ORIGINAL")));

                        filaDT["PVP ORIGINAL"] = total;

                        total = dtPendienteDevolver.AsEnumerable()
                              .Where(y => y.Field<string>("FAMILIA") == filaDT["FAMILIA"].ToString() && y.Field<string>("ARTICULO") != "" && y.Field<int>("SUMAR") == 1)
                              .Sum(x => Convert.ToDecimal(x.Field<decimal>("PVP OBRA")));

                        filaDT["PVP OBRA"] = total;

                        total = dtPendienteDevolver.AsEnumerable()
                             .Where(y => y.Field<string>("FAMILIA") == filaDT["FAMILIA"].ToString() && y.Field<string>("ARTICULO") != "" && y.Field<int>("SUMAR") == 1)
                             .Sum(x => Convert.ToDecimal(x.Field<decimal>("FACTURACION")));

                        filaDT["FACTURACION"] = total.ToString("#,##0.00");

                        if (totalFamiliaPorcentaje != 0)
                            filaDT["PORCENTAJE"] = ((Convert.ToDecimal(filaDT["PVP OBRA"]) / totalFamiliaPorcentaje) * 100).ToString("#,##0.00");
                        else
                            filaDT["PORCENTAJE"] = 0;

                        total = dtPendienteDevolver.AsEnumerable()
                              .Where(y => y.Field<string>("FAMILIA") == filaDT["FAMILIA"].ToString() && y.Field<string>("ARTICULO") != "" && y.Field<int>("SUMAR") == 1)
                              .Sum(x => Convert.ToDecimal(x.Field<decimal>("FACTURACION LIQUIDACION")));

                        filaDT["FACTURACION LIQUIDACION"] = total.ToString("#,##0.00");

                        if (Convert.ToDecimal(filaDT["PVP OBRA"]) != 0)
                            filaDT["DESCUENTO"] = ((Convert.ToDecimal(filaDT["PVP OBRA"]) - Convert.ToDecimal(filaDT["FACTURACION LIQUIDACION"])) * 100) / Convert.ToDecimal(filaDT["PVP OBRA"]);
                        else
                            filaDT["DESCUENTO"] = 0;

                        filaDT.AcceptChanges();
                    }

                    // TOTAL
                    filaEncontrada = dtPendienteDevolver.Select("FAMILIA = '' AND SUBFAMILIA = '' AND ARTICULO = ''");
                    foreach (DataRow filaDT in filaEncontrada)
                    {
                        total = dtPendienteDevolver.AsEnumerable()
                              .Where(y => y.Field<string>("ARTICULO") != "" && y.Field<int>("SUMAR") == 1 && y.Field<decimal>("PVP OBRA") >= 0)
                              .Sum(x => Convert.ToDecimal(x.Field<decimal>("CANTIDAD")));

                        totalPorcentaje = dtPendienteDevolver.AsEnumerable()
                             .Where(y => y.Field<string>("ARTICULO") != "") //  && y.Field<int>("SUMAR") == 1)
                             .Sum(x => Convert.ToDecimal(x.Field<decimal>("CANTIDAD ENTREGADA")) * Convert.ToDecimal(x.Field<decimal>("PVP")));

                        cantidadOriginal = dtPendienteDevolver.AsEnumerable()
                                .Where(y => y.Field<string>("ARTICULO") != "" && y.Field<int>("SUMAR") == 1 && y.Field<decimal>("PVP OBRA") >= 0)
