        protected void grvMB_RowDataBound(object sender, GridViewRowEventArgs e)
        {
            string formattedString = "";

            if (e.Row.RowType == DataControlRowType.DataRow)
            {
                e.Row.Cells[0].Font.Bold = true;
                e.Row.Cells[0].BackColor = System.Drawing.ColorTranslator.FromHtml("#bebcbc");
                e.Row.Cells[1].BackColor = System.Drawing.ColorTranslator.FromHtml("#bebcbc");

                if (e.Row.RowIndex >= 0)
                {
                    formattedString = Convert.ToDecimal(e.Row.Cells[1].Text).ToString("##0.#0 %");
                    e.Row.Cells[1].Text = formattedString;
                }
            }
        }
        protected void grvSimulacion_RowDataBound(object sender, GridViewRowEventArgs e)
        {
            string formattedString = "";

            if (e.Row.RowType == DataControlRowType.DataRow)
            {
                e.Row.Cells[0].Font.Bold = true;
                if (btnSimular.CssClass == "btn btn-success")
                    e.Row.Cells[2].BackColor = System.Drawing.ColorTranslator.FromHtml("#ddfbd3");
                else
                    e.Row.Cells[2].BackColor = System.Drawing.ColorTranslator.FromHtml("#fbd9d3");

                if (e.Row.RowIndex == 0)
                {
                    e.Row.Cells[1].BackColor = System.Drawing.ColorTranslator.FromHtml("Black");
                    formattedString = Convert.ToDecimal(e.Row.Cells[2].Text).ToString("##0.#0 %");
                    e.Row.Cells[2].Text = formattedString;
                }
                if (e.Row.RowIndex == 1)
                {
                    formattedString = Convert.ToDecimal(e.Row.Cells[1].Text).ToString("#,##0.#0");
                    e.Row.Cells[1].Text = formattedString;

                    formattedString = Convert.ToDecimal(e.Row.Cells[2].Text).ToString("#,##0.#0");
                    e.Row.Cells[2].Text = formattedString;
                }
                if (e.Row.RowIndex == 2)
                {
                    formattedString = Convert.ToDecimal(e.Row.Cells[1].Text).ToString("#,###");
                    e.Row.Cells[1].Text = formattedString;

                    formattedString = Convert.ToDecimal(e.Row.Cells[2].Text).ToString("#,###");
                    e.Row.Cells[2].Text = formattedString;
                }
                if (e.Row.RowIndex == 3 || e.Row.RowIndex == 4)
                {
                    formattedString = Convert.ToDecimal(e.Row.Cells[1].Text).ToString("##0.#0 %");
                    e.Row.Cells[1].Text = formattedString;

                    formattedString = Convert.ToDecimal(e.Row.Cells[2].Text).ToString("##0.#0 %");
                    e.Row.Cells[2].Text = formattedString;
                }
            }
        }

