        protected void grvDatos_RowDataBound(object sender, GridViewRowEventArgs e)
        {
            if (e.Row.RowType == DataControlRowType.DataRow)
            {
                string familia = grvDatos.DataKeys[e.Row.RowIndex].Values[2].ToString();
                string subfamilia = grvDatos.DataKeys[e.Row.RowIndex].Values[3].ToString();
                string articulo = grvDatos.DataKeys[e.Row.RowIndex].Values[4].ToString();
                decimal pvpObra = Convert.ToDecimal(grvDatos.DataKeys[e.Row.RowIndex].Values[5].ToString());
                string mostrar = grvDatos.DataKeys[e.Row.RowIndex].Values[6].ToString();
                decimal pvpOriginal = Convert.ToDecimal(grvDatos.DataKeys[e.Row.RowIndex].Values[8].ToString());

                //if (mostrar == "0")

                //    e.Row.Cells[0].CssClass = "imgSimulacionExpandirClass";
                //else
                //    e.Row.Cells[0].CssClass = "imgSimulacionComprimirClass";


                if (String.IsNullOrEmpty(familia) || familia == "&nbsp;")
                {
                    e.Row.BackColor = System.Drawing.ColorTranslator.FromHtml("#d9f8f6");
                    if (pvpOriginal < 0)
                        e.Row.Cells[4].BackColor = System.Drawing.ColorTranslator.FromHtml("#f76767");
                    if (pvpObra < 0)
                        e.Row.Cells[7].BackColor = System.Drawing.ColorTranslator.FromHtml("#f76767");

                    e.Row.ForeColor = System.Drawing.ColorTranslator.FromHtml("#020202");
                    e.Row.Font.Size = FontUnit.Medium;
                    e.Row.Font.Bold = true;
                }
                else
                {
                    if (String.IsNullOrEmpty(subfamilia) || subfamilia == "&nbsp;")
                    {
                        e.Row.BackColor = System.Drawing.ColorTranslator.FromHtml("#bebcbc");
                        if (pvpOriginal < 0)
                            e.Row.Cells[4].BackColor = System.Drawing.ColorTranslator.FromHtml("#f76767");
                        if (pvpObra < 0)
                            e.Row.Cells[7].BackColor = System.Drawing.ColorTranslator.FromHtml("#f76767");
                        e.Row.ForeColor = System.Drawing.ColorTranslator.FromHtml("#020202");
                        e.Row.Font.Size = FontUnit.Small;
                        e.Row.Font.Bold = true;
                    }
                    else
                    {
                        if (String.IsNullOrEmpty(articulo) || articulo == "&nbsp;")
                        {
                            e.Row.BackColor = System.Drawing.ColorTranslator.FromHtml("#eae6e6");
                            if (pvpOriginal < 0)
                                e.Row.Cells[4].BackColor = System.Drawing.ColorTranslator.FromHtml("#f76767");
                            if (pvpObra < 0)
                                e.Row.Cells[7].BackColor = System.Drawing.ColorTranslator.FromHtml("#f76767");
                            e.Row.ForeColor = System.Drawing.ColorTranslator.FromHtml("#020202");
                            e.Row.Font.Size = FontUnit.XSmall;
                            e.Row.Font.Bold = true;
                        }
                        else
                        {
                            if (pvpOriginal < 0)
                                e.Row.Cells[4].BackColor = System.Drawing.ColorTranslator.FromHtml("#f76767");
                            if (pvpObra < 0)
                                e.Row.Cells[7].BackColor = System.Drawing.ColorTranslator.FromHtml("#f76767");
                        }
                    }
                }

                for (int i = 0; i < grvDatos.Columns.Count; i++)
                {
                    if (mostrar == "1" || e.Row.RowIndex == 0)
                        e.Row.Cells[i].Visible = true;
                    else
                        e.Row.Cells[i].Visible = false;
                }

                e.Row.Attributes.Add("onmouseover", "this.originalcolorbackground=this.style.backgroundColor;" + " this.style.backgroundColor='#fdfdd2';");
                e.Row.Attributes.Add("onmouseout", "this.style.backgroundColor=this.originalcolorbackground;");
            }
        }

        protected void grvDatos_RowUpdating(object sender, GridViewUpdateEventArgs e)
        {
            string ID = "";
            decimal cantidadOriginal = 0;
            TextBox cantidad;
            string familia = "";
            string subfamilia = "";
            string articulo = "";
            DataRow[] filaEncontrada;
            DataRow[] filaEncontradaTotal;
            decimal porcentaje = 0;
            decimal descuento = 0;
            string tipoFila = "";
            bool hayPorcentaje = false;
            bool hayDescuento = false;
            DataTable dtPendienteDevolver = new DataTable();
            dtPendienteDevolver = (DataTable)Session["dtPendienteDevolver"];
            DataTable dtSimulacion = new DataTable();
            dtSimulacion = (DataTable)Session["dtSimulacion"];
            DataTable dtValoresFicha = new DataTable();
            dtValoresFicha = (DataTable)Session["dtValoresFicha"];

            MENSAJE_ERROR.Visible = false;
            imgWarning.Visible = false;
            lblMensajeError.Visible = false;
            lblMensajeError.Text = "";

            string idioma = Session["idioma"].ToString();
            //string idioma = "";
            //HttpCookie nameCookie = Request.Cookies["idioma"];
            //if (nameCookie != null)
            //    idioma = nameCookie.Value.ToString();

            cantidadOriginal = Convert.ToDecimal(grvDatos.DataKeys[e.RowIndex].Values[1].ToString());
            cantidad = grvDatos.Rows[e.RowIndex].FindControl("txtCantidad") as TextBox;

            ID = grvDatos.DataKeys[e.RowIndex].Values[0].ToString();
            familia = grvDatos.DataKeys[e.RowIndex].Values[2].ToString();
            subfamilia = grvDatos.DataKeys[e.RowIndex].Values[3].ToString();
            articulo = grvDatos.DataKeys[e.RowIndex].Values[4].ToString();
            System.Web.UI.WebControls.GridViewRow fila = grvDatos.Rows[e.RowIndex];
            if (familia != "")
            {
                if (subfamilia != "")
                {
                    if (articulo != "")
                    {
                        tipoFila = "ARTICULO";
                        if (Math.Abs(Convert.ToDouble(cantidad.Text)) > Math.Abs(Convert.ToDouble(cantidadOriginal)) && Convert.ToDouble(cantidad.Text) != 0)
                        {
                            MENSAJE_ERROR.Visible = true;
                            imgWarning.Visible = true;
                            lblMensajeError.Visible = true;
                            lblMensajeError.Text = "La cantidad introducida es mayor a la cantidad original";
                            return;
                        }
                    }
                    else
                        tipoFila = "SUBFAMILIA";
                }
                else
                    tipoFila = "FAMILIA";
            }
            else
                tipoFila = "TODO";


            TextBox porcentajeTexto = grvDatos.Rows[e.RowIndex].FindControl("txtPorcentajeCantidad") as TextBox;
            porcentaje = Convert.ToDecimal(porcentajeTexto.Text);

            TextBox descuentoTexto = grvDatos.Rows[e.RowIndex].FindControl("txtDescuento") as TextBox;
            descuento = Convert.ToDecimal(descuentoTexto.Text);

            filaEncontrada = dtPendienteDevolver.Select("ID = '" + ID + "'");
            foreach (DataRow filaDT in filaEncontrada)
            {
                // Ha cambiado la cantidad
                // Ha cambiado el % de cantidad
                if (Convert.ToDouble(filaDT["PORCENTAJE DEVOLUCION"]) != Convert.ToDouble(porcentaje))
                {
                    if (Convert.ToDecimal(filaDT["CANTIDAD ORIGINAL"]) > 0)
                    {
                        filaDT["CANTIDAD"] = (Convert.ToDecimal(filaDT["CANTIDAD ORIGINAL"]) * porcentaje) / 100;
                        filaDT["PORCENTAJE DEVOLUCION"] = (Math.Round(porcentaje, 2)).ToString("#,##0.00");
                    }
                    hayPorcentaje = true;
                }
                else if (Convert.ToDouble(filaDT["CANTIDAD"]) != Convert.ToDouble(cantidad.Text))
                {
                    filaDT["CANTIDAD"] = cantidad.Text;
                    if (Convert.ToDecimal(filaDT["CANTIDAD ORIGINAL"]) != 0)
                        filaDT["PORCENTAJE DEVOLUCION"] = (Math.Round((Convert.ToDecimal(cantidad.Text) * 100) / Convert.ToDecimal(filaDT["CANTIDAD ORIGINAL"]), 2)).ToString("#,##0.00");
                    else
                        filaDT["PORCENTAJE DEVOLUCION"] = 0;

                    porcentaje = 0;
                    hayPorcentaje = false;
                }

                if (filaDT["PVP"].ToString() != "")
                    filaDT["PVP OBRA"] = (Convert.ToDouble(filaDT["CANTIDAD ORIGINAL"]) - Convert.ToDouble(filaDT["CANTIDAD"])) * Convert.ToDouble(filaDT["PVP"]);

                if (Convert.ToDecimal(filaDT["CANTIDAD ENTREGADA"]) != 0)
                    filaDT["FACTURACION"] = ((Convert.ToDecimal(filaDT["ALQUILER"]) / Convert.ToDecimal(filaDT["CANTIDAD ENTREGADA"])) * (Convert.ToDecimal(filaDT["CANTIDAD ORIGINAL"]) - Convert.ToDecimal(filaDT["CANTIDAD"]))).ToString("#,##0.00");
                else
                    filaDT["FACTURACION"] = 0;

                if (filaDT["PVP"].ToString() != "")
                {
                    if (Convert.ToDecimal(filaDT["CANTIDAD ENTREGADA"]) * Convert.ToDecimal(filaDT["PVP"]) != 0)
                        filaDT["PORCENTAJE"] = ((Convert.ToDecimal(filaDT["PVP OBRA"]) / (Convert.ToDecimal(filaDT["CANTIDAD ENTREGADA"]) * Convert.ToDecimal(filaDT["PVP"]))) * 100).ToString("#,##0.00");
                    else
                        filaDT["PORCENTAJE"] = 0;
                }

                if (filaDT["PVP"].ToString() != "") // && Convert.ToDecimal(filaDT["PVP OBRA"].ToString()) > 0)
                    filaDT["FACTURACION LIQUIDACION"] = (((Convert.ToDouble(filaDT["CANTIDAD ORIGINAL"]) - Convert.ToDouble(filaDT["CANTIDAD"])) * Convert.ToDouble(filaDT["PVP"])) - (((Convert.ToDouble(filaDT["CANTIDAD ORIGINAL"]) - Convert.ToDouble(filaDT["CANTIDAD"])) * Convert.ToDouble(filaDT["PVP"])) * Convert.ToDouble(filaDT["DESCUENTO"]) / 100)).ToString("#,##0.00");
                else
                    filaDT["FACTURACION LIQUIDACION"] = 0;
                // Ha cambiado el descuento
                if (Convert.ToDouble(filaDT["DESCUENTO"]) != Convert.ToDouble(descuento))
                {
                    hayDescuento = true;
                    filaDT["DESCUENTO"] = descuento;
                    if (filaDT["PVP"].ToString() != "")// && Convert.ToDecimal(filaDT["PVP OBRA"].ToString()) > 0)
                        filaDT["FACTURACION LIQUIDACION"] = (((Convert.ToDouble(filaDT["CANTIDAD ORIGINAL"]) - Convert.ToDouble(filaDT["CANTIDAD"])) * Convert.ToDouble(filaDT["PVP"])) - (((Convert.ToDouble(filaDT["CANTIDAD ORIGINAL"]) - Convert.ToDouble(filaDT["CANTIDAD"])) * Convert.ToDouble(filaDT["PVP"])) * Convert.ToDouble(descuento) / 100)).ToString("#,##0.00");
                    else
                        filaDT["FACTURACION LIQUIDACION"] = 0;
                }

                filaDT["COSTE"] = (Convert.ToDecimal(filaDT["CANTIDAD ORIGINAL"]) - Convert.ToDecimal(filaDT["CANTIDAD"])) * Convert.ToDecimal(filaDT["PS"]) * Convert.ToDecimal(filaDT["CORRECION"]);

                filaDT.AcceptChanges();
            }

            // PORCENTAJE CANTIDAD
            if (hayPorcentaje && tipoFila == "TODO")
            {
                filaEncontrada = dtPendienteDevolver.Select("ARTICULO <> ''");
                foreach (DataRow filaDT in filaEncontrada)
                {
                    if (Convert.ToDecimal(filaDT["CANTIDAD ORIGINAL"]) > 0)
                        filaDT["CANTIDAD"] = Math.Ceiling(Convert.ToDecimal(filaDT["CANTIDAD ORIGINAL"]) * porcentaje / 100);
                    if (Convert.ToDecimal(filaDT["CANTIDAD ORIGINAL"]) != 0)
                        filaDT["PORCENTAJE DEVOLUCION"] = (Math.Round(Convert.ToDecimal(filaDT["CANTIDAD"]) * 100 / Convert.ToDecimal(filaDT["CANTIDAD ORIGINAL"]), 2)).ToString("#,##0.00");
                    else
                        filaDT["PORCENTAJE DEVOLUCION"] = 0;
                    filaDT["PVP OBRA"] = (Convert.ToDouble(filaDT["CANTIDAD ORIGINAL"]) - Convert.ToDouble(filaDT["CANTIDAD"])) * Convert.ToDouble(filaDT["PVP"]);
                    //if (Convert.ToDecimal(filaDT["PVP OBRA"].ToString()) > 0)
                    filaDT["FACTURACION LIQUIDACION"] = (((Convert.ToDouble(filaDT["CANTIDAD ORIGINAL"]) - Convert.ToDouble(filaDT["CANTIDAD"])) * Convert.ToDouble(filaDT["PVP"])) - (((Convert.ToDouble(filaDT["CANTIDAD ORIGINAL"]) - Convert.ToDouble(filaDT["CANTIDAD"])) * Convert.ToDouble(filaDT["PVP"])) * Convert.ToDouble(filaDT["DESCUENTO"]) / 100)).ToString("#,##0.00");
                    //else
                    //    filaDT["FACTURACION LIQUIDACION"] = 0;

                    if (Convert.ToDecimal(filaDT["CANTIDAD ENTREGADA"]) != 0)
                        filaDT["FACTURACION"] = ((Convert.ToDecimal(filaDT["ALQUILER"]) / Convert.ToDecimal(filaDT["CANTIDAD ENTREGADA"])) * (Convert.ToDecimal(filaDT["CANTIDAD ORIGINAL"]) - Convert.ToDecimal(filaDT["CANTIDAD"]))).ToString("#,##0.00");
                    else
                        filaDT["FACTURACION"] = 0;

                    if (Convert.ToDecimal(filaDT["CANTIDAD ENTREGADA"]) * Convert.ToDecimal(filaDT["PVP"]) != 0)
                        filaDT["PORCENTAJE"] = ((Convert.ToDecimal(filaDT["PVP OBRA"]) / (Convert.ToDecimal(filaDT["CANTIDAD ENTREGADA"]) * Convert.ToDecimal(filaDT["PVP"]))) * 100).ToString("#,##0.00");
                    else
                        filaDT["PORCENTAJE"] = 0;

                    filaDT["COSTE"] = (Convert.ToDecimal(filaDT["CANTIDAD ORIGINAL"]) - Convert.ToDecimal(filaDT["CANTIDAD"])) * Convert.ToDecimal(filaDT["PS"]) * Convert.ToDecimal(filaDT["CORRECION"]);

                    filaDT.AcceptChanges();
                }
            }

            if (hayPorcentaje && tipoFila == "FAMILIA")
            {
                filaEncontrada = dtPendienteDevolver.Select("FAMILIA = '" + familia + "' AND ARTICULO <> ''");
                foreach (DataRow filaDT in filaEncontrada)
                {
                    if (Convert.ToDecimal(filaDT["CANTIDAD ORIGINAL"]) > 0)
                        filaDT["CANTIDAD"] = Math.Ceiling(Convert.ToDecimal(filaDT["CANTIDAD ORIGINAL"]) * porcentaje / 100);
                    if (Convert.ToDecimal(filaDT["CANTIDAD ORIGINAL"]) != 0)
                        filaDT["PORCENTAJE DEVOLUCION"] = (Math.Round(Convert.ToDecimal(filaDT["CANTIDAD"]) * 100 / Convert.ToDecimal(filaDT["CANTIDAD ORIGINAL"]), 2)).ToString("#,##0.00");
                    else
                        filaDT["PORCENTAJE DEVOLUCION"] = 0;
                    filaDT["PVP OBRA"] = (Convert.ToDouble(filaDT["CANTIDAD ORIGINAL"]) - Convert.ToDouble(filaDT["CANTIDAD"])) * Convert.ToDouble(filaDT["PVP"]);
                    //if (Convert.ToDecimal(filaDT["PVP OBRA"].ToString()) > 0)
                    filaDT["FACTURACION LIQUIDACION"] = (((Convert.ToDouble(filaDT["CANTIDAD ORIGINAL"]) - Convert.ToDouble(filaDT["CANTIDAD"])) * Convert.ToDouble(filaDT["PVP"])) - (((Convert.ToDouble(filaDT["CANTIDAD ORIGINAL"]) - Convert.ToDouble(filaDT["CANTIDAD"])) * Convert.ToDouble(filaDT["PVP"])) * Convert.ToDouble(filaDT["DESCUENTO"]) / 100)).ToString("#,##0.00");
                    //else
                    //    filaDT["FACTURACION LIQUIDACION"] = 0;

                    if (Convert.ToDecimal(filaDT["CANTIDAD ENTREGADA"]) != 0)
                        filaDT["FACTURACION"] = ((Convert.ToDecimal(filaDT["ALQUILER"]) / Convert.ToDecimal(filaDT["CANTIDAD ENTREGADA"])) * (Convert.ToDecimal(filaDT["CANTIDAD ORIGINAL"]) - Convert.ToDecimal(filaDT["CANTIDAD"]))).ToString("#,##0.00");
                    else
                        filaDT["FACTURACION"] = 0;

                    if (Convert.ToDecimal(filaDT["CANTIDAD ENTREGADA"]) * Convert.ToDecimal(filaDT["PVP"]) != 0)
                        filaDT["PORCENTAJE"] = ((Convert.ToDecimal(filaDT["PVP OBRA"]) / (Convert.ToDecimal(filaDT["CANTIDAD ENTREGADA"]) * Convert.ToDecimal(filaDT["PVP"]))) * 100).ToString("#,##0.00");
                    else
                        filaDT["PORCENTAJE"] = 0;

                    filaDT["COSTE"] = (Convert.ToDecimal(filaDT["CANTIDAD ORIGINAL"]) - Convert.ToDecimal(filaDT["CANTIDAD"])) * Convert.ToDecimal(filaDT["PS"]) * Convert.ToDecimal(filaDT["CORRECION"]);

                    filaDT.AcceptChanges();
                }
            }

            if (hayPorcentaje && tipoFila == "SUBFAMILIA")
            {
                filaEncontrada = dtPendienteDevolver.Select("FAMILIA = '" + familia + "' AND SUBFAMILIA = '" + subfamilia + "' AND ARTICULO <> ''");
                foreach (DataRow filaDT in filaEncontrada)
                {
                    if (Convert.ToDecimal(filaDT["CANTIDAD ORIGINAL"]) > 0)
                        filaDT["CANTIDAD"] = Math.Ceiling(Convert.ToDecimal(filaDT["CANTIDAD ORIGINAL"]) * porcentaje / 100);
                    if (Convert.ToDecimal(filaDT["CANTIDAD ORIGINAL"]) != 0)
                        filaDT["PORCENTAJE DEVOLUCION"] = (Math.Round(Convert.ToDecimal(filaDT["CANTIDAD"]) * 100 / Convert.ToDecimal(filaDT["CANTIDAD ORIGINAL"]), 2)).ToString("#,##0.00");
                    else
                        filaDT["PORCENTAJE DEVOLUCION"] = 0;
                    filaDT["PVP OBRA"] = (Convert.ToDouble(filaDT["CANTIDAD ORIGINAL"]) - Convert.ToDouble(filaDT["CANTIDAD"])) * Convert.ToDouble(filaDT["PVP"]);
                    //if (Convert.ToDecimal(filaDT["PVP OBRA"].ToString()) > 0)
                    filaDT["FACTURACION LIQUIDACION"] = (((Convert.ToDouble(filaDT["CANTIDAD ORIGINAL"]) - Convert.ToDouble(filaDT["CANTIDAD"])) * Convert.ToDouble(filaDT["PVP"])) - (((Convert.ToDouble(filaDT["CANTIDAD ORIGINAL"]) - Convert.ToDouble(filaDT["CANTIDAD"])) * Convert.ToDouble(filaDT["PVP"])) * Convert.ToDouble(filaDT["DESCUENTO"]) / 100)).ToString("#,##0.00");
                    //else
                    //    filaDT["FACTURACION LIQUIDACION"] = 0;

                    if (Convert.ToDecimal(filaDT["CANTIDAD ENTREGADA"]) != 0)
                        filaDT["FACTURACION"] = ((Convert.ToDecimal(filaDT["ALQUILER"]) / Convert.ToDecimal(filaDT["CANTIDAD ENTREGADA"])) * (Convert.ToDecimal(filaDT["CANTIDAD ORIGINAL"]) - Convert.ToDecimal(filaDT["CANTIDAD"]))).ToString("#,##0.00");
                    else
                        filaDT["FACTURACION"] = 0;

                    if (Convert.ToDecimal(filaDT["CANTIDAD ENTREGADA"]) * Convert.ToDecimal(filaDT["PVP"]) != 0)
                        filaDT["PORCENTAJE"] = ((Convert.ToDecimal(filaDT["PVP OBRA"]) / (Convert.ToDecimal(filaDT["CANTIDAD ENTREGADA"]) * Convert.ToDecimal(filaDT["PVP"]))) * 100).ToString("#,##0.00");
                    else
                        filaDT["PORCENTAJE"] = 0;

                    filaDT["COSTE"] = (Convert.ToDecimal(filaDT["CANTIDAD ORIGINAL"]) - Convert.ToDecimal(filaDT["CANTIDAD"])) * Convert.ToDecimal(filaDT["PS"]) * Convert.ToDecimal(filaDT["CORRECION"]);

                    filaDT.AcceptChanges();
                }
            }

            if (tipoFila != "TODO")
            {
                filaEncontradaTotal = dtPendienteDevolver.Select("FAMILIA = '" + familia + "' AND SUBFAMILIA <> '' AND ARTICULO = ''");
                foreach (DataRow filaTotal in filaEncontradaTotal)
                {
                    // TOTAL SUBFAMILIA
                    string strSubfamilia = filaTotal["SUBFAMILIA"].ToString();
                    decimal totalSubfamilia = dtPendienteDevolver.AsEnumerable()
                        .Where(y => y.Field<string>("FAMILIA") == familia && y.Field<string>("SUBFAMILIA") == strSubfamilia && y.Field<string>("ARTICULO") != "")
                        .Sum(x => Convert.ToDecimal(x.Field<decimal>("CANTIDAD")));

                    filaEncontrada = dtPendienteDevolver.Select("FAMILIA = '" + familia + "' AND SUBFAMILIA = '" + strSubfamilia + "' AND ARTICULO = ''");
                    foreach (DataRow filaDT in filaEncontrada)
                    {
                        filaDT["CANTIDAD"] = totalSubfamilia;
                        if (Convert.ToDecimal(filaDT["CANTIDAD ORIGINAL"]) != 0)
                            filaDT["PORCENTAJE DEVOLUCION"] = (Math.Round((totalSubfamilia * 100) / Convert.ToDecimal(filaDT["CANTIDAD ORIGINAL"]), 2)).ToString("#,##0.00");
                        else
                            filaDT["PORCENTAJE DEVOLUCION"] = 0;

                        if (Convert.ToDecimal(filaDT["CANTIDAD ENTREGADA"]) != 0)
                            filaDT["FACTURACION"] = ((Convert.ToDecimal(filaDT["ALQUILER"]) / Convert.ToDecimal(filaDT["CANTIDAD ENTREGADA"])) * (Convert.ToDecimal(filaDT["CANTIDAD ORIGINAL"]) - Convert.ToDecimal(filaDT["CANTIDAD"]))).ToString("#,##0.00");
                        else
                            filaDT["FACTURACION"] = 0;

                        filaDT.AcceptChanges();
                    }
                }

                // TOTAL FAMILIA
                decimal totalFamilia = dtPendienteDevolver.AsEnumerable()
                       .Where(y => y.Field<string>("FAMILIA") == familia && y.Field<string>("SUBFAMILIA") != "" && y.Field<string>("ARTICULO") == "")
                       .Sum(x => Convert.ToDecimal(x.Field<decimal>("CANTIDAD")));

                filaEncontrada = dtPendienteDevolver.Select("FAMILIA = '" + familia + "' AND SUBFAMILIA = '' AND ARTICULO = ''");
                foreach (DataRow filaDT in filaEncontrada)
                {
                    filaDT["CANTIDAD"] = totalFamilia;
                    if (Convert.ToDecimal(filaDT["CANTIDAD ORIGINAL"]) != 0)
                        filaDT["PORCENTAJE DEVOLUCION"] = (Math.Round((totalFamilia * 100) / Convert.ToDecimal(filaDT["CANTIDAD ORIGINAL"]), 2)).ToString("#,##0.00");
                    else
                        filaDT["PORCENTAJE DEVOLUCION"] = 0;

                    if (Convert.ToDecimal(filaDT["CANTIDAD ENTREGADA"]) != 0)
                        filaDT["FACTURACION"] = ((Convert.ToDecimal(filaDT["ALQUILER"]) / Convert.ToDecimal(filaDT["CANTIDAD ENTREGADA"])) * (Convert.ToDecimal(filaDT["CANTIDAD ORIGINAL"]) - Convert.ToDecimal(filaDT["CANTIDAD"]))).ToString("#,##0.00");
                    else
                        filaDT["FACTURACION"] = 0;

                    filaDT.AcceptChanges();
                }
            }
            else
            {
                filaEncontradaTotal = dtPendienteDevolver.Select("SUBFAMILIA <> ''");
                foreach (DataRow filaTotal in filaEncontradaTotal)
                {
                    // TOTAL SUBFAMILIA
                    string strFamilia = filaTotal["FAMILIA"].ToString();
                    string strSubfamilia = filaTotal["SUBFAMILIA"].ToString();
                    decimal totalSubfamilia = dtPendienteDevolver.AsEnumerable()
                            .Where(y => y.Field<string>("FAMILIA") == strFamilia && y.Field<string>("SUBFAMILIA") == strSubfamilia && y.Field<string>("ARTICULO") != "")
                            .Sum(x => Convert.ToDecimal(x.Field<decimal>("CANTIDAD")));

                    filaEncontrada = dtPendienteDevolver.Select("FAMILIA = '" + strFamilia + "' AND SUBFAMILIA = '" + strSubfamilia + "' AND ARTICULO = ''");
                    foreach (DataRow filaDT in filaEncontrada)
                    {
                        filaDT["CANTIDAD"] = totalSubfamilia;
                        if (Convert.ToDecimal(filaDT["CANTIDAD ORIGINAL"]) != 0)
                            filaDT["PORCENTAJE DEVOLUCION"] = (Math.Round((totalSubfamilia * 100) / Convert.ToDecimal(filaDT["CANTIDAD ORIGINAL"]), 2)).ToString("#,##0.00");
                        else
                            filaDT["PORCENTAJE DEVOLUCION"] = 0;

                        if (Convert.ToDecimal(filaDT["CANTIDAD ENTREGADA"]) != 0)
                            filaDT["FACTURACION"] = ((Convert.ToDecimal(filaDT["ALQUILER"]) / Convert.ToDecimal(filaDT["CANTIDAD ENTREGADA"])) * (Convert.ToDecimal(filaDT["CANTIDAD ORIGINAL"]) - Convert.ToDecimal(filaDT["CANTIDAD"]))).ToString("#,##0.00");
                        else
                            filaDT["FACTURACION"] = 0;

                        filaDT.AcceptChanges();
                    }

                    // TOTAL FAMILIA
                    decimal totalFamilia = dtPendienteDevolver.AsEnumerable()
                           .Where(y => y.Field<string>("FAMILIA") == strFamilia && y.Field<string>("SUBFAMILIA") != "" && y.Field<string>("ARTICULO") == "")
                           .Sum(x => Convert.ToDecimal(x.Field<decimal>("CANTIDAD")));

                    filaEncontrada = dtPendienteDevolver.Select("FAMILIA = '" + familia + "' AND SUBFAMILIA = '' AND ARTICULO = ''");
                    foreach (DataRow filaDT in filaEncontrada)
                    {
                        filaDT["CANTIDAD"] = totalFamilia;
                        if (Convert.ToDecimal(filaDT["CANTIDAD ORIGINAL"]) != 0)
                            filaDT["PORCENTAJE DEVOLUCION"] = (Math.Round((totalFamilia * 100) / Convert.ToDecimal(filaDT["CANTIDAD ORIGINAL"]), 2)).ToString("#,##0.00");
                        else
                            filaDT["PORCENTAJE DEVOLUCION"] = 0;

                        if (Convert.ToDecimal(filaDT["CANTIDAD ENTREGADA"]) != 0)
                            filaDT["FACTURACION"] = ((Convert.ToDecimal(filaDT["ALQUILER"]) / Convert.ToDecimal(filaDT["CANTIDAD ENTREGADA"])) * (Convert.ToDecimal(filaDT["CANTIDAD ORIGINAL"]) - Convert.ToDecimal(filaDT["CANTIDAD"]))).ToString("#,##0.00");
                        else
                            filaDT["FACTURACION"] = 0;

                        filaDT.AcceptChanges();
                    }
                }
            }

            // TOTAL
            decimal total = dtPendienteDevolver.AsEnumerable()
                    .Where(y => y.Field<string>("ARTICULO") != "")
                    .Sum(x => Convert.ToDecimal(x.Field<decimal>("CANTIDAD")));

            filaEncontrada = dtPendienteDevolver.Select("FAMILIA = '' AND SUBFAMILIA = '' AND ARTICULO = ''");
            foreach (DataRow filaDT in filaEncontrada)
            {
                filaDT["CANTIDAD"] = total;
                if (Convert.ToDecimal(filaDT["CANTIDAD ORIGINAL"]) != 0)
                    filaDT["PORCENTAJE DEVOLUCION"] = (Math.Round((total * 100) / Convert.ToDecimal(filaDT["CANTIDAD ORIGINAL"]), 2)).ToString("#,##0.00");
                else
                    filaDT["PORCENTAJE DEVOLUCION"] = 0;

                if (Convert.ToDecimal(filaDT["CANTIDAD ENTREGADA"]) != 0)
                    filaDT["FACTURACION"] = ((Convert.ToDecimal(filaDT["ALQUILER"]) / Convert.ToDecimal(filaDT["CANTIDAD ENTREGADA"])) * (Convert.ToDecimal(filaDT["CANTIDAD ORIGINAL"]) - Convert.ToDecimal(filaDT["CANTIDAD"]))).ToString("#,##0.00");
                else
                    filaDT["FACTURACION"] = 0;

                filaDT["DESCUENTO"] = descuento;

                filaDT.AcceptChanges();
            }

            calcularSubtotalesSimulacion(true);

            // DESCUENTO
            if (hayDescuento && tipoFila == "TODO")
            {
                filaEncontrada = dtPendienteDevolver.Select("ARTICULO <> ''");
                foreach (DataRow filaDT in filaEncontrada)
                {
                    filaDT["DESCUENTO"] = descuento;
                    //if (Convert.ToDecimal(filaDT["PVP OBRA"].ToString()) > 0)
                    filaDT["FACTURACION LIQUIDACION"] = (((Convert.ToDouble(filaDT["CANTIDAD ORIGINAL"]) - Convert.ToDouble(filaDT["CANTIDAD"])) * Convert.ToDouble(filaDT["PVP"])) - (((Convert.ToDouble(filaDT["CANTIDAD ORIGINAL"]) - Convert.ToDouble(filaDT["CANTIDAD"])) * Convert.ToDouble(filaDT["PVP"])) * Convert.ToDouble(descuento) / 100)).ToString("#,##0.00");
                    //else
                    //    filaDT["FACTURACION LIQUIDACION"] = 0;
                    filaDT.AcceptChanges();
                }
            }

            if (hayDescuento && tipoFila == "FAMILIA")
            {
                filaEncontrada = dtPendienteDevolver.Select("FAMILIA = '" + familia + "' AND ARTICULO <> ''");
                foreach (DataRow filaDT in filaEncontrada)
                {
                    filaDT["DESCUENTO"] = descuento;
                    //if (Convert.ToDecimal(filaDT["PVP OBRA"].ToString()) > 0)
                    filaDT["FACTURACION LIQUIDACION"] = (((Convert.ToDouble(filaDT["CANTIDAD ORIGINAL"]) - Convert.ToDouble(filaDT["CANTIDAD"])) * Convert.ToDouble(filaDT["PVP"])) - (((Convert.ToDouble(filaDT["CANTIDAD ORIGINAL"]) - Convert.ToDouble(filaDT["CANTIDAD"])) * Convert.ToDouble(filaDT["PVP"])) * Convert.ToDouble(descuento) / 100)).ToString("#,##0.00");
                    //else
                    //    filaDT["FACTURACION LIQUIDACION"] = 0;
                    filaDT.AcceptChanges();
                }
            }

            if (hayDescuento && tipoFila == "SUBFAMILIA")
            {
                filaEncontrada = dtPendienteDevolver.Select("FAMILIA = '" + familia + "' AND SUBFAMILIA = '" + subfamilia + "' AND ARTICULO <> ''");
                foreach (DataRow filaDT in filaEncontrada)
                {
                    filaDT["DESCUENTO"] = descuento;
                    //if (Convert.ToDecimal(filaDT["PVP OBRA"].ToString()) > 0)
                    filaDT["FACTURACION LIQUIDACION"] = (((Convert.ToDouble(filaDT["CANTIDAD ORIGINAL"]) - Convert.ToDouble(filaDT["CANTIDAD"])) * Convert.ToDouble(filaDT["PVP"])) - (((Convert.ToDouble(filaDT["CANTIDAD ORIGINAL"]) - Convert.ToDouble(filaDT["CANTIDAD"])) * Convert.ToDouble(filaDT["PVP"])) * Convert.ToDouble(descuento) / 100)).ToString("#,##0.00");
                    //else
                    //    filaDT["FACTURACION LIQUIDACION"] = 0;
                    filaDT.AcceptChanges();
                }
            }

            if (tipoFila != "TODO")
            {
                //if (tipoFila == "SUBFAMILIA")
                //{
                // TOTAL SUBFAMILIA
                decimal totalSubfamilia = dtPendienteDevolver.AsEnumerable()
                    .Where(y => y.Field<string>("FAMILIA") == familia && y.Field<string>("SUBFAMILIA") == subfamilia && y.Field<string>("ARTICULO") != "")
                    .Sum(x => Convert.ToDecimal(x.Field<decimal>("FACTURACION LIQUIDACION")));

                filaEncontrada = dtPendienteDevolver.Select("FAMILIA = '" + familia + "' AND SUBFAMILIA = '" + subfamilia + "' AND ARTICULO = ''");
                foreach (DataRow filaDT in filaEncontrada)
                {
                    filaDT["FACTURACION LIQUIDACION"] = totalSubfamilia.ToString("#,##0.00");

                    //if (Convert.ToDecimal(filaDT["PVP OBRA"]) > 0)
                    if (Convert.ToDecimal(filaDT["PVP OBRA"]) != 0)
                        filaDT["DESCUENTO"] = ((Convert.ToDecimal(filaDT["PVP OBRA"]) - Convert.ToDecimal(filaDT["FACTURACION LIQUIDACION"])) * 100) / Convert.ToDecimal(filaDT["PVP OBRA"]);
                    else
                        filaDT["DESCUENTO"] = 0;

                    filaDT.AcceptChanges();
                }
                //}

                // TOTAL FAMILIA
                decimal totalFamilia = dtPendienteDevolver.AsEnumerable()
                       .Where(y => y.Field<string>("FAMILIA") == familia && y.Field<string>("SUBFAMILIA") == "" && y.Field<string>("ARTICULO") == "")
                       .Sum(x => Convert.ToDecimal(x.Field<decimal>("FACTURACION LIQUIDACION")));

                filaEncontrada = dtPendienteDevolver.Select("FAMILIA = '" + familia + "' AND SUBFAMILIA = '' AND ARTICULO = ''");
                foreach (DataRow filaDT in filaEncontrada)
                {
                    filaDT["FACTURACION LIQUIDACION"] = totalFamilia.ToString("#,##0.00");

                    //if (Convert.ToDecimal(filaDT["PVP OBRA"]) > 0)
                    if (Convert.ToDecimal(filaDT["PVP OBRA"]) != 0)
                        filaDT["DESCUENTO"] = ((Convert.ToDecimal(filaDT["PVP OBRA"]) - Convert.ToDecimal(filaDT["FACTURACION LIQUIDACION"])) * 100) / Convert.ToDecimal(filaDT["PVP OBRA"]);
                    else
                        filaDT["DESCUENTO"] = 0;
                    filaDT.AcceptChanges();
                }
            }
            else
            {
                filaEncontradaTotal = dtPendienteDevolver.Select("SUBFAMILIA <> ''");
                foreach (DataRow filaTotal in filaEncontradaTotal)
                {
                    // TOTAL SUBFAMILIA
                    familia = filaTotal["FAMILIA"].ToString();
                    subfamilia = filaTotal["SUBFAMILIA"].ToString();
                    decimal totalSubfamilia = dtPendienteDevolver.AsEnumerable()
                            .Where(y => y.Field<string>("FAMILIA") == familia && y.Field<string>("SUBFAMILIA") == subfamilia && y.Field<string>("ARTICULO") != "")
                            .Sum(x => Convert.ToDecimal(x.Field<decimal>("FACTURACION LIQUIDACION")));

                    filaEncontrada = dtPendienteDevolver.Select("FAMILIA = '" + familia + "' AND SUBFAMILIA = '" + subfamilia + "' AND ARTICULO = ''");
                    foreach (DataRow filaDT in filaEncontrada)
                    {
                        filaDT["FACTURACION LIQUIDACION"] = totalSubfamilia.ToString("#,##0.00");

                        //if (Convert.ToDecimal(filaDT["PVP OBRA"]) > 0)
                        if (Convert.ToDecimal(filaDT["PVP OBRA"]) != 0)
                            filaDT["DESCUENTO"] = ((Convert.ToDecimal(filaDT["PVP OBRA"]) - Convert.ToDecimal(filaDT["FACTURACION LIQUIDACION"])) * 100) / Convert.ToDecimal(filaDT["PVP OBRA"]);
                        else
                            filaDT["DESCUENTO"] = 0;
                        filaDT.AcceptChanges();
                    }
                }

                filaEncontradaTotal = dtPendienteDevolver.Select("FAMILIA <> '' AND SUBFAMILIA = '' AND ARTICULO = ''");
                foreach (DataRow filaTotal in filaEncontradaTotal)
                {
                    familia = filaTotal["FAMILIA"].ToString();
                    // TOTAL FAMILIA
                    decimal totalFamilia = dtPendienteDevolver.AsEnumerable()
                           .Where(y => y.Field<string>("FAMILIA") == familia && y.Field<string>("SUBFAMILIA") != "" && y.Field<string>("ARTICULO") != "")
                           .Sum(x => Convert.ToDecimal(x.Field<decimal>("FACTURACION LIQUIDACION")));

                    filaEncontrada = dtPendienteDevolver.Select("FAMILIA = '" + familia + "' AND SUBFAMILIA = '' AND ARTICULO = ''");
                    foreach (DataRow filaDT in filaEncontrada)
                    {
                        filaDT["FACTURACION LIQUIDACION"] = totalFamilia.ToString("#,##0.00");

                        //if (Convert.ToDecimal(filaDT["PVP OBRA"]) > 0)
                        if (Convert.ToDecimal(filaDT["PVP OBRA"]) != 0)
                            filaDT["DESCUENTO"] = ((Convert.ToDecimal(filaDT["PVP OBRA"]) - Convert.ToDecimal(filaDT["FACTURACION LIQUIDACION"])) * 100) / Convert.ToDecimal(filaDT["PVP OBRA"]);
                        else
                            filaDT["DESCUENTO"] = 0;

                        filaDT.AcceptChanges();
                    }
                }
            }

            // TOTAL
            decimal totalFacturacion = dtPendienteDevolver.AsEnumerable()
                    .Where(y => y.Field<string>("ARTICULO") != "")
                    .Sum(x => Convert.ToDecimal(x.Field<decimal>("FACTURACION LIQUIDACION")));

            filaEncontrada = dtPendienteDevolver.Select("FAMILIA = '' AND SUBFAMILIA = '' AND ARTICULO = ''");
            foreach (DataRow filaDT in filaEncontrada)
            {
                filaDT["FACTURACION LIQUIDACION"] = totalFacturacion.ToString("#,##0.00");

                //if (Convert.ToDecimal(filaDT["PVP OBRA"]) > 0)
                if (Convert.ToDecimal(filaDT["PVP OBRA"]) != 0)
                    filaDT["DESCUENTO"] = ((Convert.ToDecimal(filaDT["PVP OBRA"]) - Convert.ToDecimal(filaDT["FACTURACION LIQUIDACION"])) * 100) / Convert.ToDecimal(filaDT["PVP OBRA"]);
                else
                    filaDT["DESCUENTO"] = 0;
                filaDT.AcceptChanges();
            }

            calcularSubtotalesSimulacion(false);

            // MB tabla simulación
            // MB SIN NEGATIVOS
            decimal margen = 0;
            decimal totalLiquidacion = 0;
            decimal totalCoste = 0;

            totalLiquidacion = dtPendienteDevolver.AsEnumerable()
                         .Where(y => y.Field<string>("ARTICULO") != "" && y.Field<decimal>("PVP OBRA") >= 0)
                         .Sum(x => Convert.ToDecimal(x.Field<decimal>("FACTURACION LIQUIDACION")));

            totalCoste = dtPendienteDevolver.AsEnumerable()
                         .Where(y => y.Field<string>("ARTICULO") != "" && y.Field<decimal>("PVP OBRA") >= 0)
                         //.Sum(x => Convert.ToDecimal(x.Field<decimal>("PS")) * Convert.ToDecimal(x.Field<decimal>("CORRECION")) + (Convert.ToDecimal(x.Field<decimal>("CANTIDAD ORIGINAL")) - Convert.ToDecimal(x.Field<decimal>("CANTIDAD"))));
                         .Sum(x => Convert.ToDecimal(x.Field<decimal>("COSTE")));

            if (totalLiquidacion != 0)
                margen = ((totalLiquidacion - totalCoste) / totalLiquidacion);

            grvMB.Rows[1].Cells[1].Text = margen.ToString("##0.00 %");

            filaEncontrada = dtIdiomas.Select("ETQ_Control = 'txtMBLiquidacion'");
            foreach (DataRow filaValor in filaEncontrada)
            {
                if (idioma == "ESPAÑOL")
                    grvMB.Rows[1].Cells[0].Text = Convert.ToString(filaValor["ETQ_TextoCastellano"]);
                if (idioma == "CATALAN")
                    grvMB.Rows[1].Cells[0].Text = Convert.ToString(filaValor["ETQ_TextoCatalan"]);
                if (idioma == "INGLES")
                    grvMB.Rows[1].Cells[0].Text = Convert.ToString(filaValor["ETQ_TextoIngles"]);
            }

            // MB CON NEGATIVOS
            margen = 0;
            totalLiquidacion = 0;
            totalCoste = 0;

            totalLiquidacion = dtPendienteDevolver.AsEnumerable()
                        .Where(y => y.Field<string>("ARTICULO") != "")
                        .Sum(x => Convert.ToDecimal(x.Field<decimal>("FACTURACION LIQUIDACION")));

            totalCoste = dtPendienteDevolver.AsEnumerable()
                         .Where(y => y.Field<string>("ARTICULO") != "")
                         //.Sum(x => Convert.ToDecimal(x.Field<decimal>("PS")) * Convert.ToDecimal(x.Field<decimal>("CORRECION")) + (Convert.ToDecimal(x.Field<decimal>("CANTIDAD ORIGINAL")) - Convert.ToDecimal(x.Field<decimal>("CANTIDAD"))));
                         .Sum(x => Convert.ToDecimal(x.Field<decimal>("COSTE")));

            if (totalLiquidacion != 0)
                margen = ((totalLiquidacion - totalCoste) / totalLiquidacion);

            grvMB.Rows[0].Cells[1].Text = margen.ToString("##0.00 %");

            filaEncontrada = dtIdiomas.Select("ETQ_Control = 'txtMBLiquidacionConNegativos'");
            foreach (DataRow filaValor in filaEncontrada)
            {
                if (idioma == "ESPAÑOL")
                    grvMB.Rows[0].Cells[0].Text = Convert.ToString(filaValor["ETQ_TextoCastellano"]);
                if (idioma == "CATALAN")
                    grvMB.Rows[0].Cells[0].Text = Convert.ToString(filaValor["ETQ_TextoCatalan"]);
                if (idioma == "INGLES")
                    grvMB.Rows[0].Cells[0].Text = Convert.ToString(filaValor["ETQ_TextoIngles"]);
            }

            grvSimulacion.EditIndex = -1;
            grvSimulacion.DataSource = null;
            grvSimulacion.DataSource = dtSimulacion;
            grvSimulacion.DataBind();

            grvDatos.EditIndex = -1;
            grvDatos.DataSource = null;
            DataView dvPendientes;
            dvPendientes = dtPendienteDevolver.Select("([CANTIDAD ORIGINAL] <> 0  OR [CONCEPTO COMPLETO] = 'TOTAL') AND SUMAR = 1").CopyToDataTable().DefaultView;
            dvPendientes.Sort = "FAMILIA ASC, SUBFAMILIA ASC, ARTICULO ASC";
            grvDatos.DataSource = dvPendientes.ToTable();
            //grvDatos.DataSource = dtPendienteDevolver;
            grvDatos.DataBind();

            pintarArbolNUEVO(ref dtValoresFicha, false, true, true, true);

            btnSimular.Enabled = true;
            btnSimular.CssClass = "btn btn-danger";

            grvSimulacion.DataSource = dtSimulacion;
            grvSimulacion.DataBind();

            Session["dtSimulacion"] = dtSimulacion;
            Session["dtPendienteDevolver"] = dtPendienteDevolver;
        }

