        private void validarUsuario()
        {
            string strConexion;
            SqlConnection conexion;
            SqlCommand comando;

            try
            {
                bool elegirVersion = false;
                string usuario = Session["UsuarioRed"].ToString();

                strConexion = funcionalidades.recuperarTexto(ConfigurationManager.ConnectionStrings["SQL_ROP"].ToString());
                conexion = new SqlConnection(strConexion);
                conexion.Open();
                comando = conexion.CreateCommand();
                comando.CommandText = "sp_ROP_ConfiguracionUsuarioConsulta";
                comando.CommandTimeout = 60;
                comando.CommandType = CommandType.StoredProcedure;
                comando.Parameters.Clear();
                SqlParameter parametroUsuario = new SqlParameter("@usuario", SqlDbType.NVarChar, 100);
                parametroUsuario.Value = usuario;
                comando.Parameters.Add(parametroUsuario);
                if (Session["tipoEnviado"].ToString() != "")
                    comando.Parameters.AddWithValue("@Acceso", "AXAPTA");
                else
                    comando.Parameters.AddWithValue("@Acceso", "WEB");
                comando.Parameters.AddWithValue("@Entorno", Environment.ExpandEnvironmentVariables(ConfigurationManager.AppSettings["TipoVersion"]).ToUpper());
                comando.Parameters.AddWithValue("@TipoCalculo", Session["Concepto"].ToString());
                comando.Parameters.AddWithValue("@Empresa", Session["Empresa"].ToString());
                comando.Parameters.AddWithValue("@Numero", Session["Numero"].ToString());
                comando.Parameters.AddWithValue("@incluir", 0);
                comando.Parameters.AddWithValue("@usuarioAXAPTA", Session["usuarioAXAPTA"].ToString());
                SqlDataReader dr = comando.ExecuteReader();
                if (dr.HasRows)
                {
                    dr.Read();
                    elegirVersion = dr.GetBoolean(6);
                    Session["UsuarioAdministrador"] = true;
                }
                else
                    elegirVersion = false;
                dr.Close();
                comando.Dispose();
                conexion.Close();
                conexion.Dispose();

                if (elegirVersion)
                {
                    lblVersion.Visible = true;
                    cmbVersion.Visible = true;
                    rellenarCombosVersion();
                }
                else
                {
                    lblVersion.Visible = false;
                    cmbVersion.Visible = false;
                }
            }
            catch (Exception ex)
            {
                mostrarMensaje("Validar usuario // " + ex.Message);
            }
        }

        private void rellenarCombosVersion()
        {
            string strConexion;
            SqlConnection conexion;
            SqlCommand comando;

            try
            {
                string versionActual = "";

                cmbVersion.Items.Clear();
                cmbVersion.Items.Add(new System.Web.UI.WebControls.ListItem { Text = "", Value = "-1" });

                strConexion = funcionalidades.recuperarTexto(ConfigurationManager.ConnectionStrings["SQL_ROP"].ToString());
                conexion = new SqlConnection(strConexion);
                conexion.Open();
                comando = conexion.CreateCommand();
                comando.CommandText = "sp_ROP_ConfiguracionGeneralVersionesConsulta";
                comando.CommandTimeout = 60;
                comando.CommandType = CommandType.StoredProcedure;
                comando.Parameters.Clear();
                SqlDataReader dr = comando.ExecuteReader();
                if (dr.HasRows)
                {
                    while (dr.Read())
                    {
                        cmbVersion.Items.Add(new System.Web.UI.WebControls.ListItem { Text = dr.GetString(1), Value = dr.GetInt32(0).ToString() });
                        if (dr.GetBoolean(2))
                            versionActual = dr.GetString(1).ToString();
                    }
                }
                comando.Dispose();
                conexion.Close();
                conexion.Dispose();
            }
            catch (Exception ex)
            {
                mostrarMensaje("Rellenar combo versión // " + ex.Message);
            }
        }

