                    if (idioma == "CATALAN")
                        btnDesplegar.Value = Convert.ToString(filaValor["ETQ_TextoCatalan"]);
                    if (idioma == "INGLES")
                        btnDesplegar.Value = Convert.ToString(filaValor["ETQ_TextoIngles"]);
                }

                filaEncontrada = dtIdiomas.Select("ETQ_Control = 'btnContraer'");
                foreach (DataRow filaValor in filaEncontrada)
                {
                    if (idioma == "ESPAÑOL")
                        btnContraer.Value = Convert.ToString(filaValor["ETQ_TextoCastellano"]);
                    if (idioma == "CATALAN")
                        btnContraer.Value = Convert.ToString(filaValor["ETQ_TextoCatalan"]);
                    if (idioma == "INGLES")
                        btnContraer.Value = Convert.ToString(filaValor["ETQ_TextoIngles"]);
                }

                filaEncontrada = dtIdiomas.Select("ETQ_Control = 'gridConcepto'");
                foreach (DataRow filaValor in filaEncontrada)
                {
                    if (idioma == "ESPAÑOL")
                        tituloConcepto = Convert.ToString(filaValor["ETQ_TextoCastellano"]);
                    if (idioma == "CATALAN")
                        tituloConcepto = Convert.ToString(filaValor["ETQ_TextoCatalan"]);
                    if (idioma == "INGLES")
                        tituloConcepto = Convert.ToString(filaValor["ETQ_TextoIngles"]);
                }

                filaEncontrada = dtIdiomas.Select("ETQ_Control = 'gridImporte'");
                foreach (DataRow filaValor in filaEncontrada)
                {
                    if (idioma == "ESPAÑOL")
                        tituloImporte = Convert.ToString(filaValor["ETQ_TextoCastellano"]);
                    if (idioma == "CATALAN")
                        tituloImporte = Convert.ToString(filaValor["ETQ_TextoCatalan"]);
                    if (idioma == "INGLES")
                        tituloImporte = Convert.ToString(filaValor["ETQ_TextoIngles"]);
                }

                filaEncontrada = dtIdiomas.Select("ETQ_Control = 'gridImportePrevisto'");
                foreach (DataRow filaValor in filaEncontrada)
                {
                    if (idioma == "ESPAÑOL")
                        tituloImportePrevisto = Convert.ToString(filaValor["ETQ_TextoCastellano"]);
                    if (idioma == "CATALAN")
                        tituloImportePrevisto = Convert.ToString(filaValor["ETQ_TextoCatalan"]);
                    if (idioma == "INGLES")
                        tituloImportePrevisto = Convert.ToString(filaValor["ETQ_TextoIngles"]);
                }

                string versionSoftware = ""; // funcionalidades.recuperarVersionSoftware();
                if (Environment.ExpandEnvironmentVariables(ConfigurationManager.AppSettings["TipoVersion"]).ToUpper() == "PRUEBA")
                {
                    lblTitulo.Text = "TEST " + versionSoftware; //lblTitulo.Text + "(" + Environment.ExpandEnvironmentVariables(ConfigurationManager.AppSettings["TipoVersion"]).ToUpper() + ")";
                    lblTitulo.ForeColor = System.Drawing.ColorTranslator.FromHtml("#3b7b03");
                }
                else if (Environment.ExpandEnvironmentVariables(ConfigurationManager.AppSettings["TipoVersion"]).ToUpper() == "DESARROLLO")
                {
                    lblTitulo.Text = "DESARROLLO " + versionSoftware; // lblTitulo.Text + "(" + Environment.ExpandEnvironmentVariables(ConfigurationManager.AppSettings["TipoVersion"]).ToUpper() + ")";
                    lblTitulo.ForeColor = System.Drawing.ColorTranslator.FromHtml("#042784");
                }
                else if (Environment.ExpandEnvironmentVariables(ConfigurationManager.AppSettings["TipoVersion"]).ToUpper() == "BETA")
                {
                    lblTitulo.Text = "BETA " + versionSoftware; //lblTitulo.Text + "(" + Environment.ExpandEnvironmentVariables(ConfigurationManager.AppSettings["TipoVersion"]).ToUpper() + ")";
                    lblTitulo.ForeColor = System.Drawing.ColorTranslator.FromHtml("#2e0454");
                }
                else
                {
                    lblTitulo.Text = "" + versionSoftware;
                    lblTitulo.ForeColor = System.Drawing.ColorTranslator.FromHtml("#f14d28");
                }

                string visualizacion = Session["VisualizacionOferta"].ToString();

                if (visualizacion == "CAPITULOS")
                    filaEncontrada = dtIdiomas.Select("ETQ_Control = 'btnVisualizarOfertaCapitulo'");
                else
                    filaEncontrada = dtIdiomas.Select("ETQ_Control = 'btnVisualizarOfertaTotales'");

                foreach (DataRow filaValor in filaEncontrada)
                {
                    if (idioma == "ESPAÑOL")
                        btnVisualizarOferta.Text = Convert.ToString(filaValor["ETQ_TextoCastellano"]);
                    if (idioma == "CATALAN")
                        btnVisualizarOferta.Text = Convert.ToString(filaValor["ETQ_TextoCatalan"]);
                    if (idioma == "INGLES")
                        btnVisualizarOferta.Text = Convert.ToString(filaValor["ETQ_TextoIngles"]);
                }
            }
            catch (Exception ex)
            {
                mostrarMensaje("Modificar etiquetas generales// " + ex.Message);
            }
        }

        public void recorrerColeccionControles(System.Web.UI.Control parentCtrl)
        {
            DataRow[] filaEncontrada;
            int indice = -1;
            string idioma = Session["idioma"].ToString();
            //string idioma = "";
            //HttpCookie nameCookie = Request.Cookies["idioma"];
            //if (nameCookie != null)
            //    idioma = nameCookie.Value.ToString();

            foreach (System.Web.UI.Control ctrl in parentCtrl.Controls)
            {
                Label lb = ctrl as Label;
                if (lb != null && lb.ID != "lblVersionUtilizada")
                {
                    if (lb.ID != "lblDatosSolicitados" && lb.ID != "lblIdioma")
                    {
                        filaEncontrada = dtIdiomas.Select("ETQ_Control = '" + lb.ID + "'");
                        foreach (DataRow filaValor in filaEncontrada)
                        {
                            if (idioma == "ESPAÑOL")
                                lb.Text = Convert.ToString(filaValor["ETQ_TextoCastellano"]);
                            if (idioma == "CATALAN")
                                lb.Text = Convert.ToString(filaValor["ETQ_TextoCatalan"]);
                            if (idioma == "INGLES")
                                lb.Text = Convert.ToString(filaValor["ETQ_TextoIngles"]);
                        }
                    }
                }
                else
                {
                    DropDownList ddl = ctrl as DropDownList;
                    if (ddl != null)
                    {
                        if (ddl.ID != "cmbEmpresa" && ddl.ID != "cmbVersion")
                        {
                            indice = ddl.SelectedIndex;
                            ddl.Items.Clear();
                            if (ddl.ID != "cmbFenolico")
                                ddl.Items.Add("");
                            filaEncontrada = dtIdiomas.Select("ETQ_Control = '" + ddl.ID + "'");
                            foreach (DataRow filaValor in filaEncontrada)
                            {
                                if (idioma == "ESPAÑOL")
                                    ddl.Items.Add(new System.Web.UI.WebControls.ListItem { Text = Convert.ToString(filaValor["ETQ_TextoCastellano"]), Value = Convert.ToString(filaValor["ETQ_Value"]) });
                                if (idioma == "CATALAN")
                                    ddl.Items.Add(new System.Web.UI.WebControls.ListItem { Text = Convert.ToString(filaValor["ETQ_TextoCatalan"]), Value = Convert.ToString(filaValor["ETQ_Value"]) });
                                if (idioma == "INGLES")
                                    ddl.Items.Add(new System.Web.UI.WebControls.ListItem { Text = Convert.ToString(filaValor["ETQ_TextoIngles"]), Value = Convert.ToString(filaValor["ETQ_Value"]) });
                            }
                            ddl.SelectedIndex = indice;
                        }
                    }
                    else
                    {
                        LinkButton btn = ctrl as LinkButton;
                        if (btn != null)
                        {
                            filaEncontrada = dtIdiomas.Select("ETQ_Control = '" + btn.ID + "'");
                            foreach (DataRow filaValor in filaEncontrada)
                            {
                                if (idioma == "ESPAÑOL")
                                    btn.Text = Convert.ToString(filaValor["ETQ_TextoCastellano"]);
                                if (idioma == "CATALAN")
                                    btn.Text = Convert.ToString(filaValor["ETQ_TextoCatalan"]);
                                if (idioma == "INGLES")
                                    btn.Text = Convert.ToString(filaValor["ETQ_TextoIngles"]);
                            }
                        }
                        else
                        {
                            recorrerColeccionControles(ctrl);
                        }
                    }
                }
            }
        }


        protected void sumarTotalesPrevisto(ref DataTable dtValores)
        {
            DataTable dtArbol = new DataTable();
            dtArbol = (DataTable)Session["dtArbol"];
        
            try
            {
                DataRow[] filaEncontrada;
                DataRow[] filaEncontradaHijo;
                DataRow filaValores;
                int hijo = 0;
                string etiqueta = "";
                string etiquetaTotal = "";
                decimal total = 0;
                decimal subtotal = 0;
                string color = "";
               
                // ACTUALIZAR LOS DATOS CORRECTAMENTE
                foreach (DataRow row in dtValores.Rows)
                {
                    if (row["IMPORTE PREVISTO"] == DBNull.Value)
                    {
                        row["IMPORTE PREVISTO"] = 0.00;
                        row["PORCENTAJE PREVISTO"] = 0.00;
                        row.AcceptChanges();
                    }
                }

                // LIMPIAR LOS TOTALES
                filaEncontrada = dtValores.Select("ETIQUETA LIKE 'TOTAL_%'");
                if (filaEncontrada.Count() != 0)
                {
                    foreach (DataRow filaValor in filaEncontrada)
                    {
                        filaValor["PORCENTAJE PREVISTO"] = "0.00";
                        filaValor["IMPORTE PREVISTO"] = "0.00";
                        filaValor.AcceptChanges();
                    }
                }

                // SUBTOTALES 
                filaEncontrada = dtArbol.Select("ETIQUETA_DESPLEGABLE <> ''", "ID ASC");
                foreach (DataRow fila in filaEncontrada)
                {
                    color = "";
                    etiqueta = Convert.ToString(fila["ETIQUETA_DESPLEGABLE"]);
                    etiquetaTotal = Convert.ToString(fila["ETIQUETA_TOTAL"]);

                    total = dtValores.AsEnumerable()
                            .Where(y => y.Field<string>("ETIQUETA") == etiqueta)
                            .Sum(x => Convert.ToDecimal(x.Field<decimal>("IMPORTE PREVISTO")));

                    color = dtValores.AsEnumerable()
                            .Where(y => y.Field<string>("ETIQUETA") == etiqueta)
                            .Max(x => Convert.ToString(x.Field<string>("COLOR")));

                    filaEncontrada = dtValores.Select("ETIQUETA = '" + etiquetaTotal + "'");
                    if (filaEncontrada.Count() != 0)
                    {
                        foreach (DataRow filaValor in filaEncontrada)
                        {
                            if (total == 0)
                                filaValor["PORCENTAJE PREVISTO"] = "0.00";
                            filaValor["IMPORTE PREVISTO"] = total.ToString("#,##0.00");
                            filaValor["COLOR"] = color;
                            filaValor.AcceptChanges();
                            break;
                        }
                    }
                    else
                    {
                        filaValores = dtValores.NewRow();
                        filaValores["ETIQUETA"] = etiquetaTotal;
                        filaValores["CONCEPTO"] = "";
                        filaValores["IMPORTE PREVISTO"] = total.ToString("#,##0.00");
                        filaValores["PORCENTAJE PREVISTO"] = "0.00";
                        filaValores["COLOR"] = color;
                        dtValores.Rows.Add(filaValores);
                        filaValores = null;
                    }
                }

                // TOTALES
                //voy = 0;
                filaEncontrada = dtArbol.Select("1 = 1", "ID DESC");
                foreach (DataRow fila in filaEncontrada)
                {
                    color = "";
                    hijo = Convert.ToInt32(fila["ID"]);
                    etiquetaTotal = Convert.ToString(fila["ETIQUETA_TOTAL"]);

                    total = 0;
                    filaEncontradaHijo = dtArbol.Select("HIJO_DE_ID = '" + hijo.ToString() + "'");
                    foreach (DataRow filaHijo in filaEncontradaHijo)
                    {
                        etiqueta = Convert.ToString(filaHijo["ETIQUETA_TOTAL"]);

                        subtotal = dtValores.AsEnumerable()
                            .Where(y => y.Field<string>("ETIQUETA") == etiqueta)
                            .Sum(x => Convert.ToDecimal(x.Field<decimal>("IMPORTE PREVISTO")));

                        color = dtValores.AsEnumerable()
                            .Where(y => y.Field<string>("ETIQUETA") == etiqueta)
                            .Max(x => Convert.ToString(x.Field<string>("COLOR")));

                        total = total + subtotal;
                    }

                    filaEncontrada = dtValores.Select("ETIQUETA = '" + etiquetaTotal + "'");
                    if (filaEncontrada.Count() != 0)
                    {
                        if (total != 0)
                        {
                            foreach (DataRow filaValor in filaEncontrada)
                            {
                                if (total == 0)
                                    filaValor["PORCENTAJE PREVISTO"] = "0.00";
                                filaValor["IMPORTE PREVISTO"] = total.ToString("#,##0.00");
                                filaValor["COLOR"] = color;
                                filaValor.AcceptChanges();
                                break;
                            }
                        }
                    }
                    else
                    {
                        filaValores = dtValores.NewRow();
                        filaValores["ETIQUETA"] = etiquetaTotal;
                        filaValores["CONCEPTO"] = "";
                        filaValores["IMPORTE PREVISTO"] = total.ToString("#,##0.00");
                        filaValores["PORCENTAJE PREVISTO"] = "0.00";
                        filaValores["COLOR"] = color;
                        dtValores.Rows.Add(filaValores);
                        filaValores = null;
                    }
                }

                // PORCENTAJES
                string porcentajeEtiquetaDesplegable = "";
                string porcentajeEtiquetaTotal = "";

                decimal totalFacturacion = dtValores.AsEnumerable()
                                .Where(y => y.Field<string>("ETIQUETA") == "TOTAL_FACTURACION")
                                .Sum(x => Convert.ToDecimal(x.Field<decimal>("IMPORTE PREVISTO")));

                filaEncontrada = dtArbol.Select("1 = 1", "ID ASC");
                foreach (DataRow fila in filaEncontrada)
                {
                    etiqueta = Convert.ToString(fila["ETIQUETA_DESPLEGABLE"]);
                    etiquetaTotal = Convert.ToString(fila["ETIQUETA_TOTAL"]);
                    porcentajeEtiquetaDesplegable = Convert.ToString(fila["PORCENTAJE_ETIQUETA_DESPLEGABLE"]);
                    porcentajeEtiquetaTotal = Convert.ToString(fila["PORCENTAJE_ETIQUETA_TOTAL"]);

                    if (etiqueta == "MARGEN_VENTAS_DIRECTAS" || etiquetaTotal == "TOTAL_MARGEN_VENTAS_DIRECTAS")
                        total = 0;

                    filaEncontrada = dtValores.Select("ETIQUETA = '" + etiqueta + "'");
                    if (filaEncontrada.Count() != 0)
                    {
                        foreach (DataRow filaValor in filaEncontrada)
                        {
                            if (porcentajeEtiquetaDesplegable == "")
                            {
                                if (totalFacturacion != 0)
                                    filaValor["PORCENTAJE PREVISTO"] = ((Convert.ToDecimal(filaValor["IMPORTE PREVISTO"]) * 100) / totalFacturacion).ToString("#,##0.00");
                                else
                                    filaValor["PORCENTAJE PREVISTO"] = "0.00";
                            }
                            else
                            {
                                total = dtValores.AsEnumerable()
                                    .Where(y => y.Field<string>("ETIQUETA") == porcentajeEtiquetaDesplegable)
                                    .Sum(x => Convert.ToDecimal(x.Field<decimal>("IMPORTE PREVISTO")));
                                if (total != 0)
                                    filaValor["PORCENTAJE PREVISTO"] = ((Convert.ToDecimal(filaValor["IMPORTE PREVISTO"]) * 100) / total).ToString("#,##0.00");
                                else
                                    filaValor["PORCENTAJE PREVISTO"] = "0.00";
                            }
                            filaValor.AcceptChanges();
                        }
                    }

                    filaEncontrada = dtValores.Select("ETIQUETA = '" + etiquetaTotal + "'");
                    if (filaEncontrada.Count() != 0)
                    {
                        foreach (DataRow filaValor in filaEncontrada)
                        {
                            if (porcentajeEtiquetaTotal == "")
                            {
                                if (totalFacturacion != 0)
                                    filaValor["PORCENTAJE PREVISTO"] = ((Convert.ToDecimal(filaValor["IMPORTE PREVISTO"]) * 100) / totalFacturacion).ToString("#,##0.00");
                                else
                                    filaValor["PORCENTAJE PREVISTO"] = "0.00";
                            }
                            else
                            {
                                total = dtValores.AsEnumerable()
                                        .Where(y => y.Field<string>("ETIQUETA") == porcentajeEtiquetaTotal)
                                        .Sum(x => Convert.ToDecimal(x.Field<decimal>("IMPORTE PREVISTO")));
                                if (total != 0)
                                    filaValor["PORCENTAJE PREVISTO"] = ((Convert.ToDecimal(filaValor["IMPORTE PREVISTO"]) * 100) / total).ToString("#,##0.00");
                                else
                                    filaValor["PORCENTAJE PREVISTO"] = "0.00";
                            }
                            filaValor.AcceptChanges();
                        }
                    }
                }

                // TOTAL_MARGEN
                total = dtValores.AsEnumerable()
                .Where(y => y.Field<string>("ETIQUETA") == "TOTAL_FACTURACION" || y.Field<string>("ETIQUETA") == "TOTAL_COSTES") // || y.Field<string>("ETIQUETA") == "TOTAL_ABONO_NUEVO_MARGEN")
                .Sum(x => Convert.ToDecimal(x.Field<decimal>("IMPORTE PREVISTO")));

                filaEncontrada = dtValores.Select("ETIQUETA = 'TOTAL_MARGEN'");
                if (filaEncontrada.Count() != 0)
                {
                    //if (total != 0)
                    //{
                    foreach (DataRow filaValor in filaEncontrada)
                    {
                        if (total == 0)
                            filaValor["PORCENTAJE PREVISTO"] = "0.00";
                        else
                            if (totalFacturacion != 0)
                            filaValor["PORCENTAJE PREVISTO"] = ((total * 100) / totalFacturacion).ToString("#,##0.00");
                        else
                            filaValor["PORCENTAJE PREVISTO"] = "0.00";
                        filaValor["IMPORTE PREVISTO"] = total.ToString("#,##0.00");
                        break;
                    }
                    //}
                }
                else
                {
                    filaValores = dtValores.NewRow();
                    filaValores["ETIQUETA"] = "TOTAL_MARGEN";
                    filaValores["CONCEPTO"] = "";
                    filaValores["IMPORTE PREVISTO"] = total.ToString("#,##0.00");
                    if (totalFacturacion != 0)
                        filaValores["PORCENTAJE PREVISTO"] = ((total * 100) / totalFacturacion).ToString("#,##0.00");
                    else
                        filaValores["PORCENTAJE PREVISTO"] = "0.00";
                    filaValores["COLOR"] = "";
                    dtValores.Rows.Add(filaValores);
                    filaValores = null;
                }

                // MB Fenólico Nuevo 
                total = dtValores.AsEnumerable()
                   .Where(y => y.Field<string>("ETIQUETA") == "TOTAL_FENOLICO_NUEVO")
                   .Sum(x => Convert.ToDecimal(x.Field<decimal>("IMPORTE PREVISTO")));

                filaEncontrada = dtValores.Select("ETIQUETA = 'MARGEN_FENOLICO_NUEVO' OR ETIQUETA = 'TOTAL_MARGEN_FENOLICO_NUEVO'");
                if (filaEncontrada.Count() != 0)
                {
                    foreach (DataRow filaValor in filaEncontrada)
                    {
                        if (total == 0)
                            filaValor["PORCENTAJE PREVISTO"] = "0.00";
                        else
                            filaValor["PORCENTAJE PREVISTO"] = "100.00";
                    }
                }

                // MB SVP/CIF
                total = dtValores.AsEnumerable()
                   .Where(y => y.Field<string>("ETIQUETA") == "TOTAL_SVP_CIF")
                   .Sum(x => Convert.ToDecimal(x.Field<decimal>("IMPORTE PREVISTO")));

                filaEncontrada = dtValores.Select("ETIQUETA = 'MARGEN_SVP_CIF' OR ETIQUETA = 'TOTAL_MARGEN_SVP_CIF'");
                if (filaEncontrada.Count() != 0)
                {
                    foreach (DataRow filaValor in filaEncontrada)
                    {
                        if (total == 0)
                            filaValor["PORCENTAJE PREVISTO"] = "0.00";
                        else
                            filaValor["PORCENTAJE PREVISTO"] = "100.00";
                    }
                }

                // TOTAL ROP BASICO
                total = dtValores.AsEnumerable()
                .Where(y => y.Field<string>("ETIQUETA") == "TOTAL_MARGEN" || y.Field<string>("ETIQUETA") == "TOTAL_GASTOS_VARIABLES" || y.Field<string>("ETIQUETA") == "TOTAL_GASTOS_FIJOS" || y.Field<string>("ETIQUETA") == "TOTAL_ABONO_NUEVO_ROP_BASICO")
                .Sum(x => Convert.ToDecimal(x.Field<decimal>("IMPORTE PREVISTO")));

                filaEncontrada = dtValores.Select("ETIQUETA = 'TOTAL_ROP_BASICO'");
                if (filaEncontrada.Count() != 0)
                {
                    foreach (DataRow filaValor in filaEncontrada)
                    {
                        if (total == 0)
                            filaValor["PORCENTAJE PREVISTO"] = "0.00";
                        else
                            if (totalFacturacion != 0)
                            filaValor["PORCENTAJE PREVISTO"] = ((total * 100) / totalFacturacion).ToString("#,##0.00");
                        else
                            filaValor["PORCENTAJE PREVISTO"] = "0.00";
                        filaValor["IMPORTE PREVISTO"] = total.ToString("#,##0.00");
                        break;
                    }
                }
                else
                {
                    filaValores = dtValores.NewRow();
                    filaValores["ETIQUETA"] = "TOTAL_ROP_BASICO";
                    filaValores["CONCEPTO"] = "";
                    filaValores["IMPORTE PREVISTO"] = total.ToString("#,##0.00");
                    if (totalFacturacion != 0)
                        filaValores["PORCENTAJE PREVISTO"] = ((total * 100) / totalFacturacion).ToString("#,##0.00");
                    else
                        filaValores["PORCENTAJE PREVISTO"] = "0.00";
                    filaValores["COLOR"] = "";
                    dtValores.Rows.Add(filaValores);
                    filaValores = null;
                }

                // TOTAL ROP 
                total = dtValores.AsEnumerable()
                    .Where(y => y.Field<string>("ETIQUETA") == "TOTAL_ROP_BASICO" || y.Field<string>("ETIQUETA") == "TOTAL_AJUSTES_OBRA" || y.Field<string>("ETIQUETA") == "TOTAL_AJUSTES_PRODUCTO" || y.Field<string>("ETIQUETA") == "TOTAL_AJUSTES_BU" || y.Field<string>("ETIQUETA") == "TOTAL_ABONO_NUEVO_ROP")
                    .Sum(x => Convert.ToDecimal(x.Field<decimal>("IMPORTE PREVISTO")));

                filaEncontrada = dtValores.Select("ETIQUETA = 'TOTAL_ROP'");
                if (filaEncontrada.Count() != 0)
                {
                    if (total != 0)
                    {
                        foreach (DataRow filaValor in filaEncontrada)
                        {
                            if (total == 0)
                                filaValor["PORCENTAJE PREVISTO"] = "0.00";
                            else
                                if (totalFacturacion != 0)
                                filaValor["PORCENTAJE PREVISTO"] = ((total * 100) / totalFacturacion).ToString("#,##0.00");
                            else
                                filaValor["PORCENTAJE PREVISTO"] = "0.00";
                            filaValor["IMPORTE PREVISTO"] = total.ToString("#,##0.00");
                            break;
                        }
                    }
                }
                else
                {
                    filaValores = dtValores.NewRow();
                    filaValores["ETIQUETA"] = "TOTAL_ROP";
                    filaValores["CONCEPTO"] = "";
                    filaValores["IMPORTE PREVISTO"] = total.ToString("#,##0.00");
                    if (totalFacturacion != 0)
                        filaValores["PORCENTAJE PREVISTO"] = ((total * 100) / totalFacturacion).ToString("#,##0.00");
                    else
                        filaValores["PORCENTAJE PREVISTO"] = "0.00";
                    filaValores["COLOR"] = "";
                    dtValores.Rows.Add(filaValores);
                    filaValores = null;
                }
            }
            catch (Exception ex)
            {
                mostrarMensaje("Sumar totales previsto// " + ex.Message);
            }
        }

        protected void sumarTotalesArticulos(ref DataTable dtValores, ref DataTable dtTiempos, string concepto)
        {
            string dondeVa = "";
            DataTable dtArbol = new DataTable();
            dtArbol = (DataTable)Session["dtArbol"];
            DateTime hora_1 = DateTime.Now;
            TimeSpan hora_2 = default(TimeSpan);
            DataRow oItemTiempo;

            try
            {
