        protected void sumarTotalesCapitulos(ref DataTable dtValores, string concepto)
        {
            DataTable dtArbol = new DataTable();
            dtArbol = (DataTable)Session["dtArbol"];

            try
            {
                DataRow[] filaEncontrada;
                DataRow[] filaEncontradaHijo;
                DataRow[] filaEncontradaSumar;
                DataRow filaValores;
                int hijo = 0;
                string etiqueta = "";
                string etiquetaTotal = "";
                decimal total = 0;
                decimal subtotal = 0;
                string color = "";

                string idioma = Session["idioma"].ToString();
                string usuarioRed = Session["usuarioRed"].ToString();

                string strEntrega = "";
                string strDevolucion = "";
                string strEntregaCapitulo = "";
                string strDevolucionCapitulo = "";
                DataRow[] filaEncontradaED;

                filaEncontradaED = dtIdiomas.Select("ETQ_Control = 'portesEntrega'");
                foreach (DataRow filaValor in filaEncontradaED)
                {
                    if (idioma == "ESPAÑOL")
                        strEntrega = Convert.ToString(filaValor["ETQ_TextoCastellano"]);
                    if (idioma == "CATALAN")
                        strEntrega = Convert.ToString(filaValor["ETQ_TextoCatalan"]);
                    if (idioma == "INGLES")
                        strEntrega = Convert.ToString(filaValor["ETQ_TextoIngles"]);
                }
                filaEncontradaED = dtIdiomas.Select("ETQ_Control = 'portesDevolucion'");
                foreach (DataRow filaValor in filaEncontradaED)
                {
                    if (idioma == "ESPAÑOL")
                        strDevolucion = Convert.ToString(filaValor["ETQ_TextoCastellano"]);
                    if (idioma == "CATALAN")
                        strDevolucion = Convert.ToString(filaValor["ETQ_TextoCatalan"]);
                    if (idioma == "INGLES")
                        strDevolucion = Convert.ToString(filaValor["ETQ_TextoIngles"]);
                }

                strEntregaCapitulo = concepto + " [" + strEntrega + "]";
                strDevolucionCapitulo = concepto + " [" + strDevolucion + "]";

                // LIMPIAR LOS TOTALES
                filaEncontrada = dtValores.Select("ETIQUETA LIKE 'TOTAL_%'");
                if (filaEncontrada.Count() != 0)
                {
                    foreach (DataRow filaValor in filaEncontrada)
                    {
                        filaValor["CONCEPTO"] = concepto;
                        filaValor["PORCENTAJE"] = "0.00";
                        filaValor["IMPORTE"] = "0.00";
                        filaValor.AcceptChanges();
                    }
                }

                // SUBTOTALES 
                filaEncontrada = dtArbol.Select("ETIQUETA_DESPLEGABLE <> ''", "ID ASC");
                foreach (DataRow fila in filaEncontrada)
                {
                    color = "";
                    etiqueta = Convert.ToString(fila["ETIQUETA_DESPLEGABLE"]);
                    etiquetaTotal = Convert.ToString(fila["ETIQUETA_TOTAL"]);

                    total = dtValores.AsEnumerable()
                            .Where(y => y.Field<string>("ETIQUETA") == etiqueta)
                            .Sum(x => Convert.ToDecimal(x.Field<decimal>("IMPORTE")));

                    color = dtValores.AsEnumerable()
                            .Where(y => y.Field<string>("ETIQUETA") == etiqueta)
                            .Max(x => Convert.ToString(x.Field<string>("COLOR")));

                    filaEncontrada = dtValores.Select("ETIQUETA = '" + etiquetaTotal + "'");
                    if (filaEncontrada.Count() != 0)
                    {
                        foreach (DataRow filaValor in filaEncontrada)
                        {
                            if (filaValor["CONCEPTO"].ToString().IndexOf("[" + strEntrega + "]") >= 0)
                                filaValor["CONCEPTO"] = strEntregaCapitulo;
                            else if (filaValor["CONCEPTO"].ToString().IndexOf("[" + strDevolucion + "]") >= 0)
                                filaValor["CONCEPTO"] = strDevolucionCapitulo;
                            else
                                filaValor["CONCEPTO"] = concepto;
                            if (total == 0)
                                filaValor["PORCENTAJE"] = "0.00";
                            filaValor["IMPORTE"] = total.ToString("#,##0.00");
                            filaValor["COLOR"] = color;
                            filaValor.AcceptChanges();
                            break;
                        }
                    }
                    else
                    {
                        filaValores = dtValores.NewRow();
                        filaValores["ETIQUETA"] = etiquetaTotal;
                        filaValores["CONCEPTO"] = concepto;
                        filaValores["IMPORTE"] = total.ToString("#,##0.00");
                        filaValores["PORCENTAJE"] = "0.00";
                        filaValores["COLOR"] = color;
                        dtValores.Rows.Add(filaValores);
                        filaValores = null;
                    }
                }

                // TOTALES
                filaEncontrada = dtArbol.Select("1 = 1", "ID DESC");
                foreach (DataRow fila in filaEncontrada)
                {
                    color = "";
                    hijo = Convert.ToInt32(fila["ID"]);
                    etiquetaTotal = Convert.ToString(fila["ETIQUETA_TOTAL"]);

                    total = 0;
                    filaEncontradaHijo = dtArbol.Select("HIJO_DE_ID = '" + hijo.ToString() + "'");
                    foreach (DataRow filaHijo in filaEncontradaHijo)
                    {
                        etiqueta = Convert.ToString(filaHijo["ETIQUETA_TOTAL"]);

                        subtotal = dtValores.AsEnumerable()
                            .Where(y => y.Field<string>("ETIQUETA") == etiqueta)
                            .Sum(x => Convert.ToDecimal(x.Field<decimal>("IMPORTE")));

                        color = dtValores.AsEnumerable()
                            .Where(y => y.Field<string>("ETIQUETA") == etiqueta)
                            .Max(x => Convert.ToString(x.Field<string>("COLOR")));

                        total = total + subtotal;
                    }

                    filaEncontrada = dtValores.Select("ETIQUETA = '" + etiquetaTotal + "'");
                    if (filaEncontrada.Count() != 0)
                    {
                        if (total != 0)
                        {
                            foreach (DataRow filaValor in filaEncontrada)
                            {
                                if (filaValor["CONCEPTO"].ToString().IndexOf("[" + strEntrega + "]") >= 0)
                                    filaValor["CONCEPTO"] = strEntregaCapitulo;
                                else if (filaValor["CONCEPTO"].ToString().IndexOf("[" + strDevolucion + "]") >= 0)
                                    filaValor["CONCEPTO"] = strDevolucionCapitulo;
                                else
                                    filaValor["CONCEPTO"] = concepto;
                                if (total == 0)
                                    filaValor["PORCENTAJE"] = "0.00";
                                filaValor["IMPORTE"] = total.ToString("#,##0.00");
                                filaValor["COLOR"] = color;
                                filaValor.AcceptChanges();
                                break;
                            }
                        }
                    }
                    else
                    {
                        filaValores = dtValores.NewRow();
                        filaValores["ETIQUETA"] = etiquetaTotal;
                        filaValores["CONCEPTO"] = concepto;
                        filaValores["IMPORTE"] = total.ToString("#,##0.00");
                        filaValores["PORCENTAJE"] = "0.00";
