                    }
                }
                else
                {
                    filaValores = dtValores.NewRow();
                    filaValores["ETIQUETA"] = "TOTAL_ROP";
                    filaValores["CONCEPTO"] = concepto;
                    filaValores["IMPORTE"] = total.ToString("#,##0.00");
                    if (totalFacturacion != 0)
                        filaValores["PORCENTAJE"] = ((total * 100) / totalFacturacion).ToString("#,##0.00");
                    else
                        filaValores["PORCENTAJE"] = "0.00";
                    filaValores["COLOR"] = "";
                    dtValores.Rows.Add(filaValores);
                    filaValores = null;
                }
            }
            catch (Exception ex)
            {
                mostrarMensaje("Sumar totales // " + ex.Message);
            }
        }


        protected void sumarTotales(ref DataTable dtValores)
        {
            DataTable dtArbol = new DataTable();
            dtArbol = (DataTable)Session["dtArbol"];

            try
            {
                DataRow[] filaEncontrada;
                DataRow[] filaEncontradaHijo;
                DataRow[] filaEncontradaSumar;
                DataRow filaValores;
                int hijo = 0;
                string etiqueta = "";
                string etiquetaTotal = "";
                decimal total = 0;
                decimal subtotal = 0;
                string color = "";

                // LIMPIAR LOS TOTALES
                filaEncontrada = dtValores.Select("ETIQUETA LIKE 'TOTAL_%'");
                if (filaEncontrada.Count() != 0)
                {
                    foreach (DataRow filaValor in filaEncontrada)
                    {
                        filaValor["PORCENTAJE"] = "0.00";
                        filaValor["IMPORTE"] = "0.00";
                        filaValor.AcceptChanges();
                    }
                }

                // SUBTOTALES 
                filaEncontrada = dtArbol.Select("ETIQUETA_DESPLEGABLE <> ''", "ID ASC");
                foreach (DataRow fila in filaEncontrada)
                {
                    color = "";
                    etiqueta = Convert.ToString(fila["ETIQUETA_DESPLEGABLE"]);
                    etiquetaTotal = Convert.ToString(fila["ETIQUETA_TOTAL"]);

                    total = dtValores.AsEnumerable()
                            .Where(y => y.Field<string>("ETIQUETA") == etiqueta)
                            .Sum(x => Convert.ToDecimal(x.Field<decimal>("IMPORTE")));

                    color = dtValores.AsEnumerable()
                            .Where(y => y.Field<string>("ETIQUETA") == etiqueta)
                            .Max(x => Convert.ToString(x.Field<string>("COLOR")));

                    filaEncontrada = dtValores.Select("ETIQUETA = '" + etiquetaTotal + "'");
                    if (filaEncontrada.Count() != 0)
                    {
                        foreach (DataRow filaValor in filaEncontrada)
                        {
                            if (total == 0)
                                filaValor["PORCENTAJE"] = "0.00";
                            filaValor["IMPORTE"] = total.ToString("#,##0.00");
                            filaValor["COLOR"] = color;
                            filaValor.AcceptChanges();
                            break;
                        }
                    }
                    else
                    {
                        filaValores = dtValores.NewRow();
                        filaValores["ETIQUETA"] = etiquetaTotal;
                        filaValores["CONCEPTO"] = "";
                        filaValores["IMPORTE"] = total.ToString("#,##0.00");
                        filaValores["PORCENTAJE"] = "0.00";
                        filaValores["COLOR"] = color;
                        dtValores.Rows.Add(filaValores);
                        filaValores = null;
                    }
                }

                // TOTALES
                filaEncontrada = dtArbol.Select("1 = 1", "ID DESC");
                foreach (DataRow fila in filaEncontrada)
                {
                    color = "";
                    hijo = Convert.ToInt32(fila["ID"]);
                    etiquetaTotal = Convert.ToString(fila["ETIQUETA_TOTAL"]);

                    total = 0;
                    filaEncontradaHijo = dtArbol.Select("HIJO_DE_ID = '" + hijo.ToString() + "'");
                    foreach (DataRow filaHijo in filaEncontradaHijo)
                    {
                        etiqueta = Convert.ToString(filaHijo["ETIQUETA_TOTAL"]);

                        subtotal = dtValores.AsEnumerable()
                            .Where(y => y.Field<string>("ETIQUETA") == etiqueta)
                            .Sum(x => Convert.ToDecimal(x.Field<decimal>("IMPORTE")));

                        color = dtValores.AsEnumerable()
                            .Where(y => y.Field<string>("ETIQUETA") == etiqueta)
                            .Max(x => Convert.ToString(x.Field<string>("COLOR")));

                        total = total + subtotal;
                    }

                    filaEncontrada = dtValores.Select("ETIQUETA = '" + etiquetaTotal + "'");
                    if (filaEncontrada.Count() != 0)
                    {
                        if (total != 0)
                        {
                            foreach (DataRow filaValor in filaEncontrada)
                            {
                                if (total == 0)
                                    filaValor["PORCENTAJE"] = "0.00";
                                filaValor["IMPORTE"] = total.ToString("#,##0.00");
                                filaValor["COLOR"] = color;
                                filaValor.AcceptChanges();
                                break;
                            }
                        }
                    }
                    else
                    {
                        filaValores = dtValores.NewRow();
                        filaValores["ETIQUETA"] = etiquetaTotal;
                        filaValores["CONCEPTO"] = "";
                        filaValores["IMPORTE"] = total.ToString("#,##0.00");
                        filaValores["PORCENTAJE"] = "0.00";
                        filaValores["COLOR"] = color;
                        dtValores.Rows.Add(filaValores);
                        filaValores = null;
                    }
                }

                // PORCENTAJES
                string porcentajeEtiquetaDesplegable = "";
                string porcentajeEtiquetaTotal = "";

                decimal totalFacturacion = dtValores.AsEnumerable()
                                .Where(y => y.Field<string>("ETIQUETA") == "TOTAL_FACTURACION")
                                .Sum(x => Convert.ToDecimal(x.Field<decimal>("IMPORTE")));

                filaEncontrada = dtArbol.Select("ID <= 15", "ID ASC");
                foreach (DataRow fila in filaEncontrada)
                {
                    etiqueta = Convert.ToString(fila["ETIQUETA_DESPLEGABLE"]);
                    etiquetaTotal = Convert.ToString(fila["ETIQUETA_TOTAL"]);
                    porcentajeEtiquetaDesplegable = Convert.ToString(fila["PORCENTAJE_ETIQUETA_DESPLEGABLE"]);
                    porcentajeEtiquetaTotal = Convert.ToString(fila["PORCENTAJE_ETIQUETA_TOTAL"]);

                    filaEncontrada = dtValores.Select("ETIQUETA = '" + etiqueta + "'");
                    if (filaEncontrada.Count() != 0)
                    {
                        foreach (DataRow filaValor in filaEncontrada)
                        {
                            if (porcentajeEtiquetaDesplegable == "")
                            {
                                if (totalFacturacion != 0)
                                    filaValor["PORCENTAJE"] = ((Convert.ToDecimal(filaValor["IMPORTE"]) * 100) / totalFacturacion).ToString("#,##0.00");
                                else
                                    filaValor["PORCENTAJE"] = "0.00";
                            }
                            else
                            {
                                total = dtValores.AsEnumerable()
                                    .Where(y => y.Field<string>("ETIQUETA") == porcentajeEtiquetaDesplegable)
                                    .Sum(x => Convert.ToDecimal(x.Field<decimal>("IMPORTE")));

                                if (total != 0)
                                    filaValor["PORCENTAJE"] = ((Convert.ToDecimal(filaValor["IMPORTE"]) * 100) / total).ToString("#,##0.00");
                                else
                                    filaValor["PORCENTAJE"] = "0.00";
                            }
                            filaValor.AcceptChanges();
                        }
                    }

                    filaEncontrada = dtValores.Select("ETIQUETA = '" + etiquetaTotal + "'");
                    if (filaEncontrada.Count() != 0)
                    {
                        foreach (DataRow filaValor in filaEncontrada)
                        {
                            if (porcentajeEtiquetaTotal == "")
                            {
                                if (totalFacturacion != 0)
                                    filaValor["PORCENTAJE"] = ((Convert.ToDecimal(filaValor["IMPORTE"]) * 100) / totalFacturacion).ToString("#,##0.00");
                                else
                                    filaValor["PORCENTAJE"] = "0.00";
                            }
                            else
                            {
                                total = dtValores.AsEnumerable()
                                        .Where(y => y.Field<string>("ETIQUETA") == porcentajeEtiquetaTotal)
                                        .Sum(x => Convert.ToDecimal(x.Field<decimal>("IMPORTE")));
                                if (total != 0)
                                    filaValor["PORCENTAJE"] = ((Convert.ToDecimal(filaValor["IMPORTE"]) * 100) / total).ToString("#,##0.00");
                                else
                                    filaValor["PORCENTAJE"] = "0.00";
                            }
                            filaValor.AcceptChanges();
                        }
                    }
                }

                // % que van sobre su facturación de capítulo // AND NOT ETIQUETA_DESPLEGABLE LIKE 'TOTAL%'
                filaEncontrada = dtArbol.Select("ID > 15", "ID ASC");
                foreach (DataRow fila in filaEncontrada)
                {
                    etiqueta = Convert.ToString(fila["ETIQUETA_DESPLEGABLE"]);
                    etiquetaTotal = Convert.ToString(fila["ETIQUETA_TOTAL"]);
                    porcentajeEtiquetaDesplegable = Convert.ToString(fila["PORCENTAJE_ETIQUETA_DESPLEGABLE"]);
                    porcentajeEtiquetaTotal = Convert.ToString(fila["PORCENTAJE_ETIQUETA_TOTAL"]);

                    if (etiquetaTotal == "TOTAL_MARGEN_VENTAS" || etiqueta == "MARGEN_VENTAS")
                        total = 0;

                    filaEncontrada = dtValores.Select("ETIQUETA = '" + etiqueta + "'", "CONCEPTO");
                    if (filaEncontrada.Count() != 0)
                    {
                        if (etiqueta == "MARGEN_CAPITULOS")
                        {
                            foreach (DataRow filaValor in filaEncontrada)
                            {
                                string concepto = filaValor["CONCEPTO"].ToString();

                                decimal totalFacturacionCapitulo = 0;
                                filaEncontradaSumar = dtArbol.Select("SumarParaPorcentajes = 1");
                                foreach (DataRow filaSumar in filaEncontradaSumar)
                                {
                                    string etiquetaSumar = Convert.ToString(filaSumar["ETIQUETA_DESPLEGABLE"]);

                                    decimal sumarEtiqueta = dtValores.AsEnumerable()
                                                            .Where(y => y.Field<string>("CONCEPTO") == concepto && y.Field<string>("ETIQUETA") == etiquetaSumar)
                                                            .Sum(x => Convert.ToDecimal(x.Field<decimal>("IMPORTE")));

                                    totalFacturacionCapitulo = totalFacturacionCapitulo + sumarEtiqueta;
                                }

                                if (porcentajeEtiquetaDesplegable == "")
                                {
                                    if (totalFacturacionCapitulo != 0)
                                        filaValor["PORCENTAJE"] = ((Convert.ToDecimal(filaValor["IMPORTE"]) * 100) / totalFacturacionCapitulo).ToString("#,##0.00");
                                    else
                                        filaValor["PORCENTAJE"] = "0.00";
                                }
                                else
                                {
                                    total = dtValores.AsEnumerable()
                                        .Where(y => y.Field<string>("CONCEPTO") == concepto && y.Field<string>("ETIQUETA") == etiqueta)
                                        .Sum(x => Convert.ToDecimal(x.Field<decimal>("IMPORTE")));

                                    if (total != 0)
                                        filaValor["PORCENTAJE"] = ((Convert.ToDecimal(filaValor["IMPORTE"]) * 100) / total).ToString("#,##0.00");
                                    else
                                        filaValor["PORCENTAJE"] = "0.00";
                                }
                                filaValor.AcceptChanges();
                            }
                        }
                        else
                        {
                            if (etiqueta.IndexOf("MARGEN") != -1)
                            {
                                decimal totalFacturacionCapitulo = 0;

                                foreach (DataRow filaValor in filaEncontrada)
                                {
                                    string concepto = filaValor["CONCEPTO"].ToString();

                                    totalFacturacionCapitulo = 0;
                                    totalFacturacionCapitulo = dtValores.AsEnumerable()
                                                            .Where(y => y.Field<string>("CONCEPTO") == concepto && y.Field<string>("ETIQUETA") == porcentajeEtiquetaDesplegable)
                                                            .Sum(x => Convert.ToDecimal(x.Field<decimal>("IMPORTE")));

                                    if (totalFacturacionCapitulo != 0)
                                        filaValor["PORCENTAJE"] = ((Convert.ToDecimal(filaValor["IMPORTE"]) * 100) / totalFacturacionCapitulo).ToString("#,##0.00");
                                    else
                                        filaValor["PORCENTAJE"] = "0.00";
                                    filaValor.AcceptChanges();
                                }

                                filaEncontrada = dtValores.Select("ETIQUETA = '" + etiquetaTotal + "'");
                                if (filaEncontrada.Count() != 0)
                                {
                                    foreach (DataRow filaValor in filaEncontrada)
                                    {
                                        if (totalFacturacionCapitulo != 0)
                                            filaValor["PORCENTAJE"] = ((Convert.ToDecimal(filaValor["IMPORTE"]) * 100) / totalFacturacionCapitulo).ToString("#,##0.00");
                                        else
                                            filaValor["PORCENTAJE"] = "0.00";

                                        filaValor.AcceptChanges();
                                    }
                                }
                            }
                            else
                            {
                                foreach (DataRow filaValor in filaEncontrada)
                                {
                                    string concepto = filaValor["CONCEPTO"].ToString();

                                    decimal totalFacturacionCapitulo = 0;
                                    filaEncontradaSumar = dtArbol.Select("SumarParaPorcentajes = 1");
                                    foreach (DataRow filaSumar in filaEncontradaSumar)
                                    {
                                        string etiquetaSumar = Convert.ToString(filaSumar["ETIQUETA_DESPLEGABLE"]);

                                        decimal sumarEtiqueta = dtValores.AsEnumerable()
                                                                .Where(y => y.Field<string>("CONCEPTO") == concepto && y.Field<string>("ETIQUETA") == etiquetaSumar)
                                                                .Sum(x => Convert.ToDecimal(x.Field<decimal>("IMPORTE")));

                                        totalFacturacionCapitulo = totalFacturacionCapitulo + sumarEtiqueta;
                                    }

                                    if (totalFacturacionCapitulo != 0)
                                        filaValor["PORCENTAJE"] = ((Convert.ToDecimal(filaValor["IMPORTE"]) * 100) / totalFacturacionCapitulo).ToString("#,##0.00");
                                    else
                                        filaValor["PORCENTAJE"] = "0.00";

                                    filaValor.AcceptChanges();
                                }
                            }
                        }
                    }

                    if (etiqueta.IndexOf("MARGEN") == -1 && etiquetaTotal.IndexOf("MARGEN") == -1)
                    {
                        filaEncontrada = dtValores.Select("ETIQUETA = '" + etiquetaTotal + "'");
                        if (filaEncontrada.Count() != 0)
                        {
                            foreach (DataRow filaValor in filaEncontrada)
                            {
                                if (totalFacturacion != 0)
                                    filaValor["PORCENTAJE"] = ((Convert.ToDecimal(filaValor["IMPORTE"]) * 100) / totalFacturacion).ToString("#,##0.00");
                                else
                                    filaValor["PORCENTAJE"] = "0.00";

                                filaValor.AcceptChanges();
                            }
                        }
                    }
                    else
                    {
                        filaEncontrada = dtValores.Select("ETIQUETA = '" + etiquetaTotal + "'");
                        foreach (DataRow filaValor in filaEncontrada)
                        {
                            if (porcentajeEtiquetaTotal != "")
                            {
                                total = dtValores.AsEnumerable()
                                        .Where(y => y.Field<string>("ETIQUETA") == porcentajeEtiquetaTotal)
                                        .Sum(x => Convert.ToDecimal(x.Field<decimal>("IMPORTE")));

                                if (total != 0)
                                    filaValor["PORCENTAJE"] = ((Convert.ToDecimal(filaValor["IMPORTE"]) * 100) / total).ToString("#,##0.00");
                                else
                                    filaValor["PORCENTAJE"] = "0.00";
                            }
                            filaValor.AcceptChanges();
                        }
                    }
                }

                // TOTAL_MARGEN_CAPITULOS
                filaEncontrada = dtValores.Select("ETIQUETA = 'TOTAL_MARGEN_CAPITULOS'");
                if (filaEncontrada.Count() != 0)
                {
                    foreach (DataRow filaValor in filaEncontrada)
                    {
                        if (totalFacturacion != 0)
                            filaValor["PORCENTAJE"] = ((Convert.ToDecimal(filaValor["IMPORTE"].ToString()) * 100) / totalFacturacion).ToString("#,##0.00");
                        filaValor.AcceptChanges();
                        break;
                    }
                }

                // MARGEN_VENTAS_MATERIAL_ALQUILADO_LIQUIDACIONES
                total = dtValores.AsEnumerable()
                        .Where(y => y.Field<string>("ETIQUETA") == "TOTAL_VENTAS_MATERIAL_ALQUILADO_LIQUIDACIONES_MALUSO" || y.Field<string>("ETIQUETA") == "TOTAL_COSTE_MATERIAL_ALQUILADO_Y_VENDIDO")
                        .Sum(x => Convert.ToDecimal(x.Field<decimal>("IMPORTE")));

                filaEncontrada = dtValores.Select("ETIQUETA = 'MARGEN_VENTAS_MATERIAL_ALQUILADO_LIQUIDACIONES'");
                if (filaEncontrada.Count() != 0)
                {
                    foreach (DataRow filaValor in filaEncontrada)
                    {
                        if (total == 0)
                            filaValor["PORCENTAJE"] = "0.00";
                        else
                            if (totalFacturacion != 0)
                            filaValor["PORCENTAJE"] = ((total * 100) / totalFacturacion).ToString("#,##0.00");
                        else
                            filaValor["PORCENTAJE"] = "0.00";
                        filaValor["IMPORTE"] = total.ToString("#,##0.00");
                        filaValor.AcceptChanges();
                        break;
                    }
                }
                else
                {
                    filaValores = dtValores.NewRow();
                    filaValores["ETIQUETA"] = "MARGEN_VENTAS_MATERIAL_ALQUILADO_LIQUIDACIONES";
                    filaValores["CONCEPTO"] = "";
                    filaValores["IMPORTE"] = total.ToString("#,##0.00");
                    if (totalFacturacion != 0)
                        filaValores["PORCENTAJE"] = ((total * 100) / totalFacturacion).ToString("#,##0.00");
                    else
                        filaValores["PORCENTAJE"] = "0.00";
                    filaValores["COLOR"] = "";
                    dtValores.Rows.Add(filaValores);
                    filaValores = null;
                }

                // TOTAL_MARGEN
                total = dtValores.AsEnumerable()
                .Where(y => y.Field<string>("ETIQUETA") == "TOTAL_FACTURACION" || y.Field<string>("ETIQUETA") == "TOTAL_COSTES") // || y.Field<string>("ETIQUETA") == "TOTAL_ABONO_NUEVO_MARGEN")
                .Sum(x => Convert.ToDecimal(x.Field<decimal>("IMPORTE")));

                filaEncontrada = dtValores.Select("ETIQUETA = 'TOTAL_MARGEN'");
                if (filaEncontrada.Count() != 0)
                {
                    foreach (DataRow filaValor in filaEncontrada)
                    {
                        if (total == 0)
                            filaValor["PORCENTAJE"] = "0.00";
                        else
                            if (totalFacturacion != 0)
                            filaValor["PORCENTAJE"] = ((total * 100) / totalFacturacion).ToString("#,##0.00");
                        else
                            filaValor["PORCENTAJE"] = "0.00";
                        filaValor["IMPORTE"] = total.ToString("#,##0.00");
                        filaValor.AcceptChanges();
                        break;
                    }
                }
                else
                {
                    filaValores = dtValores.NewRow();
                    filaValores["ETIQUETA"] = "TOTAL_MARGEN";
                    filaValores["CONCEPTO"] = "";
                    filaValores["IMPORTE"] = total.ToString("#,##0.00");
                    if (totalFacturacion != 0)
                        filaValores["PORCENTAJE"] = ((total * 100) / totalFacturacion).ToString("#,##0.00");
                    else
                        filaValores["PORCENTAJE"] = "0.00";
                    filaValores["COLOR"] = "";
                    dtValores.Rows.Add(filaValores);
                    filaValores = null;
                }

                // MB Fenólico Nuevo 
                total = dtValores.AsEnumerable()
                   .Where(y => y.Field<string>("ETIQUETA") == "TOTAL_FENOLICO_NUEVO")
                   .Sum(x => Convert.ToDecimal(x.Field<decimal>("IMPORTE")));

                filaEncontrada = dtValores.Select("ETIQUETA = 'MARGEN_FENOLICO_NUEVO' OR ETIQUETA = 'TOTAL_MARGEN_FENOLICO_NUEVO'");
                if (filaEncontrada.Count() != 0)
                {
                    foreach (DataRow filaValor in filaEncontrada)
                    {
                        if (total == 0)
                            filaValor["PORCENTAJE"] = "0.00";
                        else
                            filaValor["PORCENTAJE"] = "100.00";
                        filaValor.AcceptChanges();
                    }
                }

                // MB SVP/CIF
                total = dtValores.AsEnumerable()
                   .Where(y => y.Field<string>("ETIQUETA") == "TOTAL_SVP_CIF")
                   .Sum(x => Convert.ToDecimal(x.Field<decimal>("IMPORTE")));

                filaEncontrada = dtValores.Select("ETIQUETA = 'MARGEN_SVP_CIF' OR ETIQUETA = 'TOTAL_MARGEN_SVP_CIF'");
                if (filaEncontrada.Count() != 0)
                {
                    foreach (DataRow filaValor in filaEncontrada)
                    {
                        if (total == 0)
                            filaValor["PORCENTAJE"] = "0.00";
                        else
                            filaValor["PORCENTAJE"] = "100.00";
                        filaValor.AcceptChanges();
                    }
                }

                // TOTAL ROP BASICO
                total = dtValores.AsEnumerable()
                .Where(y => y.Field<string>("ETIQUETA") == "TOTAL_MARGEN" || y.Field<string>("ETIQUETA") == "TOTAL_GASTOS_VARIABLES" || y.Field<string>("ETIQUETA") == "TOTAL_GASTOS_FIJOS" || y.Field<string>("ETIQUETA") == "TOTAL_ABONO_NUEVO_ROP_BASICO")
                .Sum(x => Convert.ToDecimal(x.Field<decimal>("IMPORTE")));

                filaEncontrada = dtValores.Select("ETIQUETA = 'TOTAL_ROP_BASICO'");
                if (filaEncontrada.Count() != 0)
                {
                    //if (total != 0)
                    //{
                    foreach (DataRow filaValor in filaEncontrada)
                    {
                        if (total == 0)
                            filaValor["PORCENTAJE"] = "0.00";
                        else
                            if (totalFacturacion != 0)
                            filaValor["PORCENTAJE"] = ((total * 100) / totalFacturacion).ToString("#,##0.00");
                        else
                            filaValor["PORCENTAJE"] = "0.00";
                        filaValor["IMPORTE"] = total.ToString("#,##0.00");
                        filaValor.AcceptChanges();
                        break;
                    }
                    //}
                }
                else
                {
                    filaValores = dtValores.NewRow();
                    filaValores["ETIQUETA"] = "TOTAL_ROP_BASICO";
                    filaValores["CONCEPTO"] = "";
                    filaValores["IMPORTE"] = total.ToString("#,##0.00");
                    if (totalFacturacion != 0)
                        filaValores["PORCENTAJE"] = ((total * 100) / totalFacturacion).ToString("#,##0.00");
                    else
                        filaValores["PORCENTAJE"] = "0.00";
                    filaValores["COLOR"] = "";
                    dtValores.Rows.Add(filaValores);
                    filaValores = null;
                }

                // TOTAL ROP 
                total = dtValores.AsEnumerable()
                    .Where(y => y.Field<string>("ETIQUETA") == "TOTAL_ROP_BASICO" || y.Field<string>("ETIQUETA") == "TOTAL_AJUSTES_OBRA" || y.Field<string>("ETIQUETA") == "TOTAL_AJUSTES_PRODUCTO" || y.Field<string>("ETIQUETA") == "TOTAL_AJUSTES_BU" || y.Field<string>("ETIQUETA") == "TOTAL_ABONO_NUEVO_ROP")
                    .Sum(x => Convert.ToDecimal(x.Field<decimal>("IMPORTE")));

                filaEncontrada = dtValores.Select("ETIQUETA = 'TOTAL_ROP'");
                if (filaEncontrada.Count() != 0)
                {
                    if (total != 0)
                    {
                        foreach (DataRow filaValor in filaEncontrada)
                        {
                            if (total == 0)
                                filaValor["PORCENTAJE"] = "0.00";
                            else
                                if (totalFacturacion != 0)
                                filaValor["PORCENTAJE"] = ((total * 100) / totalFacturacion).ToString("#,##0.00");
                            else
                                filaValor["PORCENTAJE"] = "0.00";
                            filaValor["IMPORTE"] = total.ToString("#,##0.00");
                            filaValor.AcceptChanges();
                            break;
                        }
                    }
                }
                else
                {
                    filaValores = dtValores.NewRow();
                    filaValores["ETIQUETA"] = "TOTAL_ROP";
                    filaValores["CONCEPTO"] = "";
                    filaValores["IMPORTE"] = total.ToString("#,##0.00");
                    if (totalFacturacion != 0)
                        filaValores["PORCENTAJE"] = ((total * 100) / totalFacturacion).ToString("#,##0.00");
                    else
                        filaValores["PORCENTAJE"] = "0.00";
                    filaValores["COLOR"] = "";
                    dtValores.Rows.Add(filaValores);
                    filaValores = null;
                }
            }
            catch (Exception ex)
            {
                mostrarMensaje("Sumar totales // " + ex.Message);
            }
        }

        private bool BuscarNodoYAgregarHijo(JSONArbol nodoActual, string idBuscado, JSONArbol nuevoHijo)
        {
            if (nodoActual.ID == idBuscado)
            {
                nodoActual.hijo.Add(nuevoHijo);
                return true;
            }

            if (nodoActual.hijo != null)
            {
                foreach (var hijoNodo in nodoActual.hijo)
                {
                    if (BuscarNodoYAgregarHijo(hijoNodo, idBuscado, nuevoHijo))
                    {
                        return true;
                    }
                }
            }
            return false;
        }

