        private List<JSONArbol> ObtenerArbolDesdeSQL(string capitulo, DataTable dtValores, string idioma)
        {
            SqlDataAdapter adaptadorArbol;
            DataTable dtArbol = new DataTable();
            dtArbol = (DataTable)Session["dtArbol"];
            DataRow[] filaEncontrada;
            decimal totalFacturacion = 0;
            string dondeVa = "";

            string strConexion;
            SqlConnection conexion;
            SqlCommand comando;
            List<JSONArbol> nodos = new List<JSONArbol>();

            int COL_ARBOL_ID = 0;
            int COL_ARBOL_CONCEPTO = 1;
            int COL_ARBOL_COLOR = 2;
            int COL_ARBOL_HIJO_DE = 3;
            //int COL_ARBOL_ETIQUETA_DESPLEGABLE = 4;
            int COL_ARBOL_ETIQUETA_TOTAL = 5;

            string importe = "";
            string porcentaje = "";
            string importePrevisto = "";
            string porcentajePrevisto = "";
            string color = "";
            string conceptoValores = "";

            try
            {
                // CREAR NODO DEL CAPÍTULO
                JSONArbol nodo = new JSONArbol();
                nodo.ID = "0";
                nodo.Concepto = capitulo;
                nodo.Importe = "";
                nodo.Porcentaje = "";
                nodo.ImportePrevisto = "";
                nodo.PorcentajePrevisto = "";
                nodo.colorFila = "";
                nodo.colorEncabezado = "";
                nodos.Add(nodo);
                nodo = null;

                if (dtArbol.Rows.Count == 0)
                {
                    dondeVa = "ROP_ArbolROPConsulta";
                    dtArbol = new System.Data.DataTable();
                    strConexion = funcionalidades.recuperarTexto(ConfigurationManager.ConnectionStrings["SQL_ROP"].ToString());
                    conexion = new SqlConnection(strConexion);
                    conexion.Open();
                    comando = conexion.CreateCommand();
                    comando.CommandText = "ROP_ArbolROPConsulta";
                    comando.CommandTimeout = 60;
                    comando.CommandType = CommandType.StoredProcedure;
                    comando.Parameters.Clear();
                    comando.Parameters.AddWithValue("@idioma", idioma);
                    comando.Parameters.AddWithValue("@afecta", null);
                    if (cmbConcepto.SelectedValue.ToString() == "OFERTA")
                        comando.Parameters.AddWithValue("@esOferta", true);
                    else
                        comando.Parameters.AddWithValue("@esOferta", false);
                    dtArbol = new System.Data.DataTable();
                    dondeVa = "ROP_ArbolROPConsulta: ejecutar";
                    adaptadorArbol = new SqlDataAdapter(comando);
                    adaptadorArbol.Fill(dtArbol);
                    adaptadorArbol.Dispose();
                    comando.Dispose();
                    conexion.Close();
                    conexion.Dispose();
                    Session["dtArbol"] = dtArbol;
                }

                dondeVa = "FACTURACIÓN: TOTAL FACTURACION";
                totalFacturacion = 0;
                if (dtValores != null && dtValores.Rows.Count > 0)
                {
                    filaEncontrada = dtValores.Select("ETIQUETA = 'TOTAL_FACTURACION'");
                    if (filaEncontrada.Count() != 0)
                    {
                        foreach (DataRow filaValor in filaEncontrada)
                        {
                            if (String.IsNullOrEmpty(filaValor["IMPORTE"].ToString()))
                            {
                                totalFacturacion = Convert.ToDecimal(filaValor["IMPORTE"]);
                                break;
                            }
                        }
                    }
                }

                foreach (DataRow Row in dtArbol.Rows)
                {
                    importe = "0.00";
                    porcentaje = "0.00";
                    importePrevisto = "0.00";
                    porcentajePrevisto = "0.00";

                    int id = Convert.ToInt32(Row.ItemArray[COL_ARBOL_ID]);
                    int? hijoDeId = Row.ItemArray[COL_ARBOL_HIJO_DE] != DBNull.Value ? Convert.ToInt32(Row.ItemArray[COL_ARBOL_HIJO_DE]) : (int?)null;
                    string concepto = Row.ItemArray[COL_ARBOL_CONCEPTO].ToString();
                    string colorCabecera = Row.ItemArray[COL_ARBOL_COLOR].ToString();

                    if (Row.ItemArray[COL_ARBOL_ETIQUETA_TOTAL].ToString() != "")
                    {
                        filaEncontrada = dtValores.Select("ETIQUETA = '" + Row.ItemArray[COL_ARBOL_ETIQUETA_TOTAL].ToString() + "' AND CONCEPTO = '" + capitulo + "'");
                        foreach (DataRow filaValor in filaEncontrada)
                        {
                            conceptoValores = Convert.ToString(filaValor["CONCEPTO"]);
                            importe = Convert.ToString(filaValor["IMPORTE"]);
                            porcentaje = Convert.ToString(filaValor["PORCENTAJE"]);
                            importePrevisto = Convert.ToString(filaValor["IMPORTE PREVISTO"]);
                            porcentajePrevisto = Convert.ToString(filaValor["PORCENTAJE PREVISTO"]);
                            color = Convert.ToString(filaValor["COLOR"]);

                            if (Row.ItemArray[COL_ARBOL_ETIQUETA_TOTAL].ToString().IndexOf("MARGEN") == -1)
                            {
                                if (porcentaje == "0.00" || porcentaje == "0,00")
                                {
                                    if (totalFacturacion == 0)
                                        porcentaje = "0.00";
                                    else
                                        porcentaje = ((Convert.ToDecimal(importe) * 100) / totalFacturacion).ToString("##0.00");

                                    filaValor["PORCENTAJE"] = porcentaje;
                                    filaValor.AcceptChanges();
                                }
                                break;
                            }
                            else
                                dondeVa = "";
                        }
                    }

                    nodo = new JSONArbol();
                    nodo.ID = id.ToString();
                    nodo.Concepto = concepto;
                    nodo.Importe = importe;
                    nodo.Porcentaje = porcentaje;
                    nodo.ImportePrevisto = importePrevisto;
                    nodo.PorcentajePrevisto = porcentajePrevisto;
                    nodo.colorFila = color;
                    nodo.colorEncabezado = colorCabecera;

                    if (hijoDeId.HasValue)
                    {
                        bool encontrado = false;
                        foreach (JSONArbol arbolRaiz in nodos)
                        {
                            if (BuscarNodoYAgregarHijo(arbolRaiz, hijoDeId.ToString(), nodo))
                            {
                                encontrado = true;
                                break; // Si se encuentra en un árbol, no es necesario seguir buscando
                            }
                        }
                        if (!encontrado)
                            nodos.Add(nodo);
                    }
                    else
                    {
                        nodos.Add(nodo);
                    }
                    nodo = null;
                }
                return nodos;
            }
            catch (Exception ex)
            {
                mostrarMensaje("ObtenerArbolDesdeSQL // " + dondeVa + " / " + ex.Message);
                return null;
            }
        }

        protected void pintarArbolCapitulos(ref DataTable dtValores, DataTable dtCapitulos, bool inicial, bool totalesCalculados, bool esFicha, bool pintarArbol)
        {
            List<JSONArbol> estructuraTotal = new List<JSONArbol>();
            List<JSONArbol> arbolDatos = new List<JSONArbol>(); ;
            string dondeVa = "";
            DataTable dtArbol = new DataTable();
            dtArbol = (DataTable)Session["dtArbol"];
            string strConexion;
            SqlConnection conexion;
            SqlCommand comando;
            SqlDataAdapter adaptadorArbol;

            try
            {
                dondeVa = "entrar a pintar arbol";
                if (dtValores == null)
                    return;

                string idioma = Session["idioma"].ToString();
                string usuarioRed = Session["usuarioRed"].ToString();

                string strEntrega = "";
                string strDevolucion = "";
                string strEntregaCapitulo = "";
                string strDevolucionCapitulo = "";
                DataRow[] filaEncontradaED;

                filaEncontradaED = dtIdiomas.Select("ETQ_Control = 'portesEntrega'");
                foreach (DataRow filaValor in filaEncontradaED)
                {
                    if (idioma == "ESPAÑOL")
                        strEntrega = Convert.ToString(filaValor["ETQ_TextoCastellano"]);
                    if (idioma == "CATALAN")
                        strEntrega = Convert.ToString(filaValor["ETQ_TextoCatalan"]);
                    if (idioma == "INGLES")
                        strEntrega = Convert.ToString(filaValor["ETQ_TextoIngles"]);
                }
                filaEncontradaED = dtIdiomas.Select("ETQ_Control = 'portesDevolucion'");
                foreach (DataRow filaValor in filaEncontradaED)
                {
                    if (idioma == "ESPAÑOL")
                        strDevolucion = Convert.ToString(filaValor["ETQ_TextoCastellano"]);
                    if (idioma == "CATALAN")
                        strDevolucion = Convert.ToString(filaValor["ETQ_TextoCatalan"]);
                    if (idioma == "INGLES")
                        strDevolucion = Convert.ToString(filaValor["ETQ_TextoIngles"]);
                }

             
                funcionalidades.guardarTiempo(usuarioRed, "Entra a pintarArbolNuevo", 0);
                if (inicial)
                {
                    dondeVa = "entra a crear estructura nueva";
                    dtValores = new System.Data.DataTable();
                    dtValores.Columns.Add("ETIQUETA");
                    dtValores.Columns.Add("CONCEPTO");
                    dtValores.Columns.Add("IMPORTE", typeof(decimal));
                    dtValores.Columns.Add("PORCENTAJE", typeof(decimal));
                    dtValores.Columns.Add("IMPORTE PREVISTO", typeof(decimal));
                    dtValores.Columns.Add("PORCENTAJE PREVISTO", typeof(decimal));
                    dtValores.Columns.Add("COLOR");
                }

                if (dtArbol.Rows.Count == 0)
                {
                    dondeVa = "ROP_ArbolROPConsulta";
                    dtArbol = new System.Data.DataTable();
                    strConexion = funcionalidades.recuperarTexto(ConfigurationManager.ConnectionStrings["SQL_ROP"].ToString());
                    conexion = new SqlConnection(strConexion);
                    conexion.Open();
                    comando = conexion.CreateCommand();
                    comando.CommandText = "ROP_ArbolROPConsulta";
                    comando.CommandTimeout = 60;
                    comando.CommandType = CommandType.StoredProcedure;
                    comando.Parameters.Clear();
                    comando.Parameters.AddWithValue("@idioma", idioma);
                    comando.Parameters.AddWithValue("@afecta", null);
                    if (cmbConcepto.SelectedValue.ToString() == "OFERTA")
                        comando.Parameters.AddWithValue("@esOferta", true);
                    else
                        comando.Parameters.AddWithValue("@esOferta", false);
                    dtArbol = new System.Data.DataTable();
                    dondeVa = "ROP_ArbolROPConsulta: ejecutar";
                    adaptadorArbol = new SqlDataAdapter(comando);
                    adaptadorArbol.Fill(dtArbol);
                    adaptadorArbol.Dispose();
                    comando.Dispose();
                    conexion.Close();
                    conexion.Dispose();
                    Session["dtArbol"] = dtArbol;
                }

                if (pintarArbol)
                {
                    // copiamos el dtValores a una tabla temporal para seguir operando con ella
                    DataTable dtValoresOriginales;
                    dtValoresOriginales = dtValores.Copy();

                    // ARBOL
                    dondeVa = "inicioJson";
                    foreach (DataRow filaCapitulo in dtCapitulos.Rows)
                    {
                        string concepto = filaCapitulo["CAPITULO"].ToString();

                        strEntregaCapitulo = concepto + " [" + strEntrega + "]";
                        strDevolucionCapitulo = concepto + " [" + strDevolucion + "]";

                        dtValores = null;
                        IEnumerable<DataRow> query = from dtVO in dtValoresOriginales.AsEnumerable()
                                                        where dtVO.Field<string>("CONCEPTO") == concepto
                                                            || dtVO.Field<string>("CONCEPTO") == strEntregaCapitulo
                                                            || dtVO.Field<string>("CONCEPTO") == strDevolucionCapitulo
                                                        select dtVO;
                        dtValores = query.CopyToDataTable<DataRow>();

                        sumarTotalesCapitulos(ref dtValores, concepto);

                        arbolDatos = ObtenerArbolDesdeSQL(filaCapitulo["CAPITULO"].ToString(), dtValores, idioma);
                        estructuraTotal.AddRange(arbolDatos);
                    }
                    string json = JsonConvert.SerializeObject(estructuraTotal);
                    json = json.Replace(",\"hijo\":[]", "");
                    //datosJson = json;
                    string formattedJson = JsonConvert.SerializeObject(JsonConvert.DeserializeObject(json), Formatting.None);
                    datosJson = formattedJson;
                    funcionalidades.guardarTiempo(usuarioRed, "Sale de pintarArbolNuevo", 0);

                    dondeVa = "nombre del doc";
                    string nombreInforme = Server.MapPath("~/Ficheros excel/CAPITULOS_" + cmbConcepto.Text + "_" + txtNumero.Text.Replace("/", "_") + "_" + DateTime.Now.ToString("yyyy_MM_dd") + ".xlsx");
                    dondeVa = "nuevo doc";
                    SLDocument sl = new SLDocument();
                    sl.RenameWorksheet(SLDocument.DefaultFirstSheetName, "Valores");
                    dondeVa = "importar tabla";
                    sl.ImportDataTable(1, 1, dtValores, true);
                    dondeVa = "salvar tabla";
                    sl.SaveAs(nombreInforme);
                    btnAbrirExcel.Visible = true;

                    dtValores = dtValoresOriginales.Copy();
                }
            }
            catch (Exception ex)
            {
                mostrarMensaje("Pintar árbol por capítulos // " + dondeVa + " / " + ex.Message);
            }
        }

