        protected void pintarArbolNUEVO(ref DataTable dtValores, bool inicial, bool totalesCalculados, bool esFicha, bool pintarArbol)
        {
            // constantes para el manejo de los datos del árbol provenientes del SQL
            //int COL_ARBOL_ID = 0;
            int COL_ARBOL_CONCEPTO = 1;
            int COL_ARBOL_COLOR = 2;
            int COL_ARBOL_HIJO_DE = 3;
            int COL_ARBOL_ETIQUETA_DESPLEGABLE = 4;
            int COL_ARBOL_ETIQUETA_TOTAL = 5;

            string estructura = "";

            string armarDesplegableDatos = "";
            SqlDataAdapter adaptadorArbol;
            DataTable dtArbol = new DataTable();
            dtArbol = (DataTable)Session["dtArbol"];
            string hijoVa = "";
            string[] cualVa;
            string hijosAbiertos = "|";
            int cantidad = 0;
            string importe = "";
            string porcentaje = "";
            string importePrevisto = "";
            string porcentajePrevisto = "";
            DataRow[] filaEncontrada;
            decimal totalFacturacion = 0;

            string color = "";
            string dondeVa = "";

            string strConexion;
            SqlConnection conexion;
            SqlCommand comando;

            try
            {
                dondeVa = "entrar a pintar arbol";
                if (dtValores == null)
                    return;

                string idioma = Session["idioma"].ToString();
                string usuarioRed = Session["usuarioRed"].ToString();

                funcionalidades.guardarTiempo(usuarioRed, "Entra a pintarArbolNuevo", 0);
                if (inicial)
                {
                    dondeVa = "entra a crear estructura nueva";
                    dtValores = new System.Data.DataTable();
                    dtValores.Columns.Add("ETIQUETA");
                    dtValores.Columns.Add("CONCEPTO");
                    dtValores.Columns.Add("IMPORTE", typeof(decimal));
                    dtValores.Columns.Add("PORCENTAJE", typeof(decimal));
                    dtValores.Columns.Add("IMPORTE PREVISTO", typeof(decimal));
                    dtValores.Columns.Add("PORCENTAJE PREVISTO", typeof(decimal));
                    dtValores.Columns.Add("COLOR");
                }

                if (dtArbol.Rows.Count == 0)
                {
                    dondeVa = "ROP_ArbolROPConsulta";
                    dtArbol = new System.Data.DataTable();
                    strConexion = funcionalidades.recuperarTexto(ConfigurationManager.ConnectionStrings["SQL_ROP"].ToString());
                    conexion = new SqlConnection(strConexion);
                    conexion.Open();
                    comando = conexion.CreateCommand();
                    comando.CommandText = "ROP_ArbolROPConsulta";
                    comando.CommandTimeout = 60;
                    comando.CommandType = CommandType.StoredProcedure;
                    comando.Parameters.Clear();
                    comando.Parameters.AddWithValue("@idioma", idioma);
                    if (esFicha)
                    {
                        if (Session["strAfecta"] != null)
                            comando.Parameters.AddWithValue("@afecta", Session["strAfecta"]);
                        else
                            comando.Parameters.AddWithValue("@afecta", null);
                    }
                    else
                        comando.Parameters.AddWithValue("@afecta", null);
                    if (cmbConcepto.SelectedValue.ToString() == "OFERTA")
                        comando.Parameters.AddWithValue("@esOferta", true);
                    else
                        comando.Parameters.AddWithValue("@esOferta", false);
                    dtArbol = new System.Data.DataTable();
                    dondeVa = "ROP_ArbolROPConsulta: ejecutar";
                    adaptadorArbol = new SqlDataAdapter(comando);
                    adaptadorArbol.Fill(dtArbol);
                    adaptadorArbol.Dispose();
                    comando.Dispose();
                    conexion.Close();
                    conexion.Dispose();
                    Session["dtArbol"] = dtArbol;
                }

                if (!totalesCalculados && dtValores.Rows.Count > 0)
                {
                    funcionalidades.guardarTiempo(usuarioRed, "llama a sumarTotales", 0);
                    dondeVa = "sumarTotales";
                    sumarTotales(ref dtValores);
                    if (cmbConcepto.SelectedValue.ToString().ToUpper() == "FICHA" || cmbConcepto.SelectedValue.ToString().ToUpper() == "FICHA NEW")
                    {
                        funcionalidades.guardarTiempo(usuarioRed, "llama a sumarTotalesPrevisto", 0);
                        dondeVa = "sumarTotalesPrevisto";
                        sumarTotalesPrevisto(ref dtValores);
                    }
                    totalesCalculados = true;
                }

                if (pintarArbol)
                {
                    // FACTURACIÓN: TOTAL FACTURACION
                    dondeVa = "FACTURACIÓN: TOTAL FACTURACION";
                    totalFacturacion = 0;
                    if (dtValores != null && dtValores.Rows.Count > 0)
                    {
                        filaEncontrada = dtValores.Select("ETIQUETA = 'TOTAL_FACTURACION'");
                        if (filaEncontrada.Count() != 0)
                        {
                            foreach (DataRow filaValor in filaEncontrada)
                            {
                                if (String.IsNullOrEmpty(filaValor["IMPORTE"].ToString()))
                                {
                                    totalFacturacion = Convert.ToDecimal(filaValor["IMPORTE"]);
                                    break;
                                }
                            }
                        }
                    }

                    // ARBOL
                    dondeVa = "inicioJson";
                    estructura = inicioJson;
                    estructura = estructura + inicioCabecera;
                    foreach (DataRow Row in dtArbol.Rows)
                    {
                        importe = "0.00";
                        porcentaje = "0.00";
                        importePrevisto = "0.00";
                        porcentajePrevisto = "0.00";
                        if (Row.ItemArray[COL_ARBOL_ETIQUETA_TOTAL].ToString() != "" && !inicial)
                        {
                            dondeVa = "ETIQUETA antes 1";
                            filaEncontrada = dtValores.Select("ETIQUETA = '" + Row.ItemArray[COL_ARBOL_ETIQUETA_TOTAL].ToString() + "'");
                            if (filaEncontrada.Length > 0)
                            {
                                foreach (DataRow filaValor in filaEncontrada)
                                {
                                    dondeVa = "1";
                                    importe = Convert.ToString(filaValor["IMPORTE"]);
                                    porcentaje = Convert.ToString(filaValor["PORCENTAJE"]);
                                    importePrevisto = Convert.ToString(filaValor["IMPORTE PREVISTO"]);
                                    porcentajePrevisto = Convert.ToString(filaValor["PORCENTAJE PREVISTO"]);
                                    color = Convert.ToString(filaValor["COLOR"]);

                                    if (Row.ItemArray[COL_ARBOL_ETIQUETA_TOTAL].ToString().IndexOf("MARGEN") == -1)
                                    {
                                        if (porcentaje == "0.00" || porcentaje == "0,00")
                                        {
                                            if (totalFacturacion == 0)
                                                porcentaje = "0.00";
                                            else
                                                porcentaje = ((Convert.ToDecimal(importe) * 100) / totalFacturacion).ToString("##0.00");

                                            filaValor["PORCENTAJE"] = porcentaje;
                                            filaValor.AcceptChanges();
                                        }
                                        break;
                                    }
                                    else
                                        dondeVa = "";
                                }
                            }
                        }

                        if (importePrevisto == "")
                            importePrevisto = "0.00";
                        if (porcentajePrevisto == "")
                            porcentajePrevisto = "0.00";

                        if (Convert.ToInt32(Row.ItemArray[COL_ARBOL_HIJO_DE]) == 0)
                        {
                            cualVa = hijoVa.Split('|');
                            // No hay ninguna rama hijo
                            if (cualVa.GetUpperBound(0) != 0)
                            {
                                while (cualVa.GetUpperBound(0) != 0)
                                {
                                    dondeVa = "2";
                                    estructura = estructura + finHijo;
                                    hijoVa = hijoVa.Replace(cualVa[0] + "|", "");
                                    cualVa = hijoVa.Split('|');
                                    if (cualVa.GetUpperBound(0) == 0)
                                    {
                                        estructura = estructura + finCabeceraSiguiente;
                                        estructura = estructura + inicioCabecera;
                                        break;
                                    }
                                }
                            }

                            if (estructura.Substring((estructura.Length - 1), 1) != "{")
                            {
                                if (estructura.Substring((estructura.Length - 1), 1) != "}")
                                    estructura = estructura + finCabeceraSiguiente;
                                estructura = estructura + inicioCabecera;
                            }
                            dondeVa = "3";
                            estructura = estructura + cabecera;
                            estructura = estructura.Replace("__CAPITULO__", Row.ItemArray[COL_ARBOL_CONCEPTO].ToString());
                            estructura = estructura.Replace("__importeCapitulo__", Convert.ToDecimal(importe).ToString("#,#0.00"));
                            estructura = estructura.Replace("__porcentajeCapitulo__", Convert.ToDecimal(porcentaje).ToString("#,#0.00"));
                            estructura = estructura.Replace("__importeCapituloPrevisto__", Convert.ToDecimal(importePrevisto).ToString("#,#0.00"));
                            estructura = estructura.Replace("__porcentajeCapituloPrevisto__", Convert.ToDecimal(porcentajePrevisto).ToString("#,#0.00"));
                            estructura = estructura.Replace("__color__", Row.ItemArray[COL_ARBOL_COLOR].ToString());
                            estructura = estructura.Replace("__colorFila__", color);

                        }
                        else
                        {
                            //hayFinCabecera = false;

                            cualVa = hijoVa.Split('|');
                            // No hay ninguna rama hijo
                            if (cualVa.GetUpperBound(0) == 0)
                            {
                                dondeVa = "4";
                                estructura = estructura + inicioHijo;
                                estructura = estructura + primerHijo;
                                estructura = estructura.Replace("__CAPITULO__", Row.ItemArray[COL_ARBOL_CONCEPTO].ToString());
                                estructura = estructura.Replace("__importeCapitulo__", Convert.ToDecimal(importe).ToString("#,#0.00"));
                                estructura = estructura.Replace("__porcentajeCapitulo__", Convert.ToDecimal(porcentaje).ToString("#,#0.00"));
                                estructura = estructura.Replace("__importeCapituloPrevisto__", Convert.ToDecimal(importePrevisto).ToString("#,#0.00"));
                                estructura = estructura.Replace("__porcentajeCapituloPrevisto__", Convert.ToDecimal(porcentajePrevisto).ToString("#,#0.00"));
                                estructura = estructura.Replace("__color__", Row.ItemArray[COL_ARBOL_COLOR].ToString());
                                estructura = estructura.Replace("__colorFila__", color);
                                hijoVa = Row.ItemArray[COL_ARBOL_HIJO_DE].ToString() + "|";
                                hijosAbiertos = hijosAbiertos + "|" + Row.ItemArray[COL_ARBOL_HIJO_DE].ToString();
                            }
                            else
                            {

                                if (Convert.ToInt32(cualVa[0]) != Convert.ToInt32(Row.ItemArray[COL_ARBOL_HIJO_DE]))
                                {
                                    if (Convert.ToInt32(cualVa[0]) > Convert.ToInt32(Row.ItemArray[COL_ARBOL_HIJO_DE]))
                                    {
                                        while (Convert.ToInt32(cualVa[0]) > Convert.ToInt32(Row.ItemArray[COL_ARBOL_HIJO_DE]))
                                        {
                                            dondeVa = "5";
                                            estructura = estructura + finHijo;
                                            hijoVa = hijoVa.Replace(cualVa[0] + "|", "");
                                            cualVa = hijoVa.Split('|');
                                            if (cualVa.GetUpperBound(0) == 0)
                                                break;
                                        }

                                        if (Convert.ToInt32(Row.ItemArray[COL_ARBOL_HIJO_DE]) == 0)
                                        {
                                            dondeVa = "6";
                                            estructura = estructura + cabecera;
                                            estructura = estructura.Replace("__CAPITULO__", Row.ItemArray[COL_ARBOL_CONCEPTO].ToString());
                                            estructura = estructura.Replace("__importeCapitulo__", Convert.ToDecimal(importe).ToString("#,#0.00"));
                                            estructura = estructura.Replace("__porcentajeCapitulo__", Convert.ToDecimal(porcentaje).ToString("#,#0.00"));
                                            estructura = estructura.Replace("__importeCapituloPrevisto__", Convert.ToDecimal(importePrevisto).ToString("#,#0.00"));
                                            estructura = estructura.Replace("__porcentajeCapituloPrevisto__", Convert.ToDecimal(porcentajePrevisto).ToString("#,#0.00"));
                                            estructura = estructura.Replace("__color__", Row.ItemArray[COL_ARBOL_COLOR].ToString());
                                            estructura = estructura.Replace("__colorFila__", color);

                                        }
                                        else
                                        {
                                            if (hijosAbiertos.IndexOf("|" + Row.ItemArray[COL_ARBOL_HIJO_DE].ToString() + "|") >= 0)
                                                estructura = estructura + siguienteHijo;
                                            else
                                            {
                                                estructura = estructura + inicioHijo;
                                                estructura = estructura + primerHijo;
                                            }
                                            dondeVa = "7";
                                            estructura = estructura.Replace("__CAPITULO__", Row.ItemArray[COL_ARBOL_CONCEPTO].ToString());
                                            estructura = estructura.Replace("__importeCapitulo__", Convert.ToDecimal(importe).ToString("#,#0.00"));
                                            estructura = estructura.Replace("__porcentajeCapitulo__", Convert.ToDecimal(porcentaje).ToString("#,#0.00"));
                                            estructura = estructura.Replace("__importeCapituloPrevisto__", Convert.ToDecimal(importePrevisto).ToString("#,#0.00"));
                                            estructura = estructura.Replace("__porcentajeCapituloPrevisto__", Convert.ToDecimal(porcentajePrevisto).ToString("#,#0.00"));
                                            estructura = estructura.Replace("__color__", Row.ItemArray[COL_ARBOL_COLOR].ToString());
                                            estructura = estructura.Replace("__colorFila__", color);
                                            if (hijoVa.IndexOf("|" + Row.ItemArray[COL_ARBOL_HIJO_DE].ToString() + "|") == 0)
                                                hijoVa = Row.ItemArray[COL_ARBOL_HIJO_DE].ToString() + "|" + hijoVa;
                                            hijosAbiertos = hijosAbiertos + "|" + Row.ItemArray[COL_ARBOL_HIJO_DE].ToString();
                                        }
                                    }
                                    else
                                    {
                                        if (hijosAbiertos.IndexOf("|" + Row.ItemArray[COL_ARBOL_HIJO_DE].ToString() + "|") >= 0)
                                            estructura = estructura + siguienteHijo;
                                        else
                                        {
                                            estructura = estructura + inicioHijo;
                                            estructura = estructura + primerHijo;
                                        }
                                        dondeVa = "8";
                                        estructura = estructura.Replace("__CAPITULO__", Row.ItemArray[COL_ARBOL_CONCEPTO].ToString());
                                        estructura = estructura.Replace("__importeCapitulo__", Convert.ToDecimal(importe).ToString("#,#0.00"));
                                        estructura = estructura.Replace("__porcentajeCapitulo__", Convert.ToDecimal(porcentaje).ToString("#,#0.00"));
                                        estructura = estructura.Replace("__importeCapituloPrevisto__", Convert.ToDecimal(importePrevisto).ToString("#,#0.00"));
                                        estructura = estructura.Replace("__porcentajeCapituloPrevisto__", Convert.ToDecimal(porcentajePrevisto).ToString("#,#0.00"));
                                        estructura = estructura.Replace("__color__", Row.ItemArray[COL_ARBOL_COLOR].ToString());
                                        estructura = estructura.Replace("__colorFila__", color);
                                        hijoVa = Row.ItemArray[COL_ARBOL_HIJO_DE].ToString() + "|" + hijoVa;
                                        hijosAbiertos = hijosAbiertos + "|" + Row.ItemArray[COL_ARBOL_HIJO_DE].ToString();
                                    }
                                }
                                else
                                {
                                    dondeVa = "9";
                                    estructura = estructura + siguienteHijo;
                                    estructura = estructura.Replace("__CAPITULO__", Row.ItemArray[COL_ARBOL_CONCEPTO].ToString());
                                    estructura = estructura.Replace("__importeCapitulo__", Convert.ToDecimal(importe).ToString("#,#0.00"));
                                    estructura = estructura.Replace("__porcentajeCapitulo__", Convert.ToDecimal(porcentaje).ToString("#,#0.00"));
                                    estructura = estructura.Replace("__importeCapituloPrevisto__", Convert.ToDecimal(importePrevisto).ToString("#,#0.00"));
                                    estructura = estructura.Replace("__porcentajeCapituloPrevisto__", Convert.ToDecimal(porcentajePrevisto).ToString("#,#0.00"));
                                    estructura = estructura.Replace("__color__", Row.ItemArray[COL_ARBOL_COLOR].ToString());
                                    estructura = estructura.Replace("__colorFila__", color);
                                }
                            }
                        }

                        if (Row.ItemArray[COL_ARBOL_ETIQUETA_DESPLEGABLE].ToString() != "" && !inicial)
                        {
                            cantidad = 0;
                            armarDesplegableDatos = "";
                            dondeVa = "ETIQUETA antes 10";
                            filaEncontrada = dtValores.Select("ETIQUETA = '" + Row.ItemArray[COL_ARBOL_ETIQUETA_DESPLEGABLE].ToString() + "'");
                            if (filaEncontrada.Length > 0)
                            {
                                foreach (DataRow filaValor in filaEncontrada)
                                {
                                    dondeVa = "10";
                                    importe = Convert.ToString(filaValor["IMPORTE"]);
                                    porcentaje = Convert.ToString(filaValor["PORCENTAJE"]);
                                    if (Convert.ToString(filaValor["IMPORTE PREVISTO"]) != "")
                                    {
                                        importePrevisto = Convert.ToString(filaValor["IMPORTE PREVISTO"]);
                                        porcentajePrevisto = Convert.ToString(filaValor["PORCENTAJE PREVISTO"]);
                                    }
                                    else
                                    {
                                        importePrevisto = "0.00";
                                        porcentajePrevisto = "0.00";
                                    }
                                    color = Convert.ToString(filaValor["COLOR"]);

                                    if ((porcentaje == "0.00" || porcentaje == "0,00") && Row.ItemArray[COL_ARBOL_ETIQUETA_DESPLEGABLE].ToString().IndexOf("MARGEN") == -1)
                                    {
                                        if (totalFacturacion == 0)
                                            porcentaje = "0.00";
                                        else
                                            porcentaje = ((Convert.ToDecimal(importe) * 100) / totalFacturacion).ToString("##0.00");

                                        filaValor["PORCENTAJE"] = porcentaje;
                                        filaValor.AcceptChanges();
                                    }
                                    else
                                        dondeVa = "";

                                    if (cantidad == 0)
                                    {
                                        dondeVa = "11";
                                        armarDesplegableDatos = inicioHijo + primerHijo;
                                        dondeVa = "11-1";
                                        armarDesplegableDatos = armarDesplegableDatos.Replace("__CAPITULO__", Convert.ToString(filaValor["CONCEPTO"]));
                                        dondeVa = "11-2";
                                        armarDesplegableDatos = armarDesplegableDatos.Replace("__importeCapitulo__", Convert.ToDecimal(importe).ToString("#,#0.00"));
                                        dondeVa = "11-3";
                                        armarDesplegableDatos = armarDesplegableDatos.Replace("__porcentajeCapitulo__", Convert.ToDecimal(porcentaje).ToString("#,#0.00"));
                                        dondeVa = "11-4";
                                        armarDesplegableDatos = armarDesplegableDatos.Replace("__importeCapituloPrevisto__", Convert.ToDecimal(importePrevisto).ToString("#,#0.00"));
                                        dondeVa = "11-5";
                                        armarDesplegableDatos = armarDesplegableDatos.Replace("__porcentajeCapituloPrevisto__", Convert.ToDecimal(porcentajePrevisto).ToString("#,#0.00"));
                                        dondeVa = "11-6";
                                        armarDesplegableDatos = armarDesplegableDatos.Replace("__color__", Row.ItemArray[COL_ARBOL_COLOR].ToString());
                                        dondeVa = "11-7";
                                        armarDesplegableDatos = armarDesplegableDatos.Replace("__colorFila__", color);
                                        dondeVa = "11-8";
                                    }
                                    else
                                    {
                                        dondeVa = "12";
                                        armarDesplegableDatos = armarDesplegableDatos + siguienteHijo;
                                        armarDesplegableDatos = armarDesplegableDatos.Replace("__CAPITULO__", Convert.ToString(filaValor["CONCEPTO"]));
                                        armarDesplegableDatos = armarDesplegableDatos.Replace("__importeCapitulo__", Convert.ToDecimal(importe).ToString("#,#0.00"));
                                        armarDesplegableDatos = armarDesplegableDatos.Replace("__porcentajeCapitulo__", Convert.ToDecimal(porcentaje).ToString("#,#0.00"));
                                        armarDesplegableDatos = armarDesplegableDatos.Replace("__importeCapituloPrevisto__", Convert.ToDecimal(importePrevisto).ToString("#,#0.00"));
                                        armarDesplegableDatos = armarDesplegableDatos.Replace("__porcentajeCapituloPrevisto__", Convert.ToDecimal(porcentajePrevisto).ToString("#,#0.00"));
                                        armarDesplegableDatos = armarDesplegableDatos.Replace("__color__", Row.ItemArray[COL_ARBOL_COLOR].ToString());
                                        armarDesplegableDatos = armarDesplegableDatos.Replace("__colorFila__", color);
                                    }
                                    cantidad = cantidad + 1;
                                }
                            }
                            if (armarDesplegableDatos != "")
                            {
                                dondeVa = "13";
                                armarDesplegableDatos = armarDesplegableDatos + finHijo;
                                estructura = estructura + armarDesplegableDatos;
                            }
                        }
                    }
                    cualVa = hijoVa.Split('|');
                    while (cualVa.GetUpperBound(0) != 0)
                    {
                        dondeVa = "14";
                        estructura = estructura + finHijo;
                        hijoVa = hijoVa.Replace(cualVa[0] + "|", "");
                        cualVa = hijoVa.Split('|');
                    }

                    estructura = estructura + finCabecera;
                    estructura = estructura + finJson;
                    estructura = estructura.Replace("__id__", "");

                    // datosJson = estructura;
                    //aca hace un parse del json "estructura" si funciona bien manda ese parse a string en la variable datosJson
                    string formattedJson = JsonConvert.SerializeObject(JsonConvert.DeserializeObject(estructura), Formatting.None);
