                                            {
                                                fechaPrecios = Convert.ToDateTime(filaCapitulo["FECHA"].ToString()).AddDays((-1) * diasRestar);
                                                tabla = "Pedido-SalesQuotationTable";
                                                campo = "CreatedDateTime - " + diasRestar.ToString();
