                                    dtPortes.Rows.Add(oPorte);
                                    oPorte = null;

                                    dondeVa = "VENTAS: Gastos fijos";
                                    // CALCULO GASTOS FIJOS Y AJUSTES DURACION OBRA POR LINEA
