                                        BUimporteLinea = (KABU * costeAlquiler);
                                        centralImporteLinea = (KAHQ * costeAlquiler);
                                    }

                                    GF = 0;
                                    if (ajustesAlcance == "GF BU")
                                        GF = BUimporteLinea;
