                            var parameter = new SqlParameter
                            {
                                SqlDbType = SqlDbType.Structured, //El tipo Structured es el que se tomara la estructura del Data Table para
                                ParameterName = "temporalValores", //Hacer match con el Tipo Table en SQL, respetando el nombre declarado en el StoreProcedure
                                Value = dtValores
                            };
                            comando.Parameters.Add(parameter);
