                                    else
                                        filaMovimiento["PORCENTAJE"] = 0;

                                    totalImporte = Convert.ToDecimal(Convert.ToDouble(totalImporte) + (Convert.ToDouble(totalPositivo + totalNegativo) * Convert.ToDouble(filaMovimiento["PVP"])));

                                    dtPendienteDevolver.Rows.Add(filaMovimiento);
                                    filaMovimiento = null;
                                    numeroPendienteDevolver = numeroPendienteDevolver + 1;
