                                    if (filaEncontrada.Length > 0)
                                        fechaFactura = dtFacturasLineas.AsEnumerable()
                                            .Where(y => y.Field<int>("CANON") == 0 && y.Field<string>("ITEM") == fila["ITEM NEGATIVO"].ToString() && y.Field<string>("SALES TYPE") == WSGeneral.SalesType.Alquiler.ToString().ToUpper())
