                        //    .Where(y => y.Field<string>("AAF") == AAF)
                        //    .Sum(x => (Convert.ToDecimal(x.Field<string>("PS entregado")) * Convert.ToDecimal(x.Field<string>("Unidades alquiler"))));

                        total = dtBuenTrato.AsEnumerable()
