                            porcentajeAmortizado = 0;

                        // CALCULAR BUEN TRATO: VME
                        totalMPO = Math.Abs(totalMPO);
                        if (totalMPO > 0) // se resta primero del nuevo
                        {
                            dondeVa = "calcular donde resta MPO";
