                            oItemAbonoMPO["COSTE MPO"] = (totalChatarraNuevas + totalChatarraUsadas).ToString("#,##0.00");
                            oItemAbonoMPO["ABONO MAX 1"] = abonoMax1.ToString("#,##0.00");
                            oItemAbonoMPO["ABONO MAX 2"] = abonoMax2.ToString("#,##0.00");
