                            oItemAbonoMPO = null;

                            //if (lineasxarticulo)
                            //{
                            //    filaValores = dtValoresFichaArticulos.NewRow();
                            //    filaValores["ETIQUETA"] = "TOTAL_ABONO_MPO_TNC";
                            //    filaValores["CONCEPTO"] = obra + " / " + nombreFicha;
