                    }

                    // 26/05/2024 recuperamos los datos de la tabla de TAX: NUEVO CALCULO DE ABONO MPO
                    // 'SALESJOBSITEOUT', 'LOSTJOBSITEOUT', 'RENTDEVOLUTIONSCRAPOUT'
                    abonoMPOTC = 0;
                    abonoMPOTNC = 0;
                    // TAX CONSUMIBLE
                    dondeVa = "Nuevo(re) cálculo de Abono MPO - Movimientos en negativo";
                    if (dtTax.Rows.Count > 0)
