                                                      || d.Field<string>("TIPO MOVIMIENTO NEGATIVO").ToUpper() == "RENTDEVOLUTIONSCRAPOUT")
                                                      && d.Field<decimal>("TAX CONSUMIBLE") != 0)
                                                group d by new
                                                {
                                                    ITEM = d.Field<string>("ITEM"),
                                                    MOVIMIENTO = d.Field<string>("TIPO MOVIMIENTO NEGATIVO"),
