                                                    CANTIDAD = grupo.Sum(x => x.Field<decimal>("CANTIDAD")),
                                                    TAXCONSUMIBLE = grupo.Sum(x => x.Field<decimal>("TAX CONSUMIBLE")),
                                                    BONIFICACION = grupo.Sum(x => x.Field<decimal>("BONIFICACION")),
                                                };

                        foreach (var itemResultados in dataResultadosTax)
                        {
                            // COSTE MPO
                            
                            decimal abonoMPO = 0;
                            dondeVa = "COSTE MPO " + itemResultados.ITEM.ToString();

                            decimal decImporteCosteMPOItem = dtCosteMPO.AsEnumerable()
