                                    .Sum(x => Convert.ToDecimal(x.Field<decimal>("IMPORTE")));

                            decimal decChatarraMPOItem = 0;
                            if (itemResultados.MOVIMIENTO.ToString().ToUpper() == "RENTDEVOLUTIONSCRAPOUT")
                            {
