                                                where ((d.Field<string>("TIPO MOVIMIENTO NEGATIVO").ToUpper() == "SALESJOBSITEOUT"
                                                    || d.Field<string>("TIPO MOVIMIENTO NEGATIVO").ToUpper() == "LOSTJOBSITEOUT"
