                            decimal abonoMPO = 0;
                            dondeVa = "COSTE MPO " + itemResultados.ITEM.ToString();

                            decimal decImporteCosteMPOItem = dtCosteMPO.AsEnumerable()
                                    .Where(y => y.Field<string>("ITEM") == itemResultados.ITEM.ToString() && Convert.ToDateTime(y.Field<DateTime>("FECHA").ToString("dd/MM/yyyy")) == Convert.ToDateTime(itemResultados.FECHA.ToString("dd/MM/yyyy")))
                                    .Sum(x => Convert.ToDecimal(x.Field<decimal>("IMPORTE")));

