                            if (abonar != 0)
                            {
                                // Si se limita calculo el abono según coste, si no el abono es el del cálculo TAX
                                if (limitarAbonoTaxMPO)
                                {
                                    abonoMax1 = ((decImporteCosteMPOItem + decChatarraMPOItem) * porcentajeAbonoTaxMPO) / 100;
                                    abonoMax2 = (abonar * porcentajeMaxAbonoTaxMPO) / 100;
                                }
                                else
                                {
                                    abonoMax1 = abonar;
                                    abonoMax2 = abonar;
                                }

