                                abonoMax2 = Math.Abs(abonoMax2);

                                dondeVa = "calcular incluir datatable dtAbonoMPONuevo";
                                oItemAbonoMPO = dtAbonoMPONuevo.NewRow();
                                oItemAbonoMPO["ITEM"] = itemResultados.ITEM.ToString();
                                oItemAbonoMPO["LIQUIDADAS"] = uLiquidadas;
                                oItemAbonoMPO["TIPO"] = "NO CONSUMIBLE";
                                oItemAbonoMPO["COSTE MPO"] = decImporteCosteMPOItem + decChatarraMPOItem;
                                oItemAbonoMPO["ABONO MAX 1"] = abonoMax1;
                                oItemAbonoMPO["ABONO CALCULADO"] = abonar;
                                oItemAbonoMPO["ABONO MAX 2"] = abonoMax2;
                                if (abonoMax1 < abonoMax2)
                                {
                                    oItemAbonoMPO["ABONO MPO"] = abonoMax1;
