                    }

                    dondeVa = "Calculo de gastos patio";
                    decimal totalClasificacionReparacion = 0;
                    importeGastosVariablesClasificacionReparacion = 0;
                    totalClasificacionReparacion = dtGastosPatioCalculo.AsEnumerable()
                            .Sum(x => Convert.ToDecimal(x.Field<decimal>("TOTAL CLASIFICAR REPARAR DIRECTO")));

                    importeGastosVariablesClasificacionReparacion = importeGastosVariablesClasificacionReparacion + totalClasificacionReparacion;

