                    totalClasificacionReparacion = dtGastosPatioCalculo.AsEnumerable()
                            .Sum(x => Convert.ToDecimal(x.Field<decimal>("TOTAL REPARAR DIRECTO")));

                    importeGastosVariablesClasificacionReparacion = importeGastosVariablesClasificacionReparacion + totalClasificacionReparacion;

                    totalClasificacionReparacion = dtGastosPatioCalculo.AsEnumerable()
                           .Sum(x => Convert.ToDecimal(x.Field<decimal>("TOTAL REPARAR INDIRECTO")));

                    importeGastosVariablesClasificacionReparacion = importeGastosVariablesClasificacionReparacion + totalClasificacionReparacion;

                    decimal totalAlquiler = 0;
                    decimal totalVenta = 0;
                    decimal totalPortes = 0;
                    decimal totalGastosOficinaAdministrativoCapitulo = 0;
                    decimal totalGastosOficinaDTCapitulo = 0;
                    decimal totalGastosOficinaComercialCapitulo = 0;

                    totalAlquiler = importeFacturacionAlquiler;
                    totalVenta = importeFacturacionVentaProducto + importeFacturacionVentaLiquidacion + importeFacturacionVentaMalUso + importeFacturacionVentaMontajes + importeFacturacionVentaDepartamentoTecnico + importeFacturacionVentFenolicoNuevo + importeFacturacionVentaUneCif + importeFacturacionVentaOtrosServicios;
                    totalPortes = importePorteEntrega_TR001 + importePorteDevolucion_TR001;

                    if (calcularConPortes)
                        total = totalAlquiler + totalVenta + totalPortes;
