                    // CALCULO GASTOS FIJOS Y AJUSTES DURACION OBRA POR LINEA
                    dondeVa = "Gastos Fijos y ajustes duración obra";
                    decimal diasCalculoGF = 0;
                    for (i = 0; i < dtTax.Rows.Count; i++)
                    {
                        item = Convert.ToString(dtTax.Rows[i]["ITEM"]).ToUpper();
                        diasCalculoGF = Convert.ToDecimal(dtTax.Rows[i]["DIAS"]);

                        decimal importeAlquilerProducto = 0;
                        decimal totalUnidadesDia = 0;
                        decimal importeFacturadoItem = 0;
                        decimal euroDia = 0;

                        DataRow oFila;
                        oFila = dtAjustesGF.NewRow();
                        oFila["ITEM"] = item;
                        totalUnidadesDia = dtTax.AsEnumerable()
                             .Where(y => y.Field<string>("ITEM") == item)
                             .Sum(x => Convert.ToDecimal(x.Field<decimal>("UNIDADES-DIA")));

                        importeFacturadoItem = 0;
                        if (dtFacturasLineas.Rows.Count > 0)
                            importeFacturadoItem = dtFacturasLineas.AsEnumerable()
                                 .Where(y => y.Field<int>("CANON") == 0 && y.Field<string>("OBRA") == obra && y.Field<string>("ITEM") == item && y.Field<string>("SALES TYPE").ToUpper() == WSGeneral.SalesType.Alquiler.ToString().ToUpper())
                                 .Sum(x => Convert.ToDecimal(x.Field<decimal>("IMPORTE")));

                        if (totalUnidadesDia != 0)
                            euroDia = importeFacturadoItem / totalUnidadesDia;

                        importeAlquilerProducto = Math.Abs(Convert.ToDecimal(dtTax.Rows[i]["CANTIDAD"])) * diasCalculoGF * euroDia;
                        oFila["CANTIDAD"] = Math.Abs(Convert.ToInt32(dtTax.Rows[i]["CANTIDAD"]));
                        oFila["DIAS"] = diasCalculoGF;
                        oFila["EURO DIA"] = euroDia;
                        oFila["IMPORTE ALQUILER"] = importeAlquilerProducto;

                        if (gastosFijosPorFacturacion)
                        {
                            BUimporteLinea = (Math.Abs(KABU) * importeAlquilerProducto);
                            centralImporteLinea = (Math.Abs(KAHQ) * importeAlquilerProducto);
                        }
                        else
                        {
                            costeAlquiler = Convert.ToDecimal(dtTax.Rows[i]["TAX CONSUMIBLE"]) + Convert.ToDecimal(dtTax.Rows[i]["TAX NO CONSUMIBLE"]) - Convert.ToDecimal(dtTax.Rows[i]["BONIFICACION"]);
                            costeAlquiler = (-1) * costeAlquiler;
                            BUimporteLinea = (KABU * costeAlquiler);
                            centralImporteLinea = (KAHQ * costeAlquiler);
                        }

                        GF = 0;
                        if (ajustesAlcance == "GF BU")
                            GF = BUimporteLinea;
                        else
                            GF = BUimporteLinea + centralImporteLinea;

                        oFila["KABU"] = Math.Abs(KABU);
                        oFila["KAHQ"] = Math.Abs(KAHQ);
                        oFila["BU IMPORTE LINEA"] = BUimporteLinea;
                        oFila["CENTRAL IMPORTE LINEA"] = centralImporteLinea;
                        GF = Math.Abs(GF);
                        if (diasCalculoGF > 0)
                            GF = (-1) * GF;
                        oFila["GF"] = GF;

                        if (item == "37603")
                            dondeVa = "";
                        bool diasNegativos = false;
                        if (diasCalculoGF < 0)
                        {
                            diasCalculoGF = Math.Abs(diasCalculoGF);
                            diasNegativos = true;
                        }

                        if (diasCalculoGF < 0)
                            porcentajeAjustesObraDuracionGFCapitulo = 0;
                        else if (diasCalculoGF == 0)
                            porcentajeAjustesObraDuracionGFCapitulo = ajustesPocentajeCargoMaximo;
                        else if (diasCalculoGF == ajustesValorObraCorta)
                            porcentajeAjustesObraDuracionGFCapitulo = ajustesPorcentajeCorreccionObraCorta;
                        else if (diasCalculoGF == ajustesValorObraLarga)
                            porcentajeAjustesObraDuracionGFCapitulo = ajustesPorcentajeCorreccionObraLarga;
                        else if (diasCalculoGF > ajustesValorMaximo)
                            porcentajeAjustesObraDuracionGFCapitulo = ajustesPorcentajeCorreccionMaximo;
                        else
                            porcentajeAjustesObraDuracionGFCapitulo = funcionalidades.interpolacion(dtAjustesDuracionGF, Convert.ToInt32(diasCalculoGF));
                        importeAjustesObraDuracionGF = importeAjustesObraDuracionGF + (GF * porcentajeAjustesObraDuracionGFCapitulo);
                        oFila["PORCENTAJE AJUSTE"] = porcentajeAjustesObraDuracionGFCapitulo;
                        if (diasNegativos)
                        {
                            oFila["IMPORTE AJUSTE ORIGINAL"] = (-1) * Math.Abs(GF * porcentajeAjustesObraDuracionGFCapitulo);
                            oFila["IMPORTE AJUSTE"] = (-1) * Math.Abs(GF * porcentajeAjustesObraDuracionGFCapitulo);
                        }
                        else
                        {
                            oFila["IMPORTE AJUSTE ORIGINAL"] = Math.Abs(GF * porcentajeAjustesObraDuracionGFCapitulo);
                            oFila["IMPORTE AJUSTE"] = Math.Abs(GF * porcentajeAjustesObraDuracionGFCapitulo);
                        }
                        dtAjustesGF.Rows.Add(oFila);
                        oFila = null;
                    }

                    // AJUSTE GASTOS FIJOS POR DURACIÓN
                    importeAjustesObraDuracionGF = 0;
                    var itemsDistintosGF = dtAjustesGF.AsEnumerable().Select(row => row.Field<string>("ITEM")).Distinct();
                    foreach (var strItem in itemsDistintosGF)
                    {
                        decimal decGF = dtAjustesGF.AsEnumerable()
                                    .Where(y => y.Field<string>("ITEM") == strItem)
                                    .Sum(x => Convert.ToDecimal(x.Field<decimal>("GF")));

                        decimal ajusteGFDuracion = dtAjustesGF.AsEnumerable()
                                .Where(y => y.Field<string>("ITEM") == strItem)
                                .Sum(x => Convert.ToDecimal(x.Field<decimal>("IMPORTE AJUSTE ORIGINAL")));


                        if (decGF < 0)
                        {
                            if (ajusteGFDuracion < 0)
                                ajusteGFDuracion = 0;
                        }
                        else
                        {
                            if (ajusteGFDuracion > 0)
                                ajusteGFDuracion = 0;
                        }

                        if (ajusteGFDuracion == 0)
                        {
                            DataRow[] filasSeleccionadas = dtAjustesGF.Select("ITEM = '" + strItem + "'");
                            foreach (DataRow row in filasSeleccionadas)
                            {
                                row["IMPORTE AJUSTE"] = 0;
                                row.AcceptChanges();
                            }
                        }
                    }

                    // TOPE
                    importeAjustesObraDuracionGF = 0;
                    itemsDistintosGF = dtAjustesGF.AsEnumerable().Select(row => row.Field<string>("ITEM")).Distinct();
                    foreach (var strItem in itemsDistintosGF)
                    {
                        decimal decGF = dtAjustesGF.AsEnumerable()
                                    .Where(y => y.Field<string>("ITEM") == strItem)
                                    .Sum(x => Convert.ToDecimal(x.Field<decimal>("GF")));

                        decimal ajusteGFDuracion = dtAjustesGF.AsEnumerable()
                                .Where(y => y.Field<string>("ITEM") == strItem)
                                .Sum(x => Convert.ToDecimal(x.Field<decimal>("IMPORTE AJUSTE")));

                        decimal topeAjusteGF = decGF * ajustesPorcentajeCorreccionMaximo;

                        if (Math.Abs(topeAjusteGF) < Math.Abs(ajusteGFDuracion))
                        {
                            if (ajusteGFDuracion < 0)
                                ajusteGFDuracion = (-1) * Math.Abs(topeAjusteGF);
                            else
                                ajusteGFDuracion = Math.Abs(topeAjusteGF);

                            DataRow[] filasSeleccionadas = dtAjustesGF.Select("ITEM = '" + strItem + "'");
                            foreach (DataRow row in filasSeleccionadas)
                            {
                                row["IMPORTE AJUSTE TOPE"] = ajusteGFDuracion;
                                row.AcceptChanges();
                                break;
                            }
                        }

                        importeAjustesObraDuracionGF = importeAjustesObraDuracionGF + ajusteGFDuracion;

                        if (lineasxarticulo)
                        {
                            filaValores = dtValoresFichaArticulos.NewRow();
                            filaValores["ETIQUETA"] = "TOTAL_AJUSTES_OBRA_DURACION_GF";
                            filaValores["CONCEPTO"] = obra + " / " + nombreFicha;
                            filaValores["ITEM"] = strItem;
                            filaValores["IMPORTE"] = ajusteGFDuracion;
                            dtValoresFichaArticulos.Rows.Add(filaValores);
                        }
                    }

                    // CALCULO AJUSTES TAXIMETRO OCUPACION
                    dondeVa = "Ajustes taximetro ocupacion";
                    importeAjustesProductoTaxCapitulo = 0;
                    decimal ajusteOcupacion = 0;
                    decimal totalNC = 0;
                    decimal totalAjuste = 0;
                    decimal totalAbonoMPONC = 0;
                    decimal totalAbonoBuenTrato = 0;
                    decimal totalC = 0;
                    decimal totalAbonoMPOC = 0;
                    dtOcupacion.Columns.Add("TAX NC", typeof(Decimal));
                    dtOcupacion.Columns.Add("AJUSTE NC", typeof(Decimal));
                    dtOcupacion.Columns.Add("ABONO MPO NC", typeof(Decimal));
                    dtOcupacion.Columns.Add("ABONO BUEN TRATO", typeof(Decimal));
                    dtOcupacion.Columns.Add("TAX C", typeof(Decimal));
                    dtOcupacion.Columns.Add("ABONO MPO C", typeof(Decimal));
                    dtOcupacion.Columns.Add("AJUSTE OCUPACION", typeof(Decimal));

                    for (i = 0; i < dtOcupacion.Rows.Count; i++)
                    {
                        dondeVa = "AJUSTE TAX OCUPACION // " + i.ToString() + " / " + dtOcupacion.Rows.Count.ToString();

                        // NO CONSUMIBLE
                        // TAX NO CONSUMIBLE x AAF
                        dondeVa = "AJUSTE TAX OCUPACION // " + "TAX NO CONSUMIBLE x AAF";
                        totalNC = dtTax.AsEnumerable()
                                .Where(y => y.Field<string>("ITEM") == dtOcupacion.Rows[i]["Articulo"].ToString())
                                .Sum(x => Convert.ToDecimal(x.Field<decimal>("TAX NO CONSUMIBLE")));

                        // AJUSTE NO CONSUMIBLE x AAF
                        dondeVa = "AJUSTE TAX OCUPACION // " + "AJUSTE NO CONSUMIBLE x AAF";
                        totalAjuste = dtTax.AsEnumerable()
                                .Where(y => y.Field<string>("ITEM") == dtOcupacion.Rows[i]["Articulo"].ToString())
                                .Sum(x => Convert.ToDecimal(x.Field<decimal>("BONIFICACION")));

                        // ABONO MPO NO CONSUMIBLE x AAF
                        dondeVa = "AJUSTE TAX OCUPACION // " + "ABONO MPO NO CONSUMIBLE x AAF";
                         totalAbonoMPONC = dtAbonoMPONuevo.AsEnumerable()
                            .Where(y => y.Field<string>("ITEM") == dtOcupacion.Rows[i]["Articulo"].ToString() && y.Field<string>("TIPO") == "NO CONSUMIBLE")
                            .Sum(x => Convert.ToDecimal(x.Field<decimal>("ABONO MPO")));

                        // ABONO BUEN TRATO TABLERO x AAF
                        dondeVa = "AJUSTE TAX OCUPACION // " + "ABONO BUEN TRATO TABLERO x AAF";
                        totalAbonoBuenTrato = dtBuenTrato.AsEnumerable()
                            .Where(y => y.Field<string>("ITEM") == dtOcupacion.Rows[i]["Articulo"].ToString())
                            .Sum(x => Convert.ToDecimal(x.Field<string>("Abono buen trato")));

                        dtOcupacion.Rows[i]["TAX NC"] = totalNC;
                        dtOcupacion.Rows[i]["AJUSTE NC"] = totalAjuste;
                        dtOcupacion.Rows[i]["ABONO MPO NC"] = totalAbonoMPONC;
                        dtOcupacion.Rows[i]["ABONO BUEN TRATO"] = totalAbonoBuenTrato;

                        decimal multiplicarPor = 1;
                        if (totalNC < 0)
                            multiplicarPor = -1;
                        totalNC = multiplicarPor * (Math.Abs(totalNC) - Math.Abs(totalAjuste) - Math.Abs(totalAbonoMPONC) - Math.Abs(totalAbonoBuenTrato));

                        // CONSUMIBLE
                        // TAX CONSUMIBLE x AAF
                        dondeVa = "AJUSTE TAX OCUPACION // " + "TAX CONSUMIBLE x AAF";
                        totalC = dtTax.AsEnumerable()
                            .Where(y => y.Field<string>("ITEM") == dtOcupacion.Rows[i]["Articulo"].ToString())
                            .Sum(x => Convert.ToDecimal(x.Field<decimal>("TAX CONSUMIBLE")));

                        // ABONO MPO CONSUMIBLE x AAF
                        dondeVa = "AJUSTE TAX OCUPACION // " + "ABONO MPO CONSUMIBLE x AAF";
                        totalAbonoMPOC = dtAbonoMPONuevo.AsEnumerable()
                            .Where(y => y.Field<string>("ITEM") == dtOcupacion.Rows[i]["Articulo"].ToString() && y.Field<string>("TIPO") == "CONSUMIBLE")
                            .Sum(x => Convert.ToDecimal(x.Field<decimal>("ABONO MPO")));

                        dtOcupacion.Rows[i]["TAX C"] = totalC;
                        dtOcupacion.Rows[i]["ABONO MPO C"] = totalAbonoMPOC;

                        multiplicarPor = 1;
                        if (totalC < 0)
                            multiplicarPor = -1;
                        totalC = multiplicarPor * (Math.Abs(totalC) - Math.Abs(totalAbonoMPOC));

                        ocupacionAjuste = Convert.ToDecimal(dtOcupacion.Rows[i]["PorcentajeAplicar"].ToString());
                        ajusteOcupacion = 0;
                        if (dtOcupacion.Rows[i]["Alcance"].ToString().ToUpper() == "TODOS")
                        {
                            ajusteOcupacion = ajusteOcupacion + (ocupacionAjuste * totalNC / 100);
                            ajusteOcupacion = ajusteOcupacion + (ocupacionAjuste * totalC / 100);
                        }
                        else if (dtOcupacion.Rows[i]["Alcance"].ToString().ToUpper() == "CONSUMIBLE")
                        {
                            ajusteOcupacion = ajusteOcupacion + (ocupacionAjuste * totalC / 100);
                        }
                        else if (dtOcupacion.Rows[i]["Alcance"].ToString().ToUpper() == "NO CONSUMIBLE")
                        {
                            ajusteOcupacion = ajusteOcupacion + (ocupacionAjuste * totalNC / 100);
                        }
                        //importeAjustesProductoTaxCapitulo = importeAjustesProductoTaxCapitulo + Math.Abs(ajusteOcupacion);
                        importeAjustesProductoTaxCapitulo = importeAjustesProductoTaxCapitulo + ajusteOcupacion;
                        dtOcupacion.Rows[i]["AJUSTE OCUPACION"] = ajusteOcupacion;
                        dtOcupacion.AcceptChanges();

                        if (lineasxarticulo)
                        {
                            dondeVa = "AJUSTE TAX OCUPACION // " + "lineasxarticulo";

                            filaValores = dtValoresFichaArticulos.NewRow();
                            filaValores["ETIQUETA"] = "TOTAL_AJUSTES_TAX_PRODUCTO";
                            filaValores["CONCEPTO"] = obra + " / " + nombreFicha;
                            filaValores["ITEM"] = Convert.ToString(dtOcupacion.Rows[i]["Articulo"].ToString()).ToUpper();
                            //filaValores["IMPORTE"] = Convert.ToString(Math.Abs(ajusteOcupacion));
                            filaValores["IMPORTE"] = Convert.ToString((-1) * ajusteOcupacion);
                            dtValoresFichaArticulos.Rows.Add(filaValores);
                        }
                    }

                    //  RECALCULA AJUSTE TAXMETRO DURACION 28/05/2025
                    dondeVa = "Ajuste taxímetro por duración";
                   
                    importeAjustesObraDuracionTax = 0;
                    var itemsDistintosTax = dtTax.AsEnumerable().Select(row => row.Field<string>("ITEM")).Distinct();
                    foreach (var strItem in itemsDistintosTax)
                    {
                        DataRow[] filasSeleccionadas = dtTax.Select("ITEM = '" + strItem + "' AND ([TAX CONSUMIBLE] <> 0 OR [TAX NO CONSUMIBLE] <> 0)");
                        foreach (DataRow row in filasSeleccionadas)
                        {
                            row["AJUSTE OBRA DURACION"] = 0;
                            row["AJUSTE OBRA DURACION SIMULACION"] = 0;
                            row["AJUSTE OBRA DURACION ORIGINAL"] = 0; 
                            row["AJUSTE OBRA DURACION SIMULACION ORIGINAL"] = 0;
                            row.AcceptChanges();
                        }

                        // CALCULO DURACION TAXIMETRO CONSUMIBLE
                        dondeVa = "Ajuste taxímetro por duración CONSUMIBLE " + strItem;

                        decimal totalTaximentoAbonoMPO = dtAbonoMPONuevo.AsEnumerable()
                                .Where(y => y.Field<string>("ITEM") == strItem && y.Field<string>("TIPO") == "CONSUMIBLE")
                                .Sum(x => Convert.ToDecimal(x.Field<decimal>("ABONO MPO")));

                        decimal taxC = dtTax.AsEnumerable()
                                .Where(y => y.Field<string>("ITEM") == strItem)
                                .Sum(x => Convert.ToDecimal(x.Field<decimal>("TAX CONSUMIBLE")) + Convert.ToDecimal(x.Field<decimal>("BONIFICACION")));

                        decimal abonoBTT = dtBuenTrato.AsEnumerable()
                            .Where(y => y.Field<string>("ITEM") == strItem)
                            .Sum(x => Convert.ToDecimal(x.Field<string>("Abono buen trato")));

                        taxC = taxC - abonoBTT;

                        if (taxC != 0)
                        {
                            decimal porcentajeDuracion = (totalTaximentoAbonoMPO / taxC);
                            porcentajeDuracion = 1 + porcentajeDuracion;

                            filasSeleccionadas = dtTax.Select("ITEM = '" + strItem + "' AND [TAX CONSUMIBLE] <> 0");
                            foreach (DataRow row in filasSeleccionadas)
                            {
                                row["TAX CONSUMIBLE PARA DURACION"] = Convert.ToDecimal(row["TAX CONSUMIBLE"]) * porcentajeDuracion;
                                row["% TAX CONSUMIBLE x ABONO MPO"] = porcentajeDuracion * 100;
                                row["AJUSTE OBRA DURACION"] = (-1) * (Convert.ToDecimal(row["DURACION AJUSTE"]) * Convert.ToDecimal(row["TAX CONSUMIBLE PARA DURACION"]) * Convert.ToDecimal(row["% AJUSTE"]));
                                row["AJUSTE OBRA DURACION SIMULACION"] = (-1) * (Convert.ToDecimal(row["DURACION AJUSTE"]) * Convert.ToDecimal(row["TAX CONSUMIBLE PARA DURACION"]) * Convert.ToDecimal(row["% AJUSTE"]));

                                row["AJUSTE OBRA DURACION ORIGINAL"] = (-1) * (Convert.ToDecimal(row["DURACION AJUSTE"]) * Convert.ToDecimal(row["TAX CONSUMIBLE PARA DURACION"]) * Convert.ToDecimal(row["% AJUSTE"]));
                                row["AJUSTE OBRA DURACION SIMULACION ORIGINAL"] = (-1) * (Convert.ToDecimal(row["DURACION AJUSTE"]) * Convert.ToDecimal(row["TAX CONSUMIBLE PARA DURACION"]) * Convert.ToDecimal(row["% AJUSTE"]));

                                row.AcceptChanges();
                            }
                        }

                        // CALCULO DURACION TAXIMETRO NO CONSUMIBLE
                        dondeVa = "Ajuste taxímetro por duración NO CONSUMIBLE " + strItem;

                        //if (strItem == "37700")
                        //    dondeVa = "";
                        decimal totalTaximentoNoAbonoMPO = dtAbonoMPONuevo.AsEnumerable()
                                .Where(y => y.Field<string>("ITEM") == strItem && y.Field<string>("TIPO") == "NO CONSUMIBLE")
                                .Sum(x => Convert.ToDecimal(x.Field<decimal>("ABONO MPO")));

                        decimal taxNC = dtTax.AsEnumerable()
                                .Where(y => y.Field<string>("ITEM") == strItem)
                                .Sum(x => Convert.ToDecimal(x.Field<decimal>("TAX NO CONSUMIBLE")));

                        if (taxNC != 0)
                        {
                            decimal porcentajeDuracion = (totalTaximentoNoAbonoMPO / taxNC);
                            porcentajeDuracion = 1 + porcentajeDuracion;

                            filasSeleccionadas = dtTax.Select("ITEM = '" + strItem + "' AND [TAX NO CONSUMIBLE] <> 0");
                            foreach (DataRow row in filasSeleccionadas)
                            {
                                row["TAX NO CONSUMIBLE PARA DURACION"] = Convert.ToDecimal(row["TAX NO CONSUMIBLE"]) * porcentajeDuracion;
                                row["% TAX NO CONSUMIBLE x ABONO MPO"] = porcentajeDuracion * 100;
                                row["AJUSTE OBRA DURACION"] = Convert.ToDecimal(row["AJUSTE OBRA DURACION"]) + ((-1) * (Convert.ToDecimal(row["DURACION AJUSTE"]) * Convert.ToDecimal(row["TAX NO CONSUMIBLE PARA DURACION"]) * Convert.ToDecimal(row["% AJUSTE"])));
                                row["AJUSTE OBRA DURACION SIMULACION"] = Convert.ToDecimal(row["AJUSTE OBRA DURACION SIMULACION"]) + ((-1) * (Convert.ToDecimal(row["DURACION AJUSTE"]) * Convert.ToDecimal(row["TAX NO CONSUMIBLE PARA DURACION"]) * Convert.ToDecimal(row["% AJUSTE"])));

                                row["AJUSTE OBRA DURACION ORIGINAL"] = Convert.ToDecimal(row["AJUSTE OBRA DURACION ORIGINAL"]) + ((-1) * (Convert.ToDecimal(row["DURACION AJUSTE"]) * Convert.ToDecimal(row["TAX NO CONSUMIBLE PARA DURACION"]) * Convert.ToDecimal(row["% AJUSTE"])));
                                row["AJUSTE OBRA DURACION SIMULACION ORIGINAL"] = Convert.ToDecimal(row["AJUSTE OBRA DURACION SIMULACION ORIGINAL"]) + ((-1) * (Convert.ToDecimal(row["DURACION AJUSTE"]) * Convert.ToDecimal(row["TAX NO CONSUMIBLE PARA DURACION"]) * Convert.ToDecimal(row["% AJUSTE"])));

                                row.AcceptChanges();
                            }
                        }

                        dondeVa = "Ajuste taxímetro por duración recuperar AAF " + strItem;
                        AAF = "";
                        filaEncontrada = dtArticulosLiquidacion.Select("ItemId = '" + strItem + "'");
                        foreach (DataRow filaAA in filaEncontrada)
                            AAF = Convert.ToString(filaAA["AAF"]);

                        decimal taxParaDuracion = dtTax.AsEnumerable()
                                .Where(y => y.Field<string>("ITEM") == strItem)
                                .Sum(x => Convert.ToDecimal(x.Field<decimal>("TAX CONSUMIBLE PARA DURACION")) + Convert.ToDecimal(x.Field<decimal>("TAX NO CONSUMIBLE PARA DURACION")));

                        decimal ajusteObraDuracion = dtTax.AsEnumerable()
                                .Where(y => y.Field<string>("ITEM") == strItem)
                                .Sum(x => Convert.ToDecimal(x.Field<decimal>("AJUSTE OBRA DURACION")));

                        decimal ajusteObraDuracionMPO = ajusteObraDuracion;

                        if (taxParaDuracion < 0)
                        {
                            if (ajusteObraDuracion < 0)
                                ajusteObraDuracion = 0;
                        }
                        else
                        {
                            if (ajusteObraDuracion > 0)
                                ajusteObraDuracion = 0;
                        }

                        if (ajusteObraDuracion == 0)
                        {
                            filasSeleccionadas = dtTax.Select("ITEM = '" + strItem + "'");
                            foreach (DataRow row in filasSeleccionadas)
                            {
                                row["AJUSTE OBRA DURACION"] = 0;
                                row["AJUSTE OBRA DURACION SIMULACION"] = 0;
                                row.AcceptChanges();
                            }
                        }
                    }

                    // TOPE duracionAjuste
                    importeAjustesObraDuracionTax = 0;
                    itemsDistintosTax = dtTax.AsEnumerable().Select(row => row.Field<string>("ITEM")).Distinct();
                    foreach (var strItem in itemsDistintosTax)
                    {
                        decimal taxParaDuracion = dtTax.AsEnumerable()
                               .Where(y => y.Field<string>("ITEM") == strItem)
                               .Sum(x => Convert.ToDecimal(x.Field<decimal>("TAX CONSUMIBLE PARA DURACION")) + Convert.ToDecimal(x.Field<decimal>("TAX NO CONSUMIBLE PARA DURACION")));

                        decimal ajusteObraDuracion = dtTax.AsEnumerable()
                                .Where(y => y.Field<string>("ITEM") == strItem)
                                .Sum(x => Convert.ToDecimal(x.Field<decimal>("AJUSTE OBRA DURACION")));

                        decimal ajusteObraDuracionMPO = ajusteObraDuracion;

                        decimal topeAjuste = (taxParaDuracion * ajustesTaxPorcentajeAbonoMensual * ((ajustesTaxDuracionMaxima - ajustesTaxDuracionMinima) / diasxMes));
                        if (Math.Abs(topeAjuste) < Math.Abs(ajusteObraDuracion))
                        {
                            if (ajusteObraDuracion < 0)
                                ajusteObraDuracion = (-1) * Math.Abs(topeAjuste);
                            else
                                ajusteObraDuracion = Math.Abs(topeAjuste);

                            DataRow[] filasSeleccionadas = dtTax.Select("ITEM = '" + strItem + "'");
                            foreach (DataRow row in filasSeleccionadas)
                            {
                                row["AJUSTE OBRA DURACION TOPE"] = ajusteObraDuracion;
                                row.AcceptChanges();
                                break;
                            }
                        }
                        
                        importeAjustesObraDuracionTax = importeAjustesObraDuracionTax + ajusteObraDuracion;

                        if (lineasxarticulo)
                        {
                            filaValores = dtValoresFichaArticulos.NewRow();
                            filaValores["ETIQUETA"] = "TOTAL_AJUSTES_OBRA_DURACION_TAXIMETRO";
                            filaValores["CONCEPTO"] = obra + " / " + nombreFicha;
                            filaValores["ITEM"] = strItem;
                            filaValores["AAF"] = AAF;
                            filaValores["IMPORTE"] = ajusteObraDuracion;
                            dtValoresFichaArticulos.Rows.Add(filaValores);

                            decimal duracionConMPO = 0;
                            if ((-1) * taxParaDuracion * ajustesTaxPorcentajeAbonoMensual != 0)
                                duracionConMPO = ajustesTaxDuracionMinima + ((ajusteObraDuracionMPO * diasxMes) / (((-1) * taxParaDuracion) * ajustesTaxPorcentajeAbonoMensual));
                            filaValores = dtValoresFichaArticulos.NewRow();
                            filaValores["ETIQUETA"] = "DURACION_CON_MPO";
                            filaValores["CONCEPTO"] = obra + " / " + nombreFicha;
                            filaValores["ITEM"] = strItem;
                            filaValores["AAF"] = AAF;
                            filaValores["IMPORTE"] = duracionConMPO;
                            dtValoresFichaArticulos.Rows.Add(filaValores);
                        }
                    }

                    dondeVa = "más etiquetas";
                    if (totalImporteAbonoBuenTrato != 0)
                    {
                        filaValores = dtValoresFicha.NewRow();
                        filaValores["ETIQUETA"] = "ABONO_BUEN_TRATO";
                        filaValores["CONCEPTO"] = obra + " / " + nombreFicha;
                        filaValores["IMPORTE"] = totalImporteAbonoBuenTrato.ToString("#,##0.00");
                        filaValores["PORCENTAJE"] = "0.00";
                        filaValores["IMPORTE PREVISTO"] = "0.00";
                        filaValores["PORCENTAJE PREVISTO"] = "0.00";
                        dtValoresFicha.Rows.Add(filaValores);
                        filaValores = null;
                    }

                    if (importeFacturacionAlquiler != 0)
                    {
                        filaValores = dtValoresFicha.NewRow();
                        filaValores["ETIQUETA"] = "ALQUILERES";
