                    // VALIDAR DURACION - ITEMS --> AAF
                    //var dataResultados = from d in dtValoresFichaArticulos.AsEnumerable()
                    var dataResultados = from d in dtTax.AsEnumerable()
                                         orderby d.Field<string>("ITEM")
                                         group d by new
                                         {
                                             ITEM = d.Field<string>("ITEM")
                                         } into grupo
