                        dondeVa = "dtValoresFichaArticulos COSTE PS";
                        coste_PS = 0;
                        filaEncontrada = dtArticulos.Select("Articulo = '" + itemResultados.ARTICULO.ToString() + "'");
                        foreach (DataRow filaTax in filaEncontrada)
                        {
                            coste_PS = Convert.ToDecimal(filaTax["Precio"].ToString());
