                        dondeVa = "dtValoresFichaArticulos PVP";
                        pvp = 0;
                        if (dtPrecios.Rows.Count == 0)
                            dtPrecios = funcionalidades.localizarPreciosVentaArticulos(ref dtTiempos, empresa, articulos, moneda, articulosCambio, obra, usuario, version, grupoPrecio, "", usuarioRed);
                        filaEncontrada = dtPrecios.Select("Articulo = '" + itemResultados.ARTICULO.ToString() + "'");
                        foreach (DataRow filaTax in filaEncontrada)
                        {
                            pvp = Convert.ToDecimal(filaTax["Precio"].ToString());
