                        }
                        dtValoresFichaArticulos.Rows.Add("PVP", itemResultados.ARTICULO.ToString(), "", obra + " / " + nombreFicha, pvp.ToString());

                        // CALCULA DURACIÓN POR ITEM
                        dondeVa = "Calcular duración por ítem: " + itemResultados.ARTICULO.ToString();
                        decimal duracionItem = 0;

                        psUnDia = dtTax.AsEnumerable()
                                .Where(y => y.Field<string>("ITEM") == itemResultados.ARTICULO.ToString())
                                .Sum(x => Convert.ToDecimal(x.Field<decimal>("PS")) * Convert.ToDecimal(x.Field<decimal>("UNIDADES-DIA")));

                        psEntregadas = dtTax.AsEnumerable()
                                    .Where(y => y.Field<string>("ITEM") == itemResultados.ARTICULO.ToString() && y.Field<string>("PACKING SLIP POSITIVO") != "")
                                    .Sum(x => Convert.ToDecimal(x.Field<decimal>("PS")) * Convert.ToDecimal(x.Field<decimal>("CANTIDAD")));

                        if (psEntregadas != 0)
                            duracionItem = psUnDia / psEntregadas;
                        else
                            duracionItem = 0;

                        dtValoresFichaArticulos.Rows.Add("DURACION", itemResultados.ARTICULO.ToString(), "", obra + " / " + nombreFicha, "", duracionItem.ToString());

                        // CALCULA ENTREGADOS
                        dondeVa = "Calcular entrega por ítem: " + itemResultados.ARTICULO.ToString();
                        entregadas = 0;

                        entregadas = dtAlbaranesEntrega.AsEnumerable()
                                .Where(y => y.Field<string>("ITEM") == itemResultados.ARTICULO.ToString())
                                .Sum(x => Convert.ToDecimal(x.Field<decimal>("CANTIDAD")));

                        dtValoresFichaArticulos.Rows.Add("ENTREGADO", itemResultados.ARTICULO.ToString(), "", obra + " / " + nombreFicha, "", entregadas.ToString());

                        // CALCULA OCUPACION DELEGACION
                        dondeVa = "Calcular ocupacion delegacion por ítem: " + itemResultados.ARTICULO.ToString();
                        ocupacionDelegacion = 0;

                        ocupacionDelegacion = dtOcupacion.AsEnumerable()
                                .Where(y => y.Field<string>("Articulo") == itemResultados.ARTICULO.ToString())
                                .Sum(x => Convert.ToDecimal(x.Field<decimal>("OcupacionDelegacion")));

                        dtValoresFichaArticulos.Rows.Add("OCUPACION DELEGACION", itemResultados.ARTICULO.ToString(), "", obra + " / " + nombreFicha, "", ocupacionDelegacion.ToString());

                        // CALCULA OCUPACION EMPRESA
                        dondeVa = "Calcular ocupacion empresa por ítem: " + itemResultados.ARTICULO.ToString();
                        ocupacionEmpresa = 0;

                        ocupacionEmpresa = dtOcupacion.AsEnumerable()
                                .Where(y => y.Field<string>("Articulo") == itemResultados.ARTICULO.ToString())
                                .Sum(x => Convert.ToDecimal(x.Field<decimal>("OcupacionEmpresa")));

                        dtValoresFichaArticulos.Rows.Add("OCUPACION EMPRESA", itemResultados.ARTICULO.ToString(), "", obra + " / " + nombreFicha, "", ocupacionEmpresa.ToString());

                        // CALCULA OCUPACION PAIS
                        dondeVa = "Calcular ocupacion ítem: " + itemResultados.ARTICULO.ToString();
                        ocupacionPais = 0;

                        ocupacionPais = dtOcupacion.AsEnumerable()
                                .Where(y => y.Field<string>("Articulo") == itemResultados.ARTICULO.ToString())
                                .Sum(x => Convert.ToDecimal(x.Field<decimal>("OcupacionPais")));

                        dtValoresFichaArticulos.Rows.Add("OCUPACION PAIS", itemResultados.ARTICULO.ToString(), "", obra + " / " + nombreFicha, "", ocupacionPais.ToString());

                        // CALCULA OCUPACION PAIS
                        dondeVa = "Calcular ocupacion país por ítem: " + itemResultados.ARTICULO.ToString();
                        ocupacion = 0;

                        ocupacion = dtOcupacion.AsEnumerable()
                                .Where(y => y.Field<string>("Articulo") == itemResultados.ARTICULO.ToString())
                                .Sum(x => Convert.ToDecimal(x.Field<decimal>("SumaDelegacionPaisEmpresa")));

                        dtValoresFichaArticulos.Rows.Add("OCUPACION", itemResultados.ARTICULO.ToString(), "", obra + " / " + nombreFicha, "", ocupacion.ToString());

                        // LOCALIZAR AAF
                        dondeVa = "1 Localizar aaf: " + itemResultados.ARTICULO.ToString();
                        if (dtArticulosLiquidacion.Rows.Count > 0)
                        {
                            filaEncontrada = dtArticulosLiquidacion.Select("ItemId = '" + itemResultados.ARTICULO.ToString() + "'");
                            foreach (DataRow filaAA in filaEncontrada)
                                AAF = Convert.ToString(filaAA["AAF"]);
                        }
                        else
                            AAF = itemResultados.ARTICULO.ToString();

                        // Actualizar tabla de valores x artículo
                        dondeVa = "Actualizar tabla de valores x ítem: " + itemResultados.ARTICULO.ToString();
                        DataRow[] filasVFA;
                        filasVFA = dtValoresFichaArticulos.Select("ITEM = '" + itemResultados.ARTICULO.ToString() + "'");
                        foreach (DataRow filaVFA in filasVFA)
                        {
                            if (!filaVFA["ETIQUETA"].ToString().Contains("VENTA")
                                             && !filaVFA["ETIQUETA"].ToString().Contains("MONTAJES")
                                             && !filaVFA["ETIQUETA"].ToString().Contains("DEPARTAMENTO")
                                             && !filaVFA["ETIQUETA"].ToString().Contains("FENOLICO")
                                             && !filaVFA["ETIQUETA"].ToString().Contains("SVP")
                                             && !filaVFA["ETIQUETA"].ToString().Contains("SERVICIOS")
                                             && !filaVFA["ETIQUETA"].ToString().Contains("MATERIAL")
                                             && !filaVFA["ETIQUETA"].ToString().Contains("COSTE_MPO")
                                             && !filaVFA["ETIQUETA"].ToString().Contains("COSTE_CHATARRA")
                                             && !filaVFA["ETIQUETA"].ToString().Contains("COSTE_VCH"))
                            {
                                filaVFA["AAF"] = AAF;
                            }
                            else
                            {
                                filaVFA["AAF"] = itemResultados.ARTICULO.ToString();
                            }
                            //filaVFA["DURACION"] = duracionItem;
                            filaVFA.AcceptChanges();
                        }
                    }

                    if (lineasxarticulo)
                    {
                        dondeVa = "Ajustar dtValoresFichaArticulos";
                        List<DataRow> rowsToDelete = new List<DataRow>();
                        foreach (DataRow row in dtValoresFichaArticulos.Rows)
                        {
                            if (String.IsNullOrEmpty(row["IMPORTE"].ToString()))
                                rowsToDelete.Add(row);
                            else
                                if (Convert.ToDecimal(row["IMPORTE"].ToString()) == 0)
                                rowsToDelete.Add(row);

                            string buscarItem = "";
                            if (row["ITEM"].ToString() == "")
                                buscarItem = row["AAF"].ToString();
                            else
                                buscarItem = row["ITEM"].ToString();

                            dondeVa = "2 Localizar aaf: " + buscarItem + " // " + row["ETIQUETA"].ToString();
                            if (dtArticulosLiquidacion.Rows.Count > 0)
                            {
                                filaEncontrada = dtArticulosLiquidacion.Select("ItemId = '" + buscarItem + "'");
                                if (filaEncontrada.Length > 0)
                                {
                                    foreach (DataRow filaAA in filaEncontrada)
                                    {
                                        AAF = Convert.ToString(filaAA["AAF"]);
                                        break;
                                    }
                                }
                            }
                            else
                                AAF = buscarItem;

                            row["AAF"] = AAF;
                            row.AcceptChanges();
                        }
                        foreach (DataRow row in rowsToDelete)
                        {
                            dtValoresFichaArticulos.Rows.Remove(row);
                        }

                        sumarTotalesArticulos(ref dtValoresFichaArticulos, ref dtTiempos, obra + " / " + nombreFicha);
                    }

                    Session["dtValoresFichaArticulosPorItem"] = dtValoresFichaArticulos;

                    dondeVa = "aplastar dtValoresFichaArticulos";
                    var dataValoresLineas = from d in dtValoresFichaArticulos.AsEnumerable()
                                            group d by new
                                            {
                                                CONCEPTO = d.Field<string>("CONCEPTO"),
                                                ETIQUETA = d.Field<string>("ETIQUETA"),
                                                AAF = d.Field<string>("AAF"),
                                            } into grupo
                                            select new
                                            {
                                                concepto = grupo.Key.CONCEPTO,
                                                etiqueta = grupo.Key.ETIQUETA,
                                                aaf = grupo.Key.AAF,
                                                importe = grupo.Key.CONCEPTO == "DURACION" || grupo.Key.CONCEPTO == "DURACION MPO"
                                                    ? grupo.Select(x => x.Field<decimal?>("IMPORTE") ?? 0).Average()
                                                    : grupo.Select(x => x.Field<decimal?>("IMPORTE") ?? 0).Sum()
                                            };

                    dondeVa = "copiar a dtValoresFichaArticulos";
                    dtValoresFichaArticulos = new System.Data.DataTable();

                    dondeVa = "creando columnas en dtValoresFichaArticulos";
                    dtValoresFichaArticulos = new System.Data.DataTable();
                    dtValoresFichaArticulos.Clear();
                    dtValoresFichaArticulos.Columns.Add("ETIQUETA");
                    dtValoresFichaArticulos.Columns.Add("AAF");
                    dtValoresFichaArticulos.Columns.Add("ITEM");
                    dtValoresFichaArticulos.Columns.Add("CONCEPTO");
                    dtValoresFichaArticulos.Columns.Add("CONCEPTO ARBOL");
                    dtValoresFichaArticulos.Columns.Add("IMPORTE", typeof(decimal));
                    dtValoresFichaArticulos.Columns.Add("TOPADO");
                  
                    dondeVa = "copiando a dtValoresFichaArticulos";
                    foreach (var itemValores in dataValoresLineas)
                    {
                        dondeVa = "copiando a dtValoresFichaArticulos " + itemValores.etiqueta.ToString() + " // " + itemValores.aaf.ToString();

                        if (itemValores.etiqueta.ToString() == "DURACION_CON_MPO" && itemValores.aaf.ToString() == "87947")
                            dondeVa = "";

                        decimal decImporte = 0;
                        if (String.IsNullOrEmpty(itemValores.importe.ToString()))
                            decImporte = 0;
                        else
                            decImporte = itemValores.importe;
                        dtValoresFichaArticulos.Rows.Add(itemValores.etiqueta.ToString(), itemValores.aaf.ToString(), "", itemValores.concepto.ToString(), "", decImporte);
                    }

 
                    // TOPES AJUSTES
                    dondeVa = " TOPES AJUSTES";
                    DataTable dtTopesValores = new DataTable();
                    dtTopesValores.Clear();
                    dtTopesValores.Columns.Add("AAF", typeof(string));
                    dtTopesValores.Columns.Add("APLICA SOBRE", typeof(string));
                    dtTopesValores.Columns.Add("IMPORTE APLICA SOBRE", typeof(decimal));
                    dtTopesValores.Columns.Add("PORCENTAJE CONFIGURADO", typeof(decimal));
                    dtTopesValores.Columns.Add("TOPE", typeof(decimal));
                    dtTopesValores.Columns.Add("ETIQUETA", typeof(string));
                    dtTopesValores.Columns.Add("IMPORTE ORIGINAL ETIQUETA", typeof(decimal));
                    dtTopesValores.Columns.Add("IMPORTE ORIGINAL TOTAL ETIQUETAS", typeof(decimal));
                    dtTopesValores.Columns.Add("IMPORTE TOPADO", typeof(decimal));
                    dtTopesValores.Columns.Add("IMPORTE DEFINITIVO", typeof(decimal));

                    DataTable dtVFA = new System.Data.DataTable();
                    dtVFA.Clear();
                    dtVFA.Columns.Add("ETIQUETA");
                    dtVFA.Columns.Add("AAF");
                    dtVFA.Columns.Add("ITEM");
                    dtVFA.Columns.Add("CONCEPTO");
                    dtVFA.Columns.Add("CONCEPTO ARBOL");
                    dtVFA.Columns.Add("IMPORTE", typeof(decimal));
                    dtVFA.Columns.Add("TOPADO");

                    decimal importeAjuste = 0;
                    string topado = "";
                    bool hayTopes = false;
                    DataTable dtTopes = new DataTable();
                    dtTopes = funcionalidades.topesAjustes(ref dtTiempos, version, masterObra, fechaPrecios, "", usuarioRed);
                    string[] aplica;
                    foreach (DataRow fila in dtTopes.Rows)
                    {
                        string concepto = fila["CFGAJU_Concepto"].ToString();
                        string aplicarSobre = fila["CFGAJU_AplicarSobre"].ToString();
                        string aplicarSobreDistinguir = fila["CFGAJU_AplicarSobreDistinguir"].ToString();
                        string aplicarSobreDistinguirOriginal = aplicarSobreDistinguir;
                        string aplicar = fila["CFGAJU_AplicarA"].ToString();
                        string aplicarOriginal = aplicar;
                        decimal porcentajeTotal = Convert.ToDecimal(fila["CFGAJU_ValorMaximoPorcentaje"].ToString());

                        // 06/06/025 SE CALCULA POR AAF
                        var AAFsDistintosTopes = dtValoresFichaArticulos.AsEnumerable().Select(row => row.Field<string>("AAF")).Distinct();
                        foreach (var strAAF in AAFsDistintosTopes)
                        {
                            aplicar = aplicarOriginal;

                            decimal sumaTotalesSobre = dtValoresFichaArticulos.AsEnumerable()
                                       .Where(y => y.Field<string>("AAF") == strAAF
                                                    && aplicarSobre.Contains(y.Field<string>("ETIQUETA")))
                                       .Sum(x => Convert.ToDecimal(x.Field<decimal>("IMPORTE")));

                            decimal tope = Math.Abs(sumaTotalesSobre) * porcentajeTotal / 100;

                            aplica = aplicar.Split('|');
                            decimal sumaTotalesA = 0;
                            while (aplica.GetUpperBound(0) != 0)
                            {
                                aplica = aplicar.Split('|');

                                sumaTotalesA = sumaTotalesA + dtValoresFichaArticulos.AsEnumerable()
                                            .Where(y => (y.Field<string>("AAF") == strAAF)
                                                        && (y.Field<string>("ETIQUETA") == aplica[0])
                                                   )
                                           .Sum(x => x.Field<decimal>("IMPORTE"));

                                aplicar = aplicar.Replace(aplica[0] + "|", "");
                                if (aplica.GetUpperBound(0) == 0)
                                    break;
                            }

                            aplicar = aplicarOriginal;
                            aplica = aplicar.Split('|');
                            dondeVa = "TOPES: articulos";
                            while (aplica.GetUpperBound(0) != 0)
                            {
                                aplica = aplicar.Split('|');
                                filaEncontrada = dtValoresFichaArticulos.Select("AAF = '" + strAAF + "' AND ETIQUETA = '" + aplica[0] + "'");
                                foreach (DataRow filaDT in filaEncontrada)
                                {
                                    importeAjuste = 0;
                                    topado = "";
                                    if (Math.Abs(tope) < Math.Abs(sumaTotalesA) && Math.Abs(sumaTotalesA) > 0)
                                    {
                                        hayTopes = true;

                                        decimal importeTopado = (tope / sumaTotalesA) * Convert.ToDecimal(filaDT["IMPORTE"]);

                                        filaValores = dtTopesValores.NewRow();
                                        filaValores["AAF"] = strAAF;
                                        filaValores["APLICA SOBRE"] = aplicarSobre;
                                        filaValores["IMPORTE APLICA SOBRE"] = sumaTotalesSobre;
                                        filaValores["PORCENTAJE CONFIGURADO"] = porcentajeTotal;
                                        filaValores["TOPE"] = tope;
                                        filaValores["ETIQUETA"] = aplica[0];
                                        filaValores["IMPORTE ORIGINAL ETIQUETA"] = filaDT["IMPORTE"];
                                        filaValores["IMPORTE ORIGINAL TOTAL ETIQUETAS"] = sumaTotalesA;
                                        if (Convert.ToDecimal(filaDT["IMPORTE"]) < 0)
                                        {
                                            filaValores["IMPORTE TOPADO"] = (-1) * Math.Abs(importeTopado);
                                            filaValores["IMPORTE DEFINITIVO"] = (-1) * Math.Abs(importeTopado);
                                            importeAjuste = (-1) * Math.Abs(importeTopado);
                                        }
                                        else
                                        {
                                            filaValores["IMPORTE TOPADO"] = Math.Abs(importeTopado);
                                            filaValores["IMPORTE DEFINITIVO"] = Math.Abs(importeTopado);
                                            importeAjuste = Math.Abs(importeTopado);
                                        }
                                        dtTopesValores.Rows.Add(filaValores);
                                        filaValores = null;

                                        if (Convert.ToDecimal(filaDT["IMPORTE"]) < 0)
                                            filaDT["IMPORTE"] = (-1) * Math.Abs(importeTopado);
                                        else
                                            filaDT["IMPORTE"] = Math.Abs(importeTopado);
                                        filaDT["TOPADO"] = "*";
                                        filaDT.AcceptChanges();
                                        topado = "*";
                                    }
                                    else
                                    {
                                        {
                                            filaValores = dtTopesValores.NewRow();
                                            filaValores["AAF"] = strAAF;
                                            filaValores["APLICA SOBRE"] = aplicarSobre;
                                            filaValores["IMPORTE APLICA SOBRE"] = sumaTotalesSobre;
                                            filaValores["PORCENTAJE CONFIGURADO"] = porcentajeTotal;
                                            filaValores["TOPE"] = tope;
                                            filaValores["ETIQUETA"] = aplica[0];
                                            filaValores["IMPORTE ORIGINAL ETIQUETA"] = filaDT["IMPORTE"];
                                            filaValores["IMPORTE ORIGINAL TOTAL ETIQUETAS"] = sumaTotalesA;
                                            filaValores["IMPORTE TOPADO"] = 0;
                                            filaValores["IMPORTE DEFINITIVO"] = filaDT["IMPORTE"];
                                            dtTopesValores.Rows.Add(filaValores);
                                            filaValores = null;

                                            importeAjuste = Convert.ToDecimal(filaDT["IMPORTE"].ToString());
                                            topado = "";
                                        }
                                    }

                                    dondeVa = "TOPES: particiones";
                                    aplicarSobreDistinguir = aplicarSobreDistinguirOriginal;
                                    string[] aplicaDistinguir = aplicarSobreDistinguir.Split('|');
                                    while (aplicaDistinguir.GetUpperBound(0) != 0)
                                    {
                                        aplicaDistinguir = aplicarSobreDistinguir.Split('|');

                                        decimal sumaDistinguir = dtValoresFichaArticulos.AsEnumerable()
                                                               .Where(y => (y.Field<string>("AAF") == strAAF)
                                                                     && (y.Field<string>("ETIQUETA") == aplicaDistinguir[0])
                                                                 )
                                                               .Sum(x => Convert.ToDecimal(x.Field<decimal>("IMPORTE")));

                                        if (sumaDistinguir != 0)
                                        {
                                            decimal porcentajeDistinguir = (sumaDistinguir * 100) / sumaTotalesSobre;

                                            filaValores = dtVFA.NewRow();
                                            filaValores["ETIQUETA"] = aplica[0] + "_" + aplicaDistinguir[0];
                                            filaValores["AAF"] = strAAF;
                                            filaValores["IMPORTE"] = importeAjuste * porcentajeDistinguir / 100;
                                            filaValores["TOPADO"] = topado;
                                            dtVFA.Rows.Add(filaValores);
                                            filaValores = null;
                                        }
                                        aplicarSobreDistinguir = aplicarSobreDistinguir.Replace(aplicaDistinguir[0] + "|", "");
                                        if (aplicaDistinguir.GetUpperBound(0) == 0)
                                            break;
                                    }
                                }
                                aplicar = aplicar.Replace(aplica[0] + "|", "");
                                if (aplica.GetUpperBound(0) == 0)
                                    break;
                            }
                        }
                    }

                    if (hayTopes)
                    {
                        if (dtVFA.Rows.Count > 0)
                        {
                            foreach (DataRow row in dtVFA.Rows)
                            {
                                dtValoresFichaArticulos.ImportRow(row);
                            }
                        }

                        sumarTotalesArticulos(ref dtValoresFichaArticulos, ref dtTiempos, obra + " / " + nombreFicha);

                        dondeVa = "TOPES: totales // pintar";

                        foreach (DataRow fila in dtTopes.Rows)
                        {
                            string concepto = fila["CFGAJU_Concepto"].ToString();
                            string aplicarSobre = fila["CFGAJU_AplicarSobre"].ToString();
                            string aplicar = fila["CFGAJU_AplicarA"].ToString();
                            string aplicarARBOL = fila["CFGAJU_AplicarAARBOL"].ToString();
                            string tipoTope = fila["CFGAJU_TipoTope"].ToString();
                            string aplicarSobreDistinguir = fila["CFGAJU_AplicarSobreDistinguir"].ToString();
                            string aplicarSobreDistinguirOriginal = aplicarSobreDistinguir;

                            string aplicarOriginal = aplicar;
                            string aplicarOriginalArbol = aplicarARBOL;
                            decimal porcentajeTotal = Convert.ToDecimal(fila["CFGAJU_ValorMaximoPorcentaje"].ToString());

                            decimal sumaTotalesSobre = dtValoresFicha.AsEnumerable()
                                        .Where(y => aplicarSobre.Contains(y.Field<string>("ETIQUETA")))
                                        .Sum(x => Convert.ToDecimal(x.Field<decimal>("IMPORTE")));

                            decimal tope = Math.Abs(sumaTotalesSobre) * porcentajeTotal / 100;

                            string[] aplicaARBOL;
                            aplica = aplicar.Split('|');
                            aplicaARBOL = aplicarARBOL.Split('|');

                            decimal sumaTotalesAxLinea = 0;
                            int hayTopados = 0;

                            decimal sumaTotalesAxLineaTOTAL = 0;
                            while (aplica.GetUpperBound(0) != 0)
                            {
                                aplica = aplicar.Split('|');
                                aplicaARBOL = aplicarARBOL.Split('|');

                                sumaTotalesAxLinea = dtValoresFichaArticulos.AsEnumerable()
                                        .Where(y => (y.Field<string>("ETIQUETA") == aplica[0]))
                                        .Sum(x => x.Field<decimal>("IMPORTE"));

                                sumaTotalesAxLineaTOTAL = sumaTotalesAxLineaTOTAL + dtValoresFicha.AsEnumerable()
                                       .Where(y => (y.Field<string>("ETIQUETA") == aplicaARBOL[0]))
                                       .Sum(x => x.Field<decimal>("IMPORTE"));

                                hayTopados = dtValoresFichaArticulos.AsEnumerable()
                                            .Count(row => row.Field<string>("TOPADO") == "*" && row.Field<string>("ETIQUETA") == aplica[0]);

                                filaEncontrada = dtValoresFicha.Select("ETIQUETA = '" + aplicaARBOL[0] + "'");
                                foreach (DataRow filaDT in filaEncontrada)
                                {
                                    filaDT["IMPORTE"] = sumaTotalesAxLinea;
                                    filaDT["COLOR"] = "";
                                    filaDT["CONCEPTO"] = filaDT["CONCEPTO"].ToString().Replace(" * ", "");
                                    filaDT.AcceptChanges();
                                }

                                dondeVa = "TOPES: particiones";
                                aplicarSobreDistinguir = aplicarSobreDistinguirOriginal;
                                string[] aplicaDistinguir = aplicarSobreDistinguir.Split('|');
                                while (aplicaDistinguir.GetUpperBound(0) != 0)
                                {
                                    aplicaDistinguir = aplicarSobreDistinguir.Split('|');

                                    if (aplicaDistinguir[0] != "")
                                    {
                                        decimal sumaDistinguir = dtValoresFicha.AsEnumerable()
                                                               .Where(y => y.Field<string>("ETIQUETA") == aplicaDistinguir[0])
                                                               .Sum(x => Convert.ToDecimal(x.Field<decimal>("IMPORTE")));

                                        if (sumaDistinguir != 0)
                                        {
                                            decimal porcentajeDistinguir = (sumaDistinguir * 100) / sumaTotalesSobre;

                                            filaValores = dtValoresFicha.NewRow();
                                            filaValores["ETIQUETA"] = aplicaARBOL[0] + "_" + aplicaDistinguir[0];
                                            filaValores["IMPORTE"] = sumaTotalesAxLinea * porcentajeDistinguir / 100;
                                            dtValoresFicha.Rows.Add(filaValores);
                                            filaValores = null;
                                        }
                                    }
                                    aplicarSobreDistinguir = aplicarSobreDistinguir.Replace(aplicaDistinguir[0] + "|", "");
                                    if (aplicaDistinguir.GetUpperBound(0) == 0)
                                        break;
                                }

                                aplicar = aplicar.Replace(aplica[0] + "|", "");
                                aplicarARBOL = aplicarARBOL.Replace(aplicaARBOL[0] + "|", "");
                                if (aplica.GetUpperBound(0) == 0)
                                    break;
                            }

                            // TOPAR O NO 
                            aplicar = aplicarOriginal;
                            aplicarARBOL = aplicarOriginalArbol;

                            aplica = aplicar.Split('|');
                            aplicaARBOL = aplicarARBOL.Split('|');
                            hayTopados = 0;

                            while (aplica.GetUpperBound(0) != 0)
