                                                oGastosPatio["E+D/Cant"] = Convert.ToDecimal(oGastosPatio["E+D/Cant"]) + (Convert.ToDecimal(filaLinea["CANTIDAD"].ToString()) * entrega) + (Convert.ToDecimal(filaLinea["CANTIDAD"].ToString()) * devolucion);
