                                        oItemTaximetro[COL_DATA_ALQUILER_GASTOS_PATIO] = (importeGastosPatioEntregaDevolucionAlquiler + importeGastosPatioClasificacionReparacionAlquiler).ToString("##0.00");

                                        // SVP/CIF
                                        if (Convert.ToDecimal(filaLinea["CANON IMPORTE"]) != 0)
                                        {
                                            oItemTaximetro[COL_DATA_IMPORTE_VENTA] = ((Convert.ToDecimal(oItemTaximetro[COL_DATA_IMPORTE_VENTA].ToString())) + ((Convert.ToDecimal(filaLinea["CANTIDAD"].ToString()) * Convert.ToDecimal(filaLinea["PRECIO"].ToString()) * Convert.ToDecimal(filaLinea["CANON"])) / 100)).ToString("#,##0.00");
                                            importeVenta = importeVenta + ((Convert.ToDecimal(filaLinea["CANTIDAD"].ToString()) * Convert.ToDecimal(filaLinea["PRECIO"].ToString()) * Convert.ToDecimal(filaLinea["CANON"].ToString())) / 100);
                                            importeVentaLinea = importeVentaLinea + ((Convert.ToDecimal(filaLinea["CANTIDAD"].ToString()) * Convert.ToDecimal(filaLinea["PRECIO"].ToString()) * Convert.ToDecimal(filaLinea["CANON"].ToString())) / 100);
                                            importeFacturacionVentaUneCifCapitulos = importeFacturacionVentaUneCifCapitulos + ((Convert.ToDecimal(filaLinea["CANTIDAD"].ToString()) * Convert.ToDecimal(filaLinea["PRECIO"].ToString()) * Convert.ToDecimal(filaLinea["CANON"].ToString())) / 100);
                                            if (Convert.ToDecimal(filaCapitulo["DIAS TOTAL"]) == -1)
                                                importeGastosFinanciacionCapitulos = importeGastosFinanciacionCapitulos + (condicionesAplicar * ((Convert.ToDecimal(filaLinea["CANTIDAD"].ToString()) * Convert.ToDecimal(filaLinea["PRECIO"].ToString()) * Convert.ToDecimal(filaLinea["CANON"].ToString())) / 100) * ((diasPagoDefecto) / Convert.ToDecimal(365)));
                                            else
                                                importeGastosFinanciacionCapitulos = importeGastosFinanciacionCapitulos + (condicionesAplicar * ((Convert.ToDecimal(filaLinea["CANTIDAD"].ToString()) * Convert.ToDecimal(filaLinea["PRECIO"].ToString()) * Convert.ToDecimal(filaLinea["CANON"].ToString())) / 100) * ((Convert.ToDecimal(filaCapitulo["DIAS TOTAL"])) / Convert.ToDecimal(365)));
