                                                        precioTaximetroNoConsumible = precioCoste; // (precioCoste - (costeSuperficie * superficie));
                                                        precioTaximetroConsumible = 0;
                                                    }
                                                    else
                                                    {
                                                        precioTaximetroNoConsumible = (precioCoste - (costeSuperficie * superficie));
