                            // APLASTAR DTfacturas POR FECHA / AAF
                            dondeVa = "aplastar dtfacturas";
                            var datafacturas = from d in dtfacturas.AsEnumerable()
                                               orderby d.Field<string>("FECHA_CREACION"), d.Field<string>("AAF")
                                               group d by new
