                                            filaCantidad["CANTIDAD_QUEDA"] = Convert.ToDecimal(filaCantidad["CANTIDAD_QUEDA"]) - faltan;
                                            faltan = 0;
                                        }
                                        if (faltan == 0)
                                            break;
                                    }
                                }

                                // MIXTO
                                if (faltan > 0)
                                {
                                    filaEncontrada = dtAlbaranesAgrupado.Select("AAF = '" + filaPedido[dtfacturasAgrupados_aaf].ToString() + "' AND FECHA <= '" + filaPedido[dtfacturasAgrupados_fechaCreacion].ToString() + "' AND ESTADO = 'MIXTO' AND CANTIDAD_QUEDA > '0'");
                                    foreach (DataRow filaCantidad in filaEncontrada)
                                    {
