                                dondeVa = "recuperar coeficiente";
                                filaEncontrada = dtDatosConfiguracion.Select("Articulo = '" + filaPedido[dtfacturasAgrupados_articulo].ToString() + "' AND Concepto = 'Coef. Corrección PS Nuevo'");
                                foreach (DataRow filaTax in filaEncontrada)
                                    coeficienteNuevo = Convert.ToDecimal(filaTax["Valor"]);
