                                {
                                    filaEncontrada = dtDatosConfiguracion.Select("Articulo = '" + filaPedido[dtfacturasAgrupados_articulo].ToString() + "' AND Concepto = 'Coef. Corrección PS Usado' AND Valorar ='MPO_LIQ'");
