                                    filaEncontrada = dtArticulos.Select("Articulo = '" + filaPedido[dtfacturasAgrupados_articulo].ToString() + "'");
                                    if (filaEncontrada.Count() == 0 && codigosTransporte.IndexOf(filaPedido[dtfacturasAgrupados_articulo].ToString().ToUpper()) == -1)
                                    {
                                        if (funcionalidades.noEsManual(filaPedido[dtfacturasAgrupados_articulo].ToString()))
                                        {
