                                            funcionalidades.guardarIncidencia(empresa, "FACTURA", numeroFactura, filaPedido[dtfacturasAgrupados_articulo].ToString(), "No hay PS del artículo.", 0, usuario, User.Identity.Name.ToString());
                                        }
