                                            precioCoste = Convert.ToDecimal(filaprecio["Precio"]);
                                    }
                                }

                                dondeVa = "calcular coste MPO";
                                importeCosteVenta = importeCosteVenta + (Convert.ToDecimal(filaPedido[dtfacturasAgrupados_usado]) * precioCoste * coeficienteUsado);
                                importeCosteVenta = importeCosteVenta + (Convert.ToDecimal(filaPedido[dtfacturasAgrupados_mixto]) * precioCoste * coeficienteMixto);
                                importeCosteVenta = importeCosteVenta + (Convert.ToDecimal(filaPedido[dtfacturasAgrupados_nuevo]) * precioCoste * coeficienteNuevo);

                                dec_importeCosteMPOMixto = dec_importeCosteMPOMixto + (Convert.ToDecimal(filaPedido[dtfacturasAgrupados_mixto]) * precioCoste * coeficienteMixto);
                                dec_importeCosteMPONuevo = dec_importeCosteMPONuevo + (Convert.ToDecimal(filaPedido[dtfacturasAgrupados_nuevo]) * precioCoste * coeficienteNuevo);
                                dec_importeCosteMPOUsado = dec_importeCosteMPOUsado + (Convert.ToDecimal(filaPedido[dtfacturasAgrupados_usado]) * precioCoste * coeficienteUsado);
