                        //            ROP = Convert.ToDecimal(fila["IMPORTE"]);
                        //    }

                        //    oItemResultados = dtResultados.NewRow();
                        //    oItemResultados["FACTURA"] = txtObra.Text;
                        //    oItemResultados["CONCEPTO"] = "FACTURACION";
                        //    oItemResultados["IMPORTE"] = facturacion;
                        //    dtResultados.Rows.Add(oItemResultados);
                        //    oItemResultados = null;

                        //    oItemResultados = dtResultados.NewRow();
                        //    oItemResultados["FACTURA"] = txtObra.Text;
                        //    oItemResultados["CONCEPTO"] = "DIAS";
