        protected void CambioVersionSeleccion(object sender, EventArgs e)
        {
            string strConexion;
            SqlConnection conexion;
            SqlCommand comando;

            try
            {
                strConexion = funcionalidades.recuperarTexto(ConfigurationManager.ConnectionStrings["SQL_ROP"].ToString());
                conexion = new SqlConnection(strConexion);
                conexion.Open();
                comando = conexion.CreateCommand();
                comando.CommandText = "sp_ROP_ConfiguracionVersionUsoActual";
                comando.CommandTimeout = 60;
                comando.CommandType = CommandType.StoredProcedure;
                comando.Parameters.Clear();
                comando.Parameters.AddWithValue("@version", cmbVersion.Text);
                comando.ExecuteNonQuery();
                comando.Dispose();
                conexion.Close();
                conexion.Dispose();

                System.Data.DataTable dtValores;
                dtValores = new System.Data.DataTable();
                dtValores.Columns.Add("ETIQUETA");
                dtValores.Columns.Add("CONCEPTO");
                dtValores.Columns.Add("IMPORTE", typeof(decimal));
                dtValores.Columns.Add("PORCENTAJE", typeof(decimal));
                dtValores.Columns.Add("IMPORTE PREVISTO", typeof(decimal));
                dtValores.Columns.Add("PORCENTAJE PREVISTO", typeof(decimal));
                pintarArbolNUEVO(ref dtValores, true, false, false, true);
                //txtNombreOferta.Text = "";
                txtObra.Text = "";
                txtNombreObra.Text = "";
                txtNombreCliente.Text = "";
                txtCuentaCliente.Text = "";
                txtMasterObra.Text = "";
                txtCentroCoste.Text = "";
                txtMoneda.Text = "";
                lblCabeceraImprimir1.Text = String.Format("{0}: {1}\t\t\t\t\t{2}: {3}\t\t\t\t\t{4}: {5}", lblConcepto.Text.Trim(), cmbConcepto.Text.Trim(), lblEmpresa.Text.Trim(), cmbEmpresa.Text.Trim(), lblNumero.Text.Trim(), txtNumero.Text.Trim());
                lblCabeceraImprimir2.Text = String.Format("{0}: {1}\t\t\t{2}: {3}", lblCuentaCliente.Text.Trim(), txtCuentaCliente.Text.Trim(), lblNombreCliente.Text.Trim(), txtNombreCliente.Text.Trim());
                lblCabeceraImprimir3.Text = String.Format("{0}: {1}\t\t\t", lblNombreObra.Text.Trim(), txtNombreObra.Text.Trim());
                lblCabeceraImprimir4.Text = String.Format("{0}: {1}\t\t\t\t\t{2}: {3}\t\t\t\t\t{4}: {5}", lblMasterObra.Text.Trim(), txtMasterObra.Text.Trim(), lblCentroCoste.Text.Trim(), txtCentroCoste.Text.Trim(), lblMoneda.Text.Trim(), txtMoneda.Text.Trim());

                lblVersionUtilizada.Text = "";
                btnAbrirExcel.Visible = false;

                //dataTiempos.Visible = false;
                //dataTax.Visible = false;
                //dataGastosPatio.Visible = false;
                //dataGastosOficina.Visible = false;
                //dataGastosFijos.Visible = false;
                //dataAbonoMPO.Visible = false;
                //dataBuenTrato.Visible = false;
                //dataChatarra.Visible = false;
                //dataLiquidacion.Visible = false;
                //dataLineasArticulos.Visible = false;
                //dataFacturas.Visible = false;

                Session["datosTransporteOriginales"] = true;
                Session["datosFenolicosOriginales"] = true;
                chkBoxSoloEntrega.Checked = false;
                chkBoxSoloDevolucion.Checked = false;
                chkBoxSoloEntrega.Enabled = false;
                chkBoxSoloDevolucion.Enabled = false;
            }
            catch (Exception ex)
            {
                mostrarMensaje("Version - " + ex.Message);
            }
        }


        protected void btnAplicar_Click(object sender, EventArgs e)
        {
            string articulos = "";
            DataTable dtTiempos = new DataTable();
            Session["dtTiempos"] = dtTiempos;
            string usuarioRed = Session["usuarioRed"].ToString();
            DataTable dtPendienteDevolver = new DataTable();
            dtPendienteDevolver = (DataTable)Session["dtPendienteDevolver"];
            DataTable dtValoresFicha = new DataTable();
            dtValoresFicha = (DataTable)Session["dtValoresFicha"];
            string articulosSimulacion = Session["articulosSimulacion"].ToString();
            string articulosSimulacionCambio = Session["articulosSimulacionCambio"].ToString();
            string monedaSimulacion = Session["monedaSimulacion"].ToString();
            string grupoPrecioSimulacion = Session["grupoPrecioSimulacion"].ToString();
            DateTime fechaCreacionObra = Convert.ToDateTime(Session["fechaCreacionObra"]);
            DateTime fechaPrecioObra = Convert.ToDateTime(Session["fechaPrecioObra"]);

            try
            {
                System.Data.DataTable dtPrecios = new System.Data.DataTable();
                DataRow[] filaEncontrada;

                // Armar los artículos con las fechas adecuadas / Calculos los precios a esas fechas
                if (cmbFechasSimulacion.SelectedValue.ToString() != "Fecha entrega artículo")
                {
                    filaEncontrada = dtPendienteDevolver.Select("ARTICULO <> ''");
                    foreach (DataRow filaDT in filaEncontrada)
                    {
                        if (cmbFechasSimulacion.SelectedValue.ToString() == "Fecha creación obra")
                            articulos = articulos + filaDT["ARTICULO"].ToString() + "|" + fechaCreacionObra + ";";
                        else
                            articulos = articulos + filaDT["ARTICULO"].ToString() + "|" + Convert.ToDateTime(txtFechaSimulacion.Text).ToString("dd/MM/yyyy") + ";";
                    }
                    dtPrecios = funcionalidades.localizarPreciosVentaArticulos(ref dtTiempos, cmbEmpresa.SelectedItem.ToString(), articulos, monedaSimulacion, articulos, txtNumero.Text, "", "", grupoPrecioSimulacion, "", usuarioRed);
                }
                else
                    dtPrecios = funcionalidades.localizarPreciosVentaArticulos(ref dtTiempos, cmbEmpresa.SelectedItem.ToString(), articulosSimulacion, monedaSimulacion, articulosSimulacionCambio, txtNumero.Text, "", "", grupoPrecioSimulacion, "", usuarioRed);

                // Recalcular las líneas del datatable de pendientes
                filaEncontrada = dtPendienteDevolver.Select("ARTICULO <> ''");
                foreach (DataRow filaDT in filaEncontrada)
                {
                    filaDT["PVP"] = 0;
                    filaEncontrada = dtPrecios.Select("Articulo = '" + filaDT["ARTICULO"].ToString().Trim() + "'");
                    foreach (DataRow filaPrecio in filaEncontrada)
                    {
                        if (!String.IsNullOrEmpty(Convert.ToString(filaPrecio["Precio"])))
                            filaDT["PVP"] = Math.Round(Convert.ToDecimal(filaPrecio["Precio"]), 2);
                    }
                    filaDT["PVP ORIGINAL"] = Convert.ToDouble(filaDT["CANTIDAD ORIGINAL"]) * Convert.ToDouble(filaDT["PVP"]);
                    filaDT["PVP OBRA"] = Convert.ToDouble(filaDT["CANTIDAD"]) * Convert.ToDouble(filaDT["PVP"]);
                    if (Convert.ToDouble(filaDT["CANTIDAD ENTREGADA"]) != 0)
                        filaDT["FACTURACION"] = (Convert.ToDouble(filaDT["ALQUILER"]) / Convert.ToDouble(filaDT["CANTIDAD ENTREGADA"]) * (Convert.ToDouble(filaDT["CANTIDAD ORIGINAL"]) - Convert.ToDouble(filaDT["CANTIDAD"]))).ToString("#,##0.00");
                    else
                        filaDT["FACTURACION"] = 0;
                    if (Convert.ToDouble(filaDT["PVP OBRA"]) != 0)
                        filaDT["PORCENTAJE"] = (Convert.ToDouble(filaDT["FACTURACION"]) / Convert.ToDouble(filaDT["PVP OBRA"])).ToString("#,##0.00");
                    else
                        filaDT["PORCENTAJE"] = 0;
                    //if (Convert.ToDouble(filaDT["PVP OBRA"]) > 0)
                    filaDT["FACTURACION LIQUIDACION"] = Convert.ToDouble(filaDT["PVP OBRA"]) - (Convert.ToDouble(filaDT["PVP OBRA"]) * Convert.ToDouble(filaDT["DESCUENTO"]) / 100);
                    //else
                    //    filaDT["FACTURACION LIQUIDACION"] = 0;
                    filaDT["COSTE"] = Convert.ToDouble(filaDT["CANTIDAD"]) * Convert.ToDouble(filaDT["PS"]) * Convert.ToDouble(filaDT["CORRECION"]);
                    filaDT.AcceptChanges();
                }

                // Calcular los subtotales
                calcularSubtotalesSimulacion(true);

                DataView dvPendientes;
                dvPendientes = dtPendienteDevolver.Select("([CANTIDAD ORIGINAL] <> 0  OR [CONCEPTO COMPLETO] = 'TOTAL') AND SUMAR = 1").CopyToDataTable().DefaultView;
                dvPendientes.Sort = "FAMILIA ASC, SUBFAMILIA ASC, ARTICULO ASC";
                grvDatos.DataSource = dvPendientes.ToTable();
                //grvDatos.DataSource = dtPendienteDevolver;
                grvDatos.DataBind();

                pintarArbolNUEVO(ref dtValoresFicha, false, true, true, true);

                btnSimular.Enabled = true;
                btnSimular.CssClass = "btn btn-danger";
            }
            catch (Exception ex)
            {
                btnSimular.Enabled = false;
                btnSimular.CssClass = "btn btn-danger";

                mostrarMensaje("Aplicar - " + ex.Message);
            }
            finally
            {
                Session["dtTiempos"] = dtTiempos;
            }
        }

