                        dias = 0;
                        importeAlquiler = 0;
                        fecha = new DateTime();

                        // COLOCO EN CERO LA CANTIDAD FACTURADA
                        filaDT["CANTIDAD FACTURADA"] = 0;

                        calcularPorPedido = false;
                        if (dtFacturasLineas.Rows.Count > 0)
                        {
                            filaEncontrada = dtFacturasLineas.Select("CANON = 0 AND ITEM = '" + filaDT["ARTICULO"].ToString() + "' AND [SALES TYPE] = '" + WSGeneral.SalesType.Alquiler.ToString().ToUpper() + "' AND [IMPORTE] >= 0 AND [SUBTIPO] = 'USAR'");
                            if (filaEncontrada.Length > 0)
                            {
                                // sumar y restar los movimientos de ese item hasta la fecha factura y eso sera lo que se fatcura.
                                fecha = dtFacturasLineas.AsEnumerable()
                                .Where(y => y.Field<int>("CANON") == 0 && y.Field<string>("ITEM") == filaDT["ARTICULO"].ToString().Trim() && y.Field<string>("SALES TYPE") == WSGeneral.SalesType.Alquiler.ToString().ToUpper())
