                                if (unidadesDia != 0)
                                    euroDia = importeAlquiler / unidadesDia;

                                simularImporteFacturacionAlquiler = simularImporteFacturacionAlquiler + (euroDia * cantidadFacturada * dias);

                                filaDT["EURO DIA"] = euroDia;
                                filaDT["DIAS"] = dias;
                                filaDT["FECHA ULTIMA FACTURA"] = fecha.ToString("dd/MM/yyyy");
                                filaDT["IMPORTE ALQUILER"] = importeAlquiler;
                                filaDT["UNIDADES DIA"] = unidadesDia;
                                filaDT["CANTIDAD FACTURADA"] = cantidadFacturada;
                                filaDT.AcceptChanges();

                                filaValores = dtFacturar.NewRow();
                                filaValores["ITEM"] = filaDT["ARTICULO"].ToString().Trim();
                                filaValores["FECHA"] = fecha;
                                filaValores["DIAS"] = dias;
                                filaValores["CANTIDAD"] = cantidadFacturada;
                                filaValores["UNIDADES DIA"] = unidadesDia;
                                filaValores["EURO DIA"] = euroDia;
                                filaValores["IMPORTE"] = (euroDia * cantidadFacturada * dias);
                                dtFacturar.Rows.Add(filaValores);
                                filaValores = null;

                                // Calcular importes de entregas posteriores a la última fecha factura // sumar al importe anterior calculado
                                dondeVa = "POSTERIORES " + filaDT["ARTICULO"].ToString().Trim();
                                importeAlquilerMovimientos = 0;
                                if (dtMovimientosAgrupados.Rows.Count > 0)
                                {
                                    filaEncontrada = dtMovimientosAgrupados.Select("ITEM = '" + filaDT["ARTICULO"].ToString().Trim() + "' AND [FECHA] > '" + fecha + "'");
                                    if (filaEncontrada.Length > 0)
                                    {
                                        foreach (DataRow fila in filaEncontrada)
                                        {
                                            if (!chkFacturarNegativos.Checked)
                                            {
                                                if (Convert.ToDecimal(filaDT["CANTIDAD FACTURADA"]) + Convert.ToDecimal(fila["CANTIDAD"]) < 0)
                                                    cantidadAFacturar = (-1) * Convert.ToDecimal(filaDT["CANTIDAD FACTURADA"]);
                                                else
                                                    cantidadAFacturar = Convert.ToDecimal(fila["CANTIDAD"]);
                                            }
                                            else
                                                cantidadAFacturar = Convert.ToDecimal(fila["CANTIDAD"]);

                                            filaDT["CANTIDAD FACTURADA"] = Convert.ToDecimal(filaDT["CANTIDAD FACTURADA"]) + Convert.ToDecimal(fila["CANTIDAD"]);
                                            filaDT.AcceptChanges();

                                            dias = Convert.ToDateTime(txtFechaSimulacion.Text).Subtract(Convert.ToDateTime(fila["FECHA"])).Days + 1;
                                            importeAlquilerMovimientos = importeAlquilerMovimientos + (euroDia * cantidadAFacturar * dias);

                                            filaValores = dtFacturar.NewRow();
                                            filaValores["ITEM"] = filaDT["ARTICULO"].ToString().Trim();
                                            filaValores["FECHA"] = Convert.ToDateTime(fila["FECHA"]);
                                            filaValores["DIAS"] = dias;
                                            filaValores["CANTIDAD"] = cantidadAFacturar; // Convert.ToInt32(fila["CANTIDAD"]);
                                            filaValores["UNIDADES DIA"] = unidadesDia;
                                            filaValores["EURO DIA"] = euroDia;
                                            filaValores["IMPORTE"] = (euroDia * cantidadAFacturar * dias);  //(euroDia * Convert.ToDecimal(fila["CANTIDAD"]) * dias);
                                            dtFacturar.Rows.Add(filaValores);
                                            filaValores = null;
                                        }
                                    }
                                }
                                simularImporteFacturacionAlquiler = simularImporteFacturacionAlquiler + importeAlquilerMovimientos;
                            }
                            else
                                calcularPorPedido = true;
                        }
                        else
                            calcularPorPedido = true;

                        if (calcularPorPedido)
                        {
                            euroDia = 0;
                            importeAlquiler = 0;
                            unidadesDia = 0;
                            if (dtPedidosAlquilerCompleto.Rows.Count > 0)
                            {
                                filaEncontrada = dtPedidosAlquilerCompleto.Select("ITEM = '" + filaDT["ARTICULO"].ToString().Trim() + "'");
                                if (filaEncontrada.Length > 0)
                                {
                                    foreach (DataRow fila in filaEncontrada)
                                    {
                                        importeAlquiler = importeAlquiler + (Convert.ToDecimal(fila["SALES QTY"]) * Convert.ToDecimal(fila["EURO DIA"]));
                                        unidadesDia = unidadesDia + Convert.ToDecimal(fila["SALES QTY"]);
                                    }
                                }
                                if (unidadesDia != 0)
                                    euroDia = importeAlquiler / unidadesDia;

                                importeAlquilerMovimientos = 0;
                                if (dtMovimientosAgrupados.Rows.Count > 0)
                                {
                                    filaEncontrada = dtMovimientosAgrupados.Select("ITEM = '" + filaDT["ARTICULO"].ToString().Trim() + "'");
                                    if (filaEncontrada.Length > 0)
                                    {
                                        foreach (DataRow fila in filaEncontrada)
                                        {
                                            if (!chkFacturarNegativos.Checked)
                                            {
                                                if (Convert.ToDecimal(filaDT["CANTIDAD FACTURADA"]) + Convert.ToDecimal(fila["CANTIDAD"]) < 0)
                                                    cantidadAFacturar = (-1) * Convert.ToDecimal(filaDT["CANTIDAD FACTURADA"]);
                                                else
                                                    cantidadAFacturar = Convert.ToDecimal(fila["CANTIDAD"]);
                                            }
                                            else
                                                cantidadAFacturar = Convert.ToDecimal(fila["CANTIDAD"]);

                                            filaDT["CANTIDAD FACTURADA"] = Convert.ToDecimal(filaDT["CANTIDAD FACTURADA"]) + Convert.ToDecimal(fila["CANTIDAD"]);
                                            filaDT.AcceptChanges();

                                            dias = Convert.ToDateTime(txtFechaSimulacion.Text).Subtract(Convert.ToDateTime(fila["FECHA"])).Days + 1;
                                            if (chkFacturarDiasMinimo.Checked && dias < diasMinimoFacturacion)
                                                dias = diasMinimoFacturacion;

                                            importeAlquilerMovimientos = importeAlquilerMovimientos + (euroDia * cantidadAFacturar * dias);

                                            filaValores = dtFacturar.NewRow();
                                            filaValores["ITEM"] = filaDT["ARTICULO"].ToString().Trim();
                                            filaValores["FECHA"] = Convert.ToDateTime(fila["FECHA"]);
                                            filaValores["DIAS"] = dias;
                                            filaValores["CANTIDAD"] = cantidadAFacturar; // Convert.ToInt32(fila["CANTIDAD"]);
                                            filaValores["EURO DIA"] = euroDia;
                                            filaValores["IMPORTE"] = (euroDia * cantidadAFacturar * dias);
                                            dtFacturar.Rows.Add(filaValores);
                                            filaValores = null;
                                        }
                                    }
                                }
                                simularImporteFacturacionAlquiler = simularImporteFacturacionAlquiler + importeAlquilerMovimientos;
                            }
                        }
                    }


                    // GASTOS_VARIABLES_ENTREGA_DEVOLUCION
                    // GASTOS_VARIABLES_CLASIFICACION_REPARACION
                    devolucion = 0;
                    precioGastosPatio = 0;
                    clasificarRepararDirecto = 0;
                    clasificarRepararIndirecto = 0;
                    clasificarDirecto = 0;
                    clasificarIndirecto = 0;
                    repararDirecto = 0;
                    repararIndirecto = 0;
                    aafBuscar = filaDT["ARTICULO"].ToString().Trim();
                    filaEncontrada = dtGastosPatio.Select("ProductId = '" + filaDT["ARTICULO"].ToString().Trim() + "'");
                    foreach (DataRow filaGP in filaEncontrada)
                    {
                        if (!String.IsNullOrEmpty(Convert.ToString(filaGP["AAF"])))
                            aafBuscar = Convert.ToString(filaGP["AAF"]);
                    }

                    filaEncontrada = dtGastosPatio.Select("ProductId = '" + aafBuscar + "'");
                    foreach (DataRow filaGP in filaEncontrada)
                    {
                        if (!String.IsNullOrEmpty(Convert.ToString(filaGP["Devolucion"])))
                            devolucion = Convert.ToDecimal(filaGP["Devolucion"]);
                        precioGastosPatio = Convert.ToDecimal(filaGP["Precio"]);
                        RatioClasificarReparar = Convert.ToDecimal(filaGP["RatioClasificarReparar"]);

                        if (!String.IsNullOrEmpty(Convert.ToString(filaGP["ClasificarReparar"])))
                        {
                            if (!String.IsNullOrEmpty(Convert.ToString(filaGP["ClasificarRepararDirecto"])))
                                clasificarRepararDirecto = Convert.ToDecimal(filaGP["ClasificarRepararDirecto"]);
                            if (!String.IsNullOrEmpty(Convert.ToString(filaGP["ClasificarRepararIndirecto"])))
                                clasificarRepararIndirecto = Convert.ToDecimal(filaGP["ClasificarRepararIndirecto"]);
                        }
                        else
                        {
                            if (!String.IsNullOrEmpty(Convert.ToString(filaGP["ClasificarDirecto"])))
                                clasificarDirecto = Convert.ToDecimal(filaGP["ClasificarDirecto"]);
                            if (!String.IsNullOrEmpty(Convert.ToString(filaGP["ClasificarIndirecto"])))
                                clasificarIndirecto = Convert.ToDecimal(filaGP["ClasificarIndirecto"]);
                            if (!String.IsNullOrEmpty(Convert.ToString(filaGP["RepararDirecto"])))
                                repararDirecto = Convert.ToDecimal(filaGP["RepararDirecto"]);
                            if (!String.IsNullOrEmpty(Convert.ToString(filaGP["RepararIndirecto"])))
                                repararIndirecto = Convert.ToDecimal(filaGP["RepararIndirecto"]);
                        }
                    }
                    importeGastosPatioEntregaDevolucionAlquiler = importeGastosPatioEntregaDevolucionAlquiler + (Convert.ToDecimal(filaDT["CANTIDAD"]) * devolucion * precioGastosPatio);

                    importeGastosPatioClasificacionReparacionAlquiler = importeGastosPatioClasificacionReparacionAlquiler + ((Convert.ToDecimal(filaDT["CANTIDAD"].ToString()) * clasificarRepararDirecto * precioGastosPatio) / efectividad);
                    importeGastosPatioClasificacionReparacionAlquiler = importeGastosPatioClasificacionReparacionAlquiler + ((Convert.ToDecimal(filaDT["CANTIDAD"].ToString()) * clasificarRepararIndirecto * precioGastosPatio) / efectividad);
                    importeGastosPatioClasificacionReparacionAlquiler = importeGastosPatioClasificacionReparacionAlquiler + ((Convert.ToDecimal(filaDT["CANTIDAD"].ToString()) * clasificarDirecto * precioGastosPatio) / efectividad);
                    importeGastosPatioClasificacionReparacionAlquiler = importeGastosPatioClasificacionReparacionAlquiler + ((Convert.ToDecimal(filaDT["CANTIDAD"].ToString()) * clasificarIndirecto * precioGastosPatio) / efectividad);
                    importeGastosPatioClasificacionReparacionAlquiler = importeGastosPatioClasificacionReparacionAlquiler + ((Convert.ToDecimal(filaDT["CANTIDAD"].ToString()) * RatioClasificarReparar * repararDirecto * precioGastosPatio) / efectividad);
                    importeGastosPatioClasificacionReparacionAlquiler = importeGastosPatioClasificacionReparacionAlquiler + ((Convert.ToDecimal(filaDT["CANTIDAD"].ToString()) * RatioClasificarReparar * repararIndirecto * precioGastosPatio) / efectividad);

                    // AJUSTES_BU 
                    decimal real = 0;
                    decimal presupuesto = 0;
                    decimal bonificacionCentral = 0;
                    decimal bonificacionBU = 0;


                    filaEncontrada = dtGastosFijos.Select("ITEM = '" + filaDT["ARTICULO"].ToString().Trim() + "'");
                    foreach (DataRow fila in filaEncontrada)
                    {
                        if (gastosFijosPorFacturacion)
                        {
                            totalAlquiler = Convert.ToDecimal(fila["FACTURACION ALQUILER"]) + simularImporteFacturacionAlquiler;
                            totalVenta = Convert.ToDecimal(fila["FACTURACION VENTA"]);

                            totalGastosFijosBU = (KABU * totalAlquiler) + (KVBU * totalVenta);
                            totalGastosFijosCentral = (KAHQ * totalAlquiler) + (KVHQ * totalVenta);
                        }
                        else
                        {
                            costeAlquiler = Convert.ToDecimal(fila["COSTE ALQUILER"]) + abonoMPOTC + abonoMPOTNC;
                            costeVentas = Convert.ToDecimal(fila["COSTE VENTA"]) + importeTotalCosteLIQUsado;

                            costeVentas = (-1) * costeVentas;
                            costeAlquiler = (-1) * costeAlquiler;

                            totalGastosFijosBU = (KABU * costeAlquiler) + (KVBU * costeVentas);
                            totalGastosFijosCentral = (KAHQ * costeAlquiler) + (KVHQ * costeVentas);
                        }
                    }

                    filaEncontrada = dtAjustesDatosBU.Select("Articulo = '" + filaDT["ARTICULO"].ToString().Trim() + "'");
                    foreach (DataRow fila in filaEncontrada)
                    {

                        if (fila["Escenario"].ToString() == "0")
                            real = Convert.ToDecimal(fila["Facturacion"].ToString());
                        if (fila["Escenario"].ToString() == "1")
                            presupuesto = Convert.ToDecimal(fila["Facturacion"].ToString());
                    }
                    if (presupuesto != 0)
                    {
                        if (Math.Abs(real / presupuesto) < cumplimientoBajoPorcentaje)
                        {
                            if (cumplimientoBajoAfectaGFCentral.ToUpper() == "SI")
                                bonificacionCentral = totalGastosFijosCentral * (bonificacionCumplimientoBajoPorcentaje); 
                            if (cumplimientoBajoAfectaGFBU.ToUpper() == "SI")
                                bonificacionBU = totalGastosFijosBU * (bonificacionCumplimientoBajoPorcentaje); 
                        }
                        if (Math.Abs(real / presupuesto) > cumplimientoAltoPorcentaje)
                        {
                            if (cumplimientoAltoAfectaGFCentral.ToUpper() == "SI")
                                bonificacionCentral = totalGastosFijosCentral * (bonificacionCumplimientoAltoPorcentaje);
                            if (cumplimientoAltoAfectaGFBU.ToUpper() == "SI")
                                bonificacionBU = totalGastosFijosBU * (bonificacionCumplimientoAltoPorcentaje);
                        }
                    }
                    bonificacionBUTotal = bonificacionBUTotal + bonificacionCentral + bonificacionBU;

                    // El TAXIMETRO y AJUSTES que han generado en esa obra los artículos y cantidades que liquidamos, tenemos que abonarlos y ponerlos en su correspondiente ABONO MPO (La parte que corresponda a CONSUMIBLE o NO CONSUMIBLE). 
                    // TAXIMETROS
                    decimal abonoTNCSimulacionLINEA = 0;
                    decimal abonoTCSimulacionLINEA = 0;

                    filaEncontrada = dtValoresFichaArticulosPorItem.Select("ETIQUETA = 'TOTAL_ABONO_MPO_TNC' AND ITEM = '" + filaDT["ARTICULO"].ToString().Trim() + "'");
                    if (filaEncontrada.Length > 0)
                    {
                        foreach (DataRow fila in filaEncontrada)
                            abonoTNCSimulacionLINEA = abonoTNCSimulacionLINEA + Convert.ToDecimal(fila["IMPORTE"]);
                    }

                    filaEncontrada = dtValoresFichaArticulosPorItem.Select("ETIQUETA = 'TOTAL_ABONO_MPO_TC' AND ITEM = '" + filaDT["ARTICULO"].ToString().Trim() + "'");
                    if (filaEncontrada.Length > 0)
                    {
                        foreach (DataRow fila in filaEncontrada)
                        {
                            abonoTCSimulacionLINEA = abonoTCSimulacionLINEA + Convert.ToDecimal(fila["IMPORTE"]);
                        }
                    }

                    abonoMPOTCLINEA = Math.Abs(abonoMPOTCLINEA);
                    abonoMPOTNCLINEA = Math.Abs(abonoMPOTNCLINEA);

                    // TOPAR ABONOS TAX MPO
                    if (limitarAbonoTaxMPO)
                    {
                        decimal abonoMax1 = 0;
                        decimal abonoMax2 = 0;

                        // ABONO MPO TC
                        abonoMax1 = (importeTotalCosteLIQUsadoLINEA * porcentajeAbonoTaxMPO) / 100;
                        abonoMax2 = ((abonoMPOTCLINEA + abonoTCSimulacionLINEA) * porcentajeMaxAbonoTaxMPO) / 100;

                        // 05/03/2025
                        abonoMax1 = Math.Abs(abonoMax1);
                        abonoMax2 = Math.Abs(abonoMax2);

                        if (abonoMax1 < abonoMax2)
                            abonoMPOTCLINEA = abonoMax1;
                        else
                            abonoMPOTCLINEA = abonoMax2;

                        DataRow oItemAbonoMPO;
                        oItemAbonoMPO = dtAbonoMPONuevo.NewRow();
                        oItemAbonoMPO["ITEM"] = filaDT["ARTICULO"].ToString().Trim();
                        oItemAbonoMPO["TIPO"] = "CONSUMIBLE";
                        oItemAbonoMPO["ABONO MPO"] = abonoMPOTCLINEA;
                        dtAbonoMPONuevo.Rows.Add(oItemAbonoMPO);
                        oItemAbonoMPO = null;

                        // ABONO MPO TNC
                        abonoMax1 = (importeTotalCosteLIQUsadoLINEA * porcentajeAbonoTaxMPO) / 100;
                        abonoMax2 = ((abonoMPOTNCLINEA + abonoTNCSimulacionLINEA) * porcentajeMaxAbonoTaxMPO) / 100;

                        // 05/03/2025
                        abonoMax1 = Math.Abs(abonoMax1);
                        abonoMax2 = Math.Abs(abonoMax2);

                        if (abonoMax1 <abonoMax2)
                            abonoMPOTNCLINEA = abonoMax1;
                        else
                            abonoMPOTNCLINEA = abonoMax2;

                        oItemAbonoMPO = dtAbonoMPONuevo.NewRow();
                        oItemAbonoMPO["ITEM"] = filaDT["ARTICULO"].ToString().Trim();
                        oItemAbonoMPO["TIPO"] = "NO CONSUMIBLE";
                        oItemAbonoMPO["ABONO MPO"] = abonoMPOTNCLINEA;
                        dtAbonoMPONuevo.Rows.Add(oItemAbonoMPO);
                        oItemAbonoMPO = null;
                    }
                }


                // FACTURACION
                dondeVa = "FACTURACION";
                filaEncontrada = dtValoresFicha.Select("ETIQUETA = 'ALQUILERES'");
                if (filaEncontrada.Length > 0)
                {
                    foreach (DataRow fila in filaEncontrada)
                    {
                        if (chkFacturarSimulacion.Checked)
                            fila["IMPORTE"] = (alquileresSimulacion + simularImporteFacturacionAlquiler).ToString("#,##0.00");
                        else
