                else
                {
                    filaValores = dtValoresFicha.NewRow();
                    filaValores["ETIQUETA"] = "ALQUILERES";
                    filaValores["CONCEPTO"] = preservarNombreObra;
                    filaValores["IMPORTE"] = (simularImporteFacturacionAlquiler).ToString("#,##0.00");
                    filaValores["PORCENTAJE"] = "0.00";
                    dtValoresFicha.Rows.Add(filaValores);
                    filaValores = null;
                }
                if (!chkFacturarSimulacion.Checked)
                    simularImporteFacturacionAlquiler = 0;

                dondeVa = "ACTUALIZAR VENTAS_MATERIAL_ALQUILADO_LIQUIDACIONES";
                if (txtFacturacionOtrosConceptos.Text != "")
                {
                    filaEncontrada = dtValoresFicha.Select("ETIQUETA = 'VENTAS_MATERIAL_ALQUILADO_LIQUIDACIONES'");
                    if (filaEncontrada.Length > 0)
                    {
                        foreach (DataRow fila in filaEncontrada)
                        {
                            fila["IMPORTE"] = (Convert.ToDecimal(fila["IMPORTE"]) + Convert.ToDecimal(txtFacturacionOtrosConceptos.Text.Replace(".", ","))).ToString("#,##0.00");
                            fila.AcceptChanges();
                        }
                    }
                    else
                    {
                        filaValores = dtValoresFicha.NewRow();
                        filaValores["ETIQUETA"] = "VENTAS_MATERIAL_ALQUILADO_LIQUIDACIONES";
                        filaValores["CONCEPTO"] = preservarNombreObra;
                        filaValores["IMPORTE"] = (Convert.ToDecimal(txtFacturacionOtrosConceptos.Text.Replace(".", ","))).ToString("#,##0.00");
                        filaValores["PORCENTAJE"] = "0.00";
                        dtValoresFicha.Rows.Add(filaValores);
                        filaValores = null;
                    }
                }

                dondeVa = "ACTUALIZAR COSTE_MPO";
                filaEncontrada = dtValoresFicha.Select("ETIQUETA = 'COSTE_MPO'");
                if (filaEncontrada.Length > 0)
                {
                    foreach (DataRow fila in filaEncontrada)
                    {
                        fila["IMPORTE"] = (costeSimulacion + ((-1) * importeTotalCosteLIQUsado)).ToString("#,##0.00");
                        fila.AcceptChanges();
                    }
                }
                else
                {
                    filaValores = dtValoresFicha.NewRow();
                    filaValores["ETIQUETA"] = "COSTE_MPO";
                    filaValores["CONCEPTO"] = preservarNombreObra;
                    filaValores["IMPORTE"] = ((-1) * importeTotalCosteLIQUsado).ToString("#,##0.00");
                    filaValores["PORCENTAJE"] = "0.00";
                    dtValoresFicha.Rows.Add(filaValores);
                    filaValores = null;
                }

                // COSTE VENTA MATERIAL ALQUILADO
                dondeVa = "COSTE VENTAS MATERIAL ALQUILADO";
                filaEncontrada = dtValoresFicha.Select("ETIQUETA = 'COSTE_VENTAS_MATERIAL_ALQUILADO'");
                if (filaEncontrada.Length > 0)
                {
                    foreach (DataRow fila in filaEncontrada)
                    {
                        fila["IMPORTE"] = (costeVentaMaterialAlquilado).ToString("#,##0.00");
                        fila.AcceptChanges();
                    }
