                else
                {
                    filaValores = dtValoresFicha.NewRow();
                    filaValores["ETIQUETA"] = "COSTE_VENTAS_MATERIAL_ALQUILADO";
                    filaValores["CONCEPTO"] = preservarNombreObra;
                    filaValores["IMPORTE"] = (costeVentaMaterialAlquilado).ToString("#,##0.00");
                    filaValores["PORCENTAJE"] = "0.00";
                    dtValoresFicha.Rows.Add(filaValores);
                    filaValores = null;
                }

                dondeVa = "TAX NO CONSUMIBLE";
                taximetroNoConsumible = dtTax.AsEnumerable()
                                 .Sum(x => Convert.ToDecimal(x.Field<decimal>("TAX NO CONSUMIBLE")));
                filaEncontrada = dtValoresFicha.Select("ETIQUETA = 'TAXIMETRO_NO_CONSUMIBLE'");
                if (filaEncontrada.Length > 0)
                {
                    foreach (DataRow fila in filaEncontrada)
                    {
                        fila["IMPORTE"] = (taximetroNoConsumible).ToString("#,##0.00");
                        fila.AcceptChanges();
                    }
                }
                else
                {
                    filaValores = dtValoresFicha.NewRow();
                    filaValores["ETIQUETA"] = "TAXIMETRO_NO_CONSUMIBLE";
                    filaValores["CONCEPTO"] = preservarNombreObra;
                    filaValores["IMPORTE"] = (taximetroNoConsumible).ToString("#,##0.00");
                    filaValores["PORCENTAJE"] = "0.00";
                    dtValoresFicha.Rows.Add(filaValores);
                    filaValores = null;
                }

                dondeVa = "TAX CONSUMIBLE";
                taximetroConsumible = dtTax.AsEnumerable()
                                .Sum(x => Convert.ToDecimal(x.Field<decimal>("TAX CONSUMIBLE")));
                filaEncontrada = dtValoresFicha.Select("ETIQUETA = 'TAXIMETRO_CONSUMIBLE'");
                if (filaEncontrada.Length > 0)
                {
                    foreach (DataRow fila in filaEncontrada)
                    {
                        fila["IMPORTE"] = (taximetroConsumible).ToString("#,##0.00");
                        fila.AcceptChanges();
                    }
                }
                else
                {
                    filaValores = dtValoresFicha.NewRow();
                    filaValores["ETIQUETA"] = "TAXIMETRO_CONSUMIBLE";
                    filaValores["CONCEPTO"] = preservarNombreObra;
                    filaValores["IMPORTE"] = (taximetroConsumible).ToString("#,##0.00");
                    filaValores["PORCENTAJE"] = "0.00";
                    dtValoresFicha.Rows.Add(filaValores);
                    filaValores = null;
                }

                dondeVa = "ACTUALIZAR ABONO_MPO_TC";
                abonoMPOTC = Math.Abs(abonoMPOTC);
                filaEncontrada = dtValoresFicha.Select("ETIQUETA = 'ABONO_MPO_TC'");
                if (filaEncontrada.Length > 0)
                {
                    foreach (DataRow fila in filaEncontrada)
                    {
                        if (abonoMPOTC != 0)
                            fila["IMPORTE"] = (abonoMPOTC).ToString("#,##0.00");
                        else
                            fila["IMPORTE"] = (abonoTCSimulacion).ToString("#,##0.00");
                        fila.AcceptChanges();
                    }
                }
                else
                {
                    filaValores = dtValoresFicha.NewRow();
                    filaValores["ETIQUETA"] = "ABONO_MPO_TC";
