                }

                dondeVa = "pintar arbol 1 ";
                pintarArbolNUEVO(ref dtValoresFicha, false, false, true, true);

                // GASTOS_VARIABLES_ADMINISTRATIVO_COMERCIAL
                // -- eliminar cualquier facturación de simulación previa
                filaEncontrada = dtFacturasMO.Select("FACTURA = 'SIMULACION'");
                if (filaEncontrada.Length > 0)
                {
                    foreach (DataRow fila in filaEncontrada)
                        dtFacturasMO.Rows.Remove(fila);

                    dtFacturasMO.AcceptChanges();
                }

                // JUNIO 2025: cambios realizados en los ajustes replicados en la simulación
                // CALCULO GASTOS FIJOS Y AJUSTES DURACION OBRA POR LINEA
                // variables 
                int i;
                decimal ajustesPocentajeCargoMaximo = 0;
                int ajustesValorObraCorta = 0;
                decimal ajustesPorcentajeCorreccionObraCorta = 0;
                int ajustesValorObraLarga = 0;
                decimal ajustesPorcentajeCorreccionObraLarga = 0;
                int ajustesValorMaximo = 0;
                decimal ajustesPorcentajeCorreccionMaximo = 0;

                for (i = 0; i < dtTablaAjustesConsulta.Rows.Count; i++)
                {
                    // gastos fijos
                    ajustesAlcance = dtTablaAjustesConsulta.Rows[i]["CFGAJU_Alcance"].ToString();
                    ajustesPocentajeCargoMaximo = Convert.ToDecimal(dtTablaAjustesConsulta.Rows[i]["CFGAJU_PocentajeCargoMaximo"]) / 100;

                    ajustesValorObraCorta = Convert.ToInt32(dtTablaAjustesConsulta.Rows[i]["CFGAJU_ValorObraCorta"]);
                    ajustesPorcentajeCorreccionObraCorta = Convert.ToDecimal(dtTablaAjustesConsulta.Rows[i]["CFGAJU_PorcentajeCorreccionObraCorta"]) / 100;

                    ajustesValorObraLarga = Convert.ToInt32(dtTablaAjustesConsulta.Rows[i]["CFGAJU_ValorObraLarga"]);
                    ajustesPorcentajeCorreccionObraLarga = Convert.ToDecimal(dtTablaAjustesConsulta.Rows[i]["CFGAJU_PorcentajeCorreccionObraLarga"]) / 100;

                    ajustesValorMaximo = Convert.ToInt32(dtTablaAjustesConsulta.Rows[i]["CFGAJU_ValorMaximo"]);
                    ajustesPorcentajeCorreccionMaximo = Convert.ToDecimal(dtTablaAjustesConsulta.Rows[i]["CFGAJU_PorcentajeCorreccionMaximo"]) / 100;
                }

                dondeVa = "Gastos Fijos y ajustes duración obra";
                decimal diasCalculoGF = 0;
                string item;
                decimal BUimporteLinea = 0;
                decimal centralImporteLinea = 0;
                decimal GF = 0;
                decimal importeAjustesObraDuracionGF = 0;
                dondeVa = "dtAjustesGF";

                DataTable dtAjustesGF = new DataTable();
                dtAjustesGF.Columns.Add("ITEM", typeof(string));
                dtAjustesGF.Columns.Add("CANTIDAD", typeof(int));
                dtAjustesGF.Columns.Add("DIAS", typeof(int));
                dtAjustesGF.Columns.Add("EURO DIA", typeof(decimal));
                dtAjustesGF.Columns.Add("IMPORTE ALQUILER", typeof(decimal));
                dtAjustesGF.Columns.Add("KABU", typeof(decimal));
                dtAjustesGF.Columns.Add("KAHQ", typeof(decimal));
                dtAjustesGF.Columns.Add("BU IMPORTE LINEA", typeof(decimal));
                dtAjustesGF.Columns.Add("CENTRAL IMPORTE LINEA", typeof(decimal));
                dtAjustesGF.Columns.Add("GF", typeof(decimal));
                dtAjustesGF.Columns.Add("PORCENTAJE AJUSTE", typeof(decimal));
                dtAjustesGF.Columns.Add("IMPORTE AJUSTE ORIGINAL", typeof(decimal));
                dtAjustesGF.Columns.Add("IMPORTE AJUSTE", typeof(decimal));
                dtAjustesGF.Columns.Add("IMPORTE AJUSTE TOPE", typeof(decimal));

                for (i = 0; i < dtTax.Rows.Count; i++)
                {
                    item = Convert.ToString(dtTax.Rows[i]["ITEM"]).ToUpper();
                    diasCalculoGF = Convert.ToDecimal(dtTax.Rows[i]["DIAS"]);

                    decimal importeAlquilerProducto = 0;
                    decimal totalUnidadesDia = 0;
                    decimal importeFacturadoItem = 0;
                    euroDia = 0;

                    oFila = dtAjustesGF.NewRow();
                    oFila["ITEM"] = item;
                    totalUnidadesDia = dtTax.AsEnumerable()
                         .Where(y => y.Field<string>("ITEM") == item)
                         .Sum(x => Convert.ToDecimal(x.Field<decimal>("UNIDADES-DIA")));

                    importeFacturadoItem = 0;
                    if (dtFacturasLineas.Rows.Count > 0)
                        importeFacturadoItem = dtFacturasLineas.AsEnumerable()
                             .Where(y => y.Field<int>("CANON") == 0 && y.Field<string>("OBRA") == obra && y.Field<string>("ITEM") == item && y.Field<string>("SALES TYPE").ToUpper() == WSGeneral.SalesType.Alquiler.ToString().ToUpper())
                             .Sum(x => Convert.ToDecimal(x.Field<decimal>("IMPORTE")));

                    if (dtFacturar.Rows.Count > 0)
                        importeFacturadoItem = importeFacturadoItem + dtFacturar.AsEnumerable()
                             .Where(y => y.Field<string>("ITEM") == item)
                             .Sum(x => Convert.ToDecimal(x.Field<decimal>("IMPORTE")));


                    if (totalUnidadesDia != 0)
                        euroDia = importeFacturadoItem / totalUnidadesDia;

                    importeAlquilerProducto = Math.Abs(Convert.ToDecimal(dtTax.Rows[i]["CANTIDAD"])) * diasCalculoGF * euroDia;
                    oFila["CANTIDAD"] = Math.Abs(Convert.ToInt32(dtTax.Rows[i]["CANTIDAD"]));
                    oFila["DIAS"] = diasCalculoGF;
                    oFila["EURO DIA"] = euroDia;
                    oFila["IMPORTE ALQUILER"] = importeAlquilerProducto;

                    if (gastosFijosPorFacturacion)
                    {
                        BUimporteLinea = (Math.Abs(KABU) * importeAlquilerProducto);
                        centralImporteLinea = (Math.Abs(KAHQ) * importeAlquilerProducto);
                    }
                    else
                    {
                        costeAlquiler = Convert.ToDecimal(dtTax.Rows[i]["TAX CONSUMIBLE"]) + Convert.ToDecimal(dtTax.Rows[i]["TAX NO CONSUMIBLE"]) - Convert.ToDecimal(dtTax.Rows[i]["BONIFICACION"]);
                        costeAlquiler = (-1) * costeAlquiler;
                        BUimporteLinea = (KABU * costeAlquiler);
                        centralImporteLinea = (KAHQ * costeAlquiler);
                    }

                    GF = 0;
                    if (ajustesAlcance == "GF BU")
                        GF = BUimporteLinea;
                    else
                        GF = BUimporteLinea + centralImporteLinea;

                    oFila["KABU"] = Math.Abs(KABU);
                    oFila["KAHQ"] = Math.Abs(KAHQ);
                    oFila["BU IMPORTE LINEA"] = BUimporteLinea;
                    oFila["CENTRAL IMPORTE LINEA"] = centralImporteLinea;
                    GF = Math.Abs(GF);
                    if (diasCalculoGF > 0)
                        GF = (-1) * GF;
                    oFila["GF"] = GF;

                    bool diasNegativos = false;
                    if (diasCalculoGF < 0)
                    {
                        diasCalculoGF = Math.Abs(diasCalculoGF);
                        diasNegativos = true;
                    }

                    if (diasCalculoGF < 0)
                        porcentajeAjustesObraDuracionGFCapitulo = 0;
                    else if (diasCalculoGF == 0)
                        porcentajeAjustesObraDuracionGFCapitulo = ajustesPocentajeCargoMaximo;
                    else if (diasCalculoGF == ajustesValorObraCorta)
                        porcentajeAjustesObraDuracionGFCapitulo = ajustesPorcentajeCorreccionObraCorta;
                    else if (diasCalculoGF == ajustesValorObraLarga)
                        porcentajeAjustesObraDuracionGFCapitulo = ajustesPorcentajeCorreccionObraLarga;
                    else if (diasCalculoGF > ajustesValorMaximo)
                        porcentajeAjustesObraDuracionGFCapitulo = ajustesPorcentajeCorreccionMaximo;
                    else
                        porcentajeAjustesObraDuracionGFCapitulo = funcionalidades.interpolacion(dtAjustesDuracionGF, Convert.ToInt32(diasCalculoGF));
                    importeAjustesObraDuracionGF = importeAjustesObraDuracionGF + (GF * porcentajeAjustesObraDuracionGFCapitulo);
                    oFila["PORCENTAJE AJUSTE"] = porcentajeAjustesObraDuracionGFCapitulo;
                    if (diasNegativos)
                    {
                        oFila["IMPORTE AJUSTE ORIGINAL"] = (-1) * Math.Abs(GF * porcentajeAjustesObraDuracionGFCapitulo);
                        oFila["IMPORTE AJUSTE"] = (-1) * Math.Abs(GF * porcentajeAjustesObraDuracionGFCapitulo);
                    }
                    else
                    {
                        oFila["IMPORTE AJUSTE ORIGINAL"] = Math.Abs(GF * porcentajeAjustesObraDuracionGFCapitulo);
                        oFila["IMPORTE AJUSTE"] = Math.Abs(GF * porcentajeAjustesObraDuracionGFCapitulo);
                    }
                    dtAjustesGF.Rows.Add(oFila);
                    oFila = null;
                }

                // AJUSTE GASTOS FIJOS POR DURACIÓN
                importeAjustesObraDuracionGF = 0;
                var itemsDistintosGF = dtAjustesGF.AsEnumerable().Select(row => row.Field<string>("ITEM")).Distinct();
                foreach (var strItem in itemsDistintosGF)
                {
                    decimal decGF = dtAjustesGF.AsEnumerable()
                                .Where(y => y.Field<string>("ITEM") == strItem)
                                .Sum(x => Convert.ToDecimal(x.Field<decimal>("GF")));

                    decimal ajusteGFDuracion = dtAjustesGF.AsEnumerable()
                            .Where(y => y.Field<string>("ITEM") == strItem)
                            .Sum(x => Convert.ToDecimal(x.Field<decimal>("IMPORTE AJUSTE ORIGINAL")));


                    if (decGF < 0)
                    {
                        if (ajusteGFDuracion < 0)
                            ajusteGFDuracion = 0;
                    }
                    else
                    {
                        if (ajusteGFDuracion > 0)
                            ajusteGFDuracion = 0;
                    }

                    if (ajusteGFDuracion == 0)
                    {
                        DataRow[] filasSeleccionadas = dtAjustesGF.Select("ITEM = '" + strItem + "'");
                        foreach (DataRow row in filasSeleccionadas)
                        {
                            row["IMPORTE AJUSTE"] = 0;
                            row.AcceptChanges();
                        }
                    }
                }

                // TOPE
                importeAjustesObraDuracionGF = 0;
                itemsDistintosGF = dtAjustesGF.AsEnumerable().Select(row => row.Field<string>("ITEM")).Distinct();
                foreach (var strItem in itemsDistintosGF)
                {
                    decimal decGF = dtAjustesGF.AsEnumerable()
                                .Where(y => y.Field<string>("ITEM") == strItem)
                                .Sum(x => Convert.ToDecimal(x.Field<decimal>("GF")));

                    decimal ajusteGFDuracion = dtAjustesGF.AsEnumerable()
                            .Where(y => y.Field<string>("ITEM") == strItem)
                            .Sum(x => Convert.ToDecimal(x.Field<decimal>("IMPORTE AJUSTE")));

                    decimal topeAjusteGF = decGF * ajustesPorcentajeCorreccionMaximo;

                    if (Math.Abs(topeAjusteGF) < Math.Abs(ajusteGFDuracion))
                    {
                        if (ajusteGFDuracion < 0)
                            ajusteGFDuracion = (-1) * Math.Abs(topeAjusteGF);
                        else
                            ajusteGFDuracion = Math.Abs(topeAjusteGF);

                        DataRow[] filasSeleccionadas = dtAjustesGF.Select("ITEM = '" + strItem + "'");
                        foreach (DataRow row in filasSeleccionadas)
                        {
                            row["IMPORTE AJUSTE TOPE"] = ajusteGFDuracion;
                            row.AcceptChanges();
                            break;
                        }
                    }

                    importeAjustesObraDuracionGF = importeAjustesObraDuracionGF + ajusteGFDuracion;
                }
                if (importeAjustesObraDuracionGF != 0)
                {
                    filaEncontrada = dtValoresFicha.Select("ETIQUETA = 'AJUSTES_OBRA_DURACION_GF'");
                    if (filaEncontrada.Length > 0)
                    {
                        foreach (DataRow fila in filaEncontrada)
                        {
                            fila["IMPORTE"] = importeAjustesObraDuracionGF.ToString("#,##0.00");
                            fila.AcceptChanges();
                        }
                    }
                    else
                    {
                        filaValores = dtValoresFicha.NewRow();
                        filaValores["ETIQUETA"] = "AJUSTES_OBRA_DURACION_GF";
                        filaValores["CONCEPTO"] = preservarNombreObra;
                        filaValores["IMPORTE"] = (importeAjustesObraDuracionGF).ToString("#,##0.00");
                        filaValores["PORCENTAJE"] = "0.00";
                        filaValores["IMPORTE PREVISTO"] = "0.00";
                        filaValores["PORCENTAJE PREVISTO"] = "0.00";
                        dtValoresFicha.Rows.Add(filaValores);
                        filaValores = null;
