                    // AJUSTE NO CONSUMIBLE x AAF
                    dondeVa = "AJUSTE TAX OCUPACION // " + "AJUSTE NO CONSUMIBLE x AAF";
                    totalAjuste = dtTax.AsEnumerable()
                            .Where(y => y.Field<string>("ITEM") == dtOcupacion.Rows[i]["Articulo"].ToString())
