                    // ABONO MPO NO CONSUMIBLE x AAF
                    dondeVa = "AJUSTE TAX OCUPACION // " + "ABONO MPO NO CONSUMIBLE x AAF";
                    totalAbonoMPONC = dtAbonoMPONuevo.AsEnumerable()
                       .Where(y => y.Field<string>("ITEM") == dtOcupacion.Rows[i]["Articulo"].ToString() && y.Field<string>("TIPO") == "NO CONSUMIBLE")
                       .Sum(x => Convert.ToDecimal(x.Field<decimal>("ABONO MPO")));

                    // ABONO BUEN TRATO TABLERO x AAF
                    dondeVa = "AJUSTE TAX OCUPACION // " + "ABONO BUEN TRATO TABLERO x AAF";
