                    decimal multiplicarPor = 1;
                    if (totalNC < 0)
                        multiplicarPor = -1;
                    totalNC = multiplicarPor * (Math.Abs(totalNC) - Math.Abs(totalAjuste) - Math.Abs(totalAbonoMPONC) - Math.Abs(totalAbonoBuenTrato));

                    // CONSUMIBLE
                    // TAX CONSUMIBLE x AAF
                    dondeVa = "AJUSTE TAX OCUPACION // " + "TAX CONSUMIBLE x AAF";
