                foreach (var strItem in itemsDistintosTax)
                {
                    haCambiado = true;
                    DataRow[] filasSeleccionadas = dtTax.Select("ITEM = '" + strItem + "' AND ([TAX CONSUMIBLE] <> 0 OR [TAX NO CONSUMIBLE] <> 0)");
                    foreach (DataRow row in filasSeleccionadas)
                    {
                        row["AJUSTE OBRA DURACION SIMULACION"] = 0;
