                    }
                    
                    // CALCULO DURACION TAXIMETRO CONSUMIBLE
                    dondeVa = "Ajuste taxímetro por duración CONSUMIBLE " + strItem;

                    decimal totalTaximentoAbonoMPO = dtAbonoMPONuevo.AsEnumerable()
