                        .Sum(x => Convert.ToDecimal(x.Field<string>("Abono buen trato")));

                    taxC = taxC - abonoBTT;

                    if (taxC != 0)
                    {
                        decimal porcentajeDuracion = (totalTaximentoAbonoMPO / taxC);
                        porcentajeDuracion = 1 + porcentajeDuracion;

                        filasSeleccionadas = dtTax.Select("ITEM = '" + strItem + "' AND [TAX CONSUMIBLE] <> 0");
                        foreach (DataRow row in filasSeleccionadas)
                        {
                            row["TAX CONSUMIBLE PARA DURACION"] = Convert.ToDecimal(row["TAX CONSUMIBLE"]) * porcentajeDuracion;
                            row["% TAX CONSUMIBLE x ABONO MPO"] = porcentajeDuracion * 100;
                            row["AJUSTE OBRA DURACION SIMULACION"] = (-1) * (Convert.ToDecimal(row["DURACION AJUSTE"]) * Convert.ToDecimal(row["TAX CONSUMIBLE PARA DURACION"]) * Convert.ToDecimal(row["% AJUSTE"]));
                            row.AcceptChanges();
