                    }

                    // CALCULO DURACION TAXIMETRO NO CONSUMIBLE
                    dondeVa = "Ajuste taxímetro por duración NO CONSUMIBLE " + strItem;

                    decimal totalTaximentoNoAbonoMPO = dtAbonoMPONuevo.AsEnumerable()
