                            row["AJUSTE OBRA DURACION SIMULACION"] = Convert.ToDecimal(row["AJUSTE OBRA DURACION SIMULACION"]) + ((-1) * (Convert.ToDecimal(row["DURACION AJUSTE"]) * Convert.ToDecimal(row["TAX NO CONSUMIBLE PARA DURACION"]) * Convert.ToDecimal(row["% AJUSTE"])));
                            row.AcceptChanges();
