                    dondeVa = "Ajuste taxímetro por duración recuperar AAF " + strItem;
                    string AAF = "";
                    filaEncontrada = dtArticulosLiquidacion.Select("ItemId = '" + strItem + "'");
                    foreach (DataRow filaAA in filaEncontrada)
                        AAF = Convert.ToString(filaAA["AAF"]);

                    decimal taxParaDuracion = dtTax.AsEnumerable()
                            .Where(y => y.Field<string>("ITEM") == strItem)
                            .Sum(x => Convert.ToDecimal(x.Field<decimal>("TAX CONSUMIBLE PARA DURACION")) + Convert.ToDecimal(x.Field<decimal>("TAX NO CONSUMIBLE PARA DURACION")));

                    decimal ajusteObraDuracion = dtTax.AsEnumerable()
