                                   .Where(y => y.Field<string>("AAF") == strAAF
                                                && aplicarSobre.Contains(y.Field<string>("ETIQUETA")))
                                   .Sum(x => Convert.ToDecimal(x.Field<decimal>("IMPORTE")));

                        decimal tope = Math.Abs(sumaTotalesSobre) * porcentajeTotal / 100;

                        aplica = aplicar.Split('|');
                        decimal sumaTotalesA = 0;
                        while (aplica.GetUpperBound(0) != 0)
                        {
                            aplica = aplicar.Split('|');

                            sumaTotalesA = sumaTotalesA + dtValoresFichaArticulos.AsEnumerable()
                                        .Where(y => (y.Field<string>("AAF") == strAAF)
                                                    && (y.Field<string>("ETIQUETA") == aplica[0])
                                               )
                                       .Sum(x => x.Field<decimal>("IMPORTE"));

