                            foreach (DataRow filaDT in filaEncontrada)
                            {
                                importeAjuste = 0;
                                topado = "";
                                if (Math.Abs(tope) < Math.Abs(sumaTotalesA) && Math.Abs(sumaTotalesA) > 0)
                                {
                                    hayTopes = true;

                                    decimal importeTopado = (tope / sumaTotalesA) * Convert.ToDecimal(filaDT["IMPORTE"]);

                                    filaValores = dtTopesValores.NewRow();
                                    filaValores["AAF"] = strAAF;
                                    filaValores["APLICA SOBRE"] = aplicarSobre;
                                    filaValores["IMPORTE APLICA SOBRE"] = sumaTotalesSobre;
                                    filaValores["PORCENTAJE CONFIGURADO"] = porcentajeTotal;
                                    filaValores["TOPE"] = tope;
