                                    filaValores["IMPORTE ORIGINAL ETIQUETA"] = filaDT["IMPORTE"];
                                    filaValores["IMPORTE ORIGINAL TOTAL ETIQUETAS"] = sumaTotalesA;
                                    if (Convert.ToDecimal(filaDT["IMPORTE"]) < 0)
                                    {
                                        filaValores["IMPORTE TOPADO"] = (-1) * Math.Abs(importeTopado);
                                        filaValores["IMPORTE DEFINITIVO"] = (-1) * Math.Abs(importeTopado);
                                        importeAjuste = (-1) * Math.Abs(importeTopado);
                                    }
                                    else
