                                    if (Convert.ToDecimal(filaDT["IMPORTE"]) < 0)
                                        filaDT["IMPORTE"] = (-1) * Math.Abs(importeTopado);
                                    else
                                        filaDT["IMPORTE"] = Math.Abs(importeTopado);
                                    filaDT["TOPADO"] = "*";
                                    filaDT.AcceptChanges();
                                    topado = "*";
                                }
                                else
                                {
                                    {
                                        filaValores = dtTopesValores.NewRow();
                                        filaValores["AAF"] = strAAF;
                                        filaValores["APLICA SOBRE"] = aplicarSobre;
                                        filaValores["IMPORTE APLICA SOBRE"] = sumaTotalesSobre;
                                        filaValores["PORCENTAJE CONFIGURADO"] = porcentajeTotal;
                                        filaValores["TOPE"] = tope;
                                        filaValores["ETIQUETA"] = aplica[0];
                                        filaValores["IMPORTE ORIGINAL ETIQUETA"] = filaDT["IMPORTE"];
                                        filaValores["IMPORTE ORIGINAL TOTAL ETIQUETAS"] = sumaTotalesA;
                                        filaValores["IMPORTE TOPADO"] = 0;
                                        filaValores["IMPORTE DEFINITIVO"] = filaDT["IMPORTE"];
                                        dtTopesValores.Rows.Add(filaValores);
                                        filaValores = null;

                                        importeAjuste = Convert.ToDecimal(filaDT["IMPORTE"].ToString());
                                        topado = "";
