                                dondeVa = "TOPES: particiones";
                                aplicarSobreDistinguir = aplicarSobreDistinguirOriginal;
                                string[] aplicaDistinguir = aplicarSobreDistinguir.Split('|');
                                while (aplicaDistinguir.GetUpperBound(0) != 0)
