                                    filaDT["CONCEPTO"] = "* " + filaDT["CONCEPTO"].ToString().Replace(" * ", "");
                                    filaDT.AcceptChanges();
                                }
                            }

                            aplicar = aplicar.Replace(aplica[0] + "|", "");
                            aplicarARBOL = aplicarARBOL.Replace(aplicaARBOL[0] + "|", "");
                            if (aplica.GetUpperBound(0) == 0)
                                break;
                        }
