                //dondeVa = " Generar excel Gastos patio car_des";
                //sl.AddWorksheet("Gastos patio valores");
                //sl.ImportDataTable(1, 1, dtGastosPatio, true);
                //sl.AutoFitColumn(1, dtGastosPatio.Columns.Count);

                //dondeVa = " Generar excel Gastos patio carga/descarga";
                //sl.AddWorksheet("Gastos patio carga_des");
                //sl.ImportDataTable(1, 1, dtGastosPatioCargaDescarga, true);
                //sl.AutoFitColumn(1, dtGastosPatioCargaDescarga.Columns.Count);

                //dondeVa = " Generar excel Gastos patio clasificación/reparación";
                //sl.AddWorksheet("Gastos patio cla_rep");
                //sl.ImportDataTable(1, 1, dtGastosPatioCalculo, true);
                //sl.SetColumnStyle(4, styleDate);
                //sl.AutoFitColumn(1, dtGastosPatioCalculo.Columns.Count);

                //dondeVa = " Generar excel Gastos fijos";
                //sl.AddWorksheet("Gastos fijos");
                //sl.ImportDataTable(1, 1, dtDatosGastosFijos, true);
                //sl.SetColumnStyle(1, styleDate);
                //sl.AutoFitColumn(1, dtDatosGastosFijos.Columns.Count);

                dondeVa = " Generar excel Gastos fijos cálculo";
                sl.AddWorksheet("Gastos fijos calculo");
                sl.ImportDataTable(1, 1, dtGastosFijos, true);
                sl.SetColumnStyle(1, styleDate);
                sl.AutoFitColumn(1, dtGastosFijos.Columns.Count);

                //dondeVa = " Generar excel Gastos oficina";
                //sl.AddWorksheet("Gastos oficina");
                //sl.ImportDataTable(1, 1, dtGastosOficina, true);
                //sl.AutoFitColumn(1, dtGastosOficina.Columns.Count);

                dondeVa = " Generar excel Ajustes datos  BU";
                sl.AddWorksheet("Ajustes datos  BU");
                sl.ImportDataTable(1, 1, dtAjustesDatosBU, true);
                sl.SetColumnStyle(2, styleDate);
                sl.AutoFitColumn(1, dtAjustesDatosBU.Columns.Count);

                //dondeVa = " Generar excel Ajustes datos  BU cáclulo";
                //sl.AddWorksheet("Ajustes datos  BU calculo");
                //sl.ImportDataTable(1, 1, dtAjustesBU, true);
                //sl.SetColumnStyle(1, styleDate);
                //sl.AutoFitColumn(1, dtAjustesBU.Columns.Count);

                dondeVa = " Generar excel Ajustes GF";
                sl.AddWorksheet("Ajustes GF");
                sl.ImportDataTable(1, 1, dtAjustesGF, true);
                sl.AutoFitColumn(1, dtAjustesGF.Columns.Count);

                dondeVa = " Generar excel Abono MPO NUEVO";
                sl.AddWorksheet("Abono MPO NUEVO");
                sl.ImportDataTable(1, 1, dtAbonoMPONuevo, true);
                sl.AutoFitColumn(1, dtAbonoMPONuevo.Columns.Count);

                //sl.ImportDataTable(dtAbonoMPONuevo.Rows.Count + 10, 1, dtPedidosAgrupado, true);
                //sl.AutoFitColumn(1, dtPedidosAgrupado.Columns.Count);

                //sl.ImportDataTable(dtAbonoMPONuevo.Rows.Count + 10 + dtPedidosAgrupado.Rows.Count + 10, 1, dtCosteMPO, true);
                //sl.AutoFitColumn(1, dtCosteMPO.Columns.Count);

                //dondeVa = " Generar excel Buen trato";
                //sl.AddWorksheet("Buen trato");
                //sl.ImportDataTable(1, 1, dtBuenTrato, true);
                //sl.AutoFitColumn(1, dtBuenTrato.Columns.Count);

                //dondeVa = " Generar excel dtTopes";
                //sl.AddWorksheet("TOPES");
                //sl.ImportDataTable(1, 1, dtTopesValores, true);
                //sl.AutoFitColumn(1, dtTopesValores.Columns.Count);

                dondeVa = " Generar excel Valores ficha";
                sl.AddWorksheet("Valores ficha");
                sl.ImportDataTable(1, 1, dtValoresFicha, true);
                sl.AutoFitColumn(1, dtValoresFicha.Columns.Count);

                //dondeVa = " Generar excel Valores ficha articulo";
                //sl.AddWorksheet("Valores ficha articulo");
                //sl.ImportDataTable(1, 1, dtValoresFichaArticulos, true);
                //sl.AutoFitColumn(1, dtValoresFichaArticulos.Columns.Count);

                dondeVa = " Generar excel SaveAs";
                sl.SaveAs(nombreInforme);
                btnAbrirExcel.Visible = true;
                funcionalidades.guardarTiempo(usuarioRed, "Crear excel", 0);

                if (Environment.ExpandEnvironmentVariables(ConfigurationManager.AppSettings["TipoVersion"]).ToUpper() != "DESARROLLO")
                {
                    btnAbrirExcel.Visible = false;
                }
                 MENSAJE_ERROR.Visible = false;
            }
            catch (Exception ex)
            {
                mostrarMensaje("Simular - " + ex.Message + " // " + dondeVa);
                if (Environment.ExpandEnvironmentVariables(ConfigurationManager.AppSettings["TipoVersion"]).ToUpper() != "DESARROLLO")
                {
                    btnAbrirExcel.Visible = false;
                }
            }
            finally
            {
                Session["dtTiempos"] = dtTiempos;
                Session["dtSimulacion"] = dtSimulacion;
                Session["primeraSimulacion"] = false;
            }
        }



