        protected void btnBuscarInformacion_Click(object sender, EventArgs e)
        {
            buscarInformacion();
        }

        protected void buscarInformacion()
        {
            try
            {
                DataRow oItemTiempo;
                crearVariables();
                string usuarioRed = Session["usuarioRed"].ToString();
                //string cabeceraEnviado = "";

                Session["Concepto"] = cmbConcepto.SelectedValue.ToString();
                Session["Empresa"] = cmbEmpresa.Text.Trim();
                Session["Numero"] = lblNumero.Text.Trim();

                //if (Session["cabeceraEnviado"].ToString() != "")
                //    cabeceraEnviado = JsonConvert.SerializeObject(Session["cabeceraEnviado"]); ;

                cmbFechasSimulacion.SelectedIndex = 0;
                string strConexion;
                SqlConnection conexion;
                strConexion = funcionalidades.recuperarTexto(ConfigurationManager.ConnectionStrings["SQL_ROP"].ToString());
                conexion = new SqlConnection(strConexion);
                conexion.Open();
                SqlCommand comando;
                comando = conexion.CreateCommand();
                comando.CommandText = "temporalTIEMPOS_Eliminar";
                comando.CommandTimeout = 60;
                comando.CommandType = CommandType.StoredProcedure;
                comando.Parameters.AddWithValue("@usuario", usuarioRed);
                comando.ExecuteNonQuery();
                comando.Dispose();
                conexion.Close();
                conexion.Dispose();

                strConexion = funcionalidades.recuperarTexto(ConfigurationManager.ConnectionStrings["SQL_ROP"].ToString());
                conexion = new SqlConnection(strConexion);
                conexion.Open();
                comando = conexion.CreateCommand();
                comando.CommandText = "temporalVALORES_Eliminar";
                comando.CommandTimeout = 60;
                comando.CommandType = CommandType.StoredProcedure;
                comando.Parameters.AddWithValue("@usuario", usuarioRed);
                comando.Parameters.AddWithValue("@ficha", null);
                comando.ExecuteNonQuery();
                comando.Dispose();
                conexion.Close();
                conexion.Dispose();

                string version = "";
                DataTable dtResultados = new DataTable();
                List<string> listadoNumeros = new List<string>();

                DataColumn column = new DataColumn();
                column.DataType = System.Type.GetType("System.Int32");
                column.ColumnName = "ID";
                column.AutoIncrement = true;
                column.AutoIncrementSeed = 1; //1000;
                column.AutoIncrementStep = 1;

                DataTable dtTiempos = new DataTable();
                dtTiempos = new DataTable();
                dtTiempos.Columns.Add("CONCEPTO");
                dtTiempos.Columns.Add("TIEMPO");
                dtTiempos.Columns.Add(column);
                Session["dtTiempos"] = dtTiempos;

                DataColumn columnP = new DataColumn();
                columnP.DataType = System.Type.GetType("System.Int32");
                columnP.AutoIncrement = true;
                columnP.ColumnName = "ID";
                columnP.AutoIncrementSeed = 1;  //1000;
                columnP.AutoIncrementStep = 1;

                DataTable dtTiemposPedidos = new DataTable();
                dtTiemposPedidos = new DataTable();
                dtTiemposPedidos.Columns.Add("CONCEPTO");
                dtTiemposPedidos.Columns.Add("TIEMPO");
                dtTiemposPedidos.Columns.Add(columnP);
                Session["dtTiemposPedidos"] = dtTiemposPedidos;

                txtFacturacionOtrosConceptos.Attributes.CssStyle.Add("TEXT-ALIGN", "right");
                txtFechaSimulacion.Attributes["min"] = DateTime.Now.ToString("yyyy-MM-dd");

                DataTable dtMB = new DataTable();
                dtMB = (DataTable)Session["dtMB"];

                dtMB.Clear();
                dtMB = new DataTable();
                dtMB.Columns.Add("CONCEPTO");
                dtMB.Columns.Add("IMPORTE");
                oItemTiempo = dtMB.NewRow();
                oItemTiempo[0] = "MB";
                oItemTiempo[1] = "0.00";
                dtMB.Rows.Add(oItemTiempo);
                oItemTiempo = dtMB.NewRow();
                oItemTiempo[0] = "MB -";
                oItemTiempo[1] = "0.00";
                dtMB.Rows.Add(oItemTiempo);
                grvMB.DataSource = null;
                grvMB.DataSource = dtMB;
                grvMB.DataBind();
                Session["dtMB"] = dtMB;

                if (cmbVersion.SelectedValue == "")
                    version = "";
                else if (Convert.ToInt32(cmbVersion.SelectedValue) == -1)
                    version = "";
                else
                    version = cmbVersion.SelectedValue.ToString();

                MENSAJE_ERROR.Visible = false;
                imgWarning.Visible = false;
                lblMensajeError.Visible = false;
