                DateTime theDate = DateTime.ParseExact(fechaSimulacion.ToString("yyyy-MM-dd"), "yyyy-MM-dd", System.Globalization.CultureInfo.InvariantCulture);
                string dateToInsert = theDate.ToString("yyyy-MM-dd");
                txtFechaSimulacion.Text = dateToInsert;

