                        if (Session["cabeceraEnviado"].ToString() != "")
                            ofertaAceler();
                        else
                            calcularOfertaNUEVO(ref dtResultados, 0, cmbEmpresa.SelectedValue.ToString(), listadoNumeros, version, chkBoxSoloEntrega.Checked, cmbFenolico.SelectedValue.Trim().ToUpper());
