                        btnBuscarInformacion.Visible = true;
                        btnVisualizarOferta.Visible = true;
                        string visualizacion = "CAPITULOS";
                        Session["VisualizacionOferta"] = "CAPITULOS";
                        DataRow[] filaEncontrada;
                        string idioma = Session["idioma"].ToString();
                        if (visualizacion == "CAPITULOS")
                            filaEncontrada = dtIdiomas.Select("ETQ_Control = 'btnVisualizarOfertaCapitulo'");
                        else
                            filaEncontrada = dtIdiomas.Select("ETQ_Control = 'btnVisualizarOfertaTotales'");

                        foreach (DataRow filaValor in filaEncontrada)
                        {
                            if (idioma == "ESPAÑOL")
                                btnVisualizarOferta.Text = Convert.ToString(filaValor["ETQ_TextoCastellano"]);
                            if (idioma == "CATALAN")
                                btnVisualizarOferta.Text = Convert.ToString(filaValor["ETQ_TextoCatalan"]);
                            if (idioma == "INGLES")
                                btnVisualizarOferta.Text = Convert.ToString(filaValor["ETQ_TextoIngles"]);
                        }
                    }
                    else if (cmbConcepto.SelectedValue.ToString().ToUpper() == "PEDIDO")
                    {
                        listadoNumeros.Clear();
                        listadoNumeros.Add(txtNumero.Text);
                        calcularPedidoNUEVO(ref dtResultados, 0, cmbEmpresa.SelectedValue.ToString(), listadoNumeros, version, chkBoxSoloEntrega.Checked, cmbFenolico.SelectedValue.Trim().ToUpper(), true, false);
                        btnBuscarInformacion.Visible = true;
                        //chkBoxSoloEntrega.Enabled = true;
                        //chkBoxSoloDevolucion.Enabled = true;
                        lblCabeceraImprimir1.Text = String.Format("{0}: {1}\t\t\t\t\t{2}: {3}\t\t\t\t\t{4}: {5}", lblConcepto.Text.Trim(), cmbConcepto.Text.Trim(), lblEmpresa.Text.Trim(), cmbEmpresa.Text.Trim(), lblNumero.Text.Trim(), txtNumero.Text.Trim());
                        lblCabeceraImprimir2.Text = String.Format("{0}: {1}\t\t\t{2}: {3}", lblCuentaCliente.Text.Trim(), txtCuentaCliente.Text.Trim(), lblNombreCliente.Text.Trim(), txtNombreCliente.Text.Trim());
