            dtValores = (DataTable)Session["dtValores"];
            DataTable dtCapitulosOferta = new DataTable();
            dtCapitulosOferta = (DataTable)Session["dtCapitulosOferta"];

            try
            {
                string idioma = Session["idioma"].ToString();
                string visualizacion = Session["VisualizacionOferta"].ToString();

                if (visualizacion == "TOTAL")
                    filaEncontrada = dtIdiomas.Select("ETQ_Control = 'btnVisualizarOfertaCapitulo'");
                else
                    filaEncontrada = dtIdiomas.Select("ETQ_Control = 'btnVisualizarOfertaTotales'");
                
                foreach (DataRow filaValor in filaEncontrada)
                {
                    if (idioma == "ESPAÑOL")
                        btnVisualizarOferta.Text = Convert.ToString(filaValor["ETQ_TextoCastellano"]);
                    if (idioma == "CATALAN")
                        btnVisualizarOferta.Text = Convert.ToString(filaValor["ETQ_TextoCatalan"]);
                    if (idioma == "INGLES")
                        btnVisualizarOferta.Text = Convert.ToString(filaValor["ETQ_TextoIngles"]);
                }

                if (visualizacion == "CAPITULOS")
                {
                    pintarArbolCapitulos(ref dtValores, dtCapitulosOferta, false, false, false, true);
                    Session["VisualizacionOferta"] = "TOTAL";
                }
                else
                { 
                    pintarArbolNUEVO(ref dtValores, false, false, false, true);
                    Session["VisualizacionOferta"] = "CAPITULOS";
                }
            }
            catch (Exception ex)
            {
                mostrarMensaje("ERROR cambio visualización // " + ex.Message);
            }
        }

