        protected void continuarCalculo()
        {
            string tipoEnviado = "";
            string empresaEnviado = "";
            string numeroEnviado = "";
            string idiomaEnviado = "";
            string idioma = "";
            string strConexion;
            SqlConnection conexion;
            SqlCommand comando;
            int i = 0;

            try
            {
                btnBuscarInformacion.Visible = false;

                CABECERA_MOSTRAR.Visible = true;
                PREGUNTAR_MOSTRAR.Visible = false;
                botonesTabla.Visible = true;
                zonaImprimir.Visible = true;

                idiomaEnviado = "";
                tipoEnviado = "";
                empresaEnviado = "";
                numeroEnviado = "";
                if (Session["idioma"].ToString() != "")
                    idioma = Session["idioma"].ToString();
                if (Session["idiomaEnviado"].ToString() != "")
                    idiomaEnviado = Session["idiomaEnviado"].ToString();
                if (Session["tipoEnviado"].ToString() != "")
                    tipoEnviado = Session["tipoEnviado"].ToString();
                if (Session["empresaEnviado"].ToString() != "")
                    empresaEnviado = Session["empresaEnviado"].ToString();
                if (Session["numeroEnviado"].ToString() != "")
                    numeroEnviado = Session["numeroEnviado"].ToString();

                if (idioma == "ESPAÑOL")
                {
                    imgCatalonian.Visible = false;
                    imgEnglish.Visible = false;
                    imgSpain.Visible = true;
                }
                else if (idioma == "CATALAN")
                {
                    imgCatalonian.Visible = true;
                    imgEnglish.Visible = false;
                    imgSpain.Visible = false;
                }
                else if (idioma == "INGLES")
                {
                    imgCatalonian.Visible = false;
                    imgEnglish.Visible = true;
                    imgSpain.Visible = false;
                }

                if (idiomaEnviado != "" && tipoEnviado != "" && empresaEnviado != "" && numeroEnviado != "")
                {
                    SqlDataReader dr;

                    strConexion = funcionalidades.recuperarTexto(ConfigurationManager.ConnectionStrings["SQL_ROP"].ToString());
                    conexion = new SqlConnection(strConexion);
                    conexion.Open();
                    comando = conexion.CreateCommand();
                    comando.CommandText = "sp_ConceptosConsulta";
                    comando.CommandTimeout = 60;
                    comando.CommandType = CommandType.StoredProcedure;
                    comando.Parameters.AddWithValue("@ID", Convert.ToInt32(tipoEnviado));
                    dr = comando.ExecuteReader();
                    if (dr.HasRows)
                    {
                        dr.Read();
                        cmbConcepto.SelectedValue = dr["Concepto"].ToString().ToUpper();
                    }
                    comando.Dispose();
                    conexion.Close();
                    conexion.Dispose();

                    i = 0;
                    foreach (var itemEmpresa in cmbEmpresa.Items)
                    {
                        if (itemEmpresa.ToString().ToUpper() == empresaEnviado.ToUpper())
                            break;
                        i = i + 1;
                    }

                    chkBoxCalcularPedidos.Checked = chkMostrarPedidos.Checked;
                    cmbEmpresa.SelectedIndex = i;
                    txtNumero.Text = numeroEnviado;

                    //calcularTiempos(false, 0);
                    buscarInformacion();
                }
            }
            catch (Exception ex)
            {
                mostrarMensaje("ERROR continuando // " + ex.Message);
            }
        }
