                        OBRAID = AxdEntity_ObraTable.ObraId.ToString();
                        oFila["MASTER OBRA"] = AxdEntity_ObraTable.MasterObrasId.ToString();
                        if (AxdEntity_ObraTable.InventLocationId.Equals(null))
                             oFila["ALMACEN"] = "";
                        else
                            oFila["ALMACEN"] = AxdEntity_ObraTable.InventLocationId;
