                        {
                            oFila["FECHA APERTURA"] = new DateTime();
                            fechaApertura = new DateTime();
                        }
                        else
                        {
                            oFila["FECHA APERTURA"] = Convert.ToDateTime(AxdEntity_ObraTable.FechaApertura.ToString());
                            fechaApertura = Convert.ToDateTime(AxdEntity_ObraTable.FechaApertura.ToString());
                        }
                        if (AxdEntity_ObraTable.FechaCierre.Equals(null))
                            oFila["FECHA CIERRE"] = new DateTime();
                        else
                            oFila["FECHA CIERRE"] = Convert.ToDateTime(AxdEntity_ObraTable.FechaCierre.Value.ToString());
                        oFila["MONEDA"] = AxdEntity_ObraTable.CurrencyCode.ToString();
