                        oFila["HORAS TEORICAS"] = Convert.ToDecimal(AxdEntity_WorkPaperPaletTable.TheoreticalHours);
                        oFila["TIPO"] = AxdEntity_WorkPaperPaletTable.WorkRegisterType.ToString().ToUpper();
                        dtHojasTrabajoCabecera.Rows.Add(oFila);

                        for (int linea = 0; linea < AxdEntity_WorkPaperPaletLines.Length; linea++)
                        {
                            AxdEntity_WorkPaperPaletLine = AxdEntity_WorkPaperPaletLines[linea];

                            oFila = dtHojasTrabajoLineas.NewRow();
                            va = "obra " + OBRAID;
                            oFila["OBRA"] = OBRAID;
                            va = "WorkPaperPaletId " + AxdEntity_WorkPaperPaletTable.WorkPaperPaletId.ToString();
                            oFila["WORKPAPERPALETID"] = AxdEntity_WorkPaperPaletTable.WorkPaperPaletId.ToString();
                            if (!(AxdEntity_WorkPaperPaletTable.PackingSlipDevolutionId is null))
                            {
                                va = "PackingSlipDevolutionId " + AxdEntity_WorkPaperPaletTable.PackingSlipDevolutionId.ToString();
                                oFila["PackingSlipDevolutionId"] = AxdEntity_WorkPaperPaletTable.PackingSlipDevolutionId.ToString();
                            }
                            else
                                va = "WorkPaperPaletId " + AxdEntity_WorkPaperPaletTable.WorkPaperPaletId.ToString();
                            va = "ItemDevolutionType " + AxdEntity_WorkPaperPaletLine.ItemDevolutionType.GetHashCode().ToString();
                            oFila["ID TIPO DEVOLUCION"] = AxdEntity_WorkPaperPaletLine.ItemDevolutionType.GetHashCode();
                            va = "ItemDevolutionType " + AxdEntity_WorkPaperPaletLine.ItemDevolutionType;
                            oFila["TIPO DEVOLUCION"] = AxdEntity_WorkPaperPaletLine.ItemDevolutionType;
                            //dondeVa = tablaHojasTrabajoLineas.AxdEnum_ItemDevolutionType.None;
                            va = "ItemId " + AxdEntity_WorkPaperPaletLine.ItemId;
                            oFila["ITEM"] = AxdEntity_WorkPaperPaletLine.ItemId.ToString();
                            if (articulosConfiguracion.IndexOf(AxdEntity_WorkPaperPaletLine.ItemId.ToString() + "|") == -1)
                                articulosConfiguracion = articulosConfiguracion + AxdEntity_WorkPaperPaletLine.ItemId.ToString() + "|";
                            oFila["HORAS TEORICAS"] = Convert.ToDecimal(AxdEntity_WorkPaperPaletLine.TheoreticalHours);
                            va = "Qty " + AxdEntity_WorkPaperPaletLine.Qty.ToString();
                            oFila["CANTIDAD"] = Convert.ToDecimal(AxdEntity_WorkPaperPaletLine.Qty);
                            va = "CustMisuse " + AxdEntity_WorkPaperPaletLine.CustMisuse.ToString();
                            oFila["MAL USO"] = Convert.ToBoolean(AxdEntity_WorkPaperPaletLine.CustMisuse);
                            dtHojasTrabajoLineas.Rows.Add(oFila);
                        }
                    }
                }
                error = "";
            }
            catch (Exception ex)
            {
                error = dondeVa + " // " + va + " //// " + ex.Message;
                mostrarMensaje("estructuraFichas: (" + dondeVa + ") // " + ex.Message);
                funcionalidades.guardarIncidencia(empresa, "FICHA", listaNumeros.ElementAt(0), "", "Error al crear las estructuras de datos para la ficha // " + "estructuraFichas: (" + dondeVa + ") // " + ex.Message, 1, usuario, User.Identity.Name.ToString());
            }
            finally
            {
                Session["dtTiempos"] = dtTiempos;
            }
        }

        private void estructuraFacturasNUEVO(ref string error, ref List<string> listaObras, ref DataTable dtCabeceraFactura, ref DataTable dtLineasFactura, ref DataTable dtAlbaranesEntrega, string empresa, List<string> listaNumeros)
        {
            DataTable dtTiempos = new DataTable();
            dtTiempos = (DataTable)Session["dtTiempos"];
            DataRow oItemTiempo;

            DataRow oFila;
            string numeroFactura = "";
            bool puedeConvertir;
            decimal numeroDecimal;
            string formaPago;
            string multivencimiento;
            int n = 0;
            string PeriodUnit = "";
            decimal QtyUnit = 0;
            decimal Qty = 0;
            decimal Valor = 0;
            string dondeVa = "";

            int cantidad = -1;
            List<int> listaCantidades = new List<int>();

            DateTime hora_1 = default(DateTime);
            TimeSpan hora_2 = default(TimeSpan);

            try
            {
                dondeVa = "Cabecera facturas";
                hora_1 = DateTime.Now;

                WSGeneral.CallContext contexto_facturasCabecera = new WSGeneral.CallContext();
                contexto_facturasCabecera.Company = empresa.ToString();

                WSGeneral.QueryCriteria criterio_facturasCabecera = new WSGeneral.QueryCriteria();
                criterio_facturasCabecera.CriteriaElement = new WSGeneral.CriteriaElement[listaNumeros.Count];
                int numFactura = 0;
                foreach (string nFactura in listaNumeros)
                {
                    criterio_facturasCabecera.CriteriaElement[numFactura] = new WSGeneral.CriteriaElement();
                    criterio_facturasCabecera.CriteriaElement[numFactura].DataSourceName = "CustInvoiceJour";
                    criterio_facturasCabecera.CriteriaElement[numFactura].FieldName = "InvoiceId";
                    criterio_facturasCabecera.CriteriaElement[numFactura].Operator = WSGeneral.Operator.Equal;
                    criterio_facturasCabecera.CriteriaElement[numFactura].Value1 = nFactura;
                    numFactura = numFactura + 1;
                }

                WSGeneral.WSROPServiceClient proxy_facturasCabacera = new WSGeneral.WSROPServiceClient();
                proxy_facturasCabacera.ClientCredentials.Windows.ClientCredential.Domain = WSDominio;
                proxy_facturasCabacera.ClientCredentials.Windows.ClientCredential.UserName = WSUsuario;
                proxy_facturasCabacera.ClientCredentials.Windows.ClientCredential.Password = WSContrasena;

                WSGeneral.WSCustInvoiceJourContract[] axdtablaCabeceraFacturas_1 = proxy_facturasCabacera.getCustInvoiceJour(contexto_facturasCabecera, criterio_facturasCabecera);

                IEnumerable<WSGeneral.WSCustInvoiceJourContract> enumerableCabecera = axdtablaCabeceraFacturas_1;
                IEnumerator<WSGeneral.WSCustInvoiceJourContract> enumeratorCabecera = enumerableCabecera.GetEnumerator();

                hora_2 = DateTime.Now.Subtract(hora_1);
                oItemTiempo = dtTiempos.NewRow();
                oItemTiempo[0] = "TIEMPO llamar al ws tablaCabeceraFacturas";
                oItemTiempo[1] = ((Convert.ToDecimal(hora_2.Minutes) * 60) + Convert.ToDecimal(hora_2.Seconds) + (Convert.ToDecimal(hora_2.Milliseconds) / 1000)).ToString("#,##0.000000");
                dtTiempos.Rows.Add(oItemTiempo);

                while (enumeratorCabecera.MoveNext())
                {
                    WSGeneral.WSCustInvoiceJourContract enumeratorCabeceraFactura = enumeratorCabecera.Current;

                    if (enumeratorCabeceraFactura.parmTipoVenta.ToString().ToUpper() == WSGeneral.TiposVentas.Nuevo.ToString().ToUpper() || enumeratorCabeceraFactura.parmTipoVenta.ToString().ToUpper() == WSGeneral.TiposVentas.Usado.ToString().ToUpper())
                    {
                        oFila = dtCabeceraFactura.NewRow();
                        numeroFactura = enumeratorCabeceraFactura.parmInvoiceId.ToString();
                        oFila["FACTURA"] = enumeratorCabeceraFactura.parmInvoiceId.ToString();
                        oFila["FECHA"] = Convert.ToDateTime(enumeratorCabeceraFactura.parmInvoiceDate.ToString());
                        oFila["MASTER OBRA"] = enumeratorCabeceraFactura.parmMasterObrasId.ToString();
                        if (enumeratorCabeceraFactura.parmObraId == "")
                            oFila["OBRA"] = "";
                        else
                        {
                            oFila["OBRA"] = enumeratorCabeceraFactura.parmObraId.ToString();
                            if (!listaObras.Contains(enumeratorCabeceraFactura.parmObraId.ToString()))
                                listaObras.Add(enumeratorCabeceraFactura.parmObraId.ToString());
                        }
                        oFila["CUENTA CLIENTE"] = enumeratorCabeceraFactura.parmInvoiceAccount.ToString();
                        oFila["MONEDA"] = enumeratorCabeceraFactura.parmCurrencyCode.ToString();
                        oFila["CUENTA CLIENTE"] = enumeratorCabeceraFactura.parmInvoiceAccount.ToString();
                        oFila["CENTRO COSTE"] = enumeratorCabeceraFactura.parmCostCenter.ToString();
                        oFila["DELEGACION"] = enumeratorCabeceraFactura.parmDelegation.ToString();
                        oFila["TIPO"] = "";
                        oFila["MODO ENTREGA"] = enumeratorCabeceraFactura.parmDlvMode;

                        oFila["FORMA PAGO"] = enumeratorCabeceraFactura.parmPayment.ToString();
                        formaPago = enumeratorCabeceraFactura.parmPayment.ToString();
                        oFila["MULTIVENCIMIENTO"] = enumeratorCabeceraFactura.parmPaymentSched.ToString();
                        multivencimiento = enumeratorCabeceraFactura.parmPaymentSched.ToString();
                        oFila["NUMERO MESES"] = 0;
                        oFila["NUMERO DIAS"] = 0;
                        oFila["DIAS ADD"] = 0;
                        oFila["DIAS PAGO"] = 0;
                        oFila["DIAS TOTAL"] = -1;

                        // PAGOS
                        hora_1 = DateTime.Now;
                        WSGeneral.CallContext contextoPagos = new WSGeneral.CallContext();
                        contextoPagos.Company = empresa;

                        WSGeneral.QueryCriteria criterioPagos = new WSGeneral.QueryCriteria();
                        criterioPagos.CriteriaElement = new WSGeneral.CriteriaElement[1];

                        criterioPagos.CriteriaElement[0] = new WSGeneral.CriteriaElement();
                        criterioPagos.CriteriaElement[0].DataSourceName = "PaymTerm";
                        criterioPagos.CriteriaElement[0].FieldName = "PaymTermId";
                        criterioPagos.CriteriaElement[0].Operator = WSGeneral.Operator.Equal;
                        criterioPagos.CriteriaElement[0].Value1 = formaPago;

                        WSGeneral.WSROPServiceClient proxyPagos = new WSGeneral.WSROPServiceClient();
                        proxyPagos.ClientCredentials.Windows.ClientCredential.Domain = WSDominio;
                        proxyPagos.ClientCredentials.Windows.ClientCredential.UserName = WSUsuario;
                        proxyPagos.ClientCredentials.Windows.ClientCredential.Password = WSContrasena;

                        WSGeneral.WSPaymTermContract[] axtablaPagos = proxyPagos.getPaymTerm(contextoPagos, criterioPagos);

                        IEnumerable<WSGeneral.WSPaymTermContract> enumerablePago = axtablaPagos;
                        IEnumerator<WSGeneral.WSPaymTermContract> enumeratorPago = enumerablePago.GetEnumerator();

                        hora_2 = DateTime.Now.Subtract(hora_1);
                        oItemTiempo = dtTiempos.NewRow();
                        oItemTiempo[0] = "TIEMPO llamar al WSGeneral /  tablaPagos con PaytemId = " + formaPago;
                        oItemTiempo[1] = ((Convert.ToDecimal(hora_2.Minutes) * 60) + Convert.ToDecimal(hora_2.Seconds) + (Convert.ToDecimal(hora_2.Milliseconds) / 1000)).ToString("#,##0.000000");
                        dtTiempos.Rows.Add(oItemTiempo);

                        while (enumeratorPago.MoveNext())
                        {
                            WSGeneral.WSPaymTermContract enumerator_Pago = enumeratorPago.Current;

                            oFila["NUMERO MESES"] = Convert.ToInt32(enumerator_Pago.parmNumOfMonths);
                            oFila["DIAS PAGO"] = Convert.ToInt32(enumerator_Pago.parmNumOfMonths) * 30;

                            oFila["NUMERO DIAS"] = Convert.ToInt32(enumerator_Pago.parmNumOfDays);
                            oFila["DIAS PAGO"] = Convert.ToInt32(oFila["DIAS PAGO"]) + Convert.ToInt32(enumerator_Pago.parmNumOfDays);

                            oFila["DIAS ADD"] = 0;
                        }
                        proxyPagos.Close();

                        // MULTIVENCIMIENTOS 
                        hora_1 = DateTime.Now;
                        WSGeneral.CallContext contextoVencimientoCabecera = new WSGeneral.CallContext();
                        contextoVencimientoCabecera.Company = empresa;

                        WSGeneral.QueryCriteria criterioVencimientoCabecera = new WSGeneral.QueryCriteria();
                        criterioVencimientoCabecera.CriteriaElement = new WSGeneral.CriteriaElement[1];

                        criterioVencimientoCabecera.CriteriaElement[0] = new WSGeneral.CriteriaElement();
                        criterioVencimientoCabecera.CriteriaElement[0].DataSourceName = "PaymSched";
                        criterioVencimientoCabecera.CriteriaElement[0].FieldName = "Name";
                        criterioVencimientoCabecera.CriteriaElement[0].Operator = WSGeneral.Operator.Equal;
                        criterioVencimientoCabecera.CriteriaElement[0].Value1 = multivencimiento;

                        WSGeneral.WSROPServiceClient proxyVencimientoCabecera = new WSGeneral.WSROPServiceClient();
                        proxyVencimientoCabecera.ClientCredentials.Windows.ClientCredential.Domain = WSDominio;
                        proxyVencimientoCabecera.ClientCredentials.Windows.ClientCredential.UserName = WSUsuario;
                        proxyVencimientoCabecera.ClientCredentials.Windows.ClientCredential.Password = WSContrasena;

                        WSGeneral.WSPaymSchedContract[] AxdVencimientosCabecera = proxyVencimientoCabecera.getPaymSched(contextoVencimientoCabecera, criterioVencimientoCabecera);

                        IEnumerable<WSGeneral.WSPaymSchedContract> enumerableVencimientoCabecera = AxdVencimientosCabecera;
                        IEnumerator<WSGeneral.WSPaymSchedContract> enumeratorVencimientoCabecera = enumerableVencimientoCabecera.GetEnumerator();

                        hora_2 = DateTime.Now.Subtract(hora_1);
                        oItemTiempo = dtTiempos.NewRow();
                        oItemTiempo[0] = "TIEMPO llamar al ws WSGeneral / tablaVencimientosCabecera con PaymSchedName = " + multivencimiento;
                        oItemTiempo[1] = ((Convert.ToDecimal(hora_2.Minutes) * 60) + Convert.ToDecimal(hora_2.Seconds) + (Convert.ToDecimal(hora_2.Milliseconds) / 1000)).ToString("#,##0.000000");
                        dtTiempos.Rows.Add(oItemTiempo);

                        while (enumeratorVencimientoCabecera.MoveNext())
                        {
                            WSGeneral.WSPaymSchedContract enumerator_VencimientoCabecera = enumeratorVencimientoCabecera.Current;

                            n = Convert.ToInt32(enumerator_VencimientoCabecera.parmNumOfPayment);

                            oFila["PERIOD UNIT"] = enumerator_VencimientoCabecera.parmPeriodUnit.ToString().ToUpper();
                            PeriodUnit = enumerator_VencimientoCabecera.parmPeriodUnit.ToString().ToUpper();
                            oFila["QTY UNIT"] = Convert.ToInt32(enumerator_VencimientoCabecera.parmQtyUnit.ToString());
                            QtyUnit = Convert.ToInt32(enumerator_VencimientoCabecera.parmQtyUnit.ToString());

                            oFila["DIAS TOTAL"] = 0;
                            if (enumerator_VencimientoCabecera.parmPaymBy.ToString().ToUpper() == "TOTAL")
                                oFila["DIAS TOTAL"] = Convert.ToDecimal(oFila["DIAS PAGO"]) + Convert.ToDecimal(oFila["DIAS ADD"]);
                            else if (enumerator_VencimientoCabecera.parmPaymBy.ToString().ToUpper() == "NUMOFPAYMENT" || enumerator_VencimientoCabecera.parmPaymBy.ToString().ToUpper() == "AMOUNTBYPAYMENT")
                            {
                                for (int vencimiento = 0; vencimiento <= n - 1; vencimiento++)
                                {
                                    if (PeriodUnit == "MONTH")
                                        oFila["DIAS TOTAL"] = Convert.ToDecimal(oFila["DIAS TOTAL"]) + (((vencimiento * (QtyUnit * 30)) + Convert.ToDecimal(oFila["DIAS PAGO"]) + Convert.ToDecimal(oFila["DIAS ADD"])) / n);
                                    else if (PeriodUnit == "DAY")
                                        oFila["DIAS TOTAL"] = Convert.ToDecimal(oFila["DIAS TOTAL"]) + (((vencimiento * QtyUnit) + Convert.ToDecimal(oFila["DIAS PAGO"]) + Convert.ToDecimal(oFila["DIAS ADD"])) / n);
                                    else
                                        oFila["DIAS TOTAL"] = 0;
                                }
                            }
                            else if (enumerator_VencimientoCabecera.parmPaymBy.ToString().ToUpper() == "SPECIFIED")
                            {
                                // MULTIVENCIMIENTOS LÍNEAS
                                IEnumerable<WSGeneral.WSPaymSchedLineContract> enumerableVencimientoLineas = enumerator_VencimientoCabecera.parmPaymSchedLines;
                                IEnumerator<WSGeneral.WSPaymSchedLineContract> enumeratorVencimientoLineas = enumerableVencimientoLineas.GetEnumerator();

                                while (enumeratorVencimientoLineas.MoveNext())
                                {
                                    WSGeneral.WSPaymSchedLineContract enumerator_VencimientoLineas = enumeratorVencimientoLineas.Current;

                                    cantidad = Convert.ToInt32(enumerator_VencimientoLineas.parmQty.ToString());

                                    // valida si ya existe este modo de pago, en cuyo caso se ignora
                                    if (!listaCantidades.Contains(cantidad))
                                    {
                                        listaCantidades.Add(cantidad);

                                        oFila["QTY"] = Convert.ToInt32(enumerator_VencimientoLineas.parmQty.ToString());
                                        Qty = Convert.ToInt32(enumerator_VencimientoLineas.parmQty.ToString());

                                        oFila["VALUE"] = Convert.ToDecimal(enumerator_VencimientoLineas.parmValue.ToString());
                                        Valor = Convert.ToDecimal(enumerator_VencimientoLineas.parmValue.ToString());

                                        if (PeriodUnit == "MONTH")
                                            oFila["DIAS TOTAL"] = Convert.ToDecimal(oFila["DIAS TOTAL"]) + ((Valor * ((Qty * 30) + Convert.ToDecimal(oFila["DIAS PAGO"]) + Convert.ToDecimal(oFila["DIAS ADD"]))) / 100);
                                        else if (PeriodUnit == "DAY")
                                            oFila["DIAS TOTAL"] = Convert.ToDecimal(oFila["DIAS TOTAL"]) + ((Valor * (Qty + Convert.ToDecimal(oFila["DIAS PAGO"]) + Convert.ToDecimal(oFila["DIAS ADD"]))) / 100);
                                        else
                                            oFila["DIAS TOTAL"] = Convert.ToDecimal(oFila["DIAS TOTAL"]);
                                    }
                                }

                            }
                        }
                        criterioVencimientoCabecera = null;
                        contextoVencimientoCabecera = null;

                        dtCabeceraFactura.Rows.Add(oFila);
                        oFila = null;
                    }
                }

                // FACTURAS LINEAS
                dondeVa = " - FACTURAS LINEAS -";
                hora_1 = DateTime.Now;

                WSGeneral.CallContext contexto_facturas = new WSGeneral.CallContext();
                contexto_facturas.Company = empresa.ToString();

                WSGeneral.QueryCriteria criterio_facturas = new WSGeneral.QueryCriteria();
                criterio_facturas.CriteriaElement = new WSGeneral.CriteriaElement[listaNumeros.Count];
                numFactura = 0;
                foreach (string nFactura in listaNumeros)
                {
                    criterio_facturas.CriteriaElement[numFactura] = new WSGeneral.CriteriaElement();
                    criterio_facturas.CriteriaElement[numFactura].DataSourceName = "CustInvoiceTrans";
                    criterio_facturas.CriteriaElement[numFactura].FieldName = "InvoiceId";
                    criterio_facturas.CriteriaElement[numFactura].Operator = WSGeneral.Operator.Equal;
                    criterio_facturas.CriteriaElement[numFactura].Value1 = nFactura;
                    numFactura = numFactura + 1;
                }

                WSGeneral.WSROPServiceClient proxy_facturas = new WSGeneral.WSROPServiceClient();
                proxy_facturas.ClientCredentials.Windows.ClientCredential.Domain = WSDominio;
                proxy_facturas.ClientCredentials.Windows.ClientCredential.UserName = WSUsuario;
                proxy_facturas.ClientCredentials.Windows.ClientCredential.Password = WSContrasena;

                WSGeneral.WSCustInvoiceTransContract[] axdtablaFacturas = proxy_facturas.getCustInvoiceTrans(contexto_facturas, criterio_facturas);
                hora_2 = DateTime.Now.Subtract(hora_1);
                oItemTiempo = dtTiempos.NewRow();
                oItemTiempo[0] = "     (generar estructuras ficha) TIEMPO llamar al ws WSGeneral / facturasLineas";
                oItemTiempo[1] = ((Convert.ToDecimal(hora_2.Minutes) * 60) + Convert.ToDecimal(hora_2.Seconds) + (Convert.ToDecimal(hora_2.Milliseconds) / 1000)).ToString("#,##0.000000");
                dtTiempos.Rows.Add(oItemTiempo);

                IEnumerable<WSGeneral.WSCustInvoiceTransContract> enumerableLineasFacturas = axdtablaFacturas;
                IEnumerator<WSGeneral.WSCustInvoiceTransContract> enumeratorLineasFacturas = enumerableLineasFacturas.GetEnumerator();

                hora_2 = DateTime.Now.Subtract(hora_1);
                oItemTiempo = dtTiempos.NewRow();
                oItemTiempo[0] = "     (generar estructuras ficha) TIEMPO llamar al ws tablaLineasFacturas";
                oItemTiempo[1] = ((Convert.ToDecimal(hora_2.Minutes) * 60) + Convert.ToDecimal(hora_2.Seconds) + (Convert.ToDecimal(hora_2.Milliseconds) / 1000)).ToString("#,##0.000000");
                dtTiempos.Rows.Add(oItemTiempo);


                while (enumeratorLineasFacturas.MoveNext())
                {
                    WSGeneral.WSCustInvoiceTransContract enumerator_lineasFacturas = enumeratorLineasFacturas.Current;

                    if (enumerator_lineasFacturas.parmTipoVenta.ToString().ToUpper() == WSGeneral.TiposVentas.Nuevo.ToString().ToUpper() || enumerator_lineasFacturas.parmTipoVenta.ToString().ToUpper() == WSGeneral.TiposVentas.Usado.ToString().ToUpper())
                    {
                        oFila = dtLineasFactura.NewRow();
                        oFila["FACTURA"] = enumerator_lineasFacturas.parmInvoiceId.ToString();
                        oFila["TIPO"] = enumerator_lineasFacturas.parmSalesType.ToString().ToUpper();
                        oFila["FECHA"] = Convert.ToDateTime(enumerator_lineasFacturas.parmInvoiceDate.ToString());
                        oFila["ITEM"] = enumerator_lineasFacturas.parmItemId.ToString();
                        puedeConvertir = decimal.TryParse(enumerator_lineasFacturas.parmQty.ToString(), out numeroDecimal);
                        if (puedeConvertir == true)
                            oFila["CANTIDAD"] = enumerator_lineasFacturas.parmQty.ToString();
                        else
                            oFila["CANTIDAD"] = 0;
                        puedeConvertir = decimal.TryParse(enumerator_lineasFacturas.parmLineAmount.ToString(), out numeroDecimal);
                        if (puedeConvertir == true)
                            oFila["IMPORTE"] = enumerator_lineasFacturas.parmLineAmount.ToString();
                        else
                            oFila["IMPORTE"] = 0;
                        puedeConvertir = decimal.TryParse(enumerator_lineasFacturas.parmDays.ToString(), out numeroDecimal);
                        if (puedeConvertir == true)
                            oFila["DURACION"] = Convert.ToDecimal(enumerator_lineasFacturas.parmDays.ToString());
                        else
                            oFila["DURACION"] = 0;
                        oFila["CANON FENOLICO"] = 0;
                        oFila["CANON IMPORTE"] = 0;
                        oFila["CANON"] = 0;
                        puedeConvertir = decimal.TryParse(enumerator_lineasFacturas.parmEurDia.ToString(), out numeroDecimal);
                        if (puedeConvertir == true)
                            oFila["EURO DIA"] = Convert.ToDecimal(enumerator_lineasFacturas.parmEurDia);
                        else
                            oFila["EURO DIA"] = 0;
                        puedeConvertir = decimal.TryParse(enumerator_lineasFacturas.parmSalesPrice.ToString(), out numeroDecimal);
                        if (puedeConvertir == true)
                            oFila["PRECIO"] = Convert.ToDecimal(enumerator_lineasFacturas.parmSalesPrice);
                        else
                            oFila["PRECIO"] = 0;
                        dtLineasFactura.Rows.Add(oFila);
                        oFila = null;
                    }
                }
                proxy_facturas.Close();

                // ALBARANES ENTREGA
                dondeVa = "Albaranes entrega";
                if (listaObras.Count != 0)
                {
                    //System.Collections.IEnumerator enumerator_AlbaranEntrega_Coste;
                    //tablaAlbaranesEntrega.CallContext contexto_AlbaranEntrega_Coste = new tablaAlbaranesEntrega.CallContext();
                    //contexto_AlbaranEntrega_Coste.Company = empresa.ToString();

                    //tablaAlbaranesEntrega.QueryCriteria criterio_AlbaranEntrega_Coste = new tablaAlbaranesEntrega.QueryCriteria();
                    //criterio_AlbaranEntrega_Coste.CriteriaElement = new tablaAlbaranesEntrega.CriteriaElement[listaObras.Count];
                    //numFactura = 0;
                    //foreach (string nObraAlbaranEntrega in listaObras)
                    //{
                    //    criterio_AlbaranEntrega_Coste.CriteriaElement[numFactura] = new tablaAlbaranesEntrega.CriteriaElement();
                    //    criterio_AlbaranEntrega_Coste.CriteriaElement[numFactura].DataSourceName = "CustPackingSlipTrans";
                    //    criterio_AlbaranEntrega_Coste.CriteriaElement[numFactura].FieldName = "ObraId";
                    //    criterio_AlbaranEntrega_Coste.CriteriaElement[numFactura].Operator = tablaAlbaranesEntrega.Operator.Equal;
                    //    criterio_AlbaranEntrega_Coste.CriteriaElement[numFactura].Value1 = nObraAlbaranEntrega;
                    //    numFactura = numFactura + 1;
                    //}
                    //tablaAlbaranesEntrega.CustPackingServiceClient proxy_AlbaranEntrega_Coste = new tablaAlbaranesEntrega.CustPackingServiceClient();
                    //proxy_AlbaranEntrega_Coste.ClientCredentials.Windows.ClientCredential.Domain = WSDominio;
                    //proxy_AlbaranEntrega_Coste.ClientCredentials.Windows.ClientCredential.UserName = WSUsuario;
                    //proxy_AlbaranEntrega_Coste.ClientCredentials.Windows.ClientCredential.Password = WSContrasena;

                    //tablaAlbaranesEntrega.AxdCustPacking AxdCustPacking_Coste = proxy_AlbaranEntrega_Coste.find(contexto_AlbaranEntrega_Coste, criterio_AlbaranEntrega_Coste);

                    //if (AxdCustPacking_Coste.CustPackingSlipTrans is null)
                    //{
