                    //        // ALQUILER ENTREGA
                    //        if (salesType.ToUpper() == tablaAlbaranesEntrega.AxdEnum_SalesType.Alquiler.ToString().ToUpper())
                    //        {
                    //            oFila = dtAlbaranesEntrega.NewRow();
                    //            oFila["FACTURA"] = numeroFactura;
                    //            oFila["OBRA"] = AxdEntity_CustPackingSlipTrans.ObraId.ToString();
                    //            oFila["SALES TYPE"] = salesType;
                    //            oFila["SALES ID"] = AxdEntity_CustPackingSlipTrans.SalesId.ToString();
                    //            oFila["ALBARAN"] = AxdEntity_CustPackingSlipTrans.PackingSlipId.ToString();
                    //            oFila["TIPO"] = "ALQUILER";
                    //            oFila["FECHA ENTREGA"] = Convert.ToString(AxdEntity_CustPackingSlipTrans.DeliveryDate.ToString("yyyyMMdd"));
                    //            oFila["ITEM"] = AxdEntity_CustPackingSlipTrans.ItemId.ToString();
                    //            if (AxdEntity_CustPackingSlipTrans.Qty.HasValue)
                    //                oFila["CANTIDAD"] = Convert.ToDecimal(AxdEntity_CustPackingSlipTrans.Qty.ToString());
                    //            else
                    //                oFila["CANTIDAD"] = 0;
                    //            dtAlbaranesEntrega.Rows.Add(oFila);
                    //            oFila = null;
                    //        }
                    //    }
                    //}
                    WSGeneral.CallContext contextoAlbaranEntrega = new WSGeneral.CallContext();
                    contextoAlbaranEntrega.Company = empresa.ToString();

                    WSGeneral.QueryCriteria criterio_AlbaranEntrega = new WSGeneral.QueryCriteria();
                    criterio_AlbaranEntrega.CriteriaElement = new WSGeneral.CriteriaElement[listaNumeros.Count];
                    int numero = 0;
                    foreach (string nObraAlbaranEntrega in listaObras)
                    {
                        criterio_AlbaranEntrega.CriteriaElement[numero] = new WSGeneral.CriteriaElement();
                        criterio_AlbaranEntrega.CriteriaElement[numero].DataSourceName = "CustPackingSlipTrans";
                        criterio_AlbaranEntrega.CriteriaElement[numero].FieldName = "OBRAID";
                        criterio_AlbaranEntrega.CriteriaElement[numero].Operator = WSGeneral.Operator.Equal;
                        criterio_AlbaranEntrega.CriteriaElement[numero].Value1 = nObraAlbaranEntrega;
                        numero = numero + 1;
                    }

                    WSGeneral.WSROPServiceClient proxy_AlbaranEntrega = new WSGeneral.WSROPServiceClient();
                    proxy_AlbaranEntrega.ClientCredentials.Windows.ClientCredential.Domain = WSDominio;
                    proxy_AlbaranEntrega.ClientCredentials.Windows.ClientCredential.UserName = WSUsuario;
                    proxy_AlbaranEntrega.ClientCredentials.Windows.ClientCredential.Password = WSContrasena;

                    WSGeneral.WSCustPackingSlipTransContract[] axdtablaAlbaranEntrega = proxy_AlbaranEntrega.getCustPackingSlipTrans(contextoAlbaranEntrega, criterio_AlbaranEntrega);

                    IEnumerable<WSGeneral.WSCustPackingSlipTransContract> enumerableAlbaranEntrega = axdtablaAlbaranEntrega;
                    IEnumerator<WSGeneral.WSCustPackingSlipTransContract> enumeratorAlbaranEntrega = enumerableAlbaranEntrega.GetEnumerator();

                    hora_2 = DateTime.Now.Subtract(hora_1);
                    oItemTiempo = dtTiempos.NewRow();
                    oItemTiempo[0] = "     (generar estructuras ficha) TIEMPO llamar al wsGeneral / tablaAlbaranesEntrega";
                    oItemTiempo[1] = ((Convert.ToDecimal(hora_2.Minutes) * 60) + Convert.ToDecimal(hora_2.Seconds) + (Convert.ToDecimal(hora_2.Milliseconds) / 1000)).ToString("#,##0.000000");
                    dtTiempos.Rows.Add(oItemTiempo);

                    while (enumeratorAlbaranEntrega.MoveNext())
                    {
                        WSGeneral.WSCustPackingSlipTransContract enumerator_AlbaranEntrega = enumeratorAlbaranEntrega.Current;

                        string salesType = enumerator_AlbaranEntrega.parmSalesType.ToString();

                        // VENTA ENTREGA
                        if (salesType.ToUpper() == WSGeneral.SalesType.Sales.ToString().ToUpper())
                        {
                            oFila = dtAlbaranesEntrega.NewRow();
                            oFila["OBRA"] = enumerator_AlbaranEntrega.parmObraId.ToString();
                            oFila["FACTURA"] = numeroFactura;
                            oFila["SALES TYPE"] = salesType;
                            oFila["SALES ID"] = enumerator_AlbaranEntrega.parmSalesId.ToString();
                            oFila["ALBARAN"] = enumerator_AlbaranEntrega.parmPackingSlipId.ToString();
                            oFila["TIPO"] = "VENTA";
                            oFila["FECHA ENTREGA"] = Convert.ToString(enumerator_AlbaranEntrega.parmDeliveryDate.ToString("yyyyMMdd"));
                            oFila["ITEM"] = enumerator_AlbaranEntrega.parmItemId.ToString();
                            oFila["CANTIDAD"] = Convert.ToDecimal(enumerator_AlbaranEntrega.parmQty.ToString());
                            dtAlbaranesEntrega.Rows.Add(oFila);
                            oFila = null;
                        }

                        // ALQUILER ENTREGA
                        if (salesType.ToUpper() == WSGeneral.SalesType.Alquiler.ToString().ToUpper())
                        {
                            oFila = dtAlbaranesEntrega.NewRow();
                            oFila["OBRA"] = enumerator_AlbaranEntrega.parmObraId.ToString();
                            oFila["FACTURA"] = numeroFactura;
                            oFila["SALES TYPE"] = salesType;
                            oFila["SALES ID"] = enumerator_AlbaranEntrega.parmSalesId.ToString();
                            oFila["ALBARAN"] = enumerator_AlbaranEntrega.parmPackingSlipId.ToString();
                            oFila["TIPO"] = "ALQUILER";
                            oFila["FECHA ENTREGA"] = Convert.ToString(enumerator_AlbaranEntrega.parmDeliveryDate.ToString("yyyyMMdd"));
                            oFila["ITEM"] = enumerator_AlbaranEntrega.parmItemId.ToString();
                            oFila["CANTIDAD"] = Convert.ToDecimal(enumerator_AlbaranEntrega.parmQty.ToString());
                            dtAlbaranesEntrega.Rows.Add(oFila);
                            oFila = null;
                        }
                    }
                    proxy_AlbaranEntrega.Close();
                }
                error = "";
            }
            catch (Exception ex)
            {
                error = dondeVa + " // " + ex.Message;
                mostrarMensaje("estructuraFacturas // " + dondeVa + " // " + ex.Message);
            }
            finally
            {
                Session["dtTiempos"] = dtTiempos;
            }
        }

        private void estructuraPedidosNUEVO(ref string error, ref List<string> listaObras, ref DataTable dtCapitulosPedido, ref DataTable dtLineasPedido, ref DataTable dtAlbaranesEntrega, string empresa, List<string> listaNumeros, bool esFicha)
        {
            string usuarioRed = Session["usuarioRed"].ToString();
            DataTable dtTiempos = new DataTable();
            if (esFicha)
                dtTiempos = (DataTable)Session["dtTiemposPedidos"];
            else
                dtTiempos = (DataTable)Session["dtTiempos"];
            DataRow oItemTiempo;

            DataRow oFila;
            DataRow oFilaLinea;
            string numeroPedido = "";
            bool puedeConvertir;
            decimal numeroDecimal;
            string formaPago;
            string multivencimiento;
            int n = 0;
            string PeriodUnit = "";
            decimal QtyUnit = 0;
            decimal Qty = 0;
            decimal Valor = 0;
            string dondeVa = "";
            int cantidad = -1;
            List<int> listaCantidades = new List<int>();

            DateTime hora_1 = default(DateTime);
            TimeSpan hora_2 = default(TimeSpan);

            try
            {
                dondeVa = "Cabecera pedidos";
                hora_1 = DateTime.Now;
                WSGeneral.CallContext contexto_Pedido = new WSGeneral.CallContext();
                contexto_Pedido.Company = empresa;

                WSGeneral.QueryCriteria criterio_Pedido = new WSGeneral.QueryCriteria();
                criterio_Pedido.CriteriaElement = new WSGeneral.CriteriaElement[listaNumeros.Count];
                int numPedido = 0;
                foreach (string nPedido in listaNumeros)
                {
                    criterio_Pedido.CriteriaElement[numPedido] = new WSGeneral.CriteriaElement();
                    criterio_Pedido.CriteriaElement[numPedido].DataSourceName = "SalesTable";
                    criterio_Pedido.CriteriaElement[numPedido].FieldName = "SalesID";
                    criterio_Pedido.CriteriaElement[numPedido].Operator = WSGeneral.Operator.Equal;
                    criterio_Pedido.CriteriaElement[numPedido].Value1 = nPedido;
                    numPedido = numPedido + 1;
                }

                WSGeneral.WSROPServiceClient proxy_Pedido = new WSGeneral.WSROPServiceClient();
                proxy_Pedido.ClientCredentials.Windows.ClientCredential.Domain = WSDominio;
                proxy_Pedido.ClientCredentials.Windows.ClientCredential.UserName = WSUsuario;
                proxy_Pedido.ClientCredentials.Windows.ClientCredential.Password = WSContrasena;

                WSGeneral.WSSalesTableContract[] axdtablaPedidos = proxy_Pedido.getSalesOrders(contexto_Pedido, criterio_Pedido);

                IEnumerable<WSGeneral.WSSalesTableContract> enumerablePedido = axdtablaPedidos;
                IEnumerator<WSGeneral.WSSalesTableContract> enumeratorPedido = enumerablePedido.GetEnumerator();

                hora_2 = DateTime.Now.Subtract(hora_1);
                oItemTiempo = dtTiempos.NewRow();
                oItemTiempo[0] = "TIEMPO llamar al WSGeneral Pedidos con lista de pedidos (" + listaNumeros.Count.ToString() + ")";
                oItemTiempo[1] = ((Convert.ToDecimal(hora_2.Minutes) * 60) + Convert.ToDecimal(hora_2.Seconds) + (Convert.ToDecimal(hora_2.Milliseconds) / 1000)).ToString("#,##0.000000");
                funcionalidades.guardarTiempo(usuarioRed, oItemTiempo[0].ToString(), Convert.ToDecimal(oItemTiempo[1].ToString()));
                dtTiempos.Rows.Add(oItemTiempo);
                proxy_Pedido.Close();
                while (enumeratorPedido.MoveNext())
                {
                    WSGeneral.WSSalesTableContract enumerator_Pedido = enumeratorPedido.Current;
                
                    oFila = dtCapitulosPedido.NewRow();
                    numeroPedido = enumerator_Pedido.parmSalesId.ToString();
                    oFila["PEDIDO"] = enumerator_Pedido.parmSalesId.ToString();
                    oFila["NOMBRE PEDIDO"] = enumerator_Pedido.parmSalesName.ToString().Replace("'", "");
                    oFila["FECHA"] = Convert.ToDateTime(enumerator_Pedido.parmCreatedDateTime.ToString());
                    oFila["OFERTA"] = enumerator_Pedido.parmQuotationId.ToString();
                    oFila["MASTER OBRA"] = enumerator_Pedido.parmMasterObrasId.ToString();
                    if (enumerator_Pedido.parmObraId == "")
                        oFila["OBRA"] = "";
                    else
                    {
                        oFila["OBRA"] = enumerator_Pedido.parmObraId.ToString();
                        if (!listaObras.Contains(enumerator_Pedido.parmObraId.ToString()))
                            listaObras.Add(enumerator_Pedido.parmObraId.ToString());
                    }
                    if (enumerator_Pedido.parmMasterObrasName is null)
                        oFila["NOMBRE OBRA"] = "";
                    else
                        oFila["NOMBRE OBRA"] = enumerator_Pedido.parmMasterObrasName.ToString();
                    oFila["MONEDA"] = enumerator_Pedido.parmCurrencyCode.ToString();
                    oFila["CUENTA CLIENTE"] = enumerator_Pedido.parmCustAccount.ToString();
                    oFila["CENTRO COSTE"] = enumerator_Pedido.parmCostCenter.ToString();
                    oFila["DELEGACION"] = enumerator_Pedido.parmDelegation.ToString();
                    if (enumerator_Pedido.parmTipoVenta.ToString().ToUpper() == WSGeneral.TiposVentas.Liquidacion.ToString().ToUpper())
                    {
                        // Liquidación por venta
                        if (enumerator_Pedido.parmSettlementReason.ToString() == "0")
                            oFila["TIPO"] = "LIQUIDACION VENTA";

                        // Liquidación por pérdida MPO
                        if (enumerator_Pedido.parmSettlementReason.ToString() == "1")
                            oFila["TIPO"] = "LIQUIDACION MPO";
                    }
                    else
                        oFila["TIPO"] = "";
                    puedeConvertir = decimal.TryParse(enumerator_Pedido.parmKilometer.ToString(), out numeroDecimal);
                    if (puedeConvertir == true)
                        oFila["KILOMETRO"] = Convert.ToDecimal(enumerator_Pedido.parmKilometer);
                    else
                        oFila["KILOMETRO"] = 0;
                    oFila["MODO ENTREGA"] = enumerator_Pedido.parmDlvMode;
                    //puedeConvertir = Int32.TryParse(enumerator_Pedido.parmGestionPorte.GetHashCode(), out numeroEntero);
                    oFila["GESTION PORTE"] = Convert.ToInt32(enumerator_Pedido.parmGestionPorte.GetHashCode());
                    oFila["TIPO PORTE"] = Convert.ToInt32(enumerator_Pedido.parmTipoPorte.GetHashCode());
                    oFila["FORMA PAGO"] = enumerator_Pedido.parmPayment.ToString();
                    formaPago = enumerator_Pedido.parmPayment.ToString();
                    oFila["MULTIVENCIMIENTO"] = enumerator_Pedido.parmPaymentSched.ToString();
                    multivencimiento = enumerator_Pedido.parmPaymentSched.ToString();
                    oFila["NUMERO MESES"] = 0;
                    oFila["NUMERO DIAS"] = 0;
                    oFila["DIAS ADD"] = 0;
                    oFila["DIAS PAGO"] = 0;
                    oFila["DIAS TOTAL"] = -1;

                    // PAGOS
                    dondeVa = "Pagos";
                    hora_1 = DateTime.Now;
                    WSGeneral.CallContext contextoPagos = new WSGeneral.CallContext();
                    contextoPagos.Company = empresa;

                    WSGeneral.QueryCriteria criterioPagos = new WSGeneral.QueryCriteria();
                    criterioPagos.CriteriaElement = new WSGeneral.CriteriaElement[1];

                    criterioPagos.CriteriaElement[0] = new WSGeneral.CriteriaElement();
                    criterioPagos.CriteriaElement[0].DataSourceName = "PaymTerm";
                    criterioPagos.CriteriaElement[0].FieldName = "PaymTermId";
                    criterioPagos.CriteriaElement[0].Operator = WSGeneral.Operator.Equal;
                    criterioPagos.CriteriaElement[0].Value1 = formaPago;

                    WSGeneral.WSROPServiceClient proxyPagos = new WSGeneral.WSROPServiceClient();
                    proxyPagos.ClientCredentials.Windows.ClientCredential.Domain = WSDominio;
                    proxyPagos.ClientCredentials.Windows.ClientCredential.UserName = WSUsuario;
                    proxyPagos.ClientCredentials.Windows.ClientCredential.Password = WSContrasena;

                    WSGeneral.WSPaymTermContract[] axtablaPagos = proxyPagos.getPaymTerm(contextoPagos, criterioPagos);

                    IEnumerable<WSGeneral.WSPaymTermContract> enumerablePago = axtablaPagos;
                    IEnumerator<WSGeneral.WSPaymTermContract> enumeratorPago = enumerablePago.GetEnumerator();

                    hora_2 = DateTime.Now.Subtract(hora_1);
                    oItemTiempo = dtTiempos.NewRow();
                    oItemTiempo[0] = "TIEMPO llamar al WSGeneral /  tablaPagos con PaytemId = " + formaPago;
                    oItemTiempo[1] = ((Convert.ToDecimal(hora_2.Minutes) * 60) + Convert.ToDecimal(hora_2.Seconds) + (Convert.ToDecimal(hora_2.Milliseconds) / 1000)).ToString("#,##0.000000");
                    funcionalidades.guardarTiempo(usuarioRed, oItemTiempo[0].ToString(), Convert.ToDecimal(oItemTiempo[1].ToString()));
                    dtTiempos.Rows.Add(oItemTiempo);
                    proxyPagos.Close();

                    while (enumeratorPago.MoveNext())
                    {
                        WSGeneral.WSPaymTermContract enumerator_Pago = enumeratorPago.Current;

                        oFila["NUMERO MESES"] = Convert.ToInt32(enumerator_Pago.parmNumOfMonths);
                        oFila["DIAS PAGO"] = Convert.ToInt32(enumerator_Pago.parmNumOfMonths) * 30;

                        oFila["NUMERO DIAS"] = Convert.ToInt32(enumerator_Pago.parmNumOfDays);
                        oFila["DIAS PAGO"] = Convert.ToInt32(oFila["DIAS PAGO"]) + Convert.ToInt32(enumerator_Pago.parmNumOfDays);

                        oFila["DIAS ADD"] = 0;
                    }

                    // MULTIVENCIMIENTOS 
                    dondeVa = "Multivencimientos";
                    hora_1 = DateTime.Now;
                    WSGeneral.CallContext contextoVencimientoCabecera = new WSGeneral.CallContext();
                    contextoVencimientoCabecera.Company = empresa;

                    WSGeneral.QueryCriteria criterioVencimientoCabecera = new WSGeneral.QueryCriteria();
                    criterioVencimientoCabecera.CriteriaElement = new WSGeneral.CriteriaElement[1];

                    criterioVencimientoCabecera.CriteriaElement[0] = new WSGeneral.CriteriaElement();
                    criterioVencimientoCabecera.CriteriaElement[0].DataSourceName = "PaymSched";
                    criterioVencimientoCabecera.CriteriaElement[0].FieldName = "Name";
                    criterioVencimientoCabecera.CriteriaElement[0].Operator = WSGeneral.Operator.Equal;
                    criterioVencimientoCabecera.CriteriaElement[0].Value1 = multivencimiento;

                    WSGeneral.WSROPServiceClient proxyVencimientoCabecera = new WSGeneral.WSROPServiceClient();
                    proxyVencimientoCabecera.ClientCredentials.Windows.ClientCredential.Domain = WSDominio;
                    proxyVencimientoCabecera.ClientCredentials.Windows.ClientCredential.UserName = WSUsuario;
                    proxyVencimientoCabecera.ClientCredentials.Windows.ClientCredential.Password = WSContrasena;

                    WSGeneral.WSPaymSchedContract[] AxdVencimientosCabecera = proxyVencimientoCabecera.getPaymSched(contextoVencimientoCabecera, criterioVencimientoCabecera);

                    IEnumerable<WSGeneral.WSPaymSchedContract> enumerableVencimientoCabecera = AxdVencimientosCabecera;
                    IEnumerator<WSGeneral.WSPaymSchedContract> enumeratorVencimientoCabecera = enumerableVencimientoCabecera.GetEnumerator();

                    hora_2 = DateTime.Now.Subtract(hora_1);
                    oItemTiempo = dtTiempos.NewRow();
                    oItemTiempo[0] = "TIEMPO llamar al ws WSGeneral / tablaVencimientosCabecera con PaymSchedName = " + multivencimiento;
                    oItemTiempo[1] = ((Convert.ToDecimal(hora_2.Minutes) * 60) + Convert.ToDecimal(hora_2.Seconds) + (Convert.ToDecimal(hora_2.Milliseconds) / 1000)).ToString("#,##0.000000");
                    funcionalidades.guardarTiempo(usuarioRed, oItemTiempo[0].ToString(), Convert.ToDecimal(oItemTiempo[1].ToString()));
                    dtTiempos.Rows.Add(oItemTiempo);
                    proxyVencimientoCabecera.Close();

                    while (enumeratorVencimientoCabecera.MoveNext())
                    {
                        WSGeneral.WSPaymSchedContract enumerator_VencimientoCabecera = enumeratorVencimientoCabecera.Current;

                        n = Convert.ToInt32(enumerator_VencimientoCabecera.parmNumOfPayment);

                        oFila["PERIOD UNIT"] = enumerator_VencimientoCabecera.parmPeriodUnit.ToString().ToUpper();
                        PeriodUnit = enumerator_VencimientoCabecera.parmPeriodUnit.ToString().ToUpper();
                        oFila["QTY UNIT"] = Convert.ToInt32(enumerator_VencimientoCabecera.parmQtyUnit.ToString());
                        QtyUnit = Convert.ToInt32(enumerator_VencimientoCabecera.parmQtyUnit.ToString());

                        oFila["DIAS TOTAL"] = 0;
                        if (enumerator_VencimientoCabecera.parmPaymBy.ToString().ToUpper() == "TOTAL")
                            oFila["DIAS TOTAL"] = Convert.ToDecimal(oFila["DIAS PAGO"]) + Convert.ToDecimal(oFila["DIAS ADD"]);
                        else if (enumerator_VencimientoCabecera.parmPaymBy.ToString().ToUpper() == "NUMOFPAYMENT" || enumerator_VencimientoCabecera.parmPaymBy.ToString().ToUpper() == "AMOUNTBYPAYMENT")
                        {
                            for (int vencimiento = 0; vencimiento <= n - 1; vencimiento++)
                            {
                                if (PeriodUnit == "MONTH")
                                    oFila["DIAS TOTAL"] = Convert.ToDecimal(oFila["DIAS TOTAL"]) + (((vencimiento * (QtyUnit * 30)) + Convert.ToDecimal(oFila["DIAS PAGO"]) + Convert.ToDecimal(oFila["DIAS ADD"])) / n);
                                else if (PeriodUnit == "DAY")
                                    oFila["DIAS TOTAL"] = Convert.ToDecimal(oFila["DIAS TOTAL"]) + (((vencimiento * QtyUnit) + Convert.ToDecimal(oFila["DIAS PAGO"]) + Convert.ToDecimal(oFila["DIAS ADD"])) / n);
                                else
                                    oFila["DIAS TOTAL"] = 0;
                            }
                        }
                        else if (enumerator_VencimientoCabecera.parmPaymBy.ToString().ToUpper() == "SPECIFIED")
                        {
                            dondeVa = "Multivencimientos líneas";
                            // MULTIVENCIMIENTOS LÍNEAS
                            IEnumerable<WSGeneral.WSPaymSchedLineContract> enumerableVencimientoLineas = enumerator_VencimientoCabecera.parmPaymSchedLines;
                            IEnumerator<WSGeneral.WSPaymSchedLineContract> enumeratorVencimientoLineas = enumerableVencimientoLineas.GetEnumerator();

                            while (enumeratorVencimientoLineas.MoveNext())
                            {
                                WSGeneral.WSPaymSchedLineContract enumerator_VencimientoLineas = enumeratorVencimientoLineas.Current;

                                cantidad = Convert.ToInt32(enumerator_VencimientoLineas.parmQty.ToString());

                                // valida si ya existe este modo de pago, en cuyo caso se ignora
                                if (!listaCantidades.Contains(cantidad))
                                {
                                    listaCantidades.Add(cantidad);

                                    oFila["QTY"] = Convert.ToInt32(enumerator_VencimientoLineas.parmQty.ToString());
                                    Qty = Convert.ToInt32(enumerator_VencimientoLineas.parmQty.ToString());

                                    oFila["VALUE"] = Convert.ToDecimal(enumerator_VencimientoLineas.parmValue.ToString());
                                    Valor = Convert.ToDecimal(enumerator_VencimientoLineas.parmValue.ToString());

                                    if (PeriodUnit == "MONTH")
                                        oFila["DIAS TOTAL"] = Convert.ToDecimal(oFila["DIAS TOTAL"]) + ((Valor * ((Qty * 30) + Convert.ToDecimal(oFila["DIAS PAGO"]) + Convert.ToDecimal(oFila["DIAS ADD"]))) / 100);
                                    else if (PeriodUnit == "DAY")
                                        oFila["DIAS TOTAL"] = Convert.ToDecimal(oFila["DIAS TOTAL"]) + ((Valor * (Qty + Convert.ToDecimal(oFila["DIAS PAGO"]) + Convert.ToDecimal(oFila["DIAS ADD"]))) / 100);
                                    else
                                        oFila["DIAS TOTAL"] = Convert.ToDecimal(oFila["DIAS TOTAL"]);
                                }
                            }

                        }
                    }
                    criterioVencimientoCabecera = null;
                    contextoVencimientoCabecera = null;

                    IEnumerable<WSGeneral.WSSalesLineContract> enumerableLineas = enumerator_Pedido.parmSalesLines;
                    IEnumerator<WSGeneral.WSSalesLineContract> enumeratorLineas = enumerableLineas.GetEnumerator();

                    dondeVa = "Líneas pedidos";
                    while (enumeratorLineas.MoveNext())
                    {
                        WSGeneral.WSSalesLineContract enumerator_PedidoLineas = enumeratorLineas.Current;

                        if (enumerator_PedidoLineas.parmLineNum != 0)
                        {
                            oFilaLinea = dtLineasPedido.NewRow();
                            oFilaLinea["PEDIDO"] = enumerator_Pedido.parmSalesId.ToString();
                            oFilaLinea["TIPO"] = enumerator_PedidoLineas.parmSalesType.ToString().ToUpper();
                            oFilaLinea["CAPITULO"] = enumerator_Pedido.parmSalesId.ToString().Replace("'", "") + " / " + enumerator_Pedido.parmSalesName.ToString().Replace("'", "");
                            oFilaLinea["FECHA"] = Convert.ToDateTime(enumerator_PedidoLineas.parmCreatedDateTime.ToString());

                            oFilaLinea["ITEM"] = enumerator_PedidoLineas.parmItemId.ToString();
                            puedeConvertir = decimal.TryParse(enumerator_PedidoLineas.parmSalesQty.ToString(), out numeroDecimal);
                            if (puedeConvertir == true)
                                oFilaLinea["CANTIDAD"] = enumerator_PedidoLineas.parmSalesQty.ToString();
                            else
                                oFilaLinea["CANTIDAD"] = 0;
                            puedeConvertir = decimal.TryParse(enumerator_PedidoLineas.parmLineAmount.ToString(), out numeroDecimal);
                            if (puedeConvertir == true)
                                oFilaLinea["IMPORTE"] = enumerator_PedidoLineas.parmLineAmount.ToString();
                            else
                                oFilaLinea["IMPORTE"] = 0;
                            //enumerator_PedidoLineas.parmCurrencyCode;
                            puedeConvertir = decimal.TryParse(enumerator_PedidoLineas.parmDuracionEstimada.ToString(), out numeroDecimal);
                            if (puedeConvertir == true)
                                oFilaLinea["DURACION"] = Convert.ToDecimal(enumerator_PedidoLineas.parmDuracionEstimada.ToString());
                            else
                                oFilaLinea["DURACION"] = 0;
                            oFilaLinea["CANON FENOLICO"] = 0;
                            oFilaLinea["CANON IMPORTE"] = 0;
                            oFila["CANON FENOLICO"] = 0;
                            oFilaLinea["CANON"] = 0;
                            oFilaLinea["CANON FENOLICO"] = enumerator_PedidoLineas.parmCanonFenolico;
                            oFila["CANON FENOLICO"] = enumerator_PedidoLineas.parmCanonFenolico;
                            oFilaLinea["CANON IMPORTE"] = Convert.ToDecimal(enumerator_PedidoLineas.parmCanonImport);
                            oFilaLinea["CANON"] = Convert.ToDecimal(enumerator_PedidoLineas.parmCanon);
                            puedeConvertir = decimal.TryParse(enumerator_PedidoLineas.parmEurDia.ToString(), out numeroDecimal);
                            if (puedeConvertir == true)
                                oFilaLinea["EURO DIA"] = Convert.ToDecimal(enumerator_PedidoLineas.parmEurDia);
                            else
                                oFilaLinea["EURO DIA"] = 0;
                            puedeConvertir = decimal.TryParse(enumerator_PedidoLineas.parmSalesPrice.ToString(), out numeroDecimal);
                            if (puedeConvertir == true)
                                oFilaLinea["PRECIO"] = Convert.ToDecimal(enumerator_PedidoLineas.parmSalesPrice);
                            else
                                oFilaLinea["PRECIO"] = 0;
                            dtLineasPedido.Rows.Add(oFilaLinea);
                            oFilaLinea = null;
                        }
                    }
                    dtCapitulosPedido.Rows.Add(oFila);
                    oFila = null;
                }

                // ALBARANES ENTREGA
                dondeVa = "Albaranes entrega";
                if (esFicha && !Convert.ToBoolean(Session["albaranesEntregaProcesados"]))
                {
                    Session["albaranesEntregaProcesados"] = true;
                    if (listaObras.Count != 0)
                    {
                        WSGeneral.CallContext contextoAlbaranEntrega = new WSGeneral.CallContext();
                        contextoAlbaranEntrega.Company = empresa.ToString();

                        WSGeneral.QueryCriteria criterio_AlbaranEntrega = new WSGeneral.QueryCriteria();
                        criterio_AlbaranEntrega.CriteriaElement = new WSGeneral.CriteriaElement[listaNumeros.Count];
                        int numero = 0;
                        foreach (string nObraAlbaranEntrega in listaObras)
                        {
                            criterio_AlbaranEntrega.CriteriaElement[numero] = new WSGeneral.CriteriaElement();
                            criterio_AlbaranEntrega.CriteriaElement[numero].DataSourceName = "CustPackingSlipTrans";
                            criterio_AlbaranEntrega.CriteriaElement[numero].FieldName = "OBRAID";
                            criterio_AlbaranEntrega.CriteriaElement[numero].Operator = WSGeneral.Operator.Equal;
                            criterio_AlbaranEntrega.CriteriaElement[numero].Value1 = nObraAlbaranEntrega;
                            numero = numero + 1;
                        }

                        WSGeneral.WSROPServiceClient proxy_AlbaranEntrega = new WSGeneral.WSROPServiceClient();
                        proxy_AlbaranEntrega.ClientCredentials.Windows.ClientCredential.Domain = WSDominio;
                        proxy_AlbaranEntrega.ClientCredentials.Windows.ClientCredential.UserName = WSUsuario;
                        proxy_AlbaranEntrega.ClientCredentials.Windows.ClientCredential.Password = WSContrasena;

                        WSGeneral.WSCustPackingSlipTransContract[] axdtablaAlbaranEntrega = proxy_AlbaranEntrega.getCustPackingSlipTrans(contextoAlbaranEntrega, criterio_AlbaranEntrega);

                        IEnumerable<WSGeneral.WSCustPackingSlipTransContract> enumerableAlbaranEntrega = axdtablaAlbaranEntrega;
                        IEnumerator<WSGeneral.WSCustPackingSlipTransContract> enumeratorAlbaranEntrega = enumerableAlbaranEntrega.GetEnumerator();

                        hora_2 = DateTime.Now.Subtract(hora_1);
                        oItemTiempo = dtTiempos.NewRow();
                        oItemTiempo[0] = "     (generar estructuras ficha) TIEMPO llamar al wsGeneral / tablaAlbaranesEntrega";
                        oItemTiempo[1] = ((Convert.ToDecimal(hora_2.Minutes) * 60) + Convert.ToDecimal(hora_2.Seconds) + (Convert.ToDecimal(hora_2.Milliseconds) / 1000)).ToString("#,##0.000000");
                        funcionalidades.guardarTiempo(usuarioRed, oItemTiempo[0].ToString(), Convert.ToDecimal(oItemTiempo[1].ToString()));
                        dtTiempos.Rows.Add(oItemTiempo);

                        int cuantos = 0;
                        proxy_AlbaranEntrega.Close();
                        while (enumeratorAlbaranEntrega.MoveNext())
                        {
                            cuantos++;

                            WSGeneral.WSCustPackingSlipTransContract enumerator_AlbaranEntrega = enumeratorAlbaranEntrega.Current;

                            string salesType = enumerator_AlbaranEntrega.parmSalesType.ToString();

                            // VENTA ENTREGA
                            if (salesType.ToUpper() == WSGeneral.SalesType.Sales.ToString().ToUpper())
                            {
                                oFila = dtAlbaranesEntrega.NewRow();
                                oFila["PEDIDO"] = numeroPedido;
                                oFila["OBRA"] = enumerator_AlbaranEntrega.parmObraId.ToString();
                                oFila["SALES TYPE"] = salesType;
                                oFila["SALES ID"] = enumerator_AlbaranEntrega.parmSalesId.ToString();
                                oFila["ALBARAN"] = enumerator_AlbaranEntrega.parmPackingSlipId.ToString();
                                oFila["TIPO"] = "VENTA";
                                oFila["FECHA ENTREGA"] = Convert.ToString(enumerator_AlbaranEntrega.parmDeliveryDate.ToString("yyyyMMdd"));
                                oFila["ITEM"] = enumerator_AlbaranEntrega.parmItemId.ToString();
                                oFila["CANTIDAD"] = Convert.ToDecimal(enumerator_AlbaranEntrega.parmQty.ToString());
                                dtAlbaranesEntrega.Rows.Add(oFila);
                                oFila = null;
                            }

                            // ALQUILER ENTREGA
                            if (salesType.ToUpper() == WSGeneral.SalesType.Alquiler.ToString().ToUpper())
                            {
                                oFila = dtAlbaranesEntrega.NewRow();
                                oFila["PEDIDO"] = numeroPedido;
                                oFila["OBRA"] = enumerator_AlbaranEntrega.parmObraId.ToString();
                                oFila["SALES TYPE"] = salesType;
                                oFila["SALES ID"] = enumerator_AlbaranEntrega.parmSalesId.ToString();
                                oFila["ALBARAN"] = enumerator_AlbaranEntrega.parmPackingSlipId.ToString();
                                oFila["TIPO"] = "ALQUILER";
                                oFila["FECHA ENTREGA"] = Convert.ToString(enumerator_AlbaranEntrega.parmDeliveryDate.ToString("yyyyMMdd"));
                                oFila["ITEM"] = enumerator_AlbaranEntrega.parmItemId.ToString();
                                oFila["CANTIDAD"] = Convert.ToDecimal(enumerator_AlbaranEntrega.parmQty.ToString());
                                dtAlbaranesEntrega.Rows.Add(oFila);
                                oFila = null;
                            }
                        }
                    }
                }
                error = "";
            }
            catch (Exception ex)
            {
                error = dondeVa + " // " + ex.Message;
                mostrarMensaje("estructuraPedidos // " + dondeVa + " // " + ex.Message);
                funcionalidades.guardarIncidencia(empresa, "PEDIDO", listaNumeros.ElementAt(0), "", "Error al crear las estructuras de datos para el pedido // " + "estructuraPedidos: (" + dondeVa + ") // " + ex.Message, 1, Session["usuarioRed"].ToString(), User.Identity.Name.ToString());
            }
            finally
            {
                Session["dtTiempos"] = dtTiempos;
            }
        }

        private void calcularTiempos(bool vieneAxapta, int lineasAceler)
        {
            decimal factorCalculo = 0;
            string tipo = "";
            string empresa = "";
            string numero = "";
            string strConexion;
            SqlConnection conexion;
            SqlCommand comando;

            if (vieneAxapta)
            {
                if (Session["tipoEnviado"].ToString() == "1")
                    tipo = "OFERTA";
                else if (Session["tipoEnviado"].ToString() == "2")
                    tipo = "PEDIDO";
                else if (Session["tipoEnviado"].ToString() == "3")
                    tipo = "FACTURA";
                else if (Session["tipoEnviado"].ToString() == "4")
                    tipo = "FICHA";
                empresa = Session["empresaEnviado"].ToString().ToUpper();
                numero = Session["numeroEnviado"].ToString().ToUpper();
            }
            else
            {
                tipo = cmbConcepto.SelectedValue.ToString().ToUpper();
                empresa = cmbEmpresa.SelectedItem.ToString();
                numero = txtNumero.Text;
            }

            if (lineasAceler != 0)
            {
                tipo = "OFERTA";
                factorCalculo = lineasAceler * 2;
            }
            else
            {
                if (tipo == "OFERTA")
                {
                    WSGeneral.CallContext contexto_Oferta = new WSGeneral.CallContext();
                    contexto_Oferta.Company = empresa;

                    WSGeneral.QueryCriteria criterio_Oferta = new WSGeneral.QueryCriteria();
                    criterio_Oferta.CriteriaElement = new WSGeneral.CriteriaElement[1];

                    criterio_Oferta.CriteriaElement[0] = new WSGeneral.CriteriaElement();
                    criterio_Oferta.CriteriaElement[0].FieldName = "QuotationId";
                    criterio_Oferta.CriteriaElement[0].DataSourceName = "SalesQuotationMasterTable";
                    criterio_Oferta.CriteriaElement[0].Operator = WSGeneral.Operator.Equal;
                    criterio_Oferta.CriteriaElement[0].Value1 = numero;

                    WSGeneral.WSROPServiceClient proxy_Oferta = new WSGeneral.WSROPServiceClient();
                    proxy_Oferta.ClientCredentials.Windows.ClientCredential.Domain = WSDominio;
                    proxy_Oferta.ClientCredentials.Windows.ClientCredential.UserName = WSUsuario;
                    proxy_Oferta.ClientCredentials.Windows.ClientCredential.Password = WSContrasena;

                    WSGeneral.WSSalesQuotationMasterTableContract[] axdtablaOfertas = proxy_Oferta.getQuotations(contexto_Oferta, criterio_Oferta);
                    IEnumerable<WSGeneral.WSSalesQuotationMasterTableContract> enumerableOferta = axdtablaOfertas;
                    IEnumerator<WSGeneral.WSSalesQuotationMasterTableContract> enumeratorOferta = enumerableOferta.GetEnumerator();

                    proxy_Oferta.Close();

                    while (enumeratorOferta.MoveNext())
                    {
                        WSGeneral.WSSalesQuotationMasterTableContract enumerator_MasterOferta = enumeratorOferta.Current;

                        IEnumerable<WSGeneral.WSSalesQuotationTableContract> enumerableCapitulos = enumerator_MasterOferta.parmQuotationTable;
                        IEnumerator<WSGeneral.WSSalesQuotationTableContract> enumeratorCapitulos = enumerableCapitulos.GetEnumerator();

                        while (enumeratorCapitulos.MoveNext())
                        {
                            WSGeneral.WSSalesQuotationTableContract enumerator_Capitulos = enumeratorCapitulos.Current;

                            IEnumerable<WSGeneral.WSSalesQuotationLineContract> enumerableLineas = enumerator_Capitulos.parmQuotationLine;
                            IEnumerator<WSGeneral.WSSalesQuotationLineContract> enumeratorLineas = enumerableLineas.GetEnumerator();

                            while (enumeratorLineas.MoveNext())
                            {
                                factorCalculo = factorCalculo + 1;
                            }
                        }
                    }

                }

                if (tipo == "PEDIDO")
                {
                    WSGeneral.CallContext contexto_Pedido = new WSGeneral.CallContext();
                    contexto_Pedido.Company = empresa;

                    WSGeneral.QueryCriteria criterio_Pedido = new WSGeneral.QueryCriteria();
                    criterio_Pedido.CriteriaElement = new WSGeneral.CriteriaElement[1];

                    criterio_Pedido.CriteriaElement[0] = new WSGeneral.CriteriaElement();
                    criterio_Pedido.CriteriaElement[0].DataSourceName = "SalesTable";
                    criterio_Pedido.CriteriaElement[0].FieldName = "SalesID";
                    criterio_Pedido.CriteriaElement[0].Operator = WSGeneral.Operator.Equal;
                    criterio_Pedido.CriteriaElement[0].Value1 = numero;

                    WSGeneral.WSROPServiceClient proxy_Pedido = new WSGeneral.WSROPServiceClient();
                    proxy_Pedido.ClientCredentials.Windows.ClientCredential.Domain = WSDominio;
                    proxy_Pedido.ClientCredentials.Windows.ClientCredential.UserName = WSUsuario;
                    proxy_Pedido.ClientCredentials.Windows.ClientCredential.Password = WSContrasena;

                    WSGeneral.WSSalesTableContract[] axdtablaPedidos = proxy_Pedido.getSalesOrders(contexto_Pedido, criterio_Pedido);

                    IEnumerable<WSGeneral.WSSalesTableContract> enumerablePedido = axdtablaPedidos;
                    IEnumerator<WSGeneral.WSSalesTableContract> enumeratorPedido = enumerablePedido.GetEnumerator();
                    proxy_Pedido.Close();

                    while (enumeratorPedido.MoveNext())
                    {
                        WSGeneral.WSSalesTableContract enumerator_Pedido = enumeratorPedido.Current;

                        IEnumerable<WSGeneral.WSSalesLineContract> enumerableLineas = enumerator_Pedido.parmSalesLines;
                        IEnumerator<WSGeneral.WSSalesLineContract> enumeratorLineas = enumerableLineas.GetEnumerator();

                        while (enumeratorLineas.MoveNext())
                        {
                            factorCalculo = factorCalculo + 1;
                        }

                    }
                }

                if (tipo == "FACTURA")
                {
                    WSGeneral.CallContext contexto_facturas = new WSGeneral.CallContext();
                    contexto_facturas.Company = empresa;

                    WSGeneral.QueryCriteria criterio_facturas = new WSGeneral.QueryCriteria();
                    criterio_facturas.CriteriaElement = new WSGeneral.CriteriaElement[1];

                    criterio_facturas.CriteriaElement[0] = new WSGeneral.CriteriaElement();
                    criterio_facturas.CriteriaElement[0].DataSourceName = "CustInvoiceTrans";
                    criterio_facturas.CriteriaElement[0].FieldName = "InvoiceId";
                    criterio_facturas.CriteriaElement[0].Operator = WSGeneral.Operator.Equal;
                    criterio_facturas.CriteriaElement[0].Value1 = numero;

                    WSGeneral.WSROPServiceClient proxy_facturas = new WSGeneral.WSROPServiceClient();
                    proxy_facturas.ClientCredentials.Windows.ClientCredential.Domain = WSDominio;
                    proxy_facturas.ClientCredentials.Windows.ClientCredential.UserName = WSUsuario;
                    proxy_facturas.ClientCredentials.Windows.ClientCredential.Password = WSContrasena;

                    WSGeneral.WSCustInvoiceTransContract[] axdtablaFacturas = proxy_facturas.getCustInvoiceTrans(contexto_facturas, criterio_facturas);

                    IEnumerable<WSGeneral.WSCustInvoiceTransContract> enumerableLineasFacturas = axdtablaFacturas;
                    IEnumerator<WSGeneral.WSCustInvoiceTransContract> enumeratorLineasFacturas = enumerableLineasFacturas.GetEnumerator();
                    proxy_facturas.Close();
                    while (enumeratorLineasFacturas.MoveNext())
                    {
                        factorCalculo = factorCalculo + 1;
                    }

                }

                if (tipo == "FICHA")
                {
                    WSGeneral.CallContext contexto_Pedido = new WSGeneral.CallContext();
                    contexto_Pedido.Company = empresa;

                    WSGeneral.QueryCriteria criterio_Pedido = new WSGeneral.QueryCriteria();
                    criterio_Pedido.CriteriaElement = new WSGeneral.CriteriaElement[1];

                    criterio_Pedido.CriteriaElement[0] = new WSGeneral.CriteriaElement();
                    criterio_Pedido.CriteriaElement[0].DataSourceName = "SalesTable";
                    criterio_Pedido.CriteriaElement[0].FieldName = "OBRAID";
                    criterio_Pedido.CriteriaElement[0].Operator = WSGeneral.Operator.Equal;
                    criterio_Pedido.CriteriaElement[0].Value1 = numero;

                    WSGeneral.WSROPServiceClient proxy_Pedido = new WSGeneral.WSROPServiceClient();
                    proxy_Pedido.ClientCredentials.Windows.ClientCredential.Domain = WSDominio;
                    proxy_Pedido.ClientCredentials.Windows.ClientCredential.UserName = WSUsuario;
                    proxy_Pedido.ClientCredentials.Windows.ClientCredential.Password = WSContrasena;

                    WSGeneral.WSSalesTableContract[] axdtablaPedidos = proxy_Pedido.getSalesOrders(contexto_Pedido, criterio_Pedido);

                    IEnumerable<WSGeneral.WSSalesTableContract> enumerable = axdtablaPedidos;
                    IEnumerator<WSGeneral.WSSalesTableContract> enumerator = enumerable.GetEnumerator();
                    proxy_Pedido.Close();
                    while (enumerator.MoveNext())
                    {
                        factorCalculo = factorCalculo + 1;
                    }
                }
            }

            // DATOS TECNICOS
            decimal barraProgreso = 0;
            decimal barraProgresoSegunConcepto = 0;

            strConexion = funcionalidades.recuperarTexto(ConfigurationManager.ConnectionStrings["SQL_ROP"].ToString());
            conexion = new SqlConnection(strConexion);
            conexion.Open();
            comando = conexion.CreateCommand();
            comando.CommandText = "sp_ROP_ConfiguracionTecnicoConsulta";
            comando.CommandTimeout = 60;
            comando.CommandType = CommandType.StoredProcedure;
            comando.Parameters.Clear();
            SqlDataReader dr = comando.ExecuteReader();
            if (dr.HasRows)
            {
                dr.Read();
                barraProgreso = Convert.ToDecimal(dr["BarraProgreso"].ToString());

                if (tipo == "OFERTA")
                    barraProgresoSegunConcepto = Convert.ToDecimal(dr["BarraProgresoOfertas"].ToString());
                else if (tipo == "PEDIDO" || tipo == "FACTURA")
                    barraProgresoSegunConcepto = Convert.ToDecimal(dr["BarraProgresoPedidosFacturas"].ToString());
                else if (tipo == "FICHA")
                    barraProgresoSegunConcepto = Convert.ToDecimal(dr["BarraProgresoFichas"].ToString());
            }
            dr.Close();
            comando.Dispose();
            conexion.Close();
            conexion.Dispose();

            decimal tiempo = factorCalculo * barraProgreso * barraProgresoSegunConcepto;
            lblTiempo.Text = tiempo.ToString();
        }

        private void estructuraOfertasNUEVO(ref string error, ref List<string> listaObras, ref DataTable dtCabeceraOferta, ref DataTable dtCapitulosOferta, ref DataTable dtLineasOferta, ref bool existeTR001, string codigosTransporte, string empresa, List<string> listaNumeros)
        {
            DataTable dtTiempos = new DataTable();
            dtTiempos = (DataTable)Session["dtTiempos"];
            DataRow oItemTiempo;
            DataRow oOferta;
            string dondeVa = "";
            bool puedeConvertir;
            decimal numeroDecimal;
            string formaPago;
            string multivencimiento;
            int n = 0;
            string PeriodUnit = "";
            decimal QtyUnit = 0;
            decimal Qty = 0;
            decimal Valor = 0;
            DateTime hora_1 = default(DateTime);
            TimeSpan hora_2 = default(TimeSpan);
            int cantidad = -1;
            List<int> listaCantidades = new List<int>();

            try
            {
                //myTiempo.InnerHtml = "50";
                hora_1 = DateTime.Now;
                WSGeneral.CallContext contexto_Oferta = new WSGeneral.CallContext();
                contexto_Oferta.Company = empresa.ToString();

                WSGeneral.QueryCriteria criterio_Oferta = new WSGeneral.QueryCriteria();
                criterio_Oferta.CriteriaElement = new WSGeneral.CriteriaElement[listaNumeros.Count];
                int numOferta = 0;
                foreach (string nOferta in listaNumeros)
                {
                    criterio_Oferta.CriteriaElement[numOferta] = new WSGeneral.CriteriaElement();
                    criterio_Oferta.CriteriaElement[numOferta].FieldName = "QuotationId";
                    criterio_Oferta.CriteriaElement[numOferta].DataSourceName = "SalesQuotationMasterTable";
                    criterio_Oferta.CriteriaElement[numOferta].Operator = WSGeneral.Operator.Equal;
                    criterio_Oferta.CriteriaElement[numOferta].Value1 = nOferta;
                    numOferta = numOferta + 1;
                }

                WSGeneral.WSROPServiceClient proxy_Oferta = new WSGeneral.WSROPServiceClient();
                proxy_Oferta.ClientCredentials.Windows.ClientCredential.Domain = WSDominio;
                proxy_Oferta.ClientCredentials.Windows.ClientCredential.UserName = WSUsuario;
                proxy_Oferta.ClientCredentials.Windows.ClientCredential.Password = WSContrasena;

                WSGeneral.WSSalesQuotationMasterTableContract[] axdtablaOfertas = proxy_Oferta.getQuotations(contexto_Oferta, criterio_Oferta);
                IEnumerable<WSGeneral.WSSalesQuotationMasterTableContract> enumerableOferta = axdtablaOfertas;
                IEnumerator<WSGeneral.WSSalesQuotationMasterTableContract> enumeratorOferta = enumerableOferta.GetEnumerator();

                hora_2 = DateTime.Now.Subtract(hora_1);
                oItemTiempo = dtTiempos.NewRow();
                oItemTiempo[0] = "TIEMPO llamar al ws Ofertas con lista de ofertas (" + listaNumeros.Count.ToString() + ")";
                oItemTiempo[1] = ((Convert.ToDecimal(hora_2.Minutes) * 60) + Convert.ToDecimal(hora_2.Seconds) + (Convert.ToDecimal(hora_2.Milliseconds) / 1000)).ToString("#,##0.000000");
                dtTiempos.Rows.Add(oItemTiempo);

                while (enumeratorOferta.MoveNext())
                {
                    WSGeneral.WSSalesQuotationMasterTableContract enumerator_MasterOferta = enumeratorOferta.Current;

                    oOferta = dtCabeceraOferta.NewRow();
                    oOferta["OFERTA"] = enumerator_MasterOferta.parmQuotationId.ToString();
                    oOferta["NOMBRE OFERTA"] = enumerator_MasterOferta.parmQuotationName.ToString();
                    oOferta["FECHA"] = Convert.ToDateTime(enumerator_MasterOferta.parmCreatedDateTime.ToString());
                    if (enumerator_MasterOferta.parmMasterObrasId is null)
                        oOferta["MASTER OBRA"] = "";
                    else
                        oOferta["MASTER OBRA"] = enumerator_MasterOferta.parmMasterObrasId.ToString();
                    if (enumerator_MasterOferta.parmObraId is null)
                        oOferta["OBRA"] = "";
                    else
                    {
                        oOferta["OBRA"] = enumerator_MasterOferta.parmObraId.ToString();
                        if (!listaObras.Contains(enumerator_MasterOferta.parmObraId.ToString()))
                            listaObras.Add(enumerator_MasterOferta.parmObraId.ToString());
                    }
                    if (enumerator_MasterOferta.parmObraname is null)
                    oOferta["NOMBRE OBRA"] = "";
                    else
                        oOferta["NOMBRE OBRA"] = enumerator_MasterOferta.parmObraname.ToString();

                    if (enumerator_MasterOferta.parmCurrencyCode is null)
                        oOferta["MONEDA"] = "";
                    else
                        oOferta["MONEDA"] = enumerator_MasterOferta.parmCurrencyCode.ToString();

                    oOferta["CUENTA CLIENTE"] = "";
                    if (enumerator_MasterOferta.parmCustAccount is null)
                        oOferta["CUENTA CLIENTE"] = "";
                    else
                        oOferta["CUENTA CLIENTE"] = enumerator_MasterOferta.parmCustAccount.ToString();
                    if (oOferta["CUENTA CLIENTE"].ToString() == "")
                    {
                        if (enumerator_MasterOferta.parmBusRelAccount is null)
                            oOferta["CUENTA CLIENTE"] = "";
                        else
                            oOferta["CUENTA CLIENTE"] = enumerator_MasterOferta.parmBusRelAccount.ToString();
                    }
                    if (enumerator_MasterOferta.parmCostCenter is null)
                        oOferta["CENTRO COSTE"] = "";
                    else
                        oOferta["CENTRO COSTE"] = enumerator_MasterOferta.parmCostCenter.ToString();
                    if (enumerator_MasterOferta.parmDelegation is null)
                        oOferta["DELEGACION"] = "";
                    else
                        oOferta["DELEGACION"] = enumerator_MasterOferta.parmDelegation.ToString();
                    if (enumerator_MasterOferta.parmSalesRental.ToString() is null)
                        oOferta["TIPO"] = "";
                    else
                        oOferta["TIPO"] = enumerator_MasterOferta.parmSalesRental.ToString().ToUpper();
                    puedeConvertir = decimal.TryParse(enumerator_MasterOferta.parmKilometer.ToString(), out numeroDecimal);
                    if (puedeConvertir == true)
                        oOferta["KILOMETRO"] = Convert.ToDecimal(enumerator_MasterOferta.parmKilometer);
                    else
                        oOferta["KILOMETRO"] = 0;
                    if (enumerator_MasterOferta.parmDlvMode is null)
                        oOferta["MODO ENTREGA"] = "";
                    else
                        oOferta["MODO ENTREGA"] = enumerator_MasterOferta.parmDlvMode;
                    oOferta["GESTION PORTE"] = Convert.ToInt32(enumerator_MasterOferta.parmGestionPorte.GetHashCode());
                    oOferta["TIPO PORTE"] = Convert.ToInt32(enumerator_MasterOferta.parmTipoPorte.GetHashCode());
                    if (enumerator_MasterOferta.parmPayment is null)
                    {
                        oOferta["FORMA PAGO"] = "";
                        formaPago = "";
                    }
                    else
                    {
                        oOferta["FORMA PAGO"] = enumerator_MasterOferta.parmPayment.ToString();
                        formaPago = enumerator_MasterOferta.parmPayment.ToString();
                    }
                    if (enumerator_MasterOferta.parmPaymSched is null)
                    {
                        oOferta["MULTIVENCIMIENTO"] = "";
                        multivencimiento = "";
                    }
                    else
                    {
                        oOferta["MULTIVENCIMIENTO"] = enumerator_MasterOferta.parmPaymSched.ToString();
                        multivencimiento = enumerator_MasterOferta.parmPaymSched.ToString();
                    }

                    oOferta["NUMERO MESES"] = 0;
                    oOferta["NUMERO DIAS"] = 0;
                    oOferta["DIAS ADD"] = 0;
                    oOferta["DIAS PAGO"] = 0;
                    oOferta["DIAS TOTAL"] = -1;

                    // PAGOS
                    hora_1 = DateTime.Now;
                    WSGeneral.CallContext contextoPagos = new WSGeneral.CallContext();
                    contextoPagos.Company = empresa;

                    WSGeneral.QueryCriteria criterioPagos = new WSGeneral.QueryCriteria();
                    criterioPagos.CriteriaElement = new WSGeneral.CriteriaElement[1];

                    criterioPagos.CriteriaElement[0] = new WSGeneral.CriteriaElement();
                    criterioPagos.CriteriaElement[0].DataSourceName = "PaymTerm";
                    criterioPagos.CriteriaElement[0].FieldName = "PaymTermId";
                    criterioPagos.CriteriaElement[0].Operator = WSGeneral.Operator.Equal;
                    criterioPagos.CriteriaElement[0].Value1 = formaPago;

                    WSGeneral.WSROPServiceClient proxyPagos = new WSGeneral.WSROPServiceClient();
                    proxyPagos.ClientCredentials.Windows.ClientCredential.Domain = WSDominio;
                    proxyPagos.ClientCredentials.Windows.ClientCredential.UserName = WSUsuario;
                    proxyPagos.ClientCredentials.Windows.ClientCredential.Password = WSContrasena;

                    WSGeneral.WSPaymTermContract[] axtablaPagos = proxyPagos.getPaymTerm(contextoPagos, criterioPagos);

                    IEnumerable<WSGeneral.WSPaymTermContract> enumerablePago = axtablaPagos;
                    IEnumerator<WSGeneral.WSPaymTermContract> enumeratorPago = enumerablePago.GetEnumerator();

                    hora_2 = DateTime.Now.Subtract(hora_1);
                    oItemTiempo = dtTiempos.NewRow();
                    oItemTiempo[0] = "TIEMPO llamar al WSGeneral /  tablaPagos con PaytemId = " + formaPago;
                    oItemTiempo[1] = ((Convert.ToDecimal(hora_2.Minutes) * 60) + Convert.ToDecimal(hora_2.Seconds) + (Convert.ToDecimal(hora_2.Milliseconds) / 1000)).ToString("#,##0.000000");
                    dtTiempos.Rows.Add(oItemTiempo);

                    while (enumeratorPago.MoveNext())
                    {
                        WSGeneral.WSPaymTermContract enumerator_Pago = enumeratorPago.Current;

                        oOferta["NUMERO MESES"] = Convert.ToInt32(enumerator_Pago.parmNumOfMonths);
                        oOferta["DIAS PAGO"] = Convert.ToInt32(enumerator_Pago.parmNumOfMonths) * 30;

                        oOferta["NUMERO DIAS"] = Convert.ToInt32(enumerator_Pago.parmNumOfDays);
                        oOferta["DIAS PAGO"] = Convert.ToInt32(oOferta["DIAS PAGO"]) + Convert.ToInt32(enumerator_Pago.parmNumOfDays);

                        oOferta["DIAS ADD"] = 0;
                    }
                    proxyPagos.Close();

                    // MULTIVENCIMIENTOS 
                    hora_1 = DateTime.Now;
                    WSGeneral.CallContext contextoVencimientoCabecera = new WSGeneral.CallContext();
                    contextoVencimientoCabecera.Company = empresa;

                    WSGeneral.QueryCriteria criterioVencimientoCabecera = new WSGeneral.QueryCriteria();
                    criterioVencimientoCabecera.CriteriaElement = new WSGeneral.CriteriaElement[1];

                    criterioVencimientoCabecera.CriteriaElement[0] = new WSGeneral.CriteriaElement();
                    criterioVencimientoCabecera.CriteriaElement[0].DataSourceName = "PaymSched";
                    criterioVencimientoCabecera.CriteriaElement[0].FieldName = "Name";
                    criterioVencimientoCabecera.CriteriaElement[0].Operator = WSGeneral.Operator.Equal;
                    criterioVencimientoCabecera.CriteriaElement[0].Value1 = multivencimiento;

                    WSGeneral.WSROPServiceClient proxyVencimientoCabecera = new WSGeneral.WSROPServiceClient();
                    proxyVencimientoCabecera.ClientCredentials.Windows.ClientCredential.Domain = WSDominio;
                    proxyVencimientoCabecera.ClientCredentials.Windows.ClientCredential.UserName = WSUsuario;
                    proxyVencimientoCabecera.ClientCredentials.Windows.ClientCredential.Password = WSContrasena;

                    WSGeneral.WSPaymSchedContract[] AxdVencimientosCabecera = proxyVencimientoCabecera.getPaymSched(contextoVencimientoCabecera, criterioVencimientoCabecera);

                    IEnumerable<WSGeneral.WSPaymSchedContract> enumerableVencimientoCabecera = AxdVencimientosCabecera;
                    IEnumerator<WSGeneral.WSPaymSchedContract> enumeratorVencimientoCabecera = enumerableVencimientoCabecera.GetEnumerator();

                    hora_2 = DateTime.Now.Subtract(hora_1);
                    oItemTiempo = dtTiempos.NewRow();
                    oItemTiempo[0] = "TIEMPO llamar al ws WSGeneral / tablaVencimientosCabecera con PaymSchedName = " + multivencimiento;
                    oItemTiempo[1] = ((Convert.ToDecimal(hora_2.Minutes) * 60) + Convert.ToDecimal(hora_2.Seconds) + (Convert.ToDecimal(hora_2.Milliseconds) / 1000)).ToString("#,##0.000000");
                    dtTiempos.Rows.Add(oItemTiempo);

                    while (enumeratorVencimientoCabecera.MoveNext())
                    {
                        WSGeneral.WSPaymSchedContract enumerator_VencimientoCabecera = enumeratorVencimientoCabecera.Current;

                        n = Convert.ToInt32(enumerator_VencimientoCabecera.parmNumOfPayment);

                        oOferta["PERIOD UNIT"] = enumerator_VencimientoCabecera.parmPeriodUnit.ToString().ToUpper();
                        PeriodUnit = enumerator_VencimientoCabecera.parmPeriodUnit.ToString().ToUpper();
                        oOferta["QTY UNIT"] = Convert.ToInt32(enumerator_VencimientoCabecera.parmQtyUnit.ToString());
                        QtyUnit = Convert.ToInt32(enumerator_VencimientoCabecera.parmQtyUnit.ToString());

                        oOferta["DIAS TOTAL"] = 0;
                        if (enumerator_VencimientoCabecera.parmPaymBy.ToString().ToUpper() == "TOTAL")
                            oOferta["DIAS TOTAL"] = Convert.ToDecimal(oOferta["DIAS PAGO"]) + Convert.ToDecimal(oOferta["DIAS ADD"]);
                        else if (enumerator_VencimientoCabecera.parmPaymBy.ToString().ToUpper() == "NUMOFPAYMENT" || enumerator_VencimientoCabecera.parmPaymBy.ToString().ToUpper() == "AMOUNTBYPAYMENT")
                        {
                            for (int vencimiento = 0; vencimiento <= n - 1; vencimiento++)
                            {
                                if (PeriodUnit == "MONTH")
                                    oOferta["DIAS TOTAL"] = Convert.ToDecimal(oOferta["DIAS TOTAL"]) + (((vencimiento * (QtyUnit * 30)) + Convert.ToDecimal(oOferta["DIAS PAGO"]) + Convert.ToDecimal(oOferta["DIAS ADD"])) / n);
                                else if (PeriodUnit == "DAY")
                                    oOferta["DIAS TOTAL"] = Convert.ToDecimal(oOferta["DIAS TOTAL"]) + (((vencimiento * QtyUnit) + Convert.ToDecimal(oOferta["DIAS PAGO"]) + Convert.ToDecimal(oOferta["DIAS ADD"])) / n);
                                else
                                    oOferta["DIAS TOTAL"] = 0;
                            }
                        }
                        else if (enumerator_VencimientoCabecera.parmPaymBy.ToString().ToUpper() == "SPECIFIED")
                        {
                            // MULTIVENCIMIENTOS LÍNEAS
                            IEnumerable<WSGeneral.WSPaymSchedLineContract> enumerableVencimientoLineas = enumerator_VencimientoCabecera.parmPaymSchedLines;
                            IEnumerator<WSGeneral.WSPaymSchedLineContract> enumeratorVencimientoLineas = enumerableVencimientoLineas.GetEnumerator();

                            while (enumeratorVencimientoLineas.MoveNext())
                            {
                                WSGeneral.WSPaymSchedLineContract enumerator_VencimientoLineas = enumeratorVencimientoLineas.Current;

                                cantidad = Convert.ToInt32(enumerator_VencimientoLineas.parmQty.ToString());

                                // valida si ya existe este modo de pago, en cuyo caso se ignora
                                if (!listaCantidades.Contains(cantidad))
                                {
                                    listaCantidades.Add(cantidad);

                                    oOferta["QTY"] = Convert.ToInt32(enumerator_VencimientoLineas.parmQty.ToString());
                                    Qty = Convert.ToInt32(enumerator_VencimientoLineas.parmQty.ToString());

                                    oOferta["VALUE"] = Convert.ToDecimal(enumerator_VencimientoLineas.parmValue.ToString());
                                    Valor = Convert.ToDecimal(enumerator_VencimientoLineas.parmValue.ToString());

                                    if (PeriodUnit == "MONTH")
                                        oOferta["DIAS TOTAL"] = Convert.ToDecimal(oOferta["DIAS TOTAL"]) + ((Valor * ((Qty * 30) + Convert.ToDecimal(oOferta["DIAS PAGO"]) + Convert.ToDecimal(oOferta["DIAS ADD"]))) / 100);
                                    else if (PeriodUnit == "DAY")
                                        oOferta["DIAS TOTAL"] = Convert.ToDecimal(oOferta["DIAS TOTAL"]) + ((Valor * (Qty + Convert.ToDecimal(oOferta["DIAS PAGO"]) + Convert.ToDecimal(oOferta["DIAS ADD"]))) / 100);
                                    else
                                        oOferta["DIAS TOTAL"] = Convert.ToDecimal(oOferta["DIAS TOTAL"]);
                                }
                            }

                        }
                    }
                    proxyVencimientoCabecera.Close();
                    criterioVencimientoCabecera = null;
                    contextoVencimientoCabecera = null;

                    dtCabeceraOferta.Rows.Add(oOferta);
                    oOferta = null;

                    IEnumerable<WSGeneral.WSSalesQuotationTableContract> enumerableCapitulos = enumerator_MasterOferta.parmQuotationTable;
                    IEnumerator<WSGeneral.WSSalesQuotationTableContract> enumeratorCapitulos = enumerableCapitulos.GetEnumerator();

                    dondeVa = "Líneas ofertas";
                    while (enumeratorCapitulos.MoveNext())
                    {
                        WSGeneral.WSSalesQuotationTableContract enumerator_Capitulos = enumeratorCapitulos.Current;

                        oOferta = dtCapitulosOferta.NewRow();
                        oOferta["OFERTA"] = enumerator_MasterOferta.parmQuotationId.ToString();
                        if (enumerator_Capitulos.parmQuotationTitle is null)
                            oOferta["CAPITULO"] = enumerator_Capitulos.parmQuotationId.ToString().Replace("'", "").Trim().Replace("\"", "").Replace("\\", ""); 
                        else
                            if (enumerator_Capitulos.parmQuotationTitle.ToString() != "")
                            oOferta["CAPITULO"] = enumerator_Capitulos.parmQuotationId.ToString().Replace("'", "").Trim().Replace("\"", "").Replace("\\", "")+ " / " + enumerator_Capitulos.parmQuotationTitle.ToString().Replace("'", "").Trim().Replace("\"", "").Replace("\\", ""); 
                        else
                            oOferta["CAPITULO"] = enumerator_Capitulos.parmQuotationId.ToString().Replace("'", "").Trim().Replace("\"", "").Replace("\\", "");
                        oOferta["FECHA"] = Convert.ToDateTime(enumerator_Capitulos.parmCreatedDateTime.ToString());
                        oOferta["TIPO"] = enumerator_Capitulos.parmSalesRental.ToString().ToUpper();
                        dtCapitulosOferta.Rows.Add(oOferta);
                        oOferta = null;

                        IEnumerable<WSGeneral.WSSalesQuotationLineContract> enumerableLineas = enumerator_Capitulos.parmQuotationLine;
                        IEnumerator<WSGeneral.WSSalesQuotationLineContract> enumeratorLineas = enumerableLineas.GetEnumerator();

                        dondeVa = "Líneas pedidos";
                        while (enumeratorLineas.MoveNext())
                        {
                            WSGeneral.WSSalesQuotationLineContract enumerator_OfertaLineas = enumeratorLineas.Current;

                            if (enumerator_OfertaLineas.parmItemId.ToString() == "57907")
                                dondeVa = "aqui";
                            oOferta = dtLineasOferta.NewRow();
                            oOferta["OFERTA"] = enumerator_MasterOferta.parmQuotationId.ToString();
                            if (enumerator_Capitulos.parmQuotationTitle is null)
                                oOferta["CAPITULO"] = enumerator_Capitulos.parmQuotationId.ToString().Replace("'", "").Trim().Replace("\"", "").Replace("\\", "");
                            else
                            if (enumerator_Capitulos.parmQuotationTitle.ToString() != "")
                                oOferta["CAPITULO"] = enumerator_Capitulos.parmQuotationId.ToString().Replace("'", "").Trim().Replace("\"", "").Replace("\\", "") + " / " + enumerator_Capitulos.parmQuotationTitle.ToString().Replace("'", "").Trim().Replace("\"", "").Replace("\\", "");
                            else
                                oOferta["CAPITULO"] = enumerator_Capitulos.parmQuotationId.ToString().Replace("'", "").Trim().Replace("\"", "").Replace("\\", "");
                            if (enumerator_OfertaLineas.parmItemId.ToString() == "57640")
                                dondeVa = "";
                            oOferta["ITEM"] = enumerator_OfertaLineas.parmItemId.ToString();
                            // DIANA existeTR001
                            if (codigosTransporte.IndexOf(enumerator_OfertaLineas.parmItemId.ToString()) >= 0)
                                existeTR001 = true;

                            puedeConvertir = decimal.TryParse(enumerator_OfertaLineas.parmSalesQty.ToString(), out numeroDecimal);
                            if (puedeConvertir == true)
                                oOferta["CANTIDAD"] = enumerator_OfertaLineas.parmSalesQty.ToString();
                            else
                                oOferta["CANTIDAD"] = 0;
                            puedeConvertir = decimal.TryParse(enumerator_OfertaLineas.parmLineAmount.ToString(), out numeroDecimal);
                            if (puedeConvertir == true)
                                oOferta["IMPORTE"] = enumerator_OfertaLineas.parmLineAmount.ToString();
                            else
                                oOferta["IMPORTE"] = 0;
                            puedeConvertir = decimal.TryParse(enumerator_OfertaLineas.parmDuracionEstimada.ToString(), out numeroDecimal);
                            if (puedeConvertir == true)
                                oOferta["DURACION"] = Convert.ToDecimal(enumerator_OfertaLineas.parmDuracionEstimada.ToString());
                            else
                                oOferta["DURACION"] = 0;
                            oOferta["CANON FENOLICO"] = 0;
                            oOferta["CANON IMPORTE"] = 0;
                            oOferta["CANON"] = 0;
                            if (enumerator_OfertaLineas.parmCanonFenolico != 0)
                                oOferta["CANON FENOLICO"] = enumerator_OfertaLineas.parmCanonFenolico;
                            if (enumerator_OfertaLineas.parmCanonImport != 0)
                                oOferta["CANON IMPORTE"] = Convert.ToDecimal(enumerator_OfertaLineas.parmCanonImport);
                            if (enumerator_OfertaLineas.parmCanon != 0)
                                oOferta["CANON"] = Convert.ToDecimal(enumerator_OfertaLineas.parmCanon);
                            puedeConvertir = decimal.TryParse(enumerator_OfertaLineas.parmEurDia.ToString(), out numeroDecimal);
                            if (puedeConvertir == true)
                                oOferta["EURO DIA"] = Convert.ToDecimal(enumerator_OfertaLineas.parmEurDia);
                            else
                                oOferta["EURO DIA"] = 0;
                            oOferta["PRECIO"] = Convert.ToDecimal(enumerator_OfertaLineas.parmSalesPrice);
                            dtLineasOferta.Rows.Add(oOferta);
                            oOferta = null;
                        }
                    }
                }
                error = "";
            }
            catch (Exception ex)
            {
                error = dondeVa + " // " + ex.Message;
                mostrarMensaje("estructuraOfertas // " + dondeVa + " // " + ex.Message);
            }
            finally
            {
                Session["dtTiempos"] = dtTiempos;
            }
        }

        private void mostrarMensaje(string mensaje)
        {
            MENSAJE_ERROR.Visible = true;
            imgWarning.Visible = true;
            lblMensajeError.Visible = true;
            lblMensajeError.Text = mensaje;
        }

        private void hacerEnParalelo(ref DataTable dtResultados, int totalHilos)
        {
            DataRow oFila;
            oFila = dtResultados.NewRow();
            oFila[0] = totalHilos;
            oFila[1] = totalHilos * 10;
            dtResultados.Rows.Add(oFila);
        }

