                sl.SetColumnWidth(3, 15);
                sl.SetColumnWidth(4, 15);
                sl.SetColumnWidth(5, 15);
                sl.SetColumnWidth(6, 15);
                sl.SetColumnWidth(7, 15);
                sl.SetColumnWidth(8, 15);
                sl.SetColumnWidth(9, 15);
                sl.SetColumnWidth(10, 15);
                sl.SetColumnWidth(11, 15);

                style.SetFont("Verdana", 10);
                style.Font.Bold = true;
                style.Border.BottomBorder.BorderStyle = BorderStyleValues.Thick;
                style.Fill.SetPattern(PatternValues.Solid, System.Drawing.Color.DarkBlue, System.Drawing.Color.DarkBlue);
                style.SetFontColor(System.Drawing.Color.White);
                style.Alignment.Horizontal = HorizontalAlignmentValues.Center;
                for (columna = 1; columna <= 11; columna++)
                    sl.SetCellStyle(1, columna, style);

                fila = 2;

                int columnaExcel = 0;
                foreach (DataRow Row in dtPendienteDevolver.Rows)
                {
                    // Datos
                    sl.SetCellValue(fila, 1, Row.ItemArray[2].ToString());
                    sl.SetCellValue(fila, 2, Row.ItemArray[3].ToString());
                    sl.SetCellValue(fila, 3, Row.ItemArray[4].ToString());

                    columnaExcel = 4;
                    decimal.TryParse(Row.ItemArray[8].ToString(), out valorDecimal);
                    sl.SetCellValue(fila, columnaExcel, valorDecimal);
                    sl.SetCellStyle(fila, columnaExcel, styleDec);

                    columnaExcel = columnaExcel + 1;
                    for (columna = 10; columna <= 16; columna++)
                    {
                        decimal.TryParse(Row.ItemArray[columna].ToString(), out valorDecimal);
                        sl.SetCellValue(fila, columnaExcel, valorDecimal);
                        sl.SetCellStyle(fila, columnaExcel, styleDec);

                        columnaExcel = columnaExcel + 1;
                    }
                    fila++;
                }
                sl.AutoFitColumn(1, 11);

                sl.SaveAs(nombreInforme);

                lblTituloInformacion.Text = "I N F O R M A C I Ó N";
                lblMensajeInformacion.Text = "Fichero excel creado.";
                mpeInformacion.Show();

                bajarExcel();
            }
            catch (Exception ex)
            {
                lblTituloInformacion.Text = "I N F O R M A C I Ó N"; // "Fichero configuración";
                lblMensajeInformacion.Text = "Error al generar el fichero: Ficheros excel/" + Session["nombreInforme"].ToString() + " // " + ex.Message;
                mpeInformacion.Show();
            }
        }

        protected void bajarExcel()
