        private void validarFacturacion(DataTable dtPendienteDevolver, DataTable dtFacturasLineas)
        {
            DataRow[] filaEncontrada;
            bool noEncontrado = false;

            try
            {
                txtFechaSimulacion.Enabled = true;
                chkFacturarSimulacion.Enabled = true;
                chkFacturarDiasMinimo.Enabled = true;

                MensajeSimulacionFacturacion.Visible = false;
                lblMensajeSimulacionFacturacion.Text = "";
                foreach (DataRow filaPD in dtPendienteDevolver.Rows)
                {
                    if (dtFacturasLineas.Rows.Count > 0)
                    {
                        if (filaPD["ARTICULO"].ToString().Trim() != "")
                        {
                            filaEncontrada = dtFacturasLineas.Select("ITEM = '" + filaPD["ARTICULO"].ToString().Trim() + "'");
                            if (filaEncontrada.Count() == 0)
                            {
                                noEncontrado = true;
                                break;
                            }
                        }
                    }
                    else
                    {
                        noEncontrado = true;
                        break;
                    }
                }
                if (noEncontrado)
                {
                    txtFechaSimulacion.Enabled = false;
                    chkFacturarSimulacion.Enabled = false;
                    chkFacturarDiasMinimo.Enabled = false;

                    MensajeSimulacionFacturacion.Visible = true;

                    string idioma = Session["idioma"].ToString();
                    filaEncontrada = dtIdiomas.Select("ETQ_Control = 'lblMensajeSimulacionFacturacion'");
                    foreach (DataRow filaValor in filaEncontrada)
                    {
                        if (idioma == "ESPAÑOL")
                            lblMensajeSimulacionFacturacion.Text = Convert.ToString(filaValor["ETQ_TextoCastellano"]);
                        if (idioma == "CATALAN")
                            lblMensajeSimulacionFacturacion.Text = Convert.ToString(filaValor["ETQ_TextoCatalan"]);
                        if (idioma == "INGLES")
                            lblMensajeSimulacionFacturacion.Text = Convert.ToString(filaValor["ETQ_TextoIngles"]);
                    }
                }
            }
            catch (Exception ex)
            {
                mostrarMensaje("validarFacturacion - " + ex.Message);
            }
        }

        #region "ACELER"
        private void ofertaAceler()
        {
            string strConexion;
            SqlCommand comando;
            SqlConnection conexion;

            string dondeVa = "";
            List<JSONLineasAceler> lineas = null;
            DateTime fecha_Entrada = DateTime.Now;
            DateTime dateTime = default(DateTime);
            DateTime fecha_Salida = dateTime;
            TimeSpan tiempo = default(TimeSpan);
            string cabecera = "";
            string json_lineas = "";
            string mensajeError = "";

            JSONCabeceraAceler json_cabecera = JsonConvert.DeserializeObject<JSONCabeceraAceler>(Session["cabeceraEnviado"].ToString());

            dondeVa = "datatables";
            DataTable dtCabeceraOferta = new DataTable();
            dtCabeceraOferta.Columns.Add("OFERTA", typeof(string));
